INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Permit-Junction/permitjunction-website/da-content-authoring', 'da-content-authoring', 'Permit-Junction', 'permitjunction-website', 'community', 'da-content-authoring Permit-Junction permitjunction-website community The da-content-authoring skill guides developers through authoring and editing content in DA for AEM Edge Delivery Services sites. It benefits developers working with content-driven development workflows. DA 内容创作是 AEM Edge Delivery Services 的网页内容编辑器，用于创建和编辑内容 DA コンテンツオーサリングは、AEM Edge Delivery Services の Web ベースのコンテンツエディターであり、コンテンツの作成と編集に使用 DA 콘텐츠 저작은 AEM Edge Delivery Services의 웹 기반 콘텐츠 편집기로서 콘텐츠의 생성과 편집에 사용 DA Content Authoring es una habilidad que te permite crear y editar contenido en Document Authoring para sitios de AEM Edge Delivery Services. L''édition de contenu DA est une compétence qui vous permet de créer et de modifier du contenu dans Document Authoring pour les sites de services AEM Edge Delivery. DA Content Authoring ist eine Fähigkeit, die es Ihnen ermöglicht, Inhalte in Document Authoring für AEM Edge Delivery Services-Seiten zu erstellen und zu bearbeiten. O DA é uma plataforma de edição de conteúdo baseada na web para AEM Edge Delivery Services. Este guia aborda a autorias de conteúdo em DA. DA - это веб-ориентированный редактор контента для сервисов AEM Edge Delivery. Это руководство охватывает создание контента в DA для ИИ Агентов. DA هي منصة تحرير المحتوى القائمة على الويب لخدمات AEM Edge Delivery. هذا الدليل يغطي تحرير المحتوى في DA للوكلاء الذكاء الاصطناعي. how to use da-content-authoring da-content-authoring tutorial AEM Edge Delivery Services content creation da-content-authoring vs content-driven-development da-content-authoring setup guide da-content-authoring for developers content authoring in DA da-content-authoring alternative da-content-authoring install da-content-authoring best practices DA 内容创作 AEM Edge Delivery Services 内容编辑 网页内容编辑器 CDD 内容驱动开发 块内容模型 AIエージェント Guides authoring and editing content in DA at da.live Supports content-driven development workflows with CDD Relies on block content models for structured content creation Integrates with building blocks for block implementation Specifically designed for AEM Edge Delivery Services sites Complements content modeling for effective content strategy da-content-authoring is a skill that enables developers to author and edit content in DA, a web-based content editor for AEM Edge Delivery Services sites.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sandnap/easy_notes/stimulus', 'community', 'sandnap', 'easy_notes', 'sandnap/easy_notes', 'stimulus', 0, 0, 60, '2026-03-08T01:57:15.642Z', '2026-03-08T02:13:42.358Z', '88ab3d606c7bc88834a96903791fcc33c6e74992ee92646e9cb9cef6cbf4e8b1', '{"id":"sandnap/easy_notes/stimulus","name":"stimulus","description":{"en":"Stimulus is a JavaScript framework designed to augment HTML with behavior, keeping HTML as the source of truth. It benefits Rails application developers by providing a modest and efficient way to add interactivity.","zh":"Stimulus 是一个用于增强 HTML 行为的 JavaScript 框架。它通过数据属性连接 JavaScript 和 DOM，保持 HTML 为事实来源。","ja":"Stimulus は、HTML の動作を拡張するための JavaScript フレームワークです。データ属性を使用して JavaScript と DOM を接続し、HTML を事実のソースとして維持します。","ko":"Stimulus는 HTML 동작을 확장하기 위한 JavaScript 프레임워크입니다. 데이터 속성을 사용하여 JavaScript와 DOM을 연결하고, HTML을 사실의 원천으로 유지합니다.","es":"Stimulus es un framework de JavaScript modesto que agrega comportamiento a tu HTML. Conecta JavaScript al DOM a través de atributos de datos, manteniendo tu HTML como fuente de verdad.","fr":"Stimulus est un framework JavaScript modeste qui ajoute un comportement à votre HTML. Il connecte JavaScript au DOM via des attributs de données, en gardant votre HTML comme source de vérité.","de":"Stimulus ist ein bescheidener JavaScript-Framework, das Verhalten zu Ihrem HTML hinzufügt. Es verbindet JavaScript mit dem DOM über Datenattribute, wobei Ihr HTML die Quelle der Wahrheit bleibt.","pt":"O Stimulus é um framework JavaScript modesto que adiciona comportamento ao seu HTML. Conheça as melhores práticas para aplicativos Rails","ru":"Stimulus - это скромный JavaScript-фреймворк, который добавляет поведение к вашему HTML. Узнайте о лучших практиках для приложений Rails - ИИ Агенты","ar":"Stimulus هو إطار العمل JavaScript المتواضع الذي يضيف سلوكًا إلى HTML الخاص بك. تعرف على أفضل الممارسات لتطبيقات Rails - أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"Stimulus: Best Practices for Rails Applications | AI Agen...","zh":"Stimulus 框架最佳实践指南","ja":"Stimulus フレームワーク設定ガイド","ko":"Stimulus 프레임워크 사용법 및 최적화","es":"Guía de configuración de Stimulus para aplicaciones Rails","fr":"Guide de mise en œuvre de Stimulus pour les applications ...","de":"Einrichtungsleitfaden für Stimulus in Rails-Anwendungen","pt":"Guia de Configuração do Stimulus para Aplicativos Rails","ru":"Руководство по настройке Stimulus для приложений Rails - ...","ar":"دليل إعداد Stimulus لتطبيقات Rails - أدوات الذكاء الاصطناعي"},"description":{"en":"Unlock the full potential of Stimulus in your Rails app. Learn how to connect JavaScript to the DOM via data attributes and get started with our setup guide.","zh":"了解 Stimulus 框架的核心概念和最佳实践，优化您的 Rails 应用程序","ja":"Stimulus フレームワークのコアコンセプトとベストプラクティスを学び、Rails アプリケーションを最適化する","ko":"Stimulus 프레임워크의 핵심 개념과 최적화 방법을 알아보세요. Rails 애플리케이션을 최적화하는 데 필요한 모든 것이 여기에 있습니다.","es":"Aprende a utilizar Stimulus en tus aplicaciones Rails con nuestras mejores prácticas y consejos para una integración exitosa","fr":"Découvrez comment utiliser Stimulus dans vos applications Rails avec nos meilleures pratiques et conseils pour une intégration réussie","de":"Erfahren Sie, wie Sie Stimulus in Ihren Rails-Anwendungen verwenden können, mit unseren besten Praktiken und Tipps für eine erfolgreiche Integration","pt":"Aprenda a configurar o Stimulus para melhorar a experiência do usuário em seus aplicativos Rails com nosso guia passo a passo","ru":"Узнайте, как настроить Stimulus для улучшения пользовательского опыта в ваших приложениях Rails с нашей пошаговой инструкцией - ИИ Агенты","ar":"تعلم كيفية إعداد Stimulus لتحسين تجربة المستخدم في تطبيقات Rails الخاصة بك مع دليلنا خطوة بخطوة - أدوات الذكاء الاصطناعي"},"definition":{"en":"Stimulus is a modest JavaScript framework that connects JavaScript to the DOM via data attributes, designed to augment HTML with just enough behavior.","zh":"Stimulus 是一个 JavaScript 框架，用于为 HTML 添加行为","ja":"Stimulus は、HTML に動作を追加するための JavaScript フレームワークです","ko":"Stimulus는 HTML에 동작을 추가하기 위한 JavaScript 프레임워크입니다","es":"Stimulus es un framework de JavaScript que agrega comportamiento a tu HTML a través de atributos de datos","fr":"Stimulus est un framework JavaScript qui ajoute un comportement à votre HTML via des attributs de données","de":"Stimulus ist ein JavaScript-Framework, das Verhalten zu Ihrem HTML über Datenattribute hinzufügt","pt":"O Stimulus é um framework JavaScript que conecta JavaScript ao DOM via atributos de dados","ru":"Stimulus - это фреймворк JavaScript, который соединяет JavaScript с DOM через атрибуты данных - ИИ Агенты","ar":"Stimulus هو إطار العمل JavaScript الذي يصل بين JavaScript و DOM عبر سمات البيانات - أدوات الذكاء الاصطناعي"},"features":{"en":["Connects JavaScript to the DOM via data attributes","Keeps HTML as the source of truth for application behavior","Supports Rails applications with efficient and modest interactivity","Follows best practices as outlined in Stimulus version 3.2.2","References the official Stimulus documentation at https://stimulus.hotwired.dev/"],"zh":["通过数据属性连接 JavaScript 和 DOM","保持 HTML 为事实来源","支持 Rails 应用程序","核心概念包括数据属性和 DOM 操作","可用于创建自定义的 JavaScript 行为"],"ja":["データ属性を使用して JavaScript と DOM を接続","HTML を事実のソースとして維持","Rails アプリケーションをサポート","コアコンセプトにはデータ属性と DOM 操作が含まれる","カスタムの JavaScript 動作を作成するために使用できます"],"ko":["데이터 속성을 사용하여 JavaScript와 DOM을 연결","HTML을 사실의 원천으로 유지","Rails 애플리케이션을 지원","핵심 개념에는 데이터 속성과 DOM 조작이 포함됨","사용자 지정 JavaScript 동작을 생성하는 데 사용할 수 있음"],"es":["Conexión de JavaScript al DOM a través de atributos de datos","Mantención de HTML como fuente de verdad","Compatibilidad con Rails","Uso de datos de atributos para agregar comportamiento","Integración con Hotwired"],"fr":["Connexion de JavaScript au DOM via des attributs de données","Maintenance de HTML comme source de vérité","Compatibilité avec Rails","Utilisation d''attributs de données pour ajouter un comportement","Intégration avec Hotwired"],"de":["Verbindung von JavaScript mit dem DOM über Datenattribute","Beibehaltung von HTML als Quelle der Wahrheit","Kompatibilität mit Rails","Verwendung von Datenattributen zum Hinzufügen von Verhalten","Integration mit Hotwired"],"pt":["Conecta JavaScript ao DOM via atributos de dados","Mantém o HTML como a fonte de verdade","Compatível com aplicativos Rails","Fácil de configurar e usar","Melhora a experiência do usuário"],"ru":["Соединяет JavaScript с DOM через атрибуты данных","Сохраняет HTML как источник истины","Компатибелен с приложениями Rails","Легко настраивается и используется","Улучшает пользовательский опыт - ИИ Агенты"],"ar":["يصل بين JavaScript و DOM عبر سمات البيانات","يحافظ على HTML ك源 الحقيقة","متوافق مع تطبيقات Rails","سهل التهيئة والاستخدام","يحسن تجربة المستخدم - أدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use stimulus in rails","what is stimulus framework","stimulus alternative to jQuery","stimulus vs react","stimulus install guide","stimulus setup for rails applications"],"zh":["Stimulus 框架","JavaScript 框架","HTML 行为","Rails 应用程序","数据属性","DOM 操作","JavaScript 开发","前端开发","Web 开发"],"ja":["Stimulus フレームワーク","JavaScript フレームワーク","HTML 動作","Rails アプリケーション","データ属性","DOM 操作","JavaScript 開発","フロントエンド開発","Web 開発"],"ko":["Stimulus 프레임워크","JavaScript 프레임워크","HTML 동작","Rails 애플리케이션","데이터 속성","DOM 조작","JavaScript 개발","프론트엔드 개발","Web 개발"],"es":["Stimulus","Rails","JavaScript","framework","atributos de datos","Hotwired","integración","configuración","mejores prácticas"],"fr":["Stimulus","Rails","JavaScript","framework","attributs de données","Hotwired","intégration","configuration","meilleures pratiques"],"de":["Stimulus","Rails","JavaScript","Framework","Datenattribute","Hotwired","Integration","Konfiguration","beste Praktiken"],"pt":["Stimulus","framework JavaScript","aplicativos Rails","melhorias de desempenho","otimização de usuário","desenvolvimento web","tecnologias web","ferramentas de desenvolvimento"],"ru":["Stimulus","фреймворк JavaScript","приложения Rails","ускорение производительности","оптимизация пользователя","веб-разработка","веб-технологии","инструменты разработки","ИИ Агенты"],"ar":["Stimulus","إطار العمل JavaScript","تطبيقات Rails","تحسين الأداء","تحسين المستخدم","تطوير الويب","تكنولوجيا الويب","أدوات التطوير","أدوات الذكاء الاصطناعي"]}},"owner":"sandnap","repo":"easy_notes","repoPath":"sandnap/easy_notes","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.642Z","topics":[],"category":"community","skillMd":{"name":"stimulus","description":"Best practices for using Stimulus controllers to add JavaScript behavior to HTML","bodyPreview":"# Stimulus Best Practices for Rails Applications\n\nRule updated on 12/15/2025 to Stimulus version 3.2.2\n\nStimulus is a modest JavaScript framework designed to augment your HTML with just enough behavior. It connects JavaScript to the DOM via data attributes, keeping your HTML as the source of truth.\n\nFor full reference see [https://stimulus.hotwired.dev/](https://stimulus.hotwired.dev/)\n\n## Core Concepts\n\n| Concept    | Purpose                                  | Data Attribute","body":"# Stimulus Best Practices for Rails Applications\n\nRule updated on 12/15/2025 to Stimulus version 3.2.2\n\nStimulus is a modest JavaScript framework designed to augment your HTML with just enough behavior. It connects JavaScript to the DOM via data attributes, keeping your HTML as the source of truth.\n\nFor full reference see [https://stimulus.hotwired.dev/](https://stimulus.hotwired.dev/)\n\n## Core Concepts\n\n| Concept    | Purpose                                  | Data Attribute                     |\n| ---------- | ---------------------------------------- | ---------------------------------- |\n| Controller | JavaScript class that adds behavior      | `data-controller=\"name\"`           |\n| Target     | Important elements referenced in JS      | `data-name-target=\"targetName\"`    |\n| Action     | Event handlers connecting DOM to methods | `data-action=\"event->name#method\"` |\n| Value      | Reactive data stored in HTML             | `data-name-value-name=\"value\"`     |\n| Class      | CSS classes toggled by the controller    | `data-name-class-name=\"class\"`     |\n| Outlet     | References to other controllers          | `data-name-outlet-name=\"selector\"` |\n\n---\n\n## When to Use Stimulus\n\n**Use Stimulus for:**\n\n- Toggle visibility (dropdowns, modals, accordions)\n- Form enhancements (character counters, auto-submit, validation UI)\n- Copy to clipboard\n- Keyboard shortcuts\n- Animations and transitions\n- Client-side filtering/sorting (small datasets)\n- Debounced input handlers\n- Any behavior that doesn''t require server data\n\n**Don''t use Stimulus for:**\n\n- Data that should come from the server (use Turbo Streams instead)\n- Complex state management (consider if your approach is right)\n- Things Turbo already handles (form submission, navigation)\n\n---\n\n## Controller Structure\n\n### File Naming & Location\n\nControllers that live in `app/javascript/controllers/` and follow the naming convention below are automatically registered.\n\n| File Name                 | Controller Name       | HTML Reference                |\n| ------------------------- | --------------------- | ----------------------------- |\n| `hello_controller.js`     | `HelloController`     | `data-controller=\"hello\"`     |\n| `clipboard_controller.js` | `ClipboardController` | `data-controller=\"clipboard\"` |\n| `user_form_controller.js` | `UserFormController`  | `data-controller=\"user-form\"` |\n\n### Basic Controller Template\n\n```javascript\nimport { Controller } from \"@hotwired/stimulus\"\n\nexport default class extends Controller {\n  static targets = [\"input\", \"output\"]\n  static values = { url: String, count: Number, active: Boolean }\n  static classes = [\"hidden\", \"active\"]\n\n  connect() {\n    // Called when controller is connected to DOM\n  }\n\n  disconnect() {\n    // Called when controller is removed from DOM\n    // Clean up event listeners, timers, etc.\n  }\n\n  // Action methods\n  toggle() {\n    this.outputTarget.classList.toggle(this.hiddenClass)\n  }\n}\n```\n\n---\n\n## Targets\n\nTargets provide named references to important elements within the controller''s scope.\n\n### Defining Targets\n\n```javascript\nexport default class extends Controller {\n  static targets = [\"input\", \"submit\", \"error\"]\n\n  validate() {\n    if (this.inputTarget.value.length < 3) {\n      this.errorTarget.textContent = \"Too short\"\n      this.submitTarget.disabled = true\n    }\n  }\n}\n```\n\n### HTML Usage\n\n```erb\n<div data-controller=\"form\">\n  <input data-form-target=\"input\" data-action=\"input->form#validate\">\n  <span data-form-target=\"error\"></span>\n  <button data-form-target=\"submit\">Submit</button>\n</div>\n```\n\n### Target Properties\n\n| Property              | Returns                           | Example           |\n| --------------------- | --------------------------------- | ----------------- |\n| `this.inputTarget`    | First matching element (or error) | Single element    |\n| `this.inputTargets`   | Array of all matching elements    | `[el1, el2, el3]` |\n| `this.hasInputTarget` | Boolean if target exists          | `true` / `false`  |\n\n---\n\n## Values\n\nValues are reactive data attributes that automatically sync between HTML and JavaScript.\n\n### Defining Values\n\n```javascript\nexport default class extends Controller {\n  static values = {\n    url: String,\n    count: Number,\n    active: Boolean,\n    config: Object,\n    items: Array,\n  }\n\n  countValueChanged(value, previousValue) {\n    // Called automatically when count value changes\n    console.log(`Count changed from ${previousValue} to ${value}`)\n  }\n}\n```\n\n### HTML Usage\n\n```erb\n<div data-controller=\"counter\"\n     data-counter-count-value=\"0\"\n     data-counter-url-value=\"<%= api_path %>\"\n     data-counter-config-value=\"<%= { limit: 10 }.to_json %>\">\n</div>\n```\n\n### Value Benefits\n\n- **Reactive**: Changes trigger `*ValueChanged` callbacks\n- **Type coercion**: Automatic conversion to declared type\n- **Default values**: `static values = { count: { type: Number, default: 0 } }`\n- **HTML as source of truth**: State is visible in the DOM\n\n---\n\n## Actions\n\nActions connect DOM events to controller methods.\n\n### Action Syntax\n\n```\ndata-action=\"event->controller#method\"\n```\n\n### Common Patterns\n\n```erb\n<!-- Click event (default for buttons) -->\n<button data-action=\"dropdown#toggle\">Menu</button>\n\n<!-- Explicit event -->\n<input data-action=\"input->search#filter\">\n\n<!-- Multiple actions -->\n<input data-action=\"focus->form#highlight blur->form#unhighlight\">\n\n<!-- Keyboard events with filters -->\n<input data-action=\"keydown.enter->form#submit keydown.escape->form#cancel\">\n\n<!-- Window/document events -->\n<div data-controller=\"modal\" data-action=\"keydown.escape@window->modal#close\">\n\n<!-- Form events -->\n<form data-action=\"submit->form#validate\">\n```\n\n### Event Modifiers\n\n| Modifier   | Effect                            |\n| ---------- | --------------------------------- |\n| `:prevent` | Calls `event.preventDefault()`    |\n| `:stop`    | Calls `event.stopPropagation()`   |\n| `:self`    | Only fires if target is element   |\n| `:once`    | Removes listener after first fire |\n\n```erb\n<a href=\"#\" data-action=\"click->nav#toggle:prevent\">Toggle</a>\n```\n\n---\n\n## Classes\n\nClasses let you reference CSS classes from your controller without hardcoding them.\n\n### Defining Classes\n\n```javascript\nexport default class extends Controller {\n  static classes = [\"active\", \"hidden\", \"loading\"]\n\n  toggle() {\n    this.element.classList.toggle(this.activeClass)\n  }\n\n  load() {\n    if (this.hasLoadingClass) {\n      this.element.classList.add(this.loadingClass)\n    }\n  }\n}\n```\n\n### HTML Usage\n\n```erb\n<div data-controller=\"toggle\"\n     data-toggle-active-class=\"bg-blue-500 text-white\"\n     data-toggle-hidden-class=\"hidden\">\n</div>\n```\n\n---\n\n## Lifecycle Callbacks\n\n```javascript\nexport default class extends Controller {\n  initialize() {\n    // Called once when controller is first instantiated\n    // Use for one-time setup that doesn''t depend on DOM\n  }\n\n  connect() {\n    // Called each time controller connects to DOM\n    // Set up event listeners, fetch data, start timers\n  }\n\n  disconnect() {\n    // Called when controller disconnects from DOM\n    // ALWAYS clean up: remove listeners, clear timers, abort fetches\n  }\n}\n```\n\n### Cleanup Example\n\n```javascript\nexport default class extends Controller {\n  connect() {\n    this.interval = setInterval(() => this.refresh(), 5000)\n    this.abortController = new AbortController()\n  }\n\n  disconnect() {\n    clearInterval(this.interval)\n    this.abortController.abort()\n  }\n\n  async refresh() {\n    const response = await fetch(this.urlValue, {\n      signal: this.abortController.signal,\n    })\n    // ...\n  }\n}\n```\n\n---\n\n## Common Controller Patterns\n\n### Toggle Controller\n\n```javascript\n// toggle_controller.js\nimport { Controller } from \"@hotwired/stimulus\"\n\nexport default class extends Controller {\n  static targets = [\"content\"]\n  static classes = [\"hidden\"]\n\n  toggle() {\n    this.contentTarget.classList.toggle(this.hiddenClass)\n  }\n\n  show() {\n    this.contentTarget.classList.remove(this.hiddenClass)\n  }\n\n  hide() {\n    this.contentTarget.classList.add(this.hiddenClass)\n  }\n}\n```\n\n### Clipboard Controller\n\n```javascript\n// clipboard_controller.js\nimport { Controller } from \"@hotwired/stimulus\"\n\nexport default class extends Controller {\n  static targets = [\"source\"]\n  static values = { successDuration: { type: Number, default: 2000 } }\n\n  copy() {\n    navigator.clipboard.writeText(this.sourceTarget.value)\n    this.showCopiedState()\n  }\n\n  showCopiedState() {\n    this.element.dataset.copied = true\n    setTimeout(() => delete this.element.dataset.copied, this.successDurationValue)\n  }\n}\n```\n\n### Debounce Controller\n\n```javascript\n// search_controller.js\nimport { Controller } from \"@hotwired/stimulus\"\n\nexport default class extends Controller {\n  static targets = [\"input\", \"form\"]\n  static values = { delay: { type: Number, default: 300 } }\n\n  search() {\n    clearTimeout(this.timeout)\n    this.timeout = setTimeout(() => {\n      this.formTarget.requestSubmit()\n    }, this.delayValue)\n  }\n\n  disconnect() {\n    clearTimeout(this.timeout)\n  }\n}\n```\n\n---\n\n## Integration with Turbo\n\n### Persisting Controllers Across Navigation\n\nTurbo Drive preserves `<head>` but replaces `<body>`. Controllers on body elements disconnect and reconnect. Use values to persist state:\n\n```erb\n<!-- State survives Turbo navigation because it''s in HTML -->\n<div data-controller=\"sidebar\" data-sidebar-open-value=\"true\">\n```\n\n### Responding to Turbo Events\n\n```javascript\nexport default class extends Controller {\n  connect() {\n    document.addEventListener(\"turbo:before-cache\", this.cleanup)\n  }\n\n  disconnect() {\n    document.removeEventListener(\"turbo:before-cache\", this.cleanup)\n  }\n\n  cleanup = () => {\n    // Reset state before Turbo caches the page\n    this.element.classList.remove(\"is-active\")\n  }\n}\n```\n\n### Working with Turbo Frames\n\n```javascript\nexport default class extends Controller {\n  connect() {\n    this.element.addEventListener(\"turbo:frame-load\", this.onFrameLoad)\n  }\n\n  onFrameLoad = (event) => {\n    // React to frame content loading\n    this.updateUI()\n  }\n}\n```\n\n---\n\n## Best Practices Summary\n\n1. **Keep controllers small** — One responsibility per controller (< 100 lines ideally)\n2. **Use values for state** — Don''t store state in instance variables; keep it in data attributes\n3. **Always clean up** — Clear timers, abort fetches, remove listeners in `disconnect()`\n4. **Prefer HTML over JS** — Use data attributes to configure behavior, not JavaScript\n5. **Name actions clearly** — `toggle`, `submit`, `validate` not `handleClick`, `onClick`\n6. **Use targets over querySelector** — More explicit and self-documenting\n7. **Compose with multiple controllers** — Combine small controllers rather than building monoliths\n8. **Let Turbo handle server communication** — Stimulus is for client-side behavior only\n\n---\n\n## Anti-Patterns to Avoid\n\n| Don''t                              | Do Instead                               |\n| ---------------------------------- | ---------------------------------------- |\n| Store state in instance variables  | Use values (`static values = {}`)        |\n| Use `querySelector` in controllers | Use targets (`static targets = []`)      |\n| Hardcode CSS classes               | Use classes (`static classes = []`)      |\n| Forget to clean up in `disconnect` | Always clean up timers, listeners, etc.  |\n| Make controllers too large         | Split into multiple focused controllers  |\n| Use Stimulus for data fetching     | Use Turbo Frames/Streams for server data |\n| Duplicate controller logic         | Extract shared behavior to base class    |\n"},"lastSynced":"2026-03-08T02:13:42.358Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing efficient JavaScript framework integration for Rails applications.","zh":"适合需要高效JavaScript框架集成的Rails应用程序的前端代理。","ja":"Railsアプリケーションに効率的なJavaScriptフレームワーク統合が必要なフロントエンドエージェントに適しています。","ko":"効率적인 JavaScript 프레임워크 통합이 필요한 Rails 애플리케이션을 위한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan una integración eficiente del framework JavaScript para aplicaciones Rails.","fr":"Parfait pour les agents Frontend qui ont besoin d''une intégration efficace du framework JavaScript pour les applications Rails.","de":"Perfekt für Frontend-Agents, die eine effiziente JavaScript-Framework-Integration für Rails-Anwendungen benötigen.","pt":"Perfeito para Agents Frontend que precisam de integração eficiente de framework JavaScript para aplicações Rails.","ru":"Идеально для агентов Frontend, которым нужна эффективная интеграция фреймворка JavaScript для приложений Rails.","ar":"مثالي للوكلاء الأمامية الذين يحتاجون إلى دمج فعال لإطار العمل JavaScript لتطبيقات Rails."},"recommendation":{"en":"Empowers agents to augment HTML with behavior using data attributes, keeping HTML as the source of truth, and leveraging Stimulus version 3.2.2 for efficient interactivity via the DOM.","zh":"赋予代理增强HTML的行为，使用数据属性，并且保持HTML为真实来源，利用Stimulus版本3.2.2实现高效的交互性通过DOM。","ja":"エージェントにHTMLをデータ属性を使用して動作を追加し、HTMLを真実の情報源として保持し、Stimulusバージョン3.2.2を使用してDOMを介した効率的なインタラクティビティを実現することを可能にします。","ko":"에이전트가 데이터 속성을 사용하여 HTML을 동작으로 보강하고 HTML을 진실한 정보 소스로 유지하며 Stimulus 버전 3.2.2를 사용하여 DOM을 통한 효율적인 상호 작용을 제공합니다.","es":"Habilita a los agentes a aumentar HTML con comportamiento utilizando atributos de datos, manteniendo HTML como la fuente de verdad, y aprovechando Stimulus versión 3.2.2 para una interactividad eficiente a través del DOM.","fr":"Permet aux agents d''augmenter HTML avec un comportement en utilisant des attributs de données, en gardant HTML comme source de vérité, et en exploitant Stimulus version 3.2.2 pour une interactivité efficace via le DOM.","de":"Ermächtigt die Agenten, HTML mit Verhalten zu erweitern, indem Datenattribute verwendet werden, wobei HTML als Quelle der Wahrheit beibehalten wird und Stimulus Version 3.2.2 für eine effiziente Interaktivität über den DOM genutzt wird.","pt":"Habilita os agentes a aumentar o HTML com comportamento usando atributos de dados, mantendo o HTML como a fonte de verdade, e aproveitando o Stimulus versão 3.2.2 para interatividade eficiente via DOM.","ru":"Наделяет агентов возможностью расширить HTML поведением с помощью атрибутов данных, сохраняя HTML в качестве источника правды, и использует Stimulus версию 3.2.2 для эффективной инт