INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sandnap/easy_notes/stimulus', 'stimulus', 'sandnap', 'easy_notes', 'community', 'stimulus sandnap easy_notes community Stimulus is a JavaScript framework designed to augment HTML with behavior, keeping HTML as the source of truth. It benefits Rails application developers by providing a modest and efficient way to add interactivity. Stimulus 是一个用于增强 HTML 行为的 JavaScript 框架。它通过数据属性连接 JavaScript 和 DOM，保持 HTML 为事实来源。 Stimulus は、HTML の動作を拡張するための JavaScript フレームワークです。データ属性を使用して JavaScript と DOM を接続し、HTML を事実のソースとして維持します。 Stimulus는 HTML 동작을 확장하기 위한 JavaScript 프레임워크입니다. 데이터 속성을 사용하여 JavaScript와 DOM을 연결하고, HTML을 사실의 원천으로 유지합니다. Stimulus es un framework de JavaScript modesto que agrega comportamiento a tu HTML. Conecta JavaScript al DOM a través de atributos de datos, manteniendo tu HTML como fuente de verdad. Stimulus est un framework JavaScript modeste qui ajoute un comportement à votre HTML. Il connecte JavaScript au DOM via des attributs de données, en gardant votre HTML comme source de vérité. Stimulus ist ein bescheidener JavaScript-Framework, das Verhalten zu Ihrem HTML hinzufügt. Es verbindet JavaScript mit dem DOM über Datenattribute, wobei Ihr HTML die Quelle der Wahrheit bleibt. O Stimulus é um framework JavaScript modesto que adiciona comportamento ao seu HTML. Conheça as melhores práticas para aplicativos Rails Stimulus - это скромный JavaScript-фреймворк, который добавляет поведение к вашему HTML. Узнайте о лучших практиках для приложений Rails - ИИ Агенты Stimulus هو إطار العمل JavaScript المتواضع الذي يضيف سلوكًا إلى HTML الخاص بك. تعرف على أفضل الممارسات لتطبيقات Rails - أدوات الذكاء الاصطناعي how to use stimulus in rails what is stimulus framework stimulus alternative to jQuery stimulus vs react stimulus install guide stimulus setup for rails applications Stimulus 框架 JavaScript 框架 HTML 行为 Rails 应用程序 数据属性 DOM 操作 JavaScript 开发 前端开发 Web 开发 Connects JavaScript to the DOM via data attributes Keeps HTML as the source of truth for application behavior Supports Rails applications with efficient and modest interactivity Follows best practices as outlined in Stimulus version 3.2.2 References the official Stimulus documentation at https://stimulus.hotwired.dev/ Stimulus is a modest JavaScript framework that connects JavaScript to the DOM via data attributes, designed to augment HTML with just enough behavior.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jamtho/xlai/xl', 'community', 'jamtho', 'xlai', 'jamtho/xlai', 'xl', 0, 0, 60, '2026-03-08T01:57:15.644Z', '2026-03-08T02:13:45.322Z', '345858e8c52569c28d89514fbaabf75d70b68d1fb98d98bb912c9391ec02a689', '{"id":"jamtho/xlai/xl","name":"xl","description":{"en":"The xl skill enables interaction with running Excel workbooks, allowing developers to explore spreadsheets, analyze formulas, and modify data through natural conversation.","zh":"xl技能允许您与运行中的Excel工作簿交互，使用xl.exe CLI工具实现电子表格探索和数据修改","ja":"xlスキルは、xl.exe CLIツールを使用して実行中のExcelワークブックと対話し、スプレッドシートの探索とデータの変更を可能にします","ko":"xl 스킬은 xl.exe CLI 툴을 사용하여 실행 중인 Excel 워크북과 상호작용하여 전자 테이블 탐색과 데이터 수정을 가능하게 합니다","es":"El skill xl permite interactuar con libros de Excel abiertos mediante el comando CLI xl.exe, facilitando la exploración y modificación de datos","fr":"Le skill xl permet d''interagir avec les classeurs Excel ouverts à l''aide de la commande CLI xl.exe, facilitant ainsi l''exploration et la modification des données","de":"Der xl-Skill ermöglicht die Interaktion mit geöffneten Excel-Arbeitsmappen über den CLI-Befehl xl.exe, wodurch die Datenexploration und -modifikation erleichtert wird","pt":"O skill xl permite interagir com planilhas do Excel abertas usando o cli xl.exe, permitindo exploração e modificação de dados","ru":"Навык xl позволяет взаимодействовать с открытыми эксель-таблицами с помощью cli xl.exe, что позволяет исследовать и изменять данные","ar":"الوظيفة xl تسمح بالتفاعل مع جداول إكسل المفتوحة باستخدام واجهة سطر الأوامر xl.exe، مما يسمح بالاستكشاف وتعديل البيانات"},"seo":{"title":{"en":"xl: Excel Exploration Skill for AI Agents | Setup Guide","zh":"xl Excel 交互技能设置指南","ja":"xl Excel 接続スキルベストプラクティス","ko":"xl 엑셀 상호작용 스킬 설정 가이드","es":"Guía de configuración de xl para exploración de Excel","fr":"Guide de mise en route de xl pour l''exploration d''Excel","de":"Einrichtungsleitfaden für xl zur Excel-Exploration","pt":"xl: Guia de Configuração para Interação com Planilhas do ...","ru":"xl: Настройка ИИ Агентов для Работы с Эксель","ar":"xl: دليل الإعداد للتفاعل مع جداول إكسل"},"description":{"en":"Discover how to interact with open Excel workbooks using xl.exe CLI tool. Learn to explore spreadsheets, analyze formulas, and modify data through conversation.","zh":"通过xl技能与运行中的Excel工作簿交互，实现电子表格探索、公式分析和数据修改","ja":"xlスキルを使用して実行中のExcelワークブックと対話し、スプレッドシートの探索、式の分析、データの変更を実現","ko":"xl 스킬을 사용하여 실행 중인 Excel 워크북과 상호작용하여 전자 테이블 탐색, 수식 분석 및 데이터 수정을 수행","es":"Descubre cómo interactuar con libros de Excel abiertos mediante la herramienta CLI xl.exe y aprovecha al máximo tus capacidades de análisis y modificación de...","fr":"Découvrez comment interagir avec les classeurs Excel ouverts à l''aide de l''outil CLI xl.exe et tirez le meilleur parti de vos capacités d''analyse et de modif...","de":"Erfahren Sie, wie Sie mit geöffneten Excel-Arbeitsmappen über das CLI-Tool xl.exe interagieren und Ihre Analyse- und Datenänderungsfähigkeiten voll ausschöpfen","pt":"Aprenda a configurar o skill xl para interagir com planilhas do Excel abertas, permitindo exploração, análise de fórmulas e modificação de dados","ru":"Узнайте, как настроить навык xl для взаимодействия с открытыми эксель-таблицами, что позволяет исследовать, анализировать формулы и изменять данные","ar":"تعرف على كيفية ضبط مهارة xl للتفاعل مع جداول إكسل المفتوحة، مما يسمح بالاستكشاف وتحليل الصيغ وتعديل البيانات"},"definition":{"en":"xl is a Claude Code skill for interacting with open Microsoft Excel workbooks using the xl.exe CLI tool.","zh":"xl技能是一种与运行中的Excel工作簿交互的技能，使用xl.exe CLI工具实现电子表格探索和数据修改","ja":"xlスキルは、xl.exe CLIツールを使用して実行中のExcelワークブックと対話するAIエージェントのスキルです","ko":"xl 스킬은 실행 중인 Excel 워크북과 상호작용하여 전자 테이블 탐색과 데이터 수정을 수행하는 AI 툴의 스킬입니다","es":"xl es un skill de código de Claude que permite interactuar con libros de Excel abiertos mediante la herramienta CLI xl.exe","fr":"xl est un skill de code de Claude qui permet d''interagir avec les classeurs Excel ouverts à l''aide de l''outil CLI xl.exe","de":"xl ist ein Code-Skill von Claude, der die Interaktion mit geöffneten Excel-Arbeitsmappen über das CLI-Tool xl.exe ermöglicht","pt":"O que é xl? É um skill que permite interagir com planilhas do Excel abertas","ru":"Что такое xl? Это навык, который позволяет взаимодействовать с открытыми эксель-таблицами","ar":"ما هو xl؟ إنه مهارة يسمح بالتفاعل مع جداول إكسل المفتوحة"},"features":{"en":["Lists available Excel workbooks using the `xl.exe` CLI tool","Returns JSON with open Excel instances and workbooks, including `target_id`","Enables spreadsheet exploration and formula analysis through natural conversation","Supports data modification in Excel workbooks","Uses the `list` command to retrieve available workbooks"],"zh":["使用xl.exe CLI工具与Excel工作簿交互","实现电子表格探索和数据修改","支持JSON格式的工作簿列表","使用target_id标识工作簿"],"ja":["xl.exe CLIツールを使用してExcelワークブックと対話","スプレッドシートの探索とデータの変更を実現","JSON形式のワークブックリストをサポート","target_idを使用してワークブックを識別"],"ko":["xl.exe CLI 툴을 사용하여 Excel 워크북과 상호작용","전자 테이블 탐색과 데이터 수정을 수행","JSON 형식의 워크북 목록을 지원","target_id를 사용하여 워크북을 식별"],"es":["Interacción con libros de Excel abiertos mediante xl.exe","Exploración y análisis de fórmulas en Excel","Modificación de datos en libros de Excel","Uso de la herramienta CLI para interactuar con Excel","Compatibilidad con varias instancias de Excel abiertas"],"fr":["Interaction avec les classeurs Excel ouverts à l''aide de xl.exe","Exploration et analyse de formules dans Excel","Modification de données dans les classeurs Excel","Utilisation de l''outil CLI pour interagir avec Excel","Compatibilité avec plusieurs instances d''Excel ouvertes"],"de":["Interaktion mit geöffneten Excel-Arbeitsmappen über xl.exe","Exploration und Analyse von Formeln in Excel","Modifikation von Daten in Excel-Arbeitsmappen","Verwendung der CLI-Tool zur Interaktion mit Excel","Kompatibilität mit mehreren geöffneten Excel-Instanzen"],"pt":["Interação com planilhas do Excel abertas","Uso do cli xl.exe para exploração e modificação de dados","Listagem de trabalhos do Excel disponíveis","Análise de fórmulas e modificação de dados","Comunicação por meio de conversa natural"],"ru":["Взаимодействие с открытыми эксель-таблицами","Использование cli xl.exe для исследования и изменения данных","Список доступных эксель-работ","Анализ формул и изменение данных","Общение через естественный разговор"],"ar":["التفاعل مع جداول إكسل المفتوحة","استخدام واجهة سطر الأوامر xl.exe للاستكشاف وتعديل البيانات","قائمة أعمال إكسل المتاحة","تحليل الصيغ وتعديل البيانات","التواصل من خلال محادثة طبيعية"]},"keywords":{"en":["how to use xl","xl setup guide","xl alternative","xl vs Excel API","xl install","what is xl","xl.exe CLI tool","Excel exploration skill"],"zh":["xl技能","Excel交互","电子表格探索","数据修改","xl.exe CLI工具","AI工具","Excel自动化"],"ja":["xlスキル","Excel接続","スプレッドシートの探索","データの変更","xl.exe CLIツール","AIエージェント","Excel自動化"],"ko":["xl 스킬","엑셀 상호작용","전자 테이블 탐색","데이터 수정","xl.exe CLI 툴","AI 툴","엑셀 자동화"],"es":["xl skill","herramienta CLI xl.exe","exploración de Excel","análisis de fórmulas","modificación de datos","integración con Excel","desarrollo de habilidades de Claude","AI Agentes para Excel"],"fr":["xl skill","outil CLI xl.exe","exploration d''Excel","analyse de formules","modification de données","intégration avec Excel","développement de compétences de Claude","Agents IA pour Excel"],"de":["xl-Skill","CLI-Tool xl.exe","Excel-Exploration","Formelanalyse","Datenmodifikation","Integration mit Excel","Entwicklung von Claude-Fähigkeiten","KI-Agents für Excel"],"pt":["xl skill","integração com excel","cli xl.exe","planilhas do excel","análise de fórmulas","modificação de dados","conversa natural"],"ru":["ИИ Агенты","скілл xl","интеграция с эксель","cli xl.exe","эксель-таблицы","анализ формул","изменение данных","естественный разговор"],"ar":["أدوات الذكاء الاصطناعي","مهارة xl","التكامل مع إكسل","واجهة سطر الأوامر xl.exe","جداول إكسل","تحليل الصيغ","تعديل البيانات","محادثة طبيعية"]}},"owner":"jamtho","repo":"xlai","repoPath":"jamtho/xlai","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.644Z","topics":[],"category":"community","skillMd":{"name":"xl","description":"Explore and modify Excel workbooks interactively. Use for spreadsheet analysis, formula understanding, refactoring, and data manipulation.","bodyPreview":"# Excel Exploration Skill\n\nYou can interact with open Microsoft Excel workbooks using the `xl.exe` CLI tool. This enables spreadsheet exploration, formula analysis, and data modification through natural conversation.\n\n## Session Workflow\n\n### 1. Start by Listing Workbooks\n\nAlways begin by showing the user what workbooks are available:\n\n```bash\n\"${CLAUDE_PLUGIN_ROOT}/bin/xl.exe\" list\n```\n\nThis returns JSON with all open Excel instances and workbooks. Each workbook has a `target_id` you''ll use for","body":"# Excel Exploration Skill\n\nYou can interact with open Microsoft Excel workbooks using the `xl.exe` CLI tool. This enables spreadsheet exploration, formula analysis, and data modification through natural conversation.\n\n## Session Workflow\n\n### 1. Start by Listing Workbooks\n\nAlways begin by showing the user what workbooks are available:\n\n```bash\n\"${CLAUDE_PLUGIN_ROOT}/bin/xl.exe\" list\n```\n\nThis returns JSON with all open Excel instances and workbooks. Each workbook has a `target_id` you''ll use for subsequent commands.\n\n### 2. Help User Select a Workbook\n\nPresent the workbooks in a readable format. Include:\n- Workbook name and path\n- Whether it has unsaved changes\n- Which one is active (if multiple)\n\nEven if only one workbook is open, show it and confirm with the user before proceeding.\n\n### 3. Explore the Workbook\n\nOnce a target is selected, gather context:\n- List sheets: `xl.exe sheet list --target <id>`\n- List named ranges: `xl.exe name list --target <id>`\n- Read specific ranges as needed\n\n### 4. Respond to User Requests\n\nUse the appropriate commands based on what the user wants to do. For modifications, always use `--mode rw`.\n\n## Command Reference\n\n### Listing and Discovery\n\n**List all open workbooks:**\n```bash\nxl.exe list\n```\n\n**List sheets in a workbook:**\n```bash\nxl.exe sheet list --target <target_id>\n```\n\n**List named ranges:**\n```bash\nxl.exe name list --target <target_id>\n```\n\n**Get named range details:**\n```bash\nxl.exe name get --target <target_id> --name <name>\n```\n\n### Reading Data\n\n**Read a range:**\n```bash\nxl.exe range read --target <target_id> --sheet <sheet_name> --a1 <range>\n```\n\nExample:\n```bash\nxl.exe range read --target \"excel:1234:0x000A1234:wb:0\" --sheet Sheet1 --a1 A1:D10\n```\n\nThe output includes:\n- `values`: 2D array of cell values\n- `formulas`: 2D array of formulas (null for non-formula cells)\n- `types`: Cell types (number, string, boolean, date_serial, error, null)\n\n### Modifying Data (requires --mode rw)\n\n**Write values to a range:**\n```bash\necho ''{\"values\": [[1, 2], [3, 4]]}'' | xl.exe range write --mode rw --target <target_id> --sheet <sheet_name> --a1 <range>\n```\n\n**Write formulas:**\n```bash\necho ''{\"formulas\": [[\"=SUM(A1:A10)\"], [\"=AVERAGE(B1:B10)\"]]}'' | xl.exe range write --mode rw --target <target_id> --sheet <sheet_name> --a1 <range>\n```\n\n**Add a sheet:**\n```bash\nxl.exe sheet add --mode rw --target <target_id> --sheet <new_sheet_name>\n```\n\n**Rename a sheet:**\n```bash\nxl.exe sheet rename --mode rw --target <target_id> --sheet <old_name> --new-name <new_name>\n```\n\n**Delete a sheet:**\n```bash\nxl.exe sheet delete --mode rw --target <target_id> --sheet <sheet_name>\n```\n\n**Add a named range:**\n```bash\nxl.exe name add --mode rw --target <target_id> --name <name> --refers-to \"=Sheet1!\\$A\\$1:\\$C\\$10\"\n```\n\n**Delete a named range:**\n```bash\nxl.exe name delete --mode rw --target <target_id> --name <name>\n```\n\n**Save the workbook:**\n```bash\nxl.exe workbook save --mode rw --target <target_id>\n```\n\n### Calculation Control\n\n**Check calculation mode:**\n```bash\nxl.exe calc status --target <target_id>\n```\n\n**Trigger calculation:**\n```bash\nxl.exe calc run --mode rw --target <target_id>\n```\n\n**Set calculation mode:**\n```bash\nxl.exe calc set --mode rw --target <target_id> --calc-mode manual\n# Options: manual, automatic, automatic_except_tables\n```\n\n## Safety Guidelines\n\n### Read-Only Mode (Default)\n\nBy default, all commands run in `--mode ro` (read-only). This guarantees:\n- No writes to values, formulas, formats, or structure\n- No calculation triggers\n- No refresh of external data connections\n- No opening or closing workbooks\n\n### Read-Write Mode\n\nUse `--mode rw` only when the user explicitly requests a modification. Always:\n1. Confirm the intended change with the user\n2. Report what was modified after the operation\n3. Remind user to save if they want to keep changes\n\n### Error Handling\n\nCommands return JSON with `\"ok\": true` on success or `\"ok\": false` with error details:\n- `NO_EXCEL_INSTANCE`: No Excel processes running\n- `WORKBOOK_NOT_OPEN`: Target workbook no longer open\n- `SHEET_NOT_FOUND`: Sheet name doesn''t exist\n- `RANGE_INVALID`: Invalid A1 reference\n- `MODE_VIOLATION`: Attempted write in read-only mode\n\n## Output Interpretation\n\n### Cell Values\n- Numbers are returned as JSON numbers\n- Strings are returned as JSON strings\n- Booleans are `true`/`false`\n- Empty cells are `null`\n- Dates are Excel serial numbers (days since 1899-12-30)\n\n### Formulas\n- Formulas include the leading `=`\n- Cells without formulas show `null` in the formulas array\n- Named range references in `refers_to` use the format `=Sheet!$A$1:$B$10`\n\n## Example User Prompts\n\nUsers might ask things like:\n\n**Exploration:**\n- \"Show me what workbooks are open\"\n- \"What sheets are in this workbook?\"\n- \"Read the data in A1:D10\"\n- \"What''s in the Summary sheet?\"\n- \"What named ranges are defined?\"\n- \"Show me the formulas in column B\"\n\n**Analysis:**\n- \"Find cells that reference Sheet2\"\n- \"What formula is in cell C5?\"\n- \"Show me all cells with SUM formulas\"\n- \"Are there any circular references?\"\n\n**Modification:**\n- \"Add a new sheet called Results\"\n- \"Rename Sheet1 to RawData\"\n- \"Create a named range called SalesTotal for B2:B100\"\n- \"Write these values to A1:C3\"\n- \"Update the formula in D5 to use the new named range\"\n\n**Refactoring:**\n- \"Replace hardcoded references with named ranges\"\n- \"Consolidate duplicate formulas\"\n- \"Standardize the sheet naming\"\n\nWhen handling these requests, break down complex tasks into steps, show the user what you find, and confirm before making changes.\n\n<!--\nThis Source Code Form is subject to the terms of the Mozilla Public\nLicense, v. 2.0. If a copy of the MPL was not distributed with this\nfile, You can obtain one at https://mozilla.org/MPL/2.0/.\n\nCopyright (c) 2026 James Thompson\n-->\n"},"lastSynced":"2026-03-08T02:13:45.322Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Analysis Agents needing interactive Excel workbook exploration and modification capabilities.","zh":"适合需要交互式 Excel 工作簿探索和修改功能的数据分析代理。","ja":"データ分析エージェントがインタラクティブな Excel ワークブックの探索と変更機能を必要とする場合に適しています。","ko":"데이터 분석 에이전트가 상호 작용 형 Excel 워크북 탐색 및 수정 기능을 필요로 할 때 적합합니다.","es":"Perfecto para Agentes de Análisis de Datos que necesitan capacidades de exploración y modificación de libros de Excel interactivos.","fr":"Parfait pour les agents d''analyse de données nécessitant des capacités d''exploration et de modification de classeurs Excel interactifs.","de":"Perfekt für Data Analysis Agents, die interaktive Excel-Arbeitsmappe-Explorations- und Modifizierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Análise de Dados que precisam de capacidades de exploração e modificação de livros de trabalho do Excel interativos.","ru":"Идеально подходит для агентов анализа данных, которым необходимы интерактивные возможности для изучения и изменения книг Excel.","ar":"مثالي لعميل تحليل البيانات الذي يحتاج إلى إمكانيات استكشاف وتعديل دفتر عمل إكسل تفاعلي."},"recommendation":{"en":"Empowers agents to explore spreadsheets, analyze formulas, and modify data through natural conversation using the `xl.exe` CLI tool and JSON output, enabling seamless integration with Excel workbooks.","zh":"赋予代理探索电子表格、分析公式和通过使用 `xl.exe` CLI 工具和 JSON 输出的自然对话修改数据的能力，从而实现与 Excel 工作簿的无缝集成。","ja":"エージェントがスプレッドシートを探索し、式を分析し、`xl.exe` CLI ツールと JSON 出力を使用した自然な会話でデータを変更する能力を付与し、Excel ワークブックとのシームレスな統合を可能にします。","ko":"에이전트가 스프레드시트를 탐색하고 수식을 분석하고 `xl.exe` CLI 도구 및 JSON 출력을 사용한 자연스러운 대화로 데이터를 수정할 수 있는 기능을 부여하여 Excel 워크북과의无缝한 통합을 가능하게 합니다.","es":"Habilita a los agentes a explorar hojas de cálculo, analizar fórmulas y modificar datos a través de conversaciones naturales utilizando la herramienta de línea de comandos `xl.exe` y la salida JSON, lo que permite una integración perfecta con los libros de Excel.","fr":"Permet aux agents d''explorer les tableurs, d''analyser les formules et de modifier les données à l''aide de conversations naturelles utilisant l''outil de ligne de commande `xl.exe` et la sortie JSON, permettant ainsi une intégration transparente avec les classeurs Excel.","de":"Ermächtigt Agenten, Tabellenkalkulationen zu erkunden, Formeln zu analysieren und Daten mithilfe natürlicher Konversationen unter Verwendung des `xl.exe`-CLI-Tools und der JSON-Ausgabe zu modifizieren, wodurch eine nahtlose Integration mit Excel-Arbeitsmappen ermöglicht wird.","pt":"Habilita os agentes a explorar planilhas, analisar fórmulas e modificar dados por meio de conversação natural usando a ferramenta CLI `xl.exe` e saída JSON, permitindo integração perfeita com livros de trabalho do Excel.","ru":"Наделяет агентов возможностью изучать таблицы, анализировать формулы и изменять данные посредством естественного разговора с использованием инструмента CLI `xl.exe` и вывода JSON, обеспечивая бесшовную интеграцию с книгами Excel.","ar":"يمنح الوكلاء القدرة على استكشاف الجداول وتحليل الصيغ وتعديل البيانات من خلال محادثة طبيعية باستخدام أداة CLI `xl.exe` وخرج JSON، مما يتيح دمجًا متوافقًا مع دفاتر عمل إكسل."},"useCases":{"en":["Exploring open Excel workbooks","Analyzing formulas and modifying data","Listing available workbooks using the `list` command"],"zh":["探索打开的 Excel 工作簿","分析公式和修改数据","使用 `list` 命令列出可用的工作簿"],"ja":["開いている Excel ワークブックを探索する","式を分析しデータを変更する","`list` コマンドを使用して利用可能なワークブックを一覧表示する"],"ko":["열린 Excel 워크북을 탐색합니다","수식을 분석하고 데이터를 수정합니다","`list` 명령을 사용하여 사용 가능한 워크북을 나열합니다"],"es":["Explorar libros de Excel abiertos","Analizar fórmulas y modificar datos","Listar los libros de trabajo disponibles mediante el comando `list`"],"fr":["Explorer les classeurs Excel ouverts","Analyser les formules et modifier les données","Lister les classeurs disponibles à l''aide de la commande `list`"],"de":["Offene Excel-Arbeitsmappen erkunden","Formeln analysieren und Daten modifizieren","Verfügbare Arbeitsmappen mithilfe des `list`-Befehls auflisten"],"pt":["Explorar livros de trabalho do Excel abertos","Analizar fórmulas e modificar dados","Listar livros de trabalho disponíveis usando o comando `list`"],"ru":["Изучать открытые книги Excel","Анализировать формулы и изменять данные","Перечислять доступные книги с помощью команды `list`"],"ar":["استكشاف دفاتر العمل إكسل المفتوحة","تحليل الصيغ و تعديل البيانات","إدراج دفاتر العمل المتاحة باستخدام أمر `list`"]},"limitations":{"en":["Requires Microsoft Excel installation","Needs `xl.exe` CLI tool access","Limited to interacting with open Excel workbooks"],"zh":["需要 Microsoft Excel 安装","需要 `xl.exe` CLI 工具访问","仅限于与打开的 Excel 工作簿交互"],"ja":["Microsoft Excel のインストールが必要","`xl.exe` CLI ツールへのアクセスが必要","開いている Excel ワークブックのみとのやり取りに限定される"],"ko":["Microsoft Excel 설치가 필요합니다","`xl.exe` CLI 도구 액세스가 필요합니다","열린 Excel 워크북과의 상호 작용만으로 제한됩니다"],"es":["Requiere instalación de Microsoft Excel","Necesita acceso a la herramienta de línea de comandos `xl.exe`","Limitado a la interacción con libros de Excel abiertos"],"fr":["Nécessite l''installation de Microsoft Excel","Nécessite l''accès à l''outil de ligne de commande `xl.exe`","Limité à l''interaction avec les classeurs Excel ouverts"],"de":["Benötigt Microsoft Excel-Installation","Benötigt Zugriff auf das `xl.exe`-CLI-Tool","Begrenzt auf die Interaktion mit offenen Excel-Arbeitsmappen"],"pt":["Exige instalação do Microsoft Excel","Necessita de acesso à ferramenta CLI `xl.exe`","Limitado à interação com livros de trabalho do Excel abertos"],"ru":["Требует установки Microsoft Excel","Требует доступа к инструменту CLI `xl.exe`","Ограничен взаимодействием с открытыми книгами Excel"],"ar":["يتطلب تثبيت مايكروسوفت إكسل","يحتاج إلى وصول إلى أداة CLI `xl.exe`","محدود بالتفاعل مع دفاتر العمل إكسل المفتوحة"]},"version":4},"contentHash":"345858e8c52569c28d89514fbaabf75d70b68d1fb98d98bb912c9391ec02a689","qualityScore":60}');
