INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jamtho/xlai/xl', 'xl', 'jamtho', 'xlai', 'community', 'xl jamtho xlai community The xl skill enables interaction with running Excel workbooks, allowing developers to explore spreadsheets, analyze formulas, and modify data through natural conversation. xl技能允许您与运行中的Excel工作簿交互，使用xl.exe CLI工具实现电子表格探索和数据修改 xlスキルは、xl.exe CLIツールを使用して実行中のExcelワークブックと対話し、スプレッドシートの探索とデータの変更を可能にします xl 스킬은 xl.exe CLI 툴을 사용하여 실행 중인 Excel 워크북과 상호작용하여 전자 테이블 탐색과 데이터 수정을 가능하게 합니다 El skill xl permite interactuar con libros de Excel abiertos mediante el comando CLI xl.exe, facilitando la exploración y modificación de datos Le skill xl permet d''interagir avec les classeurs Excel ouverts à l''aide de la commande CLI xl.exe, facilitant ainsi l''exploration et la modification des données Der xl-Skill ermöglicht die Interaktion mit geöffneten Excel-Arbeitsmappen über den CLI-Befehl xl.exe, wodurch die Datenexploration und -modifikation erleichtert wird O skill xl permite interagir com planilhas do Excel abertas usando o cli xl.exe, permitindo exploração e modificação de dados Навык xl позволяет взаимодействовать с открытыми эксель-таблицами с помощью cli xl.exe, что позволяет исследовать и изменять данные الوظيفة xl تسمح بالتفاعل مع جداول إكسل المفتوحة باستخدام واجهة سطر الأوامر xl.exe، مما يسمح بالاستكشاف وتعديل البيانات how to use xl xl setup guide xl alternative xl vs Excel API xl install what is xl xl.exe CLI tool Excel exploration skill xl技能 Excel交互 电子表格探索 数据修改 xl.exe CLI工具 AI工具 Excel自动化 Lists available Excel workbooks using the `xl.exe` CLI tool Returns JSON with open Excel instances and workbooks, including `target_id` Enables spreadsheet exploration and formula analysis through natural conversation Supports data modification in Excel workbooks Uses the `list` command to retrieve available workbooks xl is a Claude Code skill for interacting with open Microsoft Excel workbooks using the xl.exe CLI tool.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OutlineDriven/odin-codex-plugin/agno', 'community', 'OutlineDriven', 'odin-codex-plugin', 'OutlineDriven/odin-codex-plugin', 'agno', 0, 0, 60, '2026-03-08T01:57:15.650Z', '2026-03-08T02:13:52.540Z', '30dffd9b81998d70c9659f772dab968f0fe94e3bd95c44f72a04d60451322fed', '{"id":"OutlineDriven/odin-codex-plugin/agno","name":"agno","description":{"en":"Agno is a comprehensive AI agent framework for building production-ready multi-agent systems. It assists developers in creating AI agents with tools, memory, and structured outputs.","zh":"Agno是一种现代AIエージェント框架，用于构建生产就绪的多智能体系统，支持MCP集成、工作流编排和AgentOS运行时","ja":"Agnoは、AIエージェントの開発をサポートするモダンなフレームワークで、MCP統合、ワークフロー管理、AgentOSランタイムを備えています","ko":"Agno는 생산 준비가 된 다중 에이전트 시스템을 구축하기 위한 현대적인 AI 에이전트 프레임워크로, MCP 통합, 워크플로우 오케스트레이션 및 AgentOS 런타임을 지원합니다","es":"Agno es un marco de trabajo para desarrollar agentes de inteligencia artificial con herramientas, memoria y salidas estructuradas. Permite la creación de equipos multi-agente con delegación y colaboración basadas en roles","fr":"Agno est un cadre de travail pour développer des agents d''intelligence artificielle avec des outils, une mémoire et des sorties structurées. Il permet la création d''équipes multi-agents avec délégation et collaboration basées sur les rôles","de":"Agno ist ein Rahmenwerk für die Entwicklung von KI-Agents mit Tools, Speicher und strukturierten Ausgaben. Es ermöglicht die Erstellung von Multi-Agenten-Teams mit rollenbasierten Delegation und Zusammenarbeit","pt":"O Agno é um framework de agentes de inteligência artificial para desenvolver sistemas multi-agente com MCP e AgentOS. Aprenda a criar agentes e implementar fluxos de trabalho","ru":"Agno - это фреймворк ИИ агентов для разработки многоагентных систем с MCP и AgentOS. Узнайте, как создавать агентов и реализовывать рабочие процессы","ar":"Agno هو إطار 