INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OutlineDriven/odin-codex-plugin/agno', 'agno', 'OutlineDriven', 'odin-codex-plugin', 'community', 'agno OutlineDriven odin-codex-plugin community Agno is a comprehensive AI agent framework for building production-ready multi-agent systems. It assists developers in creating AI agents with tools, memory, and structured outputs. Agno是一种现代AIエージェント框架，用于构建生产就绪的多智能体系统，支持MCP集成、工作流编排和AgentOS运行时 Agnoは、AIエージェントの開発をサポートするモダンなフレームワークで、MCP統合、ワークフロー管理、AgentOSランタイムを備えています Agno는 생산 준비가 된 다중 에이전트 시스템을 구축하기 위한 현대적인 AI 에이전트 프레임워크로, MCP 통합, 워크플로우 오케스트레이션 및 AgentOS 런타임을 지원합니다 Agno es un marco de trabajo para desarrollar agentes de inteligencia artificial con herramientas, memoria y salidas estructuradas. Permite la creación de equipos multi-agente con delegación y colaboración basadas en roles Agno est un cadre de travail pour développer des agents d''intelligence artificielle avec des outils, une mémoire et des sorties structurées. Il permet la création d''équipes multi-agents avec délégation et collaboration basées sur les rôles Agno ist ein Rahmenwerk für die Entwicklung von KI-Agents mit Tools, Speicher und strukturierten Ausgaben. Es ermöglicht die Erstellung von Multi-Agenten-Teams mit rollenbasierten Delegation und Zusammenarbeit O Agno é um framework de agentes de inteligência artificial para desenvolver sistemas multi-agente com MCP e AgentOS. Aprenda a criar agentes e implementar fluxos de trabalho Agno - это фреймворк ИИ агентов для разработки многоагентных систем с MCP и AgentOS. Узнайте, как создавать агентов и реализовывать рабочие процессы Agno هو إطار عمل لوكلاء الذكاء الاصطناعي لتطوير أنظمة متعددة الوكلاء مع MCP و AgentOS. تعرف على كيفية إنشاء الوكلاء وتنفيذ سير العمل how to use agno what is agno agno alternative agno vs codex agno install agno setup guide agno for AI agents agno multi-agent systems agno workflow orchestration Agno AIエージェント Outline Driven开发 MCP集成 工作流编排 AgentOS运行时 多智能体系统 AI开发框架 Supports building AI agents with tools, memory, and structured outputs Enables creation of multi-agent teams with role-based delegation and collaboration Implements workflows with conditional branching, loops, and async execution Integrates with MCP for seamless workflow orchestration Utilizes AgentOS runtime for efficient agent execution Facilitates building production-ready multi-agent systems Agno is a modern AI agent framework for building production-ready multi-agent systems with MCP integration, workflow orchestration, and AgentOS runtime.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dreamiurg/shipmate/eod', 'community', 'dreamiurg', 'shipmate', 'dreamiurg/shipmate', 'eod', 0, 0, 60, '2026-03-08T01:57:15.650Z', '2026-03-08T02:13:52.783Z', '0a00862cfd8b7efabac44ba4b65421483a822d599845b92d7a301aa062cb60c8', '{"id":"dreamiurg/shipmate/eod","name":"eod","description":{"en":"The eod skill generates a daily summary of your GitHub activity using the github-analyzer-agent and summarizer-agent. It''s perfect for developers who want to share their progress with teammates.","zh":"eod 技术通过 GitHub 分析器和总结器生成每日开发摘要，支持自然语言查询","ja":"eod 技術は、GitHub 分析器と総結器を使用して毎日の開発サマリーを生成し、自然言語クエリをサポート","ko":"eod 기술은 깃허브 분석 및 요약 기능을 사용하여 일일 개발 요약을 생성하며 자연어 질의를 지원합니다.","es":"eod es un agente de desarrollo que resume tu actividad diaria en GitHub, utilizando agentes especializados como github-analyzer-agent y summarizer-agent","fr":"eod est un agent de développement qui résume votre activité quotidienne sur GitHub, en utilisant des agents spécialisés tels que github-analyzer-agent et summarizer-agent","de":"eod ist ein Entwicklungsagent, der Ihre tägliche Aktivität in GitHub zusammenfasst, indem er spezialisierte Agenten wie github-analyzer-agent und summarizer-agent nutzt","pt":"O eod é um skill que gera resumos diários das suas atividades no GitHub, utilizando os agentes github-analyzer-agent e summarizer-agent","ru":"eod - это навык, который генерирует ежедневные отчеты о деятельности на GitHub, используя агенты github-analyzer-agent и summarizer-agent с ИИ Агентами","ar":"eod هو مهارة تولد تلخيص يومي لأنشطتك على GitHub باستخدام وكلاء github-analyzer-agent و summarizer-agent"},"seo":{"title":{"en":"eod: End-of-Day Summary Setup Guide | AI Agent Skill","zh":"eod 技术指南：使用 GitHub 分析器和总结器","ja":"eod セットアップガイド：GitHub 活動データの分析と要約","ko":"eod 개발자 가이드: 깃허브 분석 및 요약 기능","es":"Guía de configuración de eod: Resumen diario de actividad...","fr":"Paramétrer eod : Guide pour un résumé quotidien d''activit...","de":"eod-Setup-Leitfaden: Tägliche Zusammenfassung von GitHub-...","pt":"Guia de Configuração do eod: Resumo Diário de Atividades ...","ru":"Настройка eod: Ежедневный Отчет о Деятельности на GitHub ...","ar":"دليل إعداد eod: تلخيص يومي لأنشطة GitHub"},"description":{"en":"Discover how to track your GitHub activity with eod. Get a concise summary and share it with teammates. Learn how to invoke the eod skill today!","zh":"了解 eod 技术细节，使用 GitHub 分析器和总结器生成每日开发摘要","ja":"eod の機能を詳しく知る、GitHub 活動データの分析と要約を使用して毎日の開発サマリーを生成","ko":"eod의 기능을 자세히 알아보세요. 깃허브 분석 및 요약 기능을 사용하여 일일 개발 요약을 생성합니다.","es":"Aprende a utilizar eod para obtener un resumen diario de tu actividad en GitHub y mejora tu productividad como desarrollador","fr":"Découvrez comment utiliser eod pour obtenir un résumé quotidien de votre activité GitHub et améliorer votre productivité en tant que développeur","de":"Erfahren Sie, wie Sie eod nutzen können, um täglich Ihre GitHub-Aktivitäten zusammenzufassen und Ihre Produktivität als Entwickler zu steigern","pt":"Aprenda a configurar o eod para obter resumos diários das suas atividades no GitHub e melhore a produtividade da sua equipe","ru":"Узнайте, как настроить eod для получения ежедневных отчетов о деятельности на GitHub и повысьте производительность команды с ИИ Агентами","ar":"تعرف على كيفية تعيين eod للحصول على تلخيص يومي لأنشطتك على GitHub وتحسين إنتاجية فريقك"},"definition":{"en":"eod is a specialized AI agent skill that orchestrates GitHub activity data extraction and summary generation for developers.","zh":"eod 是一种使用 GitHub 分析器和总结器生成每日开发摘要的技术","ja":"eod は、GitHub 分析器と総結器を使用して毎日の開発サマリーを生成する技術","ko":"eod는 깃허브 분석 및 요약 기능을 사용하여 일일 개발 요약을 생성하는 기술입니다.","es":"eod es un agente de desarrollo que proporciona un resumen diario de la actividad en GitHub","fr":"eod est un agent de développement qui fournit un résumé quotidien de l''activité sur GitHub","de":"eod ist ein Entwicklungsagent, der eine tägliche Zusammenfassung der Aktivität in GitHub bietet","pt":"O eod é um skill que fornece resumos diários das atividades no GitHub","ru":"eod - это навык, который предоставляет ежедневные отчеты о деятельности на GitHub","ar":"eod هو مهارة توفر تلخيص يومي لأنشطة GitHub"},"features":{"en":["Extracts GitHub activity data using the github-analyzer-agent","Generates a beautiful summary using the summarizer-agent","Supports natural language invocation with ''Generate my end-of-day summary''","Produces conversational and scannable updates for team sharing"],"zh":["使用 GitHub 分析器提取 GitHub 活动数据","使用总结器生成每日开发摘要","支持自然语言查询","生成可共享的开发摘要","集成 GitHub 分析器和总结器"],"ja":["GitHub 分析器を使用して GitHub 活動データを抽出","総結器を使用して毎日の開発サマリーを生成","自然言語クエリをサポート","共有可能な開発サマリーを生成","GitHub 分析器と総結器を統合"],"ko":["깃허브 분석기를 사용하여 깃허브 활동 데이터 추출","요약기를 사용하여 일일 개발 요약 생성","자연어 질의 지원","공유 가능한 개발 요약 생성","깃허브 분석기 및 요약기 통합"],"es":["Extracción de datos de actividad de GitHub mediante github-analyzer-agent","Generación de un resumen diario utilizando summarizer-agent","Compatibilidad con comandos naturales para generar resúmenes","Invocación directa mediante comandos de CLI","Integración con herramientas de desarrollo como GitHub"],"fr":["Extraction des données d''activité GitHub à l''aide de github-analyzer-agent","Génération d''un résumé quotidien en utilisant summarizer-agent","Prise en charge de commandes naturelles pour générer des résumés","Invocation directe via des commandes CLI","Intégration avec des outils de développement tels que GitHub"],"de":["Extraktion von GitHub-Aktivitätsdaten mithilfe von github-analyzer-agent","Erstellung eines täglichen Zusammenfassung mithilfe von summarizer-agent","Unterstützung für natürliche Befehle zum Erstellen von Zusammenfassungen","Direkte Aufruf über CLI-Befehle","Integration mit Entwicklungstools wie GitHub"],"pt":["Extração de dados de atividades do GitHub usando o agente github-analyzer-agent","Geração de resumos bonitos usando o agente summarizer-agent","Suporte à geração de relatórios diários","Integração com o GitHub","Utilização de tecnologias de análise de dados","Geração de resumos conversacionais e legíveis"],"ru":["Извлечение данных о деятельности на GitHub с помощью агента github-analyzer-agent","Генерация красивых отчетов с помощью агента summarizer-agent","Поддержка генерации ежедневных отчетов","Интеграция с GitHub","Использование технологий анализа данных","Генерация отчетов в форме разговора и легко читаемых"],"ar":["استخراج بيانات أنشطة GitHub باستخدام وكلاء github-analyzer-agent","توليد تلخيصات جميلة باستخدام وكلاء summarizer-agent","دعم توليد تقارير يومية","التكامل مع GitHub","استخدام تقنيات تحليل البيانات","توليد تلخيصات محادثية وقابلة للقراءة"]},"keywords":{"en":["how to use eod","eod setup guide","github activity tracking","eod vs github dashboard","eod install","end-of-day summary tools","github analyzer agent","summarizer agent"],"zh":["eod 技术","GitHub 分析器","总结器","每日开发摘要","自然语言查询","开发工具","AI エージェント","开发效率"],"ja":["eod 技術","GitHub 分析器","総結器","毎日の開発サマリー","自然言語クエリ","開発ツール","AIエージェント","開発効率"],"ko":["eod 기술","깃허브 분석기","요약기","일일 개발 요약","자연어 질의","개발 도구","AI 에이전트","개발 효율"],"es":["eod agente de desarrollo","resumen diario de actividad en GitHub","github-analyzer-agent","summarizer-agent","desarrollo de software","productividad para desarrolladores","herramientas de desarrollo","agente AI para desarrollo"],"fr":["eod agent de développement","résumé quotidien d''activité sur GitHub","github-analyzer-agent","summarizer-agent","développement de logiciels","productivité pour les développeurs","outils de développement","agent IA pour le développement"],"de":["eod Entwicklungsagent","tägliche Zusammenfassung von GitHub-Aktivitäten","github-analyzer-agent","summarizer-agent","Software-Entwicklung","Produktivität für Entwickler","Entwicklungstools","KI-Agent für die Entwicklung"],"pt":["eod","resumo diário","atividades github","github analyzer agent","summarizer agent","relatórios diários","integração github","análise de dados","desenvolvimento de software"],"ru":["eod","ежедневный отчет","деятельность на github","github analyzer agent","summarizer agent","ежедневные отчеты","интеграция с github","анализ данных","разработка программного обеспечения","ИИ Агенты"],"ar":["eod","تلخيص يومي","أنشطة github","وكلاء github analyzer","وكلاء summarizer","تقارير يومية","تكامل github","تحليل البيانات","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"dreamiurg","repo":"shipmate","repoPath":"dreamiurg/shipmate","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.650Z","topics":[],"category":"community","skillMd":{"name":"eod","description":"Generate a concise end-of-day summary from GitHub activity in the last 24 hours - commits, issues, and PRs","bodyPreview":"# End-of-Day Summary\n\nThis skill orchestrates two specialized agents to generate a concise summary of your GitHub activity for the current day.\n\n## What This Skill Does\n\n1. **Extracts GitHub activity data** using the `github-analyzer-agent` agent\n2. **Generates a beautiful summary** using the `summarizer-agent` agent\n\nThe result is a conversational, scannable update perfect for sharing with teammates.\n\n## Usage\n\nAsk Claude naturally: \"Generate my end-of-day summary\"\n\nOr invoke directly with the","body":"# End-of-Day Summary\n\nThis skill orchestrates two specialized agents to generate a concise summary of your GitHub activity for the current day.\n\n## What This Skill Does\n\n1. **Extracts GitHub activity data** using the `github-analyzer-agent` agent\n2. **Generates a beautiful summary** using the `summarizer-agent` agent\n\nThe result is a conversational, scannable update perfect for sharing with teammates.\n\n## Usage\n\nAsk Claude naturally: \"Generate my end-of-day summary\"\n\nOr invoke directly with the Skill tool: `shipmate:eod`\n\n## Configuration\n\nThis skill can be configured via `shipmate.yaml` in either:\n\n- `~/.claude/shipmate.yaml` (global)\n- `<project>/.claude/shipmate.yaml` (project-specific, overrides global)\n\nSee `config.example.yaml` for configuration options.\n\n## MANDATORY FIRST STEP: Create Todo List\n\n**BEFORE DOING ANYTHING ELSE**, you MUST use the TodoWrite tool to create a task list with these EXACT step names:\n\n1. \"Detect GitHub organizations and username\"\n2. \"Ask user to select activity scope\"\n3. \"Extract GitHub activity data\"\n4. \"Extract Claude Code sessions (if enabled)\"\n5. \"Analyze activity and identify themes\"\n6. \"Ask user to select main topics\"\n7. \"Generate conversational summary\"\n8. \"Present summary to user\"\n9. \"Post to enabled integrations (if configured)\"\n\nMark the first todo as `in_progress` immediately after creating the list.\n\n**Why:** This provides visibility to the user and ensures consistent progress tracking across all skill runs.\n\n## Process\n\n### Step 1: Detect GitHub Organizations (MANDATORY - DO NOT SKIP)\n\n**CRITICAL:** You MUST complete this step before proceeding. Do NOT jump to Step 3.\n\nRun these commands to detect organizations and get the username:\n\n```bash\ngh api user/orgs --jq ''.[].login''\n```\n\n```bash\ngh api user --jq ''.login''\n```\n\nStore both the list of organizations and the username.\n\n### Step 2: Ask User for Scope (MANDATORY - DO NOT SKIP)\n\n**CRITICAL:** You MUST ask the user which scope they want. Do NOT assume or skip this step.\n\nUse the AskUserQuestion tool with this EXACT question:\n\n**Question:** \"Which GitHub activity would you like to include in your end-of-day summary?\"\n\n**Options** (create one option for each scenario):\n\n- **Personal account only** ({username}) - \"Only activity from your personal GitHub account\"\n- **Organization: {org_name}** - \"Only activity from the {org_name} organization\" (one option per org discovered)\n- **All accounts** - \"Activity from your personal account and all organizations\"\n\n**IMPORTANT:**\n\n- If the user belongs to multiple organizations, include one option for EACH organization\n- Always include the \"Personal account only\" option\n- Always include the \"All accounts\" option\n- Do NOT proceed to Step 3 until the user has made a selection\n\nStore the user''s selection for use in Step 3.\n\n### Step 2.5: Read Configuration and Detect Script Paths\n\n**A. Read configuration from `shipmate.yaml`:**\n\nCheck for configuration in these locations (project-specific overrides global):\n\n- `<project>/.claude/shipmate.yaml`\n- `~/.claude/shipmate.yaml`\n\nExtract these values from the `claude_sessions` section:\n\n- `enabled` (default: true)\n- `time_window_hours` (default: 24)\n- `correlation_window_hours` (default: 2)\n- `min_duration_minutes` (default: 2)\n\nExtract these values from the `integrations` section:\n\n- `notion.enabled` (default: false)\n- `notion.daily_log_url` (required if notion.enabled is true)\n\nSet `HAS_INTEGRATIONS` flag:\n\n- `true` if any integration is enabled (e.g., `notion.enabled` is true)\n- `false` if no integrations are enabled\n\n**B. Detect script paths for agents:**\n\nRun these commands separately to find the shipmate plugin directory and set script paths:\n\n```bash\nfind ~/.claude/plugins -name \"shipmate\" -type d 2>/dev/null | head -1\n```\n\nIf the command returns a path (plugin is installed):\n\n- Set `GITHUB_SCRIPT` to `{plugin_dir}/scripts/fetch-github-activity.sh`\n- Set `CLAUDE_SCRIPT` to `{plugin_dir}/scripts/parse-claude-sessions.js`\n\nIf the command returns nothing (running locally):\n\n- Set `GITHUB_SCRIPT` to `./scripts/fetch-github-activity.sh`\n- Set `CLAUDE_SCRIPT` to `./scripts/parse-claude-sessions.js`\n\nStore these paths and flags for use in later steps.\n\n### Step 3: Invoke Data Extraction Agents in Parallel\n\n**Mark todo #2 as completed, todos #3 and #4 as in_progress.**\n\n**IMPORTANT: Run both agents in PARALLEL using a single message with TWO Task tool calls.**\n\n**Agent 1 - GitHub Analyzer:**\n\nUse the Task tool to invoke the `shipmate:github-analyzer-agent` agent (subagent_type=\"shipmate:github-analyzer-agent\"):\n\n```text\nPlease extract GitHub activity data for the last 24 hours with the following scope: [user''s selection from Step 2]\n\nUse the bundled script at this path: {GITHUB_SCRIPT from Step 2.5}\n\nRun it as:\n{GITHUB_SCRIPT} [scope] {username} [{org_name}]\n\nWhere:\n- scope: \"personal\", \"org\", or \"all\" based on user selection\n- username: {username from Step 1}\n- org_name: {org_name from Step 1} (only if scope is \"org\")\n\nThe script returns consolidated JSON with commits, issues, and PRs.\n```\n\n**Agent 2 - Claude Analyzer (Conditional):**\n\n**Check if Claude sessions integration is enabled** from the configuration read in Step 2.5.\n\n**If `claude_sessions.enabled` is true:**\n\nUse the Task tool to invoke the `shipmate:claude-analyzer-agent` agent (subagent_type=\"shipmate:claude-analyzer-agent\", model=\"haiku\") **IN THE SAME MESSAGE as Agent 1**:\n\n```text\nExtract Claude Code sessions from the last {time_window_hours} hours with minimum duration {min_duration_minutes} minutes.\n\nUse the bundled script at this path: {CLAUDE_SCRIPT from Step 2.5}\n\nRun it as:\nnode {CLAUDE_SCRIPT} {time_window_hours} {min_duration_minutes}\n\nThe script returns JSON with session metadata including:\n- session_id, project_path\n- start_time, end_time, duration_minutes\n- message_count, summary\n- tool_usage (file_edits, bash_commands, reads)\n- metadata (time_window_hours, min_duration_minutes, total_sessions)\n```\n\n**If `claude_sessions.enabled` is false:**\n\nSkip the Claude analyzer agent. Set `CLAUDE_SESSIONS` to empty result:\n\n```json\n{\n  \"sessions\": [],\n  \"metadata\": {\n    \"time_window_hours\": 24,\n    \"min_duration_minutes\": 2,\n    \"total_sessions\": 0\n  }\n}\n```\n\n**IMPORTANT:**\n\n- Launch both agents in parallel (single message with 2 Task calls) when sessions are enabled\n- Use Haiku model for Claude analyzer (fast, cheap execution)\n- Both agents run independently and return results simultaneously\n- Store GitHub data in `GITHUB_ACTIVITIES` variable\n- Store Claude data in `CLAUDE_SESSIONS` variable\n\nOnce both agents return data (or Claude sessions disabled), mark todos #3 and #4 as completed.\n\n### Step 4: Analyze Activity and Identify Key Themes\n\n**Mark todo #5 as in_progress.**\n\nReview the data from Step 3 and identify distinct themes/topics based on:\n\n- Issue bodies and titles (what questions were being answered?)\n- Commit messages and patterns\n- Repositories affected\n- Type of work (investigation, feature, bugfix, tooling, etc.)\n\nFor each theme, create a clear, descriptive label like:\n\n- \"Investigated AWS infrastructure\"\n- \"Investigated Railway deployments\"\n- \"Investigated Auth0 setup\"\n- \"Set up secret detection\"\n- \"Added markdown linting\"\n- \"Documentation improvements\"\n\n**IMPORTANT**: Identify ALL distinct themes, not just major ones. Include both substantial investigations and smaller tasks.\n\n### Step 4.5: Correlate Claude Sessions with GitHub Activity (Conditional)\n\n**Before marking todo #5 as completed**, check if correlation is needed.\n\n**If `CLAUDE_SESSIONS.metadata.total_sessions` is 0:**\n\n- Skip correlation entirely (no sessions to correlate)\n- Set `ENRICHED_ACTIVITIES` to `GITHUB_ACTIVITIES` (pass through unchanged)\n- Set `ORPHANED_SESSIONS` to empty array\n- Mark todo #5 as completed and proceed to Step 5\n\n**If `CLAUDE_SESSIONS.metadata.total_sessions` > 0:**\n\nUse the Task tool to invoke the `shipmate:correlation-agent` agent (subagent_type=\"shipmate:correlation-agent\", model=\"haiku\"):\n\n```text\nCorrelate Claude Code sessions with GitHub activities using time proximity and path matching.\n\nInput:\n- GitHub Activities: {JSON from Step 3}\n- Claude Sessions: {JSON from Step 3}\n- Correlation Window: {correlation_window_hours from config}\n\nMatch sessions to activities by:\n1. Path matching (normalized repo names)\n2. Time proximity (±{correlation_window_hours} hours)\n\nReturn enriched activities with related_sessions and identify orphaned sessions (investigation work without commits).\n```\n\n**IMPORTANT:**\n\n- Use Haiku model for fast, cheap correlation\n- The agent will return enriched activities with `related_sessions` arrays\n- Orphaned sessions represent investigation/exploration work\n- Store the agent''s output in `ENRICHED_ACTIVITIES` and `ORPHANED_SESSIONS` for use in Step 6\n\nOnce the agent returns data (or correlation was skipped), mark todo #5 as completed.\n\n### Step 5: Ask User to Select Main Topics\n\n**Mark todo #6 as in_progress.**\n\nUse the AskUserQuestion tool with multiSelect enabled:\n\n**Question:** \"Which topics should be highlighted as main accomplishments? (Select 2-4. Everything else will be grouped as ''Housekeeping'')\"\n\n**Options**: Create one option for each theme identified in Step 4, ordered by estimated importance/time spent (most significant first)\n\nExample:\n\n```text\n- \"Investigated AWS infrastructure\" - \"Documented IAM setup, S3 buckets, VPC config, and admin access\"\n- \"Investigated Railway deployments\" - \"Found two projects, identified active vs inactive deployments\"\n- \"Set up secret detection\" - \"Added pre-commit hooks with gitleaks to prevent credential leaks\"\n- \"Added markdown linting\" - \"Configured markdownlint-cli2 with auto-fix\"\n```\n\nStore the user''s selections (2-4 topics).\n\nOnce the user has made their selections, mark todo #6 as completed.\n\n### Step 6: Invoke Activity Summarizer Agent\n\n**Mark todo #7 as in_progress.**\n\nUse the Task tool to invoke the `shipmate:summarizer-agent` agent (subagent_type=\"shipmate:summarizer-agent\"):\n\n```text\nPlease create a team standup summary from this GitHub activity data:\n\n[Paste the enriched GitHub activities from Step 4.5, including any related_sessions]\n\nOrphaned Claude sessions (investigation work without commits):\n[Paste orphaned sessions from Step 4.5, if any]\n\nThe user has selected these topics to highlight as main accomplishments:\n[List the topics selected in Step 5]\n\nGenerate a conversational summary following the format with:\n- Selected topics as separate bullets with detailed findings and insights\n- All other activities grouped as \"Housekeeping\"\n- Plain URLs to documentation artifacts\n- Past tense, casual tone\n- Weave in session insights naturally where related_sessions exist (see agent instructions for guidance)\n```\n\n**IMPORTANT**:\n\n- Pass the enriched GitHub activities with related_sessions (from Step 4.5)\n- Pass orphaned sessions separately\n- Include correlation window hours in context\n- Clearly indicate which topics the user selected to highlight\n- Everything NOT selected should be grouped into \"Housekeeping\"\n- The agent will return the formatted summary\n\nOnce the agent returns the summary, mark todo #7 as completed.\n\n### Step 7: Present Summary to User\n\n**Mark todo #8 as in_progress.**\n\nDisplay the summary returned by the summarizer agent.\n\n**Optional Polish**: If the `elements-of-style:writing-clearly-and-concisely` skill is available, you may optionally use it to polish the summary further, but the summarizer agent already applies these principles.\n\nOnce the summary is displayed, mark todo #8 as completed.\n\n### Step 8: Post to Enabled Integrations (if configured)\n\n**Mark todo #9 as in_progress.**\n\nCheck the `HAS_INTEGRATIONS` flag set in Step 2.5.\n\n**If `HAS_INTEGRATIONS` is false:**\n\n- Skip integration posting entirely\n- Mark todo #9 as completed\n- You''re done!\n\n**If `HAS_INTEGRATIONS` is true:**\n\nProceed to Step 9 to post to enabled integrations.\n\n### Step 9: Post to Notion Daily Log (if enabled)\n\nIf Notion integration is enabled in config:\n\n1. Get today''s date in \"Month Day, Year\" format (e.g., \"November 4, 2025\")\n2. Fetch the Daily Log page URL from config: `integrations.notion.daily_log_url`\n3. Format the summary using the user''s preferred bullet format:\n\n```markdown\n## {Date}\n\n### What I accomplished today\n\n- **{Topic 1}** - {Description from summary}\n - [{Link text}]({{URL}})\n- **{Topic 2}** - {Description from summary}\n - [{Link text}]({{URL}})\n- **{Topic 3}** - {Description from summary}\n - [{Link text}]({{URL}})\n- **Housekeeping** - {Description from summary}\n```\n\n**IMPORTANT Formatting Rules**:\n\n- Each main accomplishment is a top-level bullet with bold topic name\n- Key artifacts (1-3 per topic) are nested bullets (indented with tab) under each accomplishment\n- Include the most relevant links: documentation files, PRs, and issues that capture the work\n- Use plain markdown links like `[Auth0 Documentation]({{URL}})` or `[PR #123]({{URL}})`\n- Extract actual GitHub URLs from the summary text and raw activity data\n- Prioritize comprehensive documentation links over minor commits\n- The Housekeeping item does NOT have nested links unless there are specific artifacts to link\n\n1. If the page already has content, prepend the new entry at the top (most recent first)\n2. If the page is blank, just add the new entry\n3. Use the `mcp__notion__notion-update-page` tool with appropriate command (`replace_content` or `insert_content_after`)\n\nOnce posted to Notion (or if Notion is not enabled), mark todo #8 as completed.\n\n**Example of final Notion format**:\n\n```markdown\n## November 4, 2025\n\n### What I accomplished today\n\n- **Investigated Auth0 setup** - Dug through the whole Auth0 configuration to see what we''re actually using. Found we have one production tenant with three main applications. Turns out we''re using Google and Microsoft for social logins, have MFA set up but not enforced, and have a bunch of roles configured. Documented all the apps, APIs, connections, rules, hooks, and who has admin access.\n - [Auth0 Documentation]({{https://github.com/example-org/docs/blob/main/infrastructure/auth0.md}})\n - [Issue #7: Auth0 Configuration Inventory]({{https://github.com/example-org/docs/issues/7}})\n- **Investigated AWS infrastructure** - Went through the AWS account to figure out what we have. Found IAM users and roles, data in S3 buckets, VPC configuration, and mapped out who has admin access. Got it all documented so we can plan the migration.\n - [AWS Documentation]({{https://github.com/example-org/docs/blob/main/infrastructure/aws.md}})\n- **Investigated deployment process** - Figured out how we actually ship code to production. Frontend deploys manually, backend auto-deploys from GitHub.\n - [Deployment Process Documentation]({{https://github.com/example-org/docs/blob/main/infrastructure/deployment-process.md}})\n - [Issue #5]({{https://github.com/example-org/docs/issues/5}})\n- **Housekeeping** - Set up pre-commit hooks with gitleaks to prevent secrets from leaking into the repo, added markdownlint for documentation quality.\n```\n\n## Agent Roles\n\n### github-analyzer-agent\n\n- **Specialty**: GitHub CLI (`gh`) expertise\n- **Tools**: Bash\n- **Model**: Haiku (fast, cost-effective for data extraction)\n- **Output**: Structured JSON data about commits, issues, PRs\n\n### summarizer-agent\n\n- **Specialty**: Writing conversational, scannable summaries\n- **Tools**: None (pure analysis and writing)\n- **Model**: Sonnet (better at nuanced writing)\n- **Output**: Formatted markdown summary ready to share\n\n## Why Two Agents?\n\n**Separation of Concerns**:\n\n- **Analyzer** focuses on technical data gathering (parallel queries, timezone handling, error handling)\n- **Summarizer** focuses on human communication (tone, grouping, insights)\n\n**Optimized Models**:\n\n- Use fast/cheap Haiku for repetitive data extraction\n- Use smart Sonnet for nuanced writing and analysis\n\n**Maintainability**:\n\n- Each agent has a single, clear responsibility\n- Can improve or swap agents independently\n- Easier to test and debug\n\n## Important Notes\n\n- **Performance**: The analyzer agent runs all GitHub queries in parallel (~2-3 seconds total)\n- **Time Range**: Last 24 hours from current time (not calendar day)\n- **Scope**: Supports personal, organization-specific, or all-account views\n- **Artifacts**: Includes links to documentation produced\n- **Tone**: Conversational and scannable, optimized for team standups\n\n## Error Handling\n\nIf the github-analyzer-agent fails:\n\n- Check `gh auth status`\n- Verify `gh` CLI is installed (requires 2.23.0+)\n- Verify organization membership for org-scoped queries\n\nIf the summarizer-agent produces unexpected format:\n\n- Ensure you passed complete raw data from analyzer\n- Verify the analyzer included issue bodies for closed issues\n\n## Customization\n\nTo customize:\n\n- Edit `agents/github-analyzer-agent.md` for different data sources\n- Edit `agents/summarizer-agent.md` for different summary formats\n- Modify this skill to change orchestration logic\n- Add new integrations in `integrations/` directory\n\n## Example Flow\n\n```text\nUser: /shipmate:eod\n\nSkill: [Detects orgs: example-org]\nSkill: [Asks user: \"Personal, example-org, or all?\"]\nUser: \"example-org\"\n\nSkill: [Invokes github-analyzer-agent]\nAnalyzer: [Runs 5 parallel gh queries, returns JSON]\n\nSkill: [Analyzes data, identifies themes]\nSkill: [Presents themes to user with multiSelect question]\nThemes identified:\n  - Investigated AWS infrastructure\n  - Investigated Railway deployments\n  - Investigated Auth0 setup\n  - Investigated deployment process\n  - Set up secret detection\n  - Added markdown linting\n  - Documentation improvements\n\nUser: [Selects: AWS, Railway, Auth0, Deployment process]\n\nSkill: [Invokes summarizer-agent with data + selected topics]\nSummarizer: [Creates summary with 4 main bullets + Housekeeping group]\n\nSkill: [Presents summary to user]\nSkill: [Checks config for enabled integrations]\nSkill: [If Notion enabled, posts to Notion Daily Log]\nSkill: \"Posted to Notion Daily Log!\" (if applicable)\n```\n\n## Files\n\nThis skill uses:\n\n- `agents/github-analyzer-agent.md` - Data extraction agent\n- `agents/summarizer-agent.md` - Summary writing agent\n- `skills/shipmate:end-of-day-summary/SKILL.md` - This orchestration skill\n- `commands/shipmate:eod.md` - Slash command shortcut\n- `integrations/notion/` - Optional Notion integration\n\n---\n\n**Version:** 1.1.5  \n**Last Updated:** 2025-11-05\n"},"lastSynced":"2026-03-08T02:13:52.783Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated GitHub activity summarization.","zh":"适合需要自动化 GitHub 活动摘要的开发代理。","ja":"GitHub の活動の自動化された要約が必要な開発エージェントに適しています。","ko":"GitHub 활동 요약 자동화가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollo que necesitan una resumen automatizado de la actividad de GitHub.","fr":"Parfait pour les agents de développement ayant besoin d''une synthèse automatisée de l''activité GitHub.","de":"Perfekt für Entwicklungssagenten, die eine automatisierte Zusammenfassung der GitHub-Aktivität benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de resumo automatizado de atividades do GitHub.","ru":"Идеально для агентов разработки, которым требуется автоматизированная сводка активности GitHub.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى تلخيص آلي للنشاط على GitHub."},"recommendation":{"en":"Empowers agents to generate concise daily summaries of GitHub activity using the github-analyzer-agent and summarizer-agent, facilitating seamless progress sharing with teammates via conversational updates.","zh":"通过 github-analyzer-agent 和 summarizer-agent 启用代理生成 GitHub 活动的简洁每日摘要，从而通过对话式更新与团队成员无缝分享进度。","ja":"github-analyzer-agent と summarizer-agent を使用してエージェントが GitHub の活動の簡潔な毎日の要約を生成できるようにし、会話式の更新を介してチームメンバーと進度を無縫に共有できるようにします。","ko":"github-analyzer-agent와 summarizer-agent를 사용하여 에이전트가 GitHub 활동의 간결한 일일 요약을 생성할 수 있도록 하여 대화식 업데이트를 통해 팀원과 진행 상황을 무縫으로 공유할 수 있습니다.","es":"Habilita a los agentes a generar resúmenes concisos diarios de la actividad de GitHub utilizando el github-analyzer-agent y el summarizer-agent, facilitando una compartición de progreso sin problemas con los compañeros de equipo a través de actualizaciones conversacionales.","fr":"Permet aux agents de générer des synthèses concises quotidiennes de l''activité GitHub en utilisant le github-analyzer-agent et le summarizer-agent, facilitant ainsi un partage de progrès sans heurts avec les membres de l''équipe via des mises à jour conversationnelles.","de":"Ermöglicht es den Agenten, mit Hilfe des github-analyzer-agent und des summarizer-agent tägliche Zusammenfassungen der GitHub-Aktivität zu erstellen und so problemlos den Projektfortschritt mit dem Team über konversationelle Updates zu teilen.","pt":"Habilita os agentes a gerar resumos diários concisos de atividades do GitHub usando o github-analyzer-agent e o summarizer-agent, facilitando a partilha de progressos com a equipe via atualizações conversacionais.","ru":"Позволяет агентам генерировать краткие ежедневные сводки активности GitHub с помощью github-analyzer-agent и summarizer-agent, что облегчает обмен прогрессом с командой через разговорные обновления.","ar":"يسمح للعميل بإنشاء ملخصات يومية موجزة لأنشطة GitHub باستخدام github-analyzer-agent وsummarizer-agent، مما يسهل مشاركة التقدم مع الفريق من خلال التحديثات الحوارية."},"useCases":{"en":["Generating end-of-day summaries for team updates","Automating GitHub activity reporting","Creating daily progress logs for project management"],"zh":["为团队更新生成每日总结","自动化 GitHub 活动报告","为项目管理创建每日进度日志"],"ja":["チームの更新のために毎日のサマリーを生成する","GitHub の活動報告を自動化する","プロジェクト管理のために毎日の進度ログを作成する"],"ko":["팀 업데이트용 일일 요약 생성","GitHub 활동 보고서 자동화","프로젝트 관리를 위한 일일 진행 로그 생성"],"es":["Generar resúmenes de fin de día para actualizaciones de equipo","Automatizar los informes de actividad de GitHub","Crear registros de progreso diario para la gestión de proyectos"],"fr":["Générer des synthèses de fin de journée pour les mises à jour d''équipe","Automatiser les rapports d''activité GitHub","Créer des journaux de progrès quotidiens pour la gestion de projet"],"de":["Erstellung von Tageszusammenfassungen für Team-Updates","Automatisierung von GitHub-Aktivitätsberichten","Erstellung von täglichen Fortschrittsprotokollen für das Projektmanagement"],"pt":["Gerar resumos de fim de dia para atualizações da equipe","Automatizar relatórios de atividades do GitHub","Criar registros de progresso diário para gerenciamento de projetos"],"ru":["Генерировать сводки конца дня для обновлений команды","Автоматизировать отчеты о активности GitHub","Создавать ежедневные журналы прогресса для управления проектами"],"ar":["إنشاء ملخصات نهاية اليوم لتحديثات الفريق","تطبيق تلقائي لتقرير أنشطة GitHub","إنشاء سجلات تقدم يومية لإدارة المشاريع"]},"limitations":{"en":["Requires github-analyzer-agent and summarizer-agent","Limited to GitHub activity data"],"zh":["需要 github-analyzer-agent 和 summarizer-agent","仅限 GitHub 活动数据"],"ja":["github-analyzer-agent と summarizer-agent が必要","GitHub の活動データのみに限定される"],"ko":["github-analyzer-agent와 summarizer-agent가 필요","GitHub 활동 데이터만으로 제한됨"],"es":["Requiere github-analyzer-agent y summarizer-agent","Limitado a los datos de actividad de GitHub"],"fr":["Nécessite github-analyzer-agent et summarizer-agent","Limité aux données d''activité GitHub"],"de":["Benötigt github-analyzer-agent und summarizer-agent","Begrenzt auf GitHub-Aktivitätsdaten"],"pt":["Exige github-analyzer-agent e summarizer-agent","Limitado a dados de atividades do GitHub"],"ru":["Требует github-analyzer-agent и summarizer-agent","Ограничен данными активности GitHub"],"ar":["يتطلب github-analyzer-agent وsummarizer-agent","محدود ببيانات أنشطة GitHub"]},"version":4},"contentHash":"0a00862cfd8b7efabac44ba4b65421483a822d599845b92d7a301aa062cb60c8","qualityScore":60}');
