INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dreamiurg/shipmate/eod', 'eod', 'dreamiurg', 'shipmate', 'community', 'eod dreamiurg shipmate community The eod skill generates a daily summary of your GitHub activity using the github-analyzer-agent and summarizer-agent. It''s perfect for developers who want to share their progress with teammates. eod 技术通过 GitHub 分析器和总结器生成每日开发摘要，支持自然语言查询 eod 技術は、GitHub 分析器と総結器を使用して毎日の開発サマリーを生成し、自然言語クエリをサポート eod 기술은 깃허브 분석 및 요약 기능을 사용하여 일일 개발 요약을 생성하며 자연어 질의를 지원합니다. eod es un agente de desarrollo que resume tu actividad diaria en GitHub, utilizando agentes especializados como github-analyzer-agent y summarizer-agent eod est un agent de développement qui résume votre activité quotidienne sur GitHub, en utilisant des agents spécialisés tels que github-analyzer-agent et summarizer-agent eod ist ein Entwicklungsagent, der Ihre tägliche Aktivität in GitHub zusammenfasst, indem er spezialisierte Agenten wie github-analyzer-agent und summarizer-agent nutzt O eod é um skill que gera resumos diários das suas atividades no GitHub, utilizando os agentes github-analyzer-agent e summarizer-agent eod - это навык, который генерирует ежедневные отчеты о деятельности на GitHub, используя агенты github-analyzer-agent и summarizer-agent с ИИ Агентами eod هو مهارة تولد تلخيص يومي لأنشطتك على GitHub باستخدام وكلاء github-analyzer-agent و summarizer-agent how to use eod eod setup guide github activity tracking eod vs github dashboard eod install end-of-day summary tools github analyzer agent summarizer agent eod 技术 GitHub 分析器 总结器 每日开发摘要 自然语言查询 开发工具 AI エージェント 开发效率 Extracts GitHub activity data using the github-analyzer-agent Generates a beautiful summary using the summarizer-agent Supports natural language invocation with ''Generate my end-of-day summary'' Produces conversational and scannable updates for team sharing eod is a specialized AI agent skill that orchestrates GitHub activity data extraction and summary generation for developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('clearclown/claude-code-aida/aida:fix', 'community', 'clearclown', 'claude-code-aida', 'clearclown/claude-code-aida', 'aida:fix', 0, 0, 60, '2026-03-08T01:57:15.650Z', '2026-03-08T02:13:52.855Z', '73d95a4c8157e14a1afecbd1b6e87d7ebd921e66b9fe8ceab2dcdbb36c7cae20', '{"id":"clearclown/claude-code-aida/aida:fix","name":"aida:fix","description":{"en":"The aida:fix skill fixes existing projects to meet all quality gates, benefiting developers who need to ensure compliance. It validates project directories and executes a mandatory protocol.","zh":"AIDA Fix是一种命令行工具，用于自动修复现有项目，满足19个质量门槛，提高开发效率","ja":"AIDA Fixは、既存のプロジェクトを自動修復し、19の品質ゲートを満たすコマンドラインツールです","ko":"AIDA Fix는 기존 프로젝트를 자동으로 수정하여 19개의 품질 게이트를 충족하는 명령줄 도구입니다","es":"aida:fix es una herramienta que repara proyectos existentes para cumplir con los 19 portones de calidad. Se ejecuta mediante la línea de comandos con el comando /aida:fix.","fr":"aida:fix est un outil qui répare les projets existants pour répondre aux 19 portes de qualité. Il s''exécute via la ligne de commande avec la commande /aida:fix.","de":"aida:fix ist ein Tool, das bestehende Projekte repariert, um die 19 Qualitätschecks zu bestehen. Es wird über die Kommandozeile mit dem Befehl /aida:fix ausgeführt.","pt":"O aida:fix é uma ferramenta de IA que corrige projetos para atender aos 19 portais de qualidade. Aprenda a usá-la para melhorar seu fluxo de trabalho.","ru":"ИИ инструмент aida:fix исправляет проекты для прохождения 19 контрольных точек качества. Узнайте, как использовать его для улучшения своего рабочего процесса.","ar":"أداة الذكاء الاصطناعي aida:fix تصحيح المشاريع لتمرير 19 بوابة جودة. تعرف على كيفية استخدامها لتحسين تدفق العمل الخاص بك."},"seo":{"title":{"en":"aida:fix: Quality Gate Compliance Setup Guide | AI Agent ...","zh":"AIDA Fix_SETUP GUIDE：使用AI工具自动修复项目","ja":"AIDA Fix セットアップガイド：AIエージェントを使用したプロジェクトの自動修復","ko":"AIDA Fix 설정 가이드: AI 에이전트를 사용하여 프로젝트 자동 수정","es":"Configuración de aida:fix: Guía de reparación de proyectos","fr":"aida:fix: Guide de configuration pour les développeurs","de":"aida:fix: Einrichtungsanleitung für Entwickler","pt":"Guia de Configuração do aida:fix - Ferramentas de IA para...","ru":"ИИ Агенты: Руководство по настройке aida:fix для разработ...","ar":"دليل إعداد aida:fix - أدوات ذكاء اصطناعي للبرمجة"},"description":{"en":"Fix your project with aida:fix and ensure it meets all 19 quality gates. Get started now and improve your development workflow!","zh":"了解如何使用AIDA Fix命令行工具自动修复现有项目，满足19个质量门槛，提高开发效率","ja":"AIDA Fixコマンドラインツールを使用して既存のプロジェクトを自動修復し、19の品質ゲートを満たす方法について学びます","ko":"AIDA Fix 명령줄 도구를 사용하여 기존 프로젝트를 자동으로 수정하고 19개의 품질 게이트를 충족하는 방법에 대해 알아보세요","es":"Aprende a utilizar aida:fix para reparar proyectos y cumplir con los 19 portones de calidad. Descubre cómo ejecutar el protocolo de ejecución obligatorio.","fr":"Découvrez comment utiliser aida:fix pour réparer des projets et répondre aux 19 portes de qualité. Apprenez à exécuter le protocole d''exécution obligatoire.","de":"Erfahren Sie, wie Sie aida:fix verwenden, um Projekte zu reparieren und die 19 Qualitätschecks zu bestehen. Erhalten Sie Informationen über das obligatorisch...","pt":"Aprenda a usar o aida:fix para corrigir projetos e atender aos 19 portais de qualidade. Descubra como melhorar seu fluxo de trabalho com ferramentas de IA.","ru":"Узнайте, как использовать aida:fix для исправления проектов и прохождения 19 контрольных точек качества. Улучшите свой рабочий процесс с помощью ИИ инструмен...","ar":"تعرف على كيفية استخدام aida:fix لتصحيح المشاريع وتمرير 19 بوابة جودة. تحسين تدفق العمل الخاص بك مع أدوات الذكاء الاصطناعي."},"definition":{"en":"aida:fix is a skill that takes an existing project and fixes it to pass all 19 quality gates, following a strict execution protocol.","zh":"AIDA Fix是一种AI工具，用于自动修复和优化现有项目","ja":"AIDA Fixは、既存のプロジェクトを自動修復および最適化するためのAIエージェントです","ko":"AIDA Fix는 기존 프로젝트를 자동으로 수정 및 최적화하는 AI 에이전트입니다","es":"aida:fix es una herramienta de reparación de proyectos que utiliza la línea de comandos para cumplir con los portones de calidad.","fr":"aida:fix est un outil de réparation de projets qui utilise la ligne de commande pour répondre aux portes de qualité.","de":"aida:fix ist ein Reparaturtool für Projekte, das die Kommandozeile nutzt, um die Qualitätschecks zu bestehen.","pt":"O aida:fix é uma ferramenta de IA que ajuda a corrigir projetos para atender aos padrões de qualidade.","ru":"ИИ инструмент aida:fix - это инструмент, который помогает исправить проекты для прохождения контрольных точек качества.","ar":"أداة الذكاء الاصطناعي aida:fix هي أداة تساعد في تصحيح المشاريع لتمرير معايير الجودة."},"features":{"en":["Validates project directories using bash commands","Executes a mandatory execution protocol to ensure quality gate compliance","Supports project fixing using the /aida:fix command","Checks for project existence and directory structure","Ensures compliance with all 19 quality gates"],"zh":["支持命令行工具","自动修复现有项目","满足19个质量门槛","提高开发效率","使用bash脚本进行项目验证"],"ja":["コマンドラインツールをサポート","既存のプロジェクトを自動修復","19の品質ゲートを満たす","開発効率を向上させる","bashスクリプトを使用したプロジェクトの検証"],"ko":["명령줄 도구 지원","기존 프로젝트 자동 수정","19개의 품질 게이트 충족","개발 효율성 향상","bash 스크립트를 사용한 프로젝트 검증"],"es":["Reparación de proyectos existentes","Cumplimiento de los 19 portones de calidad","Ejecución mediante la línea de comandos con /aida:fix","Validación de la existencia del proyecto","Compatibilidad con proyectos incompletos"],"fr":["Réparation de projets existants","Respect des 19 portes de qualité","Exécution via la ligne de commande avec /aida:fix","Validation de l''existence du projet","Compatibilité avec les projets incomplets"],"de":["Reparatur von bestehenden Projekten","Erfüllung der 19 Qualitätschecks","Ausführung über die Kommandozeile mit /aida:fix","Überprüfung der Existenz des Projekts","Kompatibilität mit unvollständigen Projekten"],"pt":["Validação de projeto","Execução de protocolo de correção","Suporte a 19 portais de qualidade","Integração com CLI","Compatibilidade com projetos existentes","Melhoria do fluxo de trabalho"],"ru":["Валидация проекта","Выполнение протокола исправления","Поддержка 19 контрольных точек качества","Интеграция с CLI","Совместимость с существующими проектами","Улучшение рабочего процесса"],"ar":["تحقق من المشروع","تنفيذ بروتوكول التصحيح","دعم 19 بوابة جودة","التكامل مع CLI","التوافق مع المشاريع الموجودة","تحسين تدفق العمل"]},"keywords":{"en":["how to use aida:fix","aida:fix setup guide","quality gate compliance","project fixing","aida:fix alternative","aida:fix vs code quality tools","what is aida:fix","aida:fix install","bash commands for project validation"],"zh":["AIDA Fix","AI工具","命令行工具","自动修复","质量门槛","开发效率","bash脚本","项目验证"],"ja":["AIDA Fix","AIエージェント","コマンドラインツール","自動修復","品質ゲート","開発効率","bashスクリプト","プロジェクトの検証"],"ko":["AIDA Fix","AI 에이전트","명령줄 도구","自動 수정","품질 게이트","개발 효율성","bash 스크립트","프로젝트 검증"],"es":["aida:fix","reparación de proyectos","portones de calidad","línea de comandos","desarrollo de software","herramientas de desarrollo","reparación de código","cumplimiento de calidad"],"fr":["aida:fix","réparation de projets","portes de qualité","ligne de commande","développement de logiciels","outils de développement","réparation de code","respect de la qualité"],"de":["aida:fix","Reparatur von Projekten","Qualitätschecks","Kommandozeile","Software-Entwicklung","Entwicklertools","Code-Reparatur","Qualitätskonformität"],"pt":["aida:fix","ferramentas de IA","desenvolvimento de software","qualidade de projeto","CLI","fluxo de trabalho","correção de projeto","padrões de qualidade","desenvolvedores"],"ru":["ИИ Агенты","aida:fix","инструменты разработки","качество проекта","CLI","рабочий процесс","исправление проекта","стандарты качества","разработчики"],"ar":["أدوات الذكاء الاصطناعي","aida:fix","تطوير البرمجيات","جودة المشروع","CLI","تدفق العمل","تصحيح المشروع","معايير الجودة","المبرمجين"]}},"owner":"clearclown","repo":"claude-code-aida","repoPath":"clearclown/claude-code-aida","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.650Z","topics":[],"category":"community","skillMd":{"name":"aida:fix","description":"|","bodyPreview":"# AIDA Fix\n\nFix an existing project to meet all 19 quality gates.\n\n## Usage\n\n```\n/aida:fix <project-name>\n```\n\nExample:\n```\n/aida:fix twitter-clone\n```\n\n---\n\n## MANDATORY EXECUTION PROTOCOL\n\n**You MUST follow this protocol exactly. Do NOT deviate.**\n\nThis command takes an existing (possibly incomplete) project and fixes it to pass all quality gates.\n\n---\n\n## Step 1: Validate Project Exists\n\nCheck project directory:\n\n```bash\nls -la ./\nls -la ./backend/\nls -la ./frontend/\n```\n\n**If project doesn''t","body":"# AIDA Fix\n\nFix an existing project to meet all 19 quality gates.\n\n## Usage\n\n```\n/aida:fix <project-name>\n```\n\nExample:\n```\n/aida:fix twitter-clone\n```\n\n---\n\n## MANDATORY EXECUTION PROTOCOL\n\n**You MUST follow this protocol exactly. Do NOT deviate.**\n\nThis command takes an existing (possibly incomplete) project and fixes it to pass all quality gates.\n\n---\n\n## Step 1: Validate Project Exists\n\nCheck project directory:\n\n```bash\nls -la ./\nls -la ./backend/\nls -la ./frontend/\n```\n\n**If project doesn''t exist:**\n```\nProject {{PROJECT}} not found.\n\nAvailable projects:\n$(ls ./)\n\nTo create a new project:\n  /aida \"Your project description\"\n```\n\n---\n\n## Step 2: Run Quality Gates (Diagnostic)\n\nRun quality gates to identify failures:\n\n```bash\n./scripts/quality-gates.sh {{PROJECT}} 2>&1 | tee /tmp/gate-diagnostic.log\n```\n\nParse the output to identify:\n- Which gates PASSED\n- Which gates FAILED\n- Specific error messages\n\n---\n\n## Step 3: Create Fix Plan\n\nBased on gate failures, create a prioritized fix plan:\n\n### Gate 1-2 (Backend Build/Tests) Failures:\n- Syntax errors in Go code\n- Missing dependencies\n- Failing tests\n\n### Gate 3-4 (Frontend Build/Tests) Failures:\n- TypeScript errors\n- Missing packages\n- Failing component tests\n\n### Gate 5-7 (Docker) Failures:\n- Dockerfile issues\n- docker-compose.yml problems\n- Health check failures\n\n### Gate 8 (API Coverage) Failures:\n- Need more handler functions\n- Missing endpoints\n\n### Gate 9 (Frontend Features) Failures:\n- Need more pages\n- Missing routing\n- No API client\n\n### Gate 10 (Integration) Failures:\n- Frontend/Backend not connected\n- Missing CORS\n- No Docker links\n\n### Gate 11 (Backend Test Count < 80) Failures:\n- Add more unit tests\n- Add integration tests\n- Add edge case tests\n\n### Gate 12 (Frontend Test Count < 100) Failures:\n- Add component tests\n- Add context tests\n- Add API client tests\n\n### Gate 13 (Empty Array Pattern) Failures:\n- Replace `var slice []T` with `make([]T, 0)`\n- Ensure JSON returns `[]` not `null`\n\n### Gate 14 (Backend Coverage < 75%) Failures:\n- Add tests for uncovered code\n- Focus on handlers and services\n\n### Gate 15-18 (E2E/Design) Failures:\n- Add Playwright tests\n- Improve UI components\n- Add more E2E scenarios\n\n### Gate 19 (E2E Execution) Failures:\n- Fix Playwright configuration\n- Update selectors\n- Fix timing issues\n\n---\n\n## Step 4: Execute Fixes\n\nFor each failure category, either:\n\n### A. Fix Directly (Minor Issues)\n- Syntax errors\n- Missing imports\n- Configuration issues\n- Small code changes (<20 lines)\n\n### B. Spawn Player (Major Issues)\n\n**Backend Player for test additions:**\n```\nTask tool:\n  description: \"Backend Player: Add Tests for Coverage\"\n  subagent_type: \"general-purpose\"\n  model: \"sonnet\"\n  prompt: |\n    You are AIDA Backend Player in FIX mode.\n\n    ## Current State\n    Project: {{PROJECT}}\n    Location: ./backend/\n\n    ## Problem\n    {{SPECIFIC_GATE_FAILURE}}\n\n    ## Your Task\n    {{SPECIFIC_FIX_INSTRUCTIONS}}\n\n    ## Requirements\n    - Follow TDD (write test first, then implementation)\n    - Run `go test ./...` after each change\n    - Achieve minimum 80 tests, 75% coverage\n\n    ## Completion\n    Write results to .aida/results/fix-backend-{{PROJECT}}.json\n```\n\n**Frontend Player for test additions:**\n```\nTask tool:\n  description: \"Frontend Player: Add Tests for Coverage\"\n  subagent_type: \"general-purpose\"\n  model: \"sonnet\"\n  prompt: |\n    You are AIDA Frontend Player in FIX mode.\n\n    ## Current State\n    Project: {{PROJECT}}\n    Location: ./frontend/\n\n    ## Problem\n    {{SPECIFIC_GATE_FAILURE}}\n\n    ## Your Task\n    {{SPECIFIC_FIX_INSTRUCTIONS}}\n\n    ## Requirements\n    - Follow TDD\n    - Run `pnpm test -- --run` after each change\n    - Achieve minimum 100 tests, 70% coverage\n    - Ensure E2E tests pass\n\n    ## Completion\n    Write results to .aida/results/fix-frontend-{{PROJECT}}.json\n```\n\n---\n\n## Step 5: Iterate Until All Gates Pass\n\n```\n┌─────────────────────────────────────────────────────────────────┐\n│  FIX LOOP (ralph-loop style)                                     │\n│                                                                  │\n│  1. RUN GATES → ./scripts/quality-gates.sh {{PROJECT}}          │\n│                                                                  │\n│  2. PARSE OUTPUT → Which gates failed?                          │\n│                                                                  │\n│  3. FOR EACH FAILURE:                                            │\n│     → Determine fix strategy                                     │\n│     → Apply fix (direct or via Player)                          │\n│     → Verify fix worked                                          │\n│                                                                  │\n│  4. RE-RUN GATES                                                 │\n│                                                                  │\n│  5. IF ALL 19 PASS → DONE                                        │\n│     ELSE → GOTO step 3                                           │\n└─────────────────────────────────────────────────────────────────┘\n```\n\n---\n\n## Step 6: Run Docker + E2E Verification\n\nAfter basic gates pass, verify Docker and E2E:\n\n```bash\n# Start Docker environment\npodman-compose up -d --build  # or docker compose\n\n# Wait for services\nsleep 30\n\n# Health checks\ncurl -sf http://localhost:8080/health\ncurl -sf http://localhost:5173/\n\n# Run E2E tests\ncd frontend\nE2E_BASE_URL=http://localhost:5173 pnpm test:e2e\n\n# Cleanup\ncd ..\npodman-compose down\n```\n\n---\n\n## Step 7: Update Session and Kanban\n\nAfter all gates pass:\n\n**Update session.json:**\n```json\n{\n  \"current_phase\": \"COMPLETED\",\n  \"quality_gates_passed\": true,\n  \"fixed_at\": \"<ISO8601>\",\n  \"fix_summary\": {\n    \"gates_fixed\": [\"Gate 11\", \"Gate 12\", \"Gate 19\"],\n    \"tests_added\": 45,\n    \"coverage_improvement\": \"68% → 83%\"\n  }\n}\n```\n\n**Update kanban.md:**\n```markdown\n## Status: COMPLETED ✅ (Fixed)\n\n## Quality Gates - ALL 19 PASSED ✅\n- [x] Gate 1-18: (existing gates)\n- [x] Gate 19: E2E Test Execution (Playwright)\n\n## Fix Summary\n- Fixed at: {{TIMESTAMP}}\n- Gates fixed: {{LIST}}\n- Tests added: {{COUNT}}\n```\n\n---\n\n## Step 8: Report Completion\n\n```\nAIDA Fix Complete\n\nProject: {{PROJECT}}\nDuration: {{DURATION}}\n\nGates Fixed:\n- Gate 11: Backend Test Count (50 → 85)\n- Gate 12: Frontend Test Count (80 → 110)\n- Gate 14: Backend Coverage (65% → 78%)\n- Gate 19: E2E Test Execution (PASS)\n\nQuality Gates: 19/19 PASSED\n\nTo run the project:\n  docker compose up -d\n  open http://localhost:5173\n```\n\n---\n\n## Common Fix Patterns\n\n### Adding Backend Tests Quickly\n\nFocus on table-driven tests for high coverage:\n\n```go\nfunc TestHandler_AllCases(t *testing.T) {\n    tests := []struct {\n        name           string\n        input          string\n        expectedStatus int\n    }{\n        {\"valid\", `{\"field\":\"value\"}`, 200},\n        {\"empty\", ``, 400},\n        {\"invalid json\", `{bad}`, 400},\n        // Add 10+ cases for quick coverage boost\n    }\n\n    for _, tt := range tests {\n        t.Run(tt.name, func(t *testing.T) {\n            // test implementation\n        })\n    }\n}\n```\n\n### Adding Frontend Tests Quickly\n\nFocus on render and interaction tests:\n\n```tsx\ndescribe(''Component'', () => {\n  it(''renders correctly'', () => { ... });\n  it(''handles click'', () => { ... });\n  it(''shows loading state'', () => { ... });\n  it(''shows error state'', () => { ... });\n  it(''handles empty data'', () => { ... });\n  // 5 tests per component = quick coverage\n});\n```\n\n### Fixing E2E Test Failures\n\nCommon issues:\n1. **Selector not found** → Update to use `getByRole` or `getByText`\n2. **Timeout** → Add explicit waits\n3. **Network error** → Ensure backend is running\n4. **State pollution** → Add proper test isolation\n\n---\n\n## Related Commands\n\n| Command | Description |\n|---------|-------------|\n| `/aida` | Start new project from scratch |\n| `/aida:resume` | Continue from last session state |\n| `/aida:status` | Check current state |\n"},"lastSynced":"2026-03-08T02:13:52.855Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated project validation and compliance.","zh":"非常适合需要自动化项目验证和合规性的开发代理。","ja":"開発エージェントが自動化されたプロジェクトの検証とコンプライアンスが必要な場合に最適です。","ko":"자동화된 프로젝트 검증 및 컴플라이언스가 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una validación y cumplimiento de proyectos automatizados.","fr":"Parfait pour les agents de développement ayant besoin d''une validation et d''un respect des projets automatisés.","de":"Perfekt für Entwicklungssagenten, die eine automatisierte Projektvalidierung und -konformität benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de validação de projeto automatizada e conformidade.","ru":"Идеально для агентов разработки, которым требуется автоматизированная проверка проектов и соблюдение требований.","ar":"مثالي لعمليات التطوير التي تحتاج إلى التحقق التلقائي من المشروع والامتثال للوائح."},"recommendation":{"en":"Empowers agents to fix existing projects and ensure compliance with 19 quality gates, validating project directories and executing a mandatory protocol using command-line interfaces like bash.","zh":"赋予代理修复现有项目并确保遵守 19 个质量门的能力，验证项目目录，并使用诸如 bash 的命令行界面执行强制协议。","ja":"エージェントが既存のプロジェクトを修復し、19 の品質ゲートに準拠することを保証する権限を付与します。プロジェクトディレクトリを検証し、bash などのコマンドラインインターフェイスを使用して、強制プロトコルを実行します。","ko":"에이전트가 기존 프로젝트를 수정하고 19개의 품질 게이트를 준수하도록 보장하는 권한을 부여합니다. 프로젝트 디렉토리를 검증하고 bash와 같은 명령줄 인터페이스를 사용하여 강제 프로토콜을 실행합니다.","es":"Habilita a los agentes a corregir proyectos existentes y asegurar el cumplimiento con 19 puertas de calidad, validando directorios de proyectos y ejecutando un protocolo obligatorio utilizando interfaces de línea de comandos como bash.","fr":"Permet aux agents de corriger les projets existants et de garantir la conformité avec 19 portes de qualité, en validant les répertoires de projets et en exécutant un protocole obligatoire en utilisant des interfaces de ligne de commande comme bash.","de":"Ermächtigt die Agenten, bestehende Projekte zu korrigieren und die Einhaltung von 19 Qualitätstoren sicherzustellen, indem Projektverzeichnisse validiert und ein obligatorisches Protokoll mithilfe von Kommandozeilen-Schnittstellen wie bash ausgeführt wird.","pt":"Habilita os agentes a corrigir projetos existentes e garantir a conformidade com 19 portas de qualidade, validando diretórios de projeto e executando um protocolo obrigatório usando interfaces de linha de comando como o bash.","ru":"Наделяет агентов возможностью исправлять существующие проекты и обеспечивать соблюдение требований с 19 контрольными точками, проверяя каталоги проектов и выполняя обязательный протокол с использованием интерфейсов командной строки, таких как bash.","ar":"يمنح الوكيل صلاحية إصلاح المشاريع الحالية وضمان الامتثال للوائح مع 19 بوابة جودة، و التحقق من دليل المشروع وتشغيل بروتوكول إجباري باستخدام واجهات سطر الأوامر مثل bash."},"useCases":{"en":["Validating project structures","Automating quality gate checks","Debugging non-compliant projects"],"zh":["验证项目结构","自动化质量门检查","调试非合规项目"],"ja":["プロジェクト構造の検証","品質ゲートの自動化チェック","準拠していないプロジェクトのデバッグ"],"ko":["프로젝트 구조 검증","품질 게이트 자동화 체크","준수하지 않는 프로젝트 디버깅"],"es":["Validar estructuras de proyectos","Automatizar comprobaciones de puertas de calidad","Depurar proyectos no conformes"],"fr":["Valider les structures de projets","Automatiser les vérifications de portes de qualité","Déboguer les projets non conformes"],"de":["Validieren von Projekstrukturen","Automatisieren von Qualitätstoren-Prüfungen","Debuggen von nicht konformen Projekten"],"pt":["Validação de estruturas de projeto","Automatização de verificações de portas de qualidade","Depuração de projetos não conformes"],"ru":["Проверка структуры проекта","Автоматизация проверок контрольных точек","Отладка не соответствующих проектов"],"ar":["التحقق من هيكل المشروع","آليّة فحص بوابات الجودة","تصحيح المشاريع غير المطابقة"]},"limitations":{"en":["Requires existing project directory","Mandatory execution protocol must be followed exactly"],"zh":["需要现有的项目目录","必须严格遵守强制执行协议"],"ja":["既存のプロジェクトディレクトリが必要","強制実行プロトコルを厳密に遵守する必要がある"],"ko":["기존의 프로젝트 디렉토리가 필요","강제 실행 프로토콜을 엄격히 준수해야 함"],"es":["Requiere un directorio de proyecto existente","El protocolo de ejecución obligatorio debe seguirse exactamente"],"fr":["Nécessite un répertoire de projet existant","Le protocole d''exécution obligatoire doit être suivi exactement"],"de":["Benötigt ein vorhandenes Projektverzeichnis","Das obligatorische Ausführungsprotokoll muss genau befolgt werden"],"pt":["Requer diretório de projeto existente","Protocolo de execução obrigatório deve ser seguido exatamente"],"ru":["Требуется существующий каталог проекта","Обязательный протокол выполнения должен быть выполнен точно"],"ar":["يتطلب دليل مشروع موجود","يجب اتباع بروتوكول التنفيذ الإجباري بدقة"]},"version":4},"contentHash":"73d95a4c8157e14a1afecbd1b6e87d7ebd921e66b9fe8ceab2dcdbb36c7cae20","qualityScore":60}');
