INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('clearclown/claude-code-aida/aida:fix', 'aida:fix', 'clearclown', 'claude-code-aida', 'community', 'aida:fix clearclown claude-code-aida community The aida:fix skill fixes existing projects to meet all quality gates, benefiting developers who need to ensure compliance. It validates project directories and executes a mandatory protocol. AIDA Fix是一种命令行工具，用于自动修复现有项目，满足19个质量门槛，提高开发效率 AIDA Fixは、既存のプロジェクトを自動修復し、19の品質ゲートを満たすコマンドラインツールです AIDA Fix는 기존 프로젝트를 자동으로 수정하여 19개의 품질 게이트를 충족하는 명령줄 도구입니다 aida:fix es una herramienta que repara proyectos existentes para cumplir con los 19 portones de calidad. Se ejecuta mediante la línea de comandos con el comando /aida:fix. aida:fix est un outil qui répare les projets existants pour répondre aux 19 portes de qualité. Il s''exécute via la ligne de commande avec la commande /aida:fix. aida:fix ist ein Tool, das bestehende Projekte repariert, um die 19 Qualitätschecks zu bestehen. Es wird über die Kommandozeile mit dem Befehl /aida:fix ausgeführt. O aida:fix é uma ferramenta de IA que corrige projetos para atender aos 19 portais de qualidade. Aprenda a usá-la para melhorar seu fluxo de trabalho. ИИ инструмент aida:fix исправляет проекты для прохождения 19 контрольных точек качества. Узнайте, как использовать его для улучшения своего рабочего процесса. أداة الذكاء الاصطناعي aida:fix تصحيح المشاريع لتمرير 19 بوابة جودة. تعرف على كيفية استخدامها لتحسين تدفق العمل الخاص بك. how to use aida:fix aida:fix setup guide quality gate compliance project fixing aida:fix alternative aida:fix vs code quality tools what is aida:fix aida:fix install bash commands for project validation AIDA Fix AI工具 命令行工具 自动修复 质量门槛 开发效率 bash脚本 项目验证 Validates project directories using bash commands Executes a mandatory execution protocol to ensure quality gate compliance Supports project fixing using the /aida:fix command Checks for project existence and directory structure Ensures compliance with all 19 quality gates aida:fix is a skill that takes an existing project and fixes it to pass all 19 quality gates, following a strict execution protocol.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SiluPanda/academic-researcher/academic-researcher', 'community', 'SiluPanda', 'academic-researcher', 'SiluPanda/academic-researcher', 'academic-researcher', 0, 0, 60, '2026-03-08T01:57:15.652Z', '2026-03-08T02:13:53.875Z', '3269cbb1d8305077f5ecc081addc7a3791333f4e01cd6de84d179fc1e942601b', '{"id":"SiluPanda/academic-researcher/academic-researcher","name":"academic-researcher","description":{"en":"The academic-researcher skill generates expert-level academic research papers with peer-reviewed source discovery and proper citation formats, benefiting researchers and academics.","zh":"AI 学术研究员帮助您创建专家级学术研究文档，具有 LaTeX 输出和 IEEE 引用格式等功能","ja":"AIエージェント学術研究者は、LaTeX 出力と IEEE 引用形式などの機能を備えた、専門家レベルの学術研究文書を作成するのに役立ちます","ko":"AI 학술 연구자는 LaTeX 출력과 IEEE 인용 형식 등의 기능을 제공하여 전문가 수준의 학술 연구 문서를 생성하는 데 도움이 됩니다","es":"El agente de investigación académica te ayuda a crear documentos de investigación expertos con fuentes verificadas y citas en formato IEEE y APA. Utiliza LaTeX para la composición matemática profesional","fr":"L''outil de recherche académique vous aide à créer des documents de recherche experts avec des sources vérifiées et des citations au format IEEE et APA. Il utilise LaTeX pour la composition mathématique professionnelle","de":"Der akademische Forschungsassistent hilft Ihnen bei der Erstellung von Experten-Forschungsdokumenten mit verifizierten Quellen und Zitaten im IEEE- und APA-Format. Er verwendet LaTeX für die professionelle mathematische Satz","pt":"Nossa ferramenta de IA para pesquisa acadêmica ajuda a criar documentos de nível expert com estrutura IMRaD e convenções de escrita acadêmica, além de formatos de citação IEEE e APA.","ru":"Наш ИИ Агент для академических исследований помогает создавать экспертные документы с структурой IMRaD и академическими конвенциями письма, а также форматами цитирования IEEE и APA.","ar":"أداة الذكاء الاصطناعي لدينا للبحث الأكاديمي تساعد على إنشاء مستندات من المستوى الخبير مع هيكل IMRaD و اتفاقيات الكتابة الأكاديمية، بالإضافة إلى صيغ الاستشهاد IEEE و APA."},"seo":{"title":{"en":"academic-researcher: Expert-Level Research Paper Generati...","zh":"AI学术研究员 Setup Guide - LaTeX 输出和 IEEE 引用格式","ja":"AIエージェント学術研究者 Setup Guide - LaTeX 出力と IEEE 引用形式","ko":"AI 학술 연구자 Setup Guide - LaTeX 출력과 IEEE 인용 형식","es":"Guía de configuración del agente de investigación académica","fr":"Guide de mise en place de l''outil de recherche académique","de":"Einrichtungsleitfaden für den akademischen Forschungsassi...","pt":"Configuração de Pesquisa Acadêmica com Ferramentas de IA","ru":"Настройка ИИ Агентов для Академических Исследований","ar":"إعداد أدوات الذكاء الاصطناعي للبحث الأكاديمي"},"description":{"en":"Unlock expert-level academic research documents with verified sources, IMRaD structure, and LaTeX output. Get started with academic-researcher today!","zh":"使用 AI 学术研究员创建专家级学术研究文档，具有同行评审来源发现和验证、IMRaD 结构和学术写作惯例等功能","ja":"AIエージェント学術研究者を使用して、専門家レベルの学術研究文書を作成します。同行評価された情報源の発見と検証、IMRaD 構造と学術的な文章作成規範などを備えています","ko":"AI 학술 연구자를 사용하여 전문가 수준의 학술 연구 문서를 생성합니다. 심사된 출처 발견 및 검증, IMRaD 구조 및 학술 작성 규범 등을 제공합니다","es":"Descubre cómo el agente de investigación académica puede ayudarte a crear documentos de investigación expertos con fuentes verificadas y citas en formato IEE...","fr":"Découvrez comment l''outil de recherche académique peut vous aider à créer des documents de recherche experts avec des sources vérifiées et des citations au f...","de":"Erfahren Sie, wie der akademische Forschungsassistent Ihnen bei der Erstellung von Experten-Forschungsdokumenten mit verifizierten Quellen und Zitaten im IEE...","pt":"Aprenda a criar documentos de pesquisa acadêmica de nível expert com nossa ferramenta de IA, incluindo descoberta e verificação de fontes revisadas por pares","ru":"Изучите, как создавать экспертные документы академических исследований с помощью нашего ИИ Агента, включая поиск и верификацию источников, прошедших рецензир...","ar":"تعرف على كيفية إنشاء مستندات بحثية أكاديمية من المستوى الخبير باستخدام أداة الذكاء الاصطناعي لدينا، بما في ذلك اكتشاف المصادر المراجعة من قبل الأقران و التحق..."},"definition":{"en":"academic-researcher is a skill that assists in creating academic research documents with verified sources, proper structure, and formatting conventions.","zh":"AI 学术研究员是一种 AI 工具，用于创建专家级学术研究文档，具有同行评审来源发现和验证等功能","ja":"AIエージェント学術研究者は、同行評価された情報源の発見と検証などの機能を備えた、専門家レベルの学術研究文書を作成するための AI ツールです","ko":"AI 학술 연구자는 심사된 출처 발견 및 검증 등의 기능을 제공하는 AI 도구로, 전문가 수준의 학술 연구 문서를 생성하는 데 사용됩니다","es":"Un agente de investigación académica es una herramienta que ayuda a crear documentos de investigación expertos con fuentes verificadas y citas en formato estándar","fr":"Un outil de recherche académique est un outil qui aide à créer des documents de recherche experts avec des sources vérifiées et des citations au format standard","de":"Ein akademischer Forschungsassistent ist ein Tool, das bei der Erstellung von Experten-Forschungsdokumenten mit verifizierten Quellen und Zitaten im Standardformat hilft","pt":"O que é uma ferramenta de IA para pesquisa acadêmica? É uma tecnologia que ajuda a criar documentos de pesquisa de nível expert com recursos como descoberta de fontes e citação automatizada.","ru":"Что такое ИИ Агент для академических исследований? Это технология, которая помогает создавать экспертные документы исследований с функциями, такими как поиск источников и автоматическое цитирование.","ar":"ما هي أداة الذكاء الاصطناعي للبحث الأكاديمي؟ هي تكنولوجيا تساعد على إنشاء مستندات بحثية من المستوى الخبير مع ميزات مثل اكتشاف المصادر والاستشهاد التلقائي."},"features":{"en":["Peer-reviewed source discovery and verification","Proper IMRaD structure and academic writing conventions","IEEE and APA citation formats support","LaTeX output for professional mathematical typesetting","Quality assurance against scholarly standards"],"zh":["同行评审来源发现和验证","IMRaD 结构和学术写作惯例","IEEE 和 APA 引用格式支持","LaTeX 输出用于专业数学排版","质量保证，确保符合学术标准"],"ja":["同行評価された情報源の発見と検証","IMRaD 構造と学術的な文章作成規範","IEEE と APA 引用形式のサポート","LaTeX 出力による専門家向け数学組版","品質保証、学術基準への適合性の確保"],"ko":["심사된 출처 발견 및 검증","IMRaD 구조 및 학술 작성 규범","IEEE 와 APA 인용 형식 지원","LaTeX 출력을 통한 전문가용 수식組版","품질 보증, 학술 표준 준수"],"es":["Descubrimiento y verificación de fuentes revisadas por pares","Estructura IMRaD y convenciones de escritura académica","Formatos de citación IEEE y APA","Salida en LaTeX para la composición matemática profesional","Garantía de calidad contra estándares académicos"],"fr":["Découverte et vérification de sources révisées par des pairs","Structure IMRaD et conventions d''écriture académique","Formats de citation IEEE et APA","Sortie en LaTeX pour la composition mathématique professionnelle","Garantie de qualité contre les normes académiques"],"de":["Entdeckung und Verifizierung von peer-reviewten Quellen","IMRaD-Struktur und akademische Schreibkonventionen","Zitierformate IEEE und APA","LaTeX-Ausgabe für die professionelle mathematische Satz","Qualitätssicherung gegen akademische Standards"],"pt":["Descoberta e verificação de fontes revisadas por pares","Estrutura IMRaD e convenções de escrita acadêmica","Formatos de citação IEEE e APA","Saída em LaTeX para composição matemática profissional","Garantia de qualidade contra padrões acadêmicos"],"ru":["Поиск и верификация источников, прошедших рецензирование","Структура IMRaD и академические конвенции письма","Форматы цитирования IEEE и APA","Выход в LaTeX для профессиональной математической верстки","Контроль качества против академических стандартов"],"ar":["اكتشاف وتحقق المصادر المراجعة من قبل الأقران","هيكل IMRaD واتفاقيات الكتابة الأكاديمية","صيغ الاستشهاد IEEE و APA","إخراج LaTeX للتركيب الرياضي المحترف","ضمان الجودة ضد المعايير الأكاديمية"]},"keywords":{"en":["how to use academic-researcher","academic-researcher alternative","academic-researcher setup guide","what is academic-researcher","academic-researcher vs research assistant","academic-researcher install"],"zh":["AI 学术研究员","学术研究文档","LaTeX 输出","IEEE 引用格式","同行评审来源发现","IMRaD 结构","学术写作惯例","AI 工具","学术研究辅助"],"ja":["AIエージェント学術研究者","学術研究文書","LaTeX 出力","IEEE 引用形式","同行評価された情報源の発見","IMRaD 構造","学術的な文章作成規範","AI ツール","学術研究支援"],"ko":["AI 학술 연구자","학술 연구 문서","LaTeX 출력","IEEE 인용 형식","심사된 출처 발견","IMRaD 구조","학술 작성 규범","AI 도구","학술 연구 보조"],"es":["agente de investigación académica","herramientas de investigación","redacción de artículos académicos","citas en formato IEEE","citas en formato APA","LaTeX para composición matemática","verificación de fuentes","estructura IMRaD"],"fr":["outil de recherche académique","outils de recherche","rédaction d''articles académiques","citations au format IEEE","citations au format APA","LaTeX pour composition mathématique","vérification de sources","structure IMRaD"],"de":["akademischer Forschungsassistent","Forschungstools","Erstellung von Forschungsartikeln","Zitate im IEEE-Format","Zitate im APA-Format","LaTeX für mathematische Satz","Quellenverifizierung","IMRaD-Struktur"],"pt":["ferramentas de IA para pesquisa acadêmica","criação de documentos de pesquisa","estrutura IMRaD","formatos de citação IEEE","LaTeX para composição matemática","garantia de qualidade acadêmica","pesquisa acadêmica de nível expert"],"ru":["ИИ Агенты для академических исследований","создание документов исследований","структура IMRaD","форматы цитирования IEEE","LaTeX для профессиональной математической верстки","контроль качества академических стандартов","экспертные документы исследований"],"ar":["أدوات الذكاء الاصطناعي للبحث الأكاديمي","إنشاء مستندات بحثية","هيكل IMRaD","صيغ الاستشهاد IEEE","LaTeX للتركيب الرياضي المحترف","ضمان الجودة للمعايير الأكاديمية","مستندات بحثية من المستوى الخبير"]}},"owner":"SiluPanda","repo":"academic-researcher","repoPath":"SiluPanda/academic-researcher","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.652Z","topics":[],"category":"community","skillMd":{"name":"academic-researcher","description":"Expert-level academic research and LaTeX paper writing with IEEE/APA citation support. Creates peer-reviewed research papers, literature reviews, and theses with proper scholarly standards.","bodyPreview":"## What I Do\n\nI help you create expert-level academic research documents with:\n- Peer-reviewed source discovery and verification\n- Proper IMRaD structure and academic writing conventions\n- IEEE (primary) and APA (secondary) citation formats\n- LaTeX output for professional mathematical typesetting\n- Quality assurance against scholarly standards\n\n## Non-Negotiables (Research Integrity)\n\n- **No fabricated citations**: never cite papers you did not locate and verify (title, authors, venue, year, DOI","body":"## What I Do\n\nI help you create expert-level academic research documents with:\n- Peer-reviewed source discovery and verification\n- Proper IMRaD structure and academic writing conventions\n- IEEE (primary) and APA (secondary) citation formats\n- LaTeX output for professional mathematical typesetting\n- Quality assurance against scholarly standards\n\n## Non-Negotiables (Research Integrity)\n\n- **No fabricated citations**: never cite papers you did not locate and verify (title, authors, venue, year, DOI/URL).\n- **Label source status precisely**: distinguish peer-reviewed articles from preprints (e.g., arXiv) and from non-academic web sources.\n- **Evidence-first writing**: every non-trivial claim should be backed by a citation or by an explicit result table/figure/theorem in the document.\n- **Traceability**: maintain a source log (citation key + DOI/URL + status + 1-2 line takeaways) and keep `references.bib` as the single source of truth.\n\n## When to Use Me\n\nUse this skill when you need to write:\n- **Research papers** for conferences (IEEE, ACM) or journals\n- **Literature reviews** and survey papers\n- **Theses/dissertations** (master''s or PhD)\n- **Research proposals** and grant applications\n- **Technical reports** with academic rigor\n\n## Workflow Overview\n\n```\nPhase 1: Requirements → Phase 2: Planning → Phase 3: Discovery\n    ↓                   ↓                    ↓\nPhase 6: QA ← Phase 5: Writing ← Phase 4: Structure\n```\n\n---\n\n## Phase 1: Requirements Clarification\n\nBefore starting, clarify with the user:\n\n### Essential Questions\n\n1. **Document Type**\n   - Research paper (conference/journal)?\n   - Literature review / survey?\n   - Thesis / dissertation chapter?\n   - Research proposal?\n\n2. **Topic & Scope**\n   - What is the main research question or contribution?\n   - What is the target word count or page limit?\n   - Any specific research questions to address?\n\n3. **Target Venue**\n   - Which conference or journal?\n   - Any specific formatting requirements?\n   - Submission deadline?\n\n4. **Citation Format**\n   - IEEE (default for CS/Engineering)?\n   - APA (social sciences)?\n   - Other (ACM, Chicago)?\n\n### User Input Template\n\n```markdown\n## Research Document Request\n\n**Type:** [Research Paper / Literature Review / Thesis]\n**Topic:** [Your research topic]\n**Target:** [Conference/Journal name or \"General\"]\n**Length:** [X pages or X words]\n**Citation:** [IEEE / APA / Other]\n**Deadline:** [Date if applicable]\n**Special Requirements:** [Any specific guidelines]\n```\n\n---\n\n## Phase 2: Research Planning\n\n### Search Strategy Development\n\n1. **Identify core concepts** - Extract key terms from the topic\n2. **Build keyword list** - Include synonyms, variants, and domain-specific terms\n3. **Select databases** - Choose appropriate sources:\n\n| Database | Best For |\n|----------|----------|\n| Google Scholar | Broad academic search |\n| IEEE Xplore | Engineering, CS |\n| ACM Digital Library | Computing |\n| arXiv | Preprints, CS, physics |\n| PubMed | Medicine, life sciences |\n| ScienceDirect | General science |\n| JSTOR | Humanities, social sciences |\n\n### Search Command Patterns (Tool-Agnostic)\n\nUse your platform''s browsing/search tool. If browsing is unavailable, ask the user to provide PDFs/DOIs/URLs (or an existing `references.bib`) and proceed from those.\n\nQuery patterns to use:\n\n- Broad first: `broad topic` + `survey` / `review`\n- Recent window: add a year range (e.g., last 3-5 years) or use the tool''s recency filter\n- Exact phrase: `\"exact phrase\"`\n- Boolean combos: `(term1 AND term2) OR term3`\n- Snowballing: find \"references\" (backward) and \"cited by\" (forward) from 2-3 anchor papers\n\nFor systematic reviews, keep a reproducible search log (see `references/systematic-review-prisma.md`).\n\n---\n\n## Phase 3: Source Discovery & Verification\n\n### Discovery Process\n\n**Step 1: Foundational Sources**\n- Search for seminal papers and foundational work\n- Look for highly-cited papers (100+ citations)\n- Find survey papers on the topic\n\n**Step 2: Recent Work**\n- Search for papers from last 2-3 years\n- Look for \"state of the art\" reviews\n- Find latest developments and advances\n\n**Step 3: Related Work**\n- Papers citing key foundational works\n- Papers cited by recent major papers\n- Parallel approaches and alternatives\n\n### Verification Checklist\n\nFor each source, verify:\n\n- [ ] Published in peer-reviewed venue (journal, conference)\n- [ ] Author credentials and institutional affiliation\n- [ ] Publication venue reputation (check Google Scholar metrics, impact factor)\n- [ ] Citation count indicates impact\n- [ ] Methodology is sound and described clearly\n- [ ] Relevance to your research question\n\n### Red Flags (Exclude These Sources)\n\n- Predatory journals (check Beall''s List or journalquality.info)\n- No peer review process\n- No institutional affiliation\n- Suspiciously high publication volume\n- Pay-to-publish without legitimate review\n\n### Source Tracking\n\nCreate a source database (and keep `references.bib` as the single source of truth):\n\n```markdown\n## Source [N]\n- **Citation Key:** [e.g., smith2023transformers]\n- **Title:** [Paper title]\n- **Authors:** [Author list]\n- **Venue/Year:** [Journal/Conference, Year]\n- **Status:** [peer-reviewed / preprint / standard / dataset / software]\n- **DOI:** [If available]\n- **URL:** [Canonical link]\n- **Citations:** [Count + date checked]\n- **Relevance:** [High/Medium/Low]\n- **Key Points:** [1-3 bullets: what you will cite]\n- **Limitations:** [1-2 bullets]\n- **Use In:** [Which section of your document]\n```\n\nSee `references/source-evaluation.md` and `references/bibliography-workflows.md`.\n\n### Paper Access Strategy\n\nWhen you find a relevant paper but cannot access the full text:\n\n1. **Check open access first:**\n   - Run `node scripts/resolve-papers.js --doi \"10.xxxx/yyyy\"` to find legal OA versions\n   - Check arXiv (most CS papers have preprints)\n   - Check PubMed Central (biomedical papers)\n   - Check the authors'' personal/lab websites (often host preprints)\n\n2. **Use available metadata:**\n   - Abstract + figures from the paper landing page are often sufficient for related-work sections\n   - Semantic Scholar provides abstracts and citation context for free\n\n3. **Ask the user:**\n   - If a paper is critical and paywalled, ask the user to provide it\n   - Users may have institutional access, interlibrary loan, or direct author contact\n\n4. **Be transparent:**\n   - If citing a paper you could only read the abstract of, note this limitation\n   - Never fabricate content from a paper you haven''t read\n\n---\n\n## Phase 4: Document Structure\n\n### Research Paper Structure (IMRaD)\n\n```\n1. Title\n2. Abstract (150-250 words)\n3. Keywords (5-7 terms)\n4. Introduction\n   - Background and motivation\n   - Problem statement\n   - Research objectives\n   - Contributions (3-5 bullet points)\n   - Paper organization\n5. Related Work / Literature Review\n   - Thematic organization\n   - Gap identification\n6. Methodology / Approach\n   - System design (if applicable)\n   - Algorithm description\n   - Technical approach\n7. Results / Evaluation\n   - Experimental setup\n   - Metrics\n   - Results presentation\n8. Discussion\n   - Interpretation\n   - Implications\n   - Limitations\n9. Conclusion\n   - Summary\n   - Future work\n10. References\n```\n\n### Literature Review Structure\n\n```\n1. Title\n2. Abstract\n3. Introduction\n   - Review scope and objectives\n   - Methodology (how sources were selected)\n4. Thematic Sections (organized by themes)\n5. Synthesis and Discussion\n   - Trends and patterns\n   - Gaps in literature\n6. Conclusion\n   - Summary\n   - Future directions\n7. References\n```\n\n### Systematic Review Structure (PRISMA-Style)\n\n```\n1. Title\n2. Abstract\n3. Introduction (scope + research questions)\n4. Methods (protocol, databases, queries, screening, extraction, appraisal)\n5. Results (selection counts + evidence tables + taxonomy)\n6. Discussion (implications, limitations, threats to validity)\n7. Conclusion (what is known + gaps + future directions)\n8. References\n9. Appendices (full queries, screening reasons, extraction schema)\n```\n\nSee `references/systematic-review-prisma.md`.\n\n### Thesis Structure\n\n```\n1. Abstract\n2. Introduction\n   - Background\n   - Problem statement\n   - Research questions\n   - Thesis objectives\n   - Contributions\n3. Literature Review\n   - Theoretical framework\n   - Related work\n   - Research gap\n4. Methodology\n   - Research design\n   - Data collection\n   - Analysis methods\n5. Results/Findings\n6. Discussion\n7. Conclusion\n8. References\n9. Appendices\n```\n\n---\n\n## Phase 5: Writing & LaTeX\n\n### LaTeX Document Setup\n\nFor submission, prefer official publisher templates (see `references/official-templates.md`). The templates below are scaffolds for learning the structure.\n\nIncluded templates:\n- `references/templates/ieee-conference.tex` (IEEE conference paper)\n- `references/templates/literature-review.tex` (narrative literature review)\n- `references/templates/systematic-review.tex` (systematic review)\n- `references/templates/thesis.tex` (thesis/dissertation)\n- `references/templates/apa7-manuscript.tex` (APA 7 manuscript)\n- `references/templates/research-proposal.tex` (research proposal)\n\nMinimal IEEE skeleton (BibTeX):\n\n```latex\n\\documentclass[conference]{IEEEtran}\n\\IEEEoverridecommandlockouts\n\n\\usepackage{cite}\n\\usepackage{amsmath,amssymb,amsfonts}\n\\usepackage{graphicx}\n\\usepackage{xcolor}\n\n\\title{Your Paper Title}\n\n\\author{\n\\IEEEauthorblockN{First Author}\n\\IEEEauthorblockA{Department, University\\\\\nCity, Country\\\\\nemail@example.edu}\n}\n\n\\begin{document}\n\\maketitle\n\n\\begin{abstract}\nYour abstract goes here (150--250 words).\n\\end{abstract}\n\n\\begin{IEEEkeywords}\nkeyword1, keyword2, keyword3\n\\end{IEEEkeywords}\n\n\\section{Introduction}\n...\n\n\\bibliographystyle{IEEEtran}\n\\bibliography{references}\n\\end{document}\n```\n\n### Academic Writing Style\n\n**Tone:**\n- Formal and objective\n- Use \"we\" for multi-author papers when describing your work (standard in CS/Engineering)\n- Use third person for discussing other work (\"Smith et al. proposed...\")\n- Precise technical terminology\n- Present tense for established facts, past tense for specific studies\n\n**Avoid:**\n- Colloquial language\n- Unsupported claims\n- Excessive quotations (paraphrase instead)\n- Vague terms (\"very\", \"significant\") without data\n\n### Citation Integration\n\n**IEEE Style (numbered):**\n```latex\nRecent work has shown this approach is effective \\cite{smith2023}.\nMultiple studies support this finding \\cite{smith2023, jones2022, doe2021}.\n```\n\n**APA Style (author-date):**\n```latex\n% Parenthetical (APA author-date)\nRecent work has shown this approach is effective \\parencite{smith2023}.\nMultiple studies support this finding \\parencite{smith2023,jones2022}.\n\n% Narrative\n\\textcite{smith2023} demonstrated this approach is effective.\n```\n\n### Paragraph Structure\n\nEach paragraph should follow a clear pattern:\n1. **Topic sentence** — state the main point\n2. **Evidence/Support** — cite sources or present data\n3. **Analysis** — explain what the evidence means\n4. **Transition** — connect to the next paragraph\n\n### Transition Patterns\n- Contrast: \"However,\" \"In contrast,\" \"While X focuses on...\"\n- Extension: \"Building on this,\" \"Furthermore,\" \"Similarly,\"\n- Consequence: \"As a result,\" \"Therefore,\" \"This suggests that\"\n- Gap: \"Despite these advances,\" \"However, X remains unexplored\"\n\n### Mathematical Typesetting\n\n**Inline math:** `$E = mc^2$`\n\n**Displayed equations:**\n```latex\n\\begin{equation}\nf(x) = \\sum_{i=1}^{n} a_i x^i\n\\end{equation}\n```\n\n**Multi-line equations:**\n```latex\n\\begin{align}\na &= b + c \\\\\n  &= d + e + f\n\\end{align}\n```\n\n**Matrices:**\n```latex\n\\begin{bmatrix}\na_{11} & a_{12} \\\\\na_{21} & a_{22}\n\\end{bmatrix}\n```\n\n**Proofs:**\n```latex\n\\begin{proof}\nLet $x$ be any element...\nTherefore, we conclude...\n\\end{proof}\n```\n\nSee `references/latex-math-guide.md` for more examples.\n\n---\n\n## Phase 6: Quality Assurance\n\n### Pre-Submission Checklist\n\n**Content:**\n- [ ] Clear research question/objective\n- [ ] Logical flow and organization\n- [ ] Minimum 15-20 sources for full paper\n- [ ] All sources verified and labeled (peer-reviewed vs preprint vs other)\n- [ ] All claims supported by citations\n- [ ] Methodology clearly explained\n- [ ] Results clearly presented with metrics\n- [ ] Limitations acknowledged\n- [ ] Contributions clearly stated\n\n**Technical (IEEE):**\n- [ ] Reference format correct\n- [ ] All citations match reference list\n- [ ] No missing references\n- [ ] Consistent citation numbering\n- [ ] Figure/table captions complete\n- [ ] Margins match venue requirements\n\n**Writing Quality:**\n- [ ] Academic tone maintained\n- [ ] No grammatical errors\n- [ ] Smooth transitions\n- [ ] Abstract matches content\n- [ ] Keywords present\n\n**Evidence & Citations:**\n- [ ] No invented citations; every reference is verifiable (title/authors/venue/year/DOI or canonical URL)\n- [ ] Every citation key used in LaTeX exists in `references.bib`\n- [ ] Key claims are not overgeneralized beyond the cited evidence (see `references/claim-evidence-map.md`)\n\n**Reproducibility (If Empirical):**\n- [ ] Dataset versions, splits, and preprocessing are specified\n- [ ] Baseline selection and tuning budget fairness are stated\n- [ ] Seeds/variance reporting policy is stated\n- [ ] Compute and environment details are included (see `references/reproducibility-checklist.md`)\n\n**Statistics (If Applicable):**\n- [ ] Uncertainty is reported where appropriate (CIs/SE/bootstrap)\n- [ ] Statistical tests (if used) are specified with assumptions and multiple-comparison handling\n- [ ] Effect sizes are emphasized over p-values alone (see `references/statistical-reporting.md`)\n\n**Threats to Validity:**\n- [ ] Threats are enumerated (internal/construct/statistical/external) with concrete mitigations (see `references/threats-to-validity.md`)\n\n---\n\n## Citation Formats\n\nPrefer managing references via `references.bib` (BibTeX/BibLaTeX) and generating the reference list automatically; see `references/bibliography-workflows.md`. The examples below are reference list patterns for manual verification.\n\n### IEEE Format\n\n**Journal Article:**\n```latex\n[1] A. Author, B. Author, and C. Author, \"Title of article,\" Journal Name, vol. X, no. Y, pp. ZZ-ZZ, Month Year.\n```\n\n**Conference Paper:**\n```latex\n[2] A. Author and B. Author, \"Title of paper,\" in Proc. Conference Name, City, Country, Year, pp. ZZ-ZZ.\n```\n\n**Book:**\n```latex\n[3] A. Author, Title of Book, Edition. City, State: Publisher, Year.\n```\n\nSee `references/ieee-citation-guide.md` for complete reference.\n\n### APA Format (7th Edition)\n\n**Journal Article:**\n```latex\nAuthor, A. A., & Author, B. B. (Year). Title of article. Journal Name, Volume(Issue), pages. https://doi.org/xxxxx\n```\n\n**Conference Paper:**\n```latex\nAuthor, A. A., & Author, B. B. (Year, Month). Title of paper. In Conference Name (pp. pages). Publisher.\n```\n\nSee `references/apa-citation-guide.md` for complete reference.\n\n---\n\n## Output\n\n### Primary Output: LaTeX Source\n\nI generate `.tex` files that you can compile with:\n- **Overleaf** (online, recommended)\n- **Local LaTeX**: TinyTeX, MacTeX, TeX Live\n- **VS Code**: LaTeX Workshop extension\n\n### Compilation Commands\n\n```bash\n# IEEE-style (BibTeX)\npdflatex paper.tex\nbibtex paper\npdflatex paper.tex\npdflatex paper.tex\n\n# APA-style (BibLaTeX + biber)\npdflatex paper.tex\nbiber paper\npdflatex paper.tex\npdflatex paper.tex\n\n# Or use latexmk (recommended if available)\nlatexmk -pdf -bibtex paper.tex\nlatexmk -pdf -usebiber paper.tex\n```\n\n### Alternative Outputs\n\nIf LaTeX is not suitable, I can also generate:\n- **Markdown** with MathJax support\n- **DOCX** via Pandoc conversion\n\n---\n\n## Important Notes\n\n- **Quality over quantity** - Fewer well-chosen sources are better than many weak ones\n- **Recent sources preferred** - Last 5-7 years unless historical context needed\n- **Research integrity** - Always cite properly, never plagiarize\n- **Be honest about limitations** - Acknowledge gaps in your research\n- **User provides content** - I structure and write; you provide the research contributions\n\n---\n\n## References\n\n- `references/ieee-citation-guide.md` - Complete IEEE reference examples\n- `references/apa-citation-guide.md` - Complete APA reference examples\n- `references/latex-math-guide.md` - LaTeX math typesetting examples\n- `references/bibliography-workflows.md` - BibTeX/BibLaTeX workflows and verification\n- `references/source-evaluation.md` - Source verification and peer-review labeling\n- `references/systematic-review-prisma.md` - Systematic review workflow (PRISMA-style)\n- `references/literature-review-extraction-matrix.md` - Extraction + thematic synthesis guidance\n- `references/claim-evidence-map.md` - Claim-to-evidence QA template\n- `references/reproducibility-checklist.md` - Reproducibility QA checklist\n- `references/statistical-reporting.md` - Practical statistical reporting guidance\n- `references/threats-to-validity.md` - Threats-to-validity prompts\n- `references/acm-citation-guide.md` - ACM citation format reference\n- `references/revision-response-guide.md` - Reviewer response and revision guidance\n- `references/official-templates.md` - Links to official publisher LaTeX templates\n- `references/templates/` - LaTeX templates (IEEE, APA, thesis, reviews, proposals)\n- `examples/` - Protocols and working templates (vocabulary, extraction matrix, claim-evidence map)\n- `scripts/resolve-papers.js` - Paper discovery and open-access resolution via Semantic Scholar, Unpaywall, CrossRef\n- `scripts/validate-bib.js` - BibTeX entry validation against CrossRef\n- `scripts/check-citations.js` - Citation key consistency checker\n"},"lastSynced":"2026-03-08T02:13:53.875Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Research Agents requiring advanced academic paper generation with proper IEEE and APA citation formats.","zh":"适合需要高级学术论文生成和正确IEEE和APA引用格式的AI研究代理。","ja":"IEEEおよびAPAの引用形式を正しく使用した高度な学術論文の生成を必要とするAI研究エージェントに適しています。","ko":"적절한 IEEE 및 APA 인용 형식을 사용하여 고급 학술 논문을 생성해야 하는 AI 연구 에이전트에 적합합니다.","es":"Ideal para agentes de investigación de IA que requieren generación de artículos académicos avanzados con formatos de citación IEEE y APA adecuados.","fr":"Idéal pour les agents de recherche en IA nécessitant une génération de documents universitaires avancée avec des formats de citation IEEE et APA appropriés.","de":"Ideal für KI-Forschungsagenten, die eine erweiterte Generierung akademischer Aufsätze mit geeigneten IEEE- und APA-Zitierformaten erfordern.","pt":"Ideal para Agentes de Pesquisa de IA que exigem geração avançada de artigos acadêmicos com formatos de citação IEEE e APA adequados.","ru":"Идеально для агентов исследований ИИ, требующих передовой генерации научных статей с правильными форматами цитирования IEEE и APA.","ar":"مثالي لوكلاء البحث الاصطناعي الذين يتطلبون توليد متقدم لالأوراق الأكاديمية يشمل صيغ الاستشهاد IEEE و APA المناسبة."},"recommendation":{"en":"Empowers agents to generate expert-level academic research documents with peer-reviewed source discovery, proper IMRaD structure, and LaTeX output for professional mathematical typesetting, ensuring adherence to scholarly standards and integrity with accurate DOI citations.","zh":"赋予代理生成专家级学术研究文档的能力，具有同行评审来源发现、正确的IMRaD结构和LaTeX输出，用于专业数学排版，确保遵守学术标准和完整性，具有准确的DOI引用。","ja":"同行評価された情報源の発見、適切なIMRaD構造、プロフェッショナルな数学的な組版のためのLaTeX出力を備えた、専門家レベルの学術研究文書を生成するエージェントの能力を与え、学術的な基準と完全性への準拠を確実にし、正確なDOI引用を提供します。","ko":"同行평가를 통해 검증된 정보源을 발견하고, 적절한 IMRaD 구조 및 전문가 수준의 수학적인 편집을 위한 LaTeX 출력을 제공하여, 학술적인 기준 및 완전성을 준수하도록 하며, 정확한 DOI 인용을 보장하는 전문가 수준의 학술 연구 문서를 생성할 수 있는 에이전트의 능력을 제공합니다.","es":"Habilita a los agentes a generar documentos de investigación académica de nivel experto con descubrimiento de fuentes revisadas por pares, estructura IMRaD adecuada y salida LaTeX para compaginación matemática profesional, asegurando el cumplimiento de los estándares académicos y la integridad con citaciones DOI precisas.","fr":"Permet aux agents de générer des documents de recherche universitaires de niveau expert avec une découverte de sources examinées par des pairs, une structure IMRaD appropriée et une sortie LaTeX pour une composition mathématique professionnelle, garantissant le respect des normes universitaires et de l''intégrité avec des citations DOI précises.","de":"Ermöglicht es Agenten, Experten-Niveau akademische Forschungsdokumente mit peer-reviewed Quellenerkennung, geeigneter IMRaD-Struktur und LaTeX-Ausgabe für professionelle mathematische Satzgestaltung zu erstellen, um die Einhaltung akademischer Standards und Integrität mit genauen DOI-Zitaten sicherzustellen.","pt":"Habilita agentes a gerar documentos de pesquisa acadêmica de nível de especialista com descoberta de fontes revisadas por pares, estrutura IMRaD adequada e saída LaTeX para composição matemática profissional, garantindo a adesão a padrões acadêmicos e integridade com citações DOI precisas.","ru":"Наделяет агентов возможностью генерировать экспертно-уровневые документы академических исследований с открытием источников, рассмотренных коллегами, правильной структурой IMRaD и выходными данными LaTeX для профессиональной математической верстки, обеспечивая соблюдение академических стандартов и целостности с точными цитатами DOI.","ar":"يمكّن الوكلاء من توليد وثائق بحثية أكاديمية على مستوى الخبراء مع اكتشاف مصادر تم فحصها من قبل الزملاء، وهيكل IMRaD مناسب ومخرجات LaTeX لتنسيق رياضي محترف، مما يضمن الالتزام بالمعايير الأكاديمية والنزاهة مع استشهادات DOI دقيقة."},"useCases":{"en":["Generating academic research papers with verified sources and citations","Creating properly structured IMRaD documents with LaTeX typesetting","Verifying and validating academic sources against scholarly standards"],"zh":["生成具有已验证来源和引用的学术研究论文","创建具有LaTeX排版的正确结构的IMRaD文档","验证和验证学术来源是否符合学术标准"],"ja":["検証済みの情報源と引用を備えた学術研究論文を生成する","LaTeX組版を備えた適切なIMRaD構造のドキュメントを作成する","学術的基準に従って学術情報源を検証および有効化する"],"ko":["검증된 출처 및 인용을 포함하는 학술 연구 논문을 생성하는 것","LaTeX 편집을 포함하는 적절한 IMRaD 구조의 문서를 생성하는 것","학술 기준에 따라 학술 출처를 검증 및 유효화하는 것"],"es":["Generación de artículos de investigación académica con fuentes verificadas y citaciones","Creación de documentos IMRaD adecuadamente estructurados con tiposetting LaTeX","Verificación y validación de fuentes académicas contra estándares universitarios"],"fr":["Génération de documents de recherche universitaires avec des sources vérifiées et des citations","Création de documents IMRaD structurés correctement avec des typesetting LaTeX","Vérification et validation de sources universitaires contre les normes universitaires"],"de":["Erstellung akademischer Forschungsarbeiten mit verifizierten Quellen und Zitaten","Erstellung ordnungsgemäß strukturierter IMRaD-Dokumente mit LaTeX-Satz","Überprüfung und Validierung akademischer Quellen gegen universitäre Standards"],"pt":["Gerar artigos de pesquisa acadêmica com fontes verificadas e citações","Criar documentos IMRaD estruturados corretamente com tipos de composição LaTeX","Verificar e validar fontes acadêmicas contra padrões acadêmicos"],"ru":["Генерировать научные статьи с проверенными источниками и цитатами","Создавать правильно структурированные документы IMRaD с типографией LaTeX","Проверять и подтверждать академические источники против академических стандартов"],"ar":["توليد أوراق بحثية أكاديمية مع مصادر تم التحقق منها واستشهادات","إنشاء وثائق IMRaD مهيكلة بشكل صحيح مع تنسيق LaTeX","التحقق من صحة المصادر الأكاديمية والتحقق منها ضد المعايير الأكاديمية"]},"limitations":{"en":["Requires access to peer-reviewed academic sources and databases","Limited to IEEE and APA citation formats","Must adhere to strict research integrity standards, including no fabricated citations"],"zh":["需要访问同行评审的学术来源和数据库","仅限于IEEE和APA引用格式","必须遵守严格的研究完整性标准，包括不允许伪造引用"],"ja":["同行評価された学術情報源およびデータベースへのアクセスが必要","IEEEおよびAPAの引用形式のみに限定される","Fabricated引用を含まない厳格な研究の完全性基準への準拠が必要"],"ko":["검증된 학술 출처 및 데이터베이스에 대한 액세스가 필요함","IEEE 및 APA 인용 형식만으로 제한됨","조작된 인용을 포함하지 않는 엄격한 연구 완전성 기준을 준수해야 함"],"es":["Requiere acceso a fuentes académicas revisadas por pares y bases de datos","Limitado a formatos de citación IEEE y APA","Debe cumplir con estrictos estándares de integridad en la investigación, incluyendo no citaciones falsas"],"fr":["Nécessite un accès à des sources universitaires examinées par des pairs et à des bases de données","Limité aux formats de citation IEEE et APA","Doit respecter des normes de recherche strictes, y compris pas de citations falsifiées"],"de":["Erfordert Zugriff auf peer-reviewed akademische Quellen und Datenbanken","Begrenzt auf IEEE- und APA-Zitierformate","Muss strengen Forschungsintegritätsstandards entsprechen, einschließlich keiner gefälschten Zitaten"],"pt":["Exige acesso a fontes acadêmicas revisadas por pares e bases de dados","Limitado a formatos de citação IEEE e APA","Deve aderir a padrões estritos de integridade da pesquisa, incluindo nenhuma citação fabricada"],"ru":["Требует доступа к научным источникам, рассмотренным коллегами, и базам данных","Ограничен форматами цитирования IEEE и APA","Должен соблюдать строгие стандарты целостности исследований, включая отсутствие фабрикованных цитат"],"ar":["يتطلب الوصول إلى مصادر أكاديمية تم فحصها من قبل الزملاء وقواعد البيانات","محدود بصيغ الاستشهاد IEEE و APA","يجب اتباع معايير صارمة للنزاهة البحثية، بما في ذلك عدم وجود استشهادات منحوتة"]},"version":4},"contentHash":"3269cbb1d8305077f5ecc081addc7a3791333f4e01cd6de84d179fc1e942601b","qualityScore":60}');
