INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SiluPanda/academic-researcher/academic-researcher', 'academic-researcher', 'SiluPanda', 'academic-researcher', 'community', 'academic-researcher SiluPanda academic-researcher community The academic-researcher skill generates expert-level academic research papers with peer-reviewed source discovery and proper citation formats, benefiting researchers and academics. AI 学术研究员帮助您创建专家级学术研究文档，具有 LaTeX 输出和 IEEE 引用格式等功能 AIエージェント学術研究者は、LaTeX 出力と IEEE 引用形式などの機能を備えた、専門家レベルの学術研究文書を作成するのに役立ちます AI 학술 연구자는 LaTeX 출력과 IEEE 인용 형식 등의 기능을 제공하여 전문가 수준의 학술 연구 문서를 생성하는 데 도움이 됩니다 El agente de investigación académica te ayuda a crear documentos de investigación expertos con fuentes verificadas y citas en formato IEEE y APA. Utiliza LaTeX para la composición matemática profesional L''outil de recherche académique vous aide à créer des documents de recherche experts avec des sources vérifiées et des citations au format IEEE et APA. Il utilise LaTeX pour la composition mathématique professionnelle Der akademische Forschungsassistent hilft Ihnen bei der Erstellung von Experten-Forschungsdokumenten mit verifizierten Quellen und Zitaten im IEEE- und APA-Format. Er verwendet LaTeX für die professionelle mathematische Satz Nossa ferramenta de IA para pesquisa acadêmica ajuda a criar documentos de nível expert com estrutura IMRaD e convenções de escrita acadêmica, além de formatos de citação IEEE e APA. Наш ИИ Агент для академических исследований помогает создавать экспертные документы с структурой IMRaD и академическими конвенциями письма, а также форматами цитирования IEEE и APA. أداة الذكاء الاصطناعي لدينا للبحث الأكاديمي تساعد على إنشاء مستندات من المستوى الخبير مع هيكل IMRaD و اتفاقيات الكتابة الأكاديمية، بالإضافة إلى صيغ الاستشهاد IEEE و APA. how to use academic-researcher academic-researcher alternative academic-researcher setup guide what is academic-researcher academic-researcher vs research assistant academic-researcher install AI 学术研究员 学术研究文档 LaTeX 输出 IEEE 引用格式 同行评审来源发现 IMRaD 结构 学术写作惯例 AI 工具 学术研究辅助 Peer-reviewed source discovery and verification Proper IMRaD structure and academic writing conventions IEEE and APA citation formats support LaTeX output for professional mathematical typesetting Quality assurance against scholarly standards academic-researcher is a skill that assists in creating academic research documents with verified sources, proper structure, and formatting conventions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jiao360124/lingmou/github-action-gen', 'community', 'jiao360124', 'lingmou', 'jiao360124/lingmou', 'github-action-gen', 0, 0, 60, '2026-03-08T01:57:15.655Z', '2026-03-08T02:13:55.919Z', '702367d412e26389bc4d35ec43bdecb6f104066af8929564c14b51cae4c4fde5', '{"id":"jiao360124/lingmou/github-action-gen","name":"github-action-gen","description":{"en":"github-action-gen generates complete GitHub Actions workflow files, handling common patterns like test, build, and deploy. It benefits developers by providing a quick and easy way to create workflows.","zh":"github-action-gen是GitHub Actions工作流生成器，支持一键生成工作流文件，包括测试、构建和部署","ja":"GitHub Action Generatorは、ワークフローの自動生成を実現するAIエージェントで、テスト、ビルド、デプロイをサポート","ko":"github-action-gen은 GitHub Actions 워크플로우 생성기로서 워크플로우 파일을 자동으로 생성하고 테스트, 빌드 및 배포를 지원","es":"github-action-gen es una herramienta que genera flujos de trabajo de GitHub completos. Automatiza tareas como pruebas, compilación y despliegue","fr":"github-action-gen est un outil qui génère des workflows GitHub complets. Il automatise des tâches comme les tests, la compilation et le déploiement","de":"github-action-gen ist ein Tool, das vollständige GitHub-Workflows generiert. Es automatisiert Aufgaben wie Tests, Build und Deployment","pt":"O github-action-gen é uma ferramenta que gera arquivos de workflow de GitHub Actions personalizados com apenas um comando","ru":"ИИ Агент github-action-gen - это инструмент, который генерирует индивидуальные файлы рабочих процессов GitHub Actions всего за одну команду","ar":"github-action-gen هي أداة تَنتج ملفات سير عمل مخصصة ل GitHub Actions باستخدام أمر واحد"},"seo":{"title":{"en":"github-action-gen: Automated Workflow Generation | AI Age...","zh":"github-action-gen 工作流生成器Setup Guide","ja":"GitHub Action Generator AIエージェントを使用したワークフローの自動生成","ko":"github-action-gen 워크플로우 생성기 Best Practices","es":"Guía de configuración de github-action-gen: Generador de ...","fr":"Guide de mise en place de github-action-gen: Générateur d...","de":"Einrichtungsleitfaden für github-action-gen: GitHub-Workf...","pt":"Guia de Configuração do github-action-gen: Ferramenta de ...","ru":"ИИ Агент github-action-gen: Руководство по Настройке","ar":"دليل إعداد github-action-gen: أداة إنشاء سير عمل"},"description":{"en":"Streamline your GitHub workflow with github-action-gen. Learn how to generate complete workflow files with one command and zero config. Get started now!","zh":"使用github-action-gen生成器，轻松创建GitHub Actions工作流，支持测试、构建和部署","ja":"GitHub Action Generatorを使用して、テスト、ビルド、デプロイを含むワークフローの自動生成を実現","ko":"github-action-gen 생성기를 사용하여 GitHub Actions 워크플로우를 자동으로 생성하고 테스트, 빌드 및 배포를 지원","es":"Descubre cómo generar flujos de trabajo de GitHub con github-action-gen. Aprende a automatizar tareas con este generador de workflows","fr":"Découvrez comment générer des workflows GitHub avec github-action-gen. Apprenez à automatiser des tâches avec ce générateur de workflows","de":"Erfahren Sie, wie Sie mit github-action-gen GitHub-Workflows generieren. Lernen Sie, Aufgaben mit diesem Workflow-Generator zu automatisieren","pt":"Aprenda a usar o github-action-gen para gerar workflows de GitHub Actions personalizados sem precisar copiar e colar código","ru":"Откройте для себя, как использовать ИИ Агент github-action-gen для создания индивидуальных рабочих процессов GitHub Actions","ar":"تعرف على كيفية استخدام github-action-gen لإنشاء سير عمل مخصصة ل GitHub Actions بدون الحاجة إلى نسخ و لصق التعليمات البرمجية"},"definition":{"en":"github-action-gen is a tool that generates complete GitHub Actions workflow files, supporting features like caching and multiple deploy targets.","zh":"github-action-gen是GitHub Actions工作流生成工具，用于自动创建工作流文件","ja":"GitHub Action Generatorは、GitHub Actionsのワークフローの自動生成ツール","ko":"github-action-gen은 GitHub Actions 워크플로우 생성 도구로서 워크플로우 파일을 자동으로 생성","es":"github-action-gen es un generador de flujos de trabajo de GitHub que crea archivos de workflow YAML completos","fr":"github-action-gen est un générateur de workflows GitHub qui crée des fichiers de workflow YAML complets","de":"github-action-gen ist ein GitHub-Workflow-Generator, der vollständige YAML-Workflow-Dateien erstellt","pt":"O github-action-gen é uma ferramenta de linha de comando que gera workflows de GitHub Actions","ru":"ИИ Агент github-action-gen - это командная утилита, которая генерирует рабочие процессы GitHub Actions","ar":"github-action-gen هي أداة سطر أوامر تنتج سير عمل ل GitHub Actions"},"features":{"en":["Generates complete GitHub Actions workflow files","Handles common patterns like test, build, and deploy","Includes caching for faster runs","Supports multiple deploy targets","Can be used with a single command: npx ai-github-action","Zero configuration required"],"zh":["支持一键生成工作流文件","包括测试、构建和部署","支持多个部署目标","包含缓存以提高运行速度","支持使用npx ai-github-action命令行工具"],"ja":["ワークフローの自動生成","テスト、ビルド、デプロイを含む","複数のデプロイ先をサポート","キャッシュを含むことで実行速度を向上","npx ai-github-actionコマンドラインツールを使用"],"ko":["워크플로우 파일을 자동으로 생성","테스트, 빌드 및 배포를 포함","複数의 배포 대상 지원","캐시를 포함하여 실행 속도를 향상","npx ai-github-action 명령줄 도구 사용"],"es":["Genera flujos de trabajo de GitHub completos","Automatiza tareas como pruebas y despliegue","Incluye caché para ejecuciones más rápidas","Soporta múltiples objetivos de despliegue"],"fr":["Génère des workflows GitHub complets","Automatise des tâches comme les tests et le déploiement","Inclut une mise en cache pour des exécutions plus rapides","Prend en charge plusieurs cibles de déploiement"],"de":["Erstellt vollständige GitHub-Workflows","Automatisiert Aufgaben wie Tests und Deployment","Enthält Caching für schnellere Ausführungen","Unterstützt mehrere Deploy-Ziele"],"pt":["Geração de arquivos de workflow de GitHub Actions personalizados","Suporte a padrões comuns como testar e implantar","Inclusão de cache para execuções mais rápidas","Suporte a múltiplos alvos de implantação"],"ru":["Генерация индивидуальных файлов рабочих процессов GitHub Actions","Поддержка общих шаблонов, таких как тестирование и развертывание","Включение кэширования для более быстрых выполнений","Поддержка нескольких целей развертывания"],"ar":["إنشاء ملفات سير عمل مخصصة ل GitHub Actions","دعم الأنماط الشائعة مثل الاختبار و النشر","تشمل التخزين المؤقت لتشغيل أسرع","دعم أهداف نشر متعددة"]},"keywords":{"en":["how to use github-action-gen","github-action-gen setup guide","github-action-gen alternative","github-action-gen vs github actions","github-action-gen install","automated workflow generation","github actions workflow files","github-action-gen tutorial"],"zh":["github-action-gen","GitHub Actions工作流生成","AI工具","工作流自动化","测试和部署","npx ai-github-action","github工作流创建"],"ja":["GitHub Action Generator","GitHub Actionsワークフローの自動生成","AIエージェント","ワークフローの自動化","テストとデプロイ","npx ai-github-action","GitHubワークフローの作成"],"ko":["github-action-gen","GitHub Actions 워크플로우 생성","AI工具","워크플로우 자동화","테스트와 배포","npx ai-github-action","GitHub 워크플로우 생성"],"es":["github action generator","generador de flujos de trabajo de github","automatización de tareas en github","workflow yaml github","github actions","despliegue automático en github"],"fr":["github action generator","générateur de workflows github","automatisation de tâches sur github","fichier workflow yaml github","github actions","déploiement automatique sur github"],"de":["github action generator","github workflow generator","automatisierung von aufgaben in github","yaml workflow datei github","github actions","automatisches deployment in github"],"pt":["github-action-gen","GitHub Actions","workflows personalizados","ferramenta de geração de workflows","linha de comando","CLI","testar e implantar","cache"],"ru":["ИИ Агент github-action-gen","GitHub Actions","индивидуальные рабочие процессы","инструмент генерации рабочих процессов","командная строка","CLI","тестирование и развертывание","кэширование"],"ar":["github-action-gen","GitHub Actions","سير عمل مخصصة","أداة إنشاء سير عمل","سطر أوامر","CLI","الاختبار و النشر","التخزين المؤقت"]}},"owner":"jiao360124","repo":"lingmou","repoPath":"jiao360124/lingmou","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.655Z","topics":[],"category":"community","skillMd":{"name":"github-action-gen","description":"Generate GitHub Actions workflows from plain English. Use when setting up CI.","bodyPreview":"# GitHub Action Generator\n\nStop copy-pasting workflow YAML from StackOverflow. Describe what you want and get a working GitHub Actions workflow.\n\n**One command. Zero config. Just works.**\n\n## Quick Start\n\n```bash\nnpx ai-github-action \"test and deploy on push to main\"\n```\n\n## What It Does\n\n- Generates complete GitHub Actions workflow files\n- Handles common patterns like test, build, deploy\n- Includes caching for faster runs\n- Supports multiple deploy targets\n\n## Usage Examples\n\n```bash\n# Test and","body":"# GitHub Action Generator\n\nStop copy-pasting workflow YAML from StackOverflow. Describe what you want and get a working GitHub Actions workflow.\n\n**One command. Zero config. Just works.**\n\n## Quick Start\n\n```bash\nnpx ai-github-action \"test and deploy on push to main\"\n```\n\n## What It Does\n\n- Generates complete GitHub Actions workflow files\n- Handles common patterns like test, build, deploy\n- Includes caching for faster runs\n- Supports multiple deploy targets\n\n## Usage Examples\n\n```bash\n# Test and deploy\nnpx ai-github-action \"test and deploy on push to main\"\n\n# PR checks\nnpx ai-github-action \"run eslint and prettier on PRs\" --install\n\n# Docker workflow\nnpx ai-github-action \"build docker image and push to ECR\" -o deploy.yml\n\n# Scheduled job\nnpx ai-github-action \"run database backup every night at 2am\"\n```\n\n## Best Practices\n\n- **Use secrets** - never hardcode credentials\n- **Cache dependencies** - saves minutes per run\n- **Fail fast** - run quick checks first\n- **Use matrix builds** - test multiple node versions\n\n## When to Use This\n\n- Setting up CI for a new repo\n- Adding deployment automation\n- Creating custom workflows\n- Learning GitHub Actions syntax\n\n## Part of the LXGIC Dev Toolkit\n\nThis is one of 110+ free developer tools built by LXGIC Studios. No paywalls, no sign-ups, no API keys on free tiers. Just tools that work.\n\n**Find more:**\n- GitHub: https://github.com/LXGIC-Studios\n- Twitter: https://x.com/lxgicstudios\n- Substack: https://lxgicstudios.substack.com\n- Website: https://lxgicstudios.com\n\n## Requirements\n\nNo install needed. Just run with npx. Node.js 18+ recommended. Needs OPENAI_API_KEY environment variable.\n\n```bash\nnpx ai-github-action --help\n```\n\n## How It Works\n\nTakes your plain English description and generates GitHub Actions YAML with the right triggers, jobs, and steps. The AI knows common patterns and best practices for different workflows.\n\n## License\n\nMIT. Free forever. Use it however you want.\n"},"lastSynced":"2026-03-08T02:13:55.919Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Agents requiring streamlined GitHub Actions workflow creation and automation.","zh":"适用于需要简化GitHub Actions工作流创建和自动化的DevOps代理。","ja":"GitHub Actionsワークフローの作成と自動化を簡素化する必要があるDevOpsエージェントに適しています。","ko":"GitHub Actions 워크플로우 생성 및 자동화를 간소화해야 하는 DevOps 에이전트에 적합합니다.","es":"Ideal para agentes de DevOps que requieren una creación y automatización de flujos de trabajo de GitHub Actions optimizados.","fr":"Idéal pour les agents DevOps nécessitant une création et une automatisation de flux de travail GitHub Actions rationalisées.","de":"Ideal für DevOps-Agents, die eine optimierte Erstellung und Automatisierung von GitHub Actions-Workflows benötigen.","pt":"Ideal para Agentes DevOps que exigem criação e automação de fluxos de trabalho do GitHub Actions de forma simplificada.","ru":"Идеально для агентов DevOps, требующих упрощенного создания и автоматизации рабочих процессов GitHub Actions.","ar":"مثالي للوكلاء DevOps الذين يتطلبون إنشاء وتوضيح تدفق عمل GitHub Actions"},"recommendation":{"en":"Empowers agents to generate complete GitHub Actions workflow files handling test, build, and deploy patterns, including caching for faster runs and support for multiple deploy targets using YAML.","zh":"使代理能够生成处理测试、构建和部署模式的完整GitHub Actions工作流文件，包括用于更快运行的缓存和使用YAML支持多个部署目标。","ja":"エージェントがテスト、ビルド、デプロイパターンを処理する完全なGitHub Actionsワークフロー ファイルを生成できるようにし、より速い実行のためのキャッシュとYAMLを使用した複数のデプロイ ターゲットのサポートを含みます。","ko":"에이전트가 테스트, 빌드 및 배포 패턴을 처리하는 완전한 GitHub Actions 워크플로우 파일을 생성할 수 있도록 하며, 더 빠른 실행을 위한 캐싱 및 YAML을 사용한 여러 배포 대상 지원을 포함합니다.","es":"Permite a los agentes generar archivos de flujo de trabajo de GitHub Actions completos que controlen patrones de prueba, compilación y implementación, incluyendo caché para ejecuciones más rápidas y soporte para varios objetivos de implementación utilizando YAML.","fr":"Permet aux agents de générer des fichiers de flux de travail GitHub Actions complets gérant les modèles de test, de build et de déploiement, y compris le caching pour des exécutions plus rapides et la prise en charge de plusieurs cibles de déploiement à l''aide de YAML.","de":"Ermächtigt Agents, vollständige GitHub Actions-Workflow-Dateien zu generieren, die Test-, Build- und Deploy-Muster verarbeiten, einschließlich Caching für schnellere Ausführungen und Unterstützung für mehrere Deploy-Ziele unter Verwendung von YAML.","pt":"Habilita os agentes a gerar arquivos de fluxo de trabalho do GitHub Actions completos, lidando com padrões de teste, compilação e implantação, incluindo cache para execuções mais rápidas e suporte a vários alvos de implantação usando YAML.","ru":"Наделяет агентов возможностью генерировать полные файлы рабочих процессов GitHub Actions, обрабатывающие шаблоны тестирования, сборки и развертывания, включая кэширование для более быстрого выполнения и поддержку нескольких целей развертывания с использованием YAML.","ar":"يمنح الوكلاء القدرة على إنشاء ملفات كاملة لتدفق عمل GitHub Actions، التعامل مع أنماط الاختبار والبناء والنشر، بما في ذلك التخزين المؤقت لأوقات التشغيل الأسرع ودعم أهداف النشر المتعددة باستخدام YAML."},"useCases":{"en":["Automating workflow creation for test and deploy on push to main","Generating workflows with caching for faster execution","Creating deploy workflows for multiple targets"],"zh":["自动为推送到主分支的测试和部署创建工作流","生成具有缓存的工作流以实现更快的执行","为多个目标创建部署工作流"],"ja":["プッシュ時にテストとデプロイのワークフローを作成する自動化","より速い実行のためのキャッシュを含むワークフローを生成する","複数のターゲットのデプロイ ワークフローを作成する"],"ko":["푸시 시 테스트 및 배포를 위한 워크플로우 자동 생성","더 빠른 실행을 위한 캐싱이 포함된 워크플로우 생성","여러 대상의 배포 워크플로우 생성"],"es":["Automatizar la creación de flujos de trabajo para pruebas y despliegue al realizar push en main","Generar flujos de trabajo con caché para una ejecución más rápida","Crear flujos de trabajo de despliegue para varios objetivos"],"fr":["Automatiser la création de flux de travail pour les tests et le déploiement lors d''un push sur main","Générer des flux de travail avec caching pour une exécution plus rapide","Créer des flux de travail de déploiement pour plusieurs cibles"],"de":["Automatisieren der Workflow-Erstellung für Test und Deploy bei Push auf main","Generieren von Workflows mit Caching für schnellere Ausführungen","Erstellen von Deploy-Workflows für mehrere Ziele"],"pt":["Automatizar a criação de fluxos de trabalho para teste e implantação em push para main","Gerar fluxos de trabalho com cache para execução mais rápida","Criar fluxos de trabalho de implantação para vários alvos"],"ru":["Автоматизировать создание рабочих процессов для тестирования и развертывания при пуше в основную ветку","Генерировать рабочие процессы с кэшированием для более быстрого выполнения","Создавать рабочие процессы развертывания для нескольких целей"],"ar":["التحكم الآلي في إنشاء تدفقات العمل للاختبار والنشر عند الضغط على الرئيسي","توليد تدفقات العمل مع التخزين المؤقت للتشغيل الأسرع","إنشاء تدفقات عمل النشر لأهداف متعددة"]},"limitations":{"en":["Requires npm or npx for installation and execution","Limited to GitHub Actions workflow generation"],"zh":["需要npm或npx进行安装和执行","仅限GitHub Actions工作流生成"],"ja":["インストールと実行にはnpmまたはnpxが必要","GitHub Actionsワークフローの生成のみ"],"ko":["설치 및 실행을 위해 npm 또는 npx가 필요","GitHub Actions 워크플로우 생성만"],"es":["Requiere npm o npx para la instalación y ejecución","Limitado a la generación de flujos de trabajo de GitHub Actions"],"fr":["Nécessite npm ou npx pour l''installation et l''exécution","Limité à la génération de flux de travail GitHub Actions"],"de":["Benötigt npm oder npx für die Installation und Ausführung","Eingeschränkt auf die Erstellung von GitHub Actions-Workflows"],"pt":["Exige npm ou npx para instalação e execução","Limitado à geração de fluxos de trabalho do GitHub Actions"],"ru":["Требует npm или npx для установки и выполнения","Ограничен генерацией рабочих процессов GitHub Actions"],"ar":["يتطلب npm أو npx للتثبيت والتشغيل","محدود بالجملة لإنشاء تدفقات عمل GitHub Actions"]},"version":4},"contentHash":"702367d412e26389bc4d35ec43bdecb6f104066af8929564c14b51cae4c4fde5","qualityScore":60}');
