INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jiao360124/lingmou/github-action-gen', 'github-action-gen', 'jiao360124', 'lingmou', 'community', 'github-action-gen jiao360124 lingmou community github-action-gen generates complete GitHub Actions workflow files, handling common patterns like test, build, and deploy. It benefits developers by providing a quick and easy way to create workflows. github-action-gen是GitHub Actions工作流生成器，支持一键生成工作流文件，包括测试、构建和部署 GitHub Action Generatorは、ワークフローの自動生成を実現するAIエージェントで、テスト、ビルド、デプロイをサポート github-action-gen은 GitHub Actions 워크플로우 생성기로서 워크플로우 파일을 자동으로 생성하고 테스트, 빌드 및 배포를 지원 github-action-gen es una herramienta que genera flujos de trabajo de GitHub completos. Automatiza tareas como pruebas, compilación y despliegue github-action-gen est un outil qui génère des workflows GitHub complets. Il automatise des tâches comme les tests, la compilation et le déploiement github-action-gen ist ein Tool, das vollständige GitHub-Workflows generiert. Es automatisiert Aufgaben wie Tests, Build und Deployment O github-action-gen é uma ferramenta que gera arquivos de workflow de GitHub Actions personalizados com apenas um comando ИИ Агент github-action-gen - это инструмент, который генерирует индивидуальные файлы рабочих процессов GitHub Actions всего за одну команду github-action-gen هي أداة تَنتج ملفات سير عمل مخصصة ل GitHub Actions باستخدام أمر واحد how to use github-action-gen github-action-gen setup guide github-action-gen alternative github-action-gen vs github actions github-action-gen install automated workflow generation github actions workflow files github-action-gen tutorial github-action-gen GitHub Actions工作流生成 AI工具 工作流自动化 测试和部署 npx ai-github-action github工作流创建 Generates complete GitHub Actions workflow files Handles common patterns like test, build, and deploy Includes caching for faster runs Supports multiple deploy targets Can be used with a single command: npx ai-github-action Zero configuration required github-action-gen is a tool that generates complete GitHub Actions workflow files, supporting features like caching and multiple deploy targets.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('0xti4n/codex-cli/babysit-pr', 'community', '0xti4n', 'codex-cli', '0xti4n/codex-cli', 'babysit-pr', 0, 0, 60, '2026-03-08T01:06:54Z', '2026-03-08T02:14:14.628Z', '165e7c05a4d5a7d1ba58afca15c3539f48b2b0cf0c3c251a0e644b2a1434ecf5', '{"id":"0xti4n/codex-cli/babysit-pr","name":"babysit-pr","description":{"en":"The babysit-pr skill automates the PR management process, persistently monitoring PRs until they are merged, closed, or require user intervention. This benefits developers by reducing manual effort and increasing productivity in CI/CD pipelines.","zh":"babysit-pr 是一个持续监控 PR 请求的工具，确保 CI 成功和代码审查。","ja":"babysit-pr は PR リクエストを永続的に監視するツールで、CI 成功とコードレビューを確実に行います。","ko":"babysit-pr는 PR 요청을 지속적으로 모니터링하는 도구로 CI 성공과 코드 리뷰를 보장합니다.","es":"babysit-pr es una herramienta que automatiza el proceso de PR, supervisando persistentemente hasta que se alcanza un resultado terminal, como la fusión o cierre de la PR","fr":"babysit-pr est un outil qui automatise le processus de PR, surveillant de manière persistante jusqu''à ce qu''un résultat terminal soit atteint, comme la fusion ou la fermeture de la PR","de":"babysit-pr ist ein Tool, das den PR-Prozess automatisiert, indem es persistent überwacht, bis ein Endresultat erreicht ist, wie die Zusammenführung oder Schließung der PR","pt":"O babysit-pr é uma ferramenta de automação que monitora persistentemente as PRs até que ocorra um dos resultados finais, como merge ou fechamento.","ru":"Babysit-PR - это инструмент автоматизации, который постоянно отслеживает PR до тех пор, пока не произойдет один из конечных результатов, таких как слияние или закрытие.","ar":"babysit-pr هو أداة آليّة تراقب الطلبات بثبات حتى تحدث واحدة من النتائج النهائية، مثل الدمج أو الإغلاق."},"seo":{"title":{"en":"babysit-pr: Automated PR Management Setup Guide | AI Agen...","zh":"babysit-pr Setup Guide: 持续监控 PR 请求","ja":"babysit-pr の設定方法: PR リクエストの永続的な監視","ko":"babysit-pr 설정 가이드: PR 요청 지속적 모니터링","es":"Guía de configuración de babysit-pr: Automatización de PR","fr":"Configurer babysit-pr: Outil d''automatisation de PR","de":"Einrichten von babysit-pr: PR-Automatisierungstool","pt":"Guia de Configuração do Babysit-PR: Automação de PRs","ru":"Настройка Babysit-PR: ИИ Агенты для Автоматизации PR","ar":"دليل إعداد babysit-pr: أدوات ذكاء اصطناعي لمراقبة الطلبات"},"description":{"en":"Streamline your PR workflow with babysit-pr. Learn how to automate PR management and resolve merge conflicts efficiently. Get started now!","zh":"了解如何使用 babysit-pr 持续监控 PR 请求，确保 CI 成功和代码审查","ja":"babysit-pr を使用して PR リクエストを永続的に監視し、CI 成功とコードレビューを確実に行う方法","ko":"babysit-pr를 사용하여 PR 요청을 지속적으로 모니터링하고 CI 성공 및 코드 리뷰를 보장하는 방법","es":"Aprende a configurar babysit-pr para automatizar el proceso de PR y mejorar la eficiencia de tu flujo de trabajo de desarrollo","fr":"Découvrez comment configurer babysit-pr pour automatiser le processus de PR et améliorer l''efficacité de votre flux de travail de développement","de":"Erfahren Sie, wie Sie babysit-pr einrichten, um den PR-Prozess zu automatisieren und die Effizienz Ihres Entwicklungswerkflusses zu verbessern","pt":"Aprenda a configurar o babysit-pr para automatizar o processo de PRs e melhorar a eficiência do seu fluxo de trabalho de desenvolvimento","ru":"Узнайте, как настроить Babysit-PR для автоматизации процесса PR и повысить эффективность вашего рабочего процесса разработки с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد babysit-pr لتحسين自动ية عملية الطلبات وزيادة كفاءة سير عمل التطوير باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"babysit-pr is a persistent PR babysitter that automates the management of pull requests until they reach a terminal outcome, such as merge, closure, or requiring user help.","zh":"babysit-pr 是一个持续监控 PR 请求的工具，用于确保 CI 成功和代码审查。","ja":"babysit-pr は PR リクエストを永続的に監視するツールで、CI 成功とコードレビューを確実に行うために使用されます。","ko":"babysit-pr는 PR 요청을 지속적으로 모니터링하는 도구로 CI 성공과 코드 리뷰를 보장하기 위해 사용됩니다.","es":"babysit-pr es una herramienta de automatización de PR que supervisa y gestiona el proceso de revisión de código","fr":"babysit-pr est un outil d''automatisation de PR qui surveille et gère le processus de révision de code","de":"babysit-pr ist ein PR-Automatisierungstool, das den Code-Überprüfungsprozess überwacht und verwaltet","pt":"O que é babysit-pr? É uma ferramenta de automação de PRs que monitora e gerencia o processo de revisão e merge.","ru":"Что такое Babysit-PR? Это инструмент автоматизации PR, который отслеживает и управляет процессом проверки и слияния.","ar":"ما هو babysit-pr؟ هو أداة آليّة لمراقبة الطلبات التي تراقب وتدير عملية المراجعة والدمج."},"features":{"en":["Monitors PRs for successful CI outcomes","Checks for unaddressed review comments","Verifies required review approval","Detects potential merge conflicts","Automates PR management until terminal outcome","Handles situations requiring user help, such as CI infrastructure issues"],"zh":["持续监控 PR 请求","自动检查 CI 成功","代码审查和评论监控","合并冲突检测","重试-budget 耗尽时的用户帮助"],"ja":["PR リクエストの永続的な監視","CI 成功の自動チェック","コードレビューとコメントの監視","マージコンフリクトの検出","リトライ予算の枯渇時にユーザーが介入"],"ko":["PR 요청의 지속적인 모니터링","CI 성공의 자동 확인","코드 리뷰 및 댓글 모니터링","병합 충돌 감지","재시도 예산 소진 시 사용자 도움"],"es":["Supervisión persistente de la PR hasta que se alcanza un resultado terminal","Automatización de la revisión de código y aprobación de cambios","Detección de conflictos de fusión y problemas de infraestructura de CI","Notificación de situaciones que requieren ayuda del usuario","Integración con herramientas de CI y sistemas de gestión de código"],"fr":["Surveillance persistante de la PR jusqu''à ce qu''un résultat terminal soit atteint","Automatisation de la révision de code et de l''approbation des modifications","Détection de conflits de fusion et de problèmes d''infrastructure de CI","Notification de situations nécessitant l''aide de l''utilisateur","Intégration avec des outils de CI et des systèmes de gestion de code"],"de":["Persistente Überwachung der PR bis ein Endresultat erreicht ist","Automatisierung der Code-Überprüfung und Änderungs-Genehmigung","Erkennung von Merge-Konflikten und CI-Infrastrukturproblemen","Benachrichtigung über Situationen, die Benutzereingriff erfordern","Integration mit CI-Tools und Code-Management-Systemen"],"pt":["Monitoramento persistente de PRs","Integração com CI para verificar a sucesso da compilação","Análise de comentários de revisão e aprovação de revisão","Detecção de conflitos de merge potenciais","Notificação de situações que requerem ajuda do usuário"],"ru":["Постоянный мониторинг PR","Интеграция с CI для проверки успешной сборки","Анализ комментариев к ревью и одобрения ревью","Обнаружение потенциальных конфликтов слияния","Уведомление о ситуациях, требующих помощи пользователя"],"ar":["مراقبة دائمة للطلبات","التكامل مع CI لتحقق من نجاح الترجمة","تحليل تعليقات المراجعة وموافقة المراجعة","اكتشاف تضارب دمج محتمل","إخطار بالحالات التي تتطلب مساعدة المستخدم"]},"keywords":{"en":["how to use babysit-pr","babysit-pr alternative","babysit-pr setup guide","what is babysit-pr","babysit-pr vs github actions","babysit-pr install","automated pr management","ci/cd pipeline optimization","pr management tools"],"zh":["babysit-pr","PR 请求监控","CI 成功","代码审查","合并冲突检测","AI 工具","持续集成","代码质量保证"],"ja":["babysit-pr","PR リクエストの監視","CI 成功","コードレビュー","マージコンフリクトの検出","AI エージェント","継続的インテグレーション","コード品質保証"],"ko":["babysit-pr","PR 요청 모니터링","CI 성공","코드 리뷰","병합 충돌 감지","AI 도구","지속적인 통합","코드 품질 보증"],"es":["herramientas de automatización de PR","automatización de revisión de código","gestión de flujo de trabajo de desarrollo","herramientas de CI","sistemas de gestión de código","automatización de aprobación de cambios","detección de conflictos de fusión","notificación de problemas de infraestructura de CI"],"fr":["outils d''automatisation de PR","automatisation de la révision de code","gestion du flux de travail de développement","outils de CI","systèmes de gestion de code","automatisation de l''approbation des modifications","détection de conflits de fusion","notification de problèmes d''infrastructure de CI"],"de":["PR-Automatisierungstools","Code-Überprüfungsautomatisierung","Entwicklungswerkfluss-Management","CI-Tools","Code-Management-Systeme","Änderungs-Genehmigungsautomatisierung","Merge-Konflikt-Erkennung","Benachrichtigung über CI-Infrastrukturprobleme"],"pt":["babysit-pr","automação de PRs","ferramentas de desenvolvimento","CI","revisão de código","merge de código","desenvolvimento de software"],"ru":["Babysit-PR","автоматизация PR","инструменты разработки","CI","ревью кода","слияние кода","разработка программного обеспечения","ИИ Агенты"],"ar":["babysit-pr","أدوات تطوير","مراقبة الطلبات","CI","مراجعة الكود","دمج الكود","تطوير البرمجيات","أدوات الذكاء الاصطناعي"]}},"owner":"0xti4n","repo":"codex-cli","repoPath":"0xti4n/codex-cli","stars":0,"forks":0,"updatedAt":"2026-03-08T01:06:54Z","topics":[],"category":"community","skillMd":{"name":"babysit-pr","description":"Babysit a GitHub pull request after creation by continuously polling CI checks/workflow runs, new review comments, and mergeability state until the PR is ready to merge (or merged/closed). Diagnose failures, retry likely flaky failures up to 3 times, auto-fix/push branch-related issues when appropriate, and stop only when user help is required (for example CI infrastructure issues, exhausted flaky retries, or ambiguous/blocking situations). Use when the user asks Codex to monitor a PR, watch CI, handle review comments, or keep an eye on failures and feedback on an open PR.","bodyPreview":"# PR Babysitter\n\n## Objective\nBabysit a PR persistently until one of these terminal outcomes occurs:\n\n- The PR is merged or closed.\n- CI is successful, there are no unaddressed review comments surfaced by the watcher, required review approval is not blocking merge, and there are no potential merge conflicts (PR is mergeable / not reporting conflict risk).\n- A situation requires user help (for example CI infrastructure issues, repeated flaky failures after retry budget is exhausted, permission pr","body":"# PR Babysitter\n\n## Objective\nBabysit a PR persistently until one of these terminal outcomes occurs:\n\n- The PR is merged or closed.\n- CI is successful, there are no unaddressed review comments surfaced by the watcher, required review approval is not blocking merge, and there are no potential merge conflicts (PR is mergeable / not reporting conflict risk).\n- A situation requires user help (for example CI infrastructure issues, repeated flaky failures after retry budget is exhausted, permission problems, or ambiguity that cannot be resolved safely).\n\nDo not stop merely because a single snapshot returns `idle` while checks are still pending.\n\n## Inputs\nAccept any of the following:\n\n- No PR argument: infer the PR from the current branch (`--pr auto`)\n- PR number\n- PR URL\n\n## Core Workflow\n\n1. When the user asks to \"monitor\"/\"watch\"/\"babysit\" a PR, start with the watcher''s continuous mode (`--watch`) unless you are intentionally doing a one-shot diagnostic snapshot.\n2. Run the watcher script to snapshot PR/CI/review state (or consume each streamed snapshot from `--watch`).\n3. Inspect the `actions` list in the JSON response.\n4. If `diagnose_ci_failure` is present, inspect failed run logs and classify the failure.\n5. If the failure is likely caused by the current branch, patch code locally, commit, and push.\n6. If `process_review_comment` is present, inspect surfaced review items and decide whether to address them.\n7. If a review item is actionable and correct, patch code locally, commit, and push.\n8. If the failure is likely flaky/unrelated and `retry_failed_checks` is present, rerun failed jobs with `--retry-failed-now`.\n9. If both actionable review feedback and `retry_failed_checks` are present, prioritize review feedback first; a new commit will retrigger CI, so avoid rerunning flaky checks on the old SHA unless you intentionally defer the review change.\n10. On every loop, verify mergeability / merge-conflict status (for example via `gh pr view`) in addition to CI and review state.\n11. After any push or rerun action, immediately return to step 1 and continue polling on the updated SHA/state.\n12. If you had been using `--watch` before pausing to patch/commit/push, relaunch `--watch` yourself in the same turn immediately after the push (do not wait for the user to re-invoke the skill).\n13. Repeat polling until the PR is green + review-clean + mergeable, `stop_pr_closed` appears, or a user-help-required blocker is reached.\n14. Maintain terminal/session ownership: while babysitting is active, keep consuming watcher output in the same turn; do not leave a detached `--watch` process running and then end the turn as if monitoring were complete.\n\n## Commands\n\n### One-shot snapshot\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --once\n```\n\n### Continuous watch (JSONL)\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --watch\n```\n\n### Trigger flaky retry cycle (only when watcher indicates)\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr auto --retry-failed-now\n```\n\n### Explicit PR target\n\n```bash\npython3 .codex/skills/babysit-pr/scripts/gh_pr_watch.py --pr <number-or-url> --once\n```\n\n## CI Failure Classification\nUse `gh` commands to inspect failed runs before deciding to rerun.\n\n- `gh run view <run-id> --json jobs,name,workflowName,conclusion,status,url,headSha`\n- `gh run view <run-id> --log-failed`\n\nPrefer treating failures as branch-related when logs point to changed code (compile/test/lint/typecheck/snapshots/static analysis in touched areas).\n\nPrefer treating failures as flaky/unrelated when logs show transient infra/external issues (timeouts, runner provisioning failures, registry/network outages, GitHub Actions infra errors).\n\nIf classification is ambiguous, perform one manual diagnosis attempt before choosing rerun.\n\nRead `.codex/skills/babysit-pr/references/heuristics.md` for a concise checklist.\n\n## Review Comment Handling\nThe watcher surfaces review items from:\n\n- PR issue comments\n- Inline review comments\n- Review submissions (COMMENT / APPROVED / CHANGES_REQUESTED)\n\nIt intentionally surfaces Codex reviewer bot feedback (for example comments/reviews from `chatgpt-codex-connector[bot]`) in addition to human reviewer feedback. Most unrelated bot noise should still be ignored.\nFor safety, the watcher only auto-surfaces trusted human review authors (for example repo OWNER/MEMBER/COLLABORATOR, plus the authenticated operator) and approved review bots such as Codex.\nOn a fresh watcher state file, existing pending review feedback may be surfaced immediately (not only comments that arrive after monitoring starts). This is intentional so already-open review comments are not missed.\n\nWhen you agree with a comment and it is actionable:\n\n1. Patch code locally.\n2. Commit with `codex: address PR review feedback (#<n>)`.\n3. Push to the PR head branch.\n4. Resume watching on the new SHA immediately (do not stop after reporting the push).\n5. If monitoring was running in `--watch` mode, restart `--watch` immediately after the push in the same turn; do not wait for the user to ask again.\n\nIf you disagree or the comment is non-actionable/already addressed, record it as handled by continuing the watcher loop (the script de-duplicates surfaced items via state after surfacing them).\nIf a code review comment/thread is already marked as resolved in GitHub, treat it as non-actionable and safely ignore it unless new unresolved follow-up feedback appears.\n\n## Git Safety Rules\n\n- Work only on the PR head branch.\n- Avoid destructive git commands.\n- Do not switch branches unless necessary to recover context.\n- Before editing, check for unrelated uncommitted changes. If present, stop and ask the user.\n- After each successful fix, commit and `git push`, then re-run the watcher.\n- If you interrupted a live `--watch` session to make the fix, restart `--watch` immediately after the push in the same turn.\n- Do not run multiple concurrent `--watch` processes for the same PR/state file; keep one watcher session active and reuse it until it stops or you intentionally restart it.\n- A push is not a terminal outcome; continue the monitoring loop unless a strict stop condition is met.\n\nCommit message defaults:\n\n- `codex: fix CI failure on PR #<n>`\n- `codex: address PR review feedback (#<n>)`\n\n## Monitoring Loop Pattern\nUse this loop in a live Codex session:\n\n1. Run `--once`.\n2. Read `actions`.\n3. First check whether the PR is now merged or otherwise closed; if so, report that terminal state and stop polling immediately.\n4. Check CI summary, new review items, and mergeability/conflict status.\n5. Diagnose CI failures and classify branch-related vs flaky/unrelated.\n6. Process actionable review comments before flaky reruns when both are present; if a review fix requires a commit, push it and skip rerunning failed checks on the old SHA.\n7. Retry failed checks only when `retry_failed_checks` is present and you are not about to replace the current SHA with a review/CI fix commit.\n8. If you pushed a commit or triggered a rerun, report the action briefly and continue polling (do not stop).\n9. After a review-fix push, proactively restart continuous monitoring (`--watch`) in the same turn unless a strict stop condition has already been reached.\n10. If everything is passing, mergeable, not blocked on required review approval, and there are no unaddressed review items, report success and stop.\n11. If blocked on a user-help-required issue (infra outage, exhausted flaky retries, unclear reviewer request, permissions), report the blocker and stop.\n12. Otherwise sleep according to the polling cadence below and repeat.\n\nWhen the user explicitly asks to monitor/watch/babysit a PR, prefer `--watch` so polling continues autonomously in one command. Use repeated `--once` snapshots only for debugging, local testing, or when the user explicitly asks for a one-shot check.\nDo not stop to ask the user whether to continue polling; continue autonomously until a strict stop condition is met or the user explicitly interrupts.\nDo not hand control back to the user after a review-fix push just because a new SHA was created; restarting the watcher and re-entering the poll loop is part of the same babysitting task.\nIf a `--watch` process is still running and no strict stop condition has been reached, the babysitting task is still in progress; keep streaming/consuming watcher output instead of ending the turn.\n\n## Polling Cadence\nUse adaptive polling and continue monitoring even after CI turns green:\n\n- While CI is not green (pending/running/queued or failing): poll every 1 minute.\n- After CI turns green: start at every 1 minute, then back off exponentially when there is no change (for example 1m, 2m, 4m, 8m, 16m, 32m), capping at every 1 hour.\n- Reset the green-state polling interval back to 1 minute whenever anything changes (new commit/SHA, check status changes, new review comments, mergeability changes, review decision changes).\n- If CI stops being green again (new commit, rerun, or regression): return to 1-minute polling.\n- If any poll shows the PR is merged or otherwise closed: stop polling immediately and report the terminal state.\n\n## Stop Conditions (Strict)\nStop only when one of the following is true:\n\n- PR merged or closed (stop as soon as a poll/snapshot confirms this).\n- PR is ready to merge: CI succeeded, no surfaced unaddressed review comments, not blocked on required review approval, and no merge conflict risk.\n- User intervention is required and Codex cannot safely proceed alone.\n\nKeep polling when:\n\n- `actions` contains only `idle` but checks are still pending.\n- CI is still running/queued.\n- Review state is quiet but CI is not terminal.\n- CI is green but mergeability is unknown/pending.\n- CI is green and mergeable, but the PR is still open and you are waiting for possible new review comments or merge-conflict changes per the green-state cadence.\n- The PR is green but blocked on review approval (`REVIEW_REQUIRED` / similar); continue polling on the green-state cadence and surface any new review comments without asking for confirmation to keep watching.\n\n## Output Expectations\nProvide concise progress updates while monitoring and a final summary that includes:\n\n- During long unchanged monitoring periods, avoid emitting a full update on every poll; summarize only status changes plus occasional heartbeat updates.\n- Treat push confirmations, intermediate CI snapshots, and review-action updates as progress updates only; do not emit the final summary or end the babysitting session unless a strict stop condition is met.\n- A user request to \"monitor\" is not satisfied by a couple of sample polls; remain in the loop until a strict stop condition or an explicit user interruption.\n- A review-fix commit + push is not a completion event; immediately resume live monitoring (`--watch`) in the same turn and continue reporting progress updates.\n- When CI first transitions to all green for the current SHA, emit a one-time celebratory progress update (do not repeat it on every green poll). Preferred style: `🚀 CI is all green! 33/33 passed. Still on watch for review approval.`\n- Do not send the final summary while a watcher terminal is still running unless the watcher has emitted/confirmed a strict stop condition; otherwise continue with progress updates.\n\n- Final PR SHA\n- CI status summary\n- Mergeability / conflict status\n- Fixes pushed\n- Flaky retry cycles used\n- Remaining unresolved failures or review comments\n\n## References\n\n- Heuristics and decision tree: `.codex/skills/babysit-pr/references/heuristics.md`\n- GitHub CLI/API details used by the watcher: `.codex/skills/babysit-pr/references/github-api-notes.md`\n"},"lastSynced":"2026-03-08T02:14:14.628Z","agentAnalysis":{"suitability":{"en":"Ideal for CI/CD Pipeline Agents needing automated PR management and monitoring capabilities.","zh":"适用于需要自动化PR管理和监控能力的CI/CD Pipeline Agents。","ja":"CI/CDパイプラインエージェントが自動化されたPR管理と監視機能を必要とする場合に最適です。","ko":"자동화된 PR 관리 및 모니터링 기능이 필요한 CI/CD 파이프라인 에이전트에 적합합니다.","es":"Ideal para agentes de canalización de CI/CD que necesitan funcionalidades de gestión y seguimiento de PR automatizadas.","fr":"Idéal pour les agents de pipeline CI/CD nécessitant une gestion et un suivi de PR automatisés.","de":"Ideal für CI/CD-Pipeline-Agents, die eine automatisierte PR-Verwaltung und Überwachungsfunktion benötigen.","pt":"Ideal para agentes de pipeline CI/CD que necessitam de gerenciamento e monitoramento de PR automatizados.","ru":"Идеально для агентов конвейера CI/CD, которым необходимы автоматизированное управление и мониторинг PR.","ar":"مثالي للوكلاء قناة CI/CD الذين يحتاجون إلى إدارة ومراقبة PR آليين."},"recommendation":{"en":"Empowers agents to persistently monitor PRs until they are merged, closed, or require user intervention, leveraging CI/CD pipeline automation and reducing manual effort, while also handling potential merge conflicts and CI infrastructure issues through protocols like Git and GitHub APIs.","zh":"赋予代理持续监控PR的能力，直到它们被合并、关闭或需要用户干预，利用CI/CD流水线自动化并减少手动努力，同时也通过Git和GitHub API等协议处理潜在的合并冲突和CI基础设施问题。","ja":"エージェントがPRをマージ、クローズ、またはユーザー介入が必要になるまで継続的に監視する能力を提供し、CI/CDパイプラインの自動化を活用して手動労力を減らし、GitおよびGitHub APIなどのプロトコルを介して潜在的なマージの競合やCIインフラストラクチャの問題も処理します。","ko":"에이전트가 PR을 병합, 닫음 또는 사용자 개입이 필요한 경우까지 지속적으로 모니터링 할 수 있는 능력을 부여하여 CI/CD 파이프라인 자동화 및 수동 노력을 줄이며 Git 및 GitHub API 등의 프로토콜을 통해 잠재적인 병합 충돌 및 CI 인프라 문제도 처리합니다.","es":"Habilita a los agentes a monitorear persistentemente las PR hasta que se fusionen, cierren o requieran intervención del usuario, aprovechando la automatización de la canalización de CI/CD y reduciendo el esfuerzo manual, así como también manejar posibles conflictos de fusión y problemas de infraestructura de CI a través de protocolos como Git y GitHub APIs.","fr":"Permet aux agents de surveiller en permanence les PR jusqu''à ce qu''elles soient fusionnées, closes ou nécessitent une intervention utilisateur, en exploitant l''automatisation de la pipeline CI/CD et en réduisant les efforts manuels, ainsi que en gérant les conflits de fusion potentiels et les problèmes d''infrastructure CI via des protocoles comme Git et GitHub APIs.","de":"Ermächtigt die Agenten, PRs persistent zu überwachen, bis sie zusammengeführt, geschlossen oder eine Benutzereingriff erfordern, und nutzt die Automatisierung der CI/CD-Pipeline, um den manuellen Aufwand zu reduzieren, und kann auch potenzielle Merge-Konflikte und CI-Infrastrukturprobleme über Protokolle wie Git und GitHub APIs handhaben.","pt":"Habilita os agentes a monitorar persistentemente os PRs até que sejam mesclados, fechados ou necessitem de intervenção do usuário, aproveitando a automação do pipeline CI/CD e reduzindo o esforço manual, além de lidar com possíveis conflitos de mesclagem e problemas de infraestrutura de CI por meio de protocolos como Git e GitHub APIs.","ru":"Наделяет агентов возможностью постоянно отслеживать PR до тех пор, пока они не будут слиты, закрыты или не потребуют вмешательства пользователя, используя автоматизацию конвейера CI/CD и снижая ручные усилия, а также обрабатывая потенциальные конфликты слияния и проблемы инфраструктуры CI с помощью протоколов, таких как Git и GitHub APIs.","ar":"يمكّن الوكلاء من مراقبة مستمرة لطلبات الإدماج حتى يتم دمجها أو إغلاقها أو تتطلب تدخلاً من المستخدم، مستفيداً من تلقائية قناة CI/CD وتقليل الجهد اليدوي، بالإضافة إلى التعامل مع تضارب الإدماج المحتملة وقضايا بنية تحتية CI من خلال بروتوكولات مثل Git و GitHub APIs."},"useCases":{"en":["Automating PR monitoring for merge or close","Debugging CI infrastructure issues causing flaky failures","Identifying potential merge conflicts in PRs"],"zh":["自动化PR监控以合并或关闭","调试导致不稳定故障的CI基础设施问题","识别PR中的潜在合并冲突"],"ja":["マージまたはクローズのためのPR監視の自動化","不安定な失敗を引き起こすCIインフラストラクチャの問題のデバッグ","PR内の潜在的なマージの競合の特定"],"ko":["병합 또는 닫기 위한 PR 모니터링 자동화","불안정한 실패를 유발하는 CI 인프라 문제 디버깅","PR 내의 잠재적인 병합 충돌 식별"],"es":["Automatización del seguimiento de PR para la fusión o el cierre","Depuración de problemas de infraestructura de CI que causan fallos inestables","Identificación de posibles conflictos de fusión en PR"],"fr":["Automatisation du suivi des PR pour la fusion ou la fermeture","Débogage des problèmes d''infrastructure CI causant des échecs instables","Identification de conflits de fusion potentiels dans les PR"],"de":["Automatisierung der Überwachung von PR für Merge oder Schließen","Fehlerbehebung bei CI-Infrastrukturproblemen, die zu unzuverlässigen Fehlern führen","Identifizierung von potenziellen Merge-Konflikten in PR"],"pt":["Automatizar monitoramento de PR para mesclagem ou fechamento","Depurar problemas de infraestrutura de CI que causam falhas instáveis","Identificar conflitos de mesclagem potenciais em PRs"],"ru":["Автоматизировать мониторинг PR для слияния или закрытия","Отладить проблемы инфраструктуры CI, вызывающие нестабильные сбои","Определить потенциальные конфликты слияния в PR"],"ar":["تأتمتة مراقبة طلبات الإدماج للدمج أو الإغلاق","تصحيح أخطاء بنية تحتية CI التي تسبب فشلات غير مستقرة","تحديد تضارب الإدماج المحتملة في طلبات الإدماج"]},"limitations":{"en":["Requires GitHub API access","Limited to Git-based version control systems","Needs permission to access and manage PRs"],"zh":["需要GitHub API访问","仅限于Git 기반的版本控制系统","需要访问和管理PR的权限"],"ja":["GitHub APIへのアクセスが必要","Gitベースのバージョン管理システムに限定される","PRへのアクセスおよび管理の許可が必要"],"ko":["GitHub API 액세스가 필요합니다.","Git 기반 버전 관리 시스템에만 제한됩니다.","PR에 액세스 및 관리를 허용해야 합니다."],"es":["Requiere acceso a GitHub API","Limitado a sistemas de control de versiones basados en Git","Necesita permiso para acceder y gestionar PR"],"fr":["Nécessite un accès à GitHub API","Limité aux systèmes de contrôle de version basés sur Git","Nécessite une autorisation pour accéder et gérer les PR"],"de":["Benötigt Zugriff auf GitHub API","Begrenzt auf Git-basierte Versionskontrollsysteme","Benötigt Berechtigung zum Zugriff und zur Verwaltung von PR"],"pt":["Requer acesso à API do GitHub","Limitado a sistemas de controle de versão baseados em Git","Necessita de permissão para acessar e gerenciar PRs"],"ru":["Требует доступа к API GitHub","Ограничен системами контроля версий на основе Git","Требует разрешения на доступ и управление PR"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات GitHub","محدود بنظم تحكم بالإصدارات القائمة على Git","يحتاج إلى إذن للوصول إلى وإدارة طلبات الإدماج"]},"version":4},"contentHash":"165e7c05a4d5a7d1ba58afca15c3539f48b2b0cf0c3c251a0e644b2a1434ecf5","qualityScore":60}');
