INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('0xti4n/codex-cli/babysit-pr', 'babysit-pr', '0xti4n', 'codex-cli', 'community', 'babysit-pr 0xti4n codex-cli community The babysit-pr skill automates the PR management process, persistently monitoring PRs until they are merged, closed, or require user intervention. This benefits developers by reducing manual effort and increasing productivity in CI/CD pipelines. babysit-pr 是一个持续监控 PR 请求的工具，确保 CI 成功和代码审查。 babysit-pr は PR リクエストを永続的に監視するツールで、CI 成功とコードレビューを確実に行います。 babysit-pr는 PR 요청을 지속적으로 모니터링하는 도구로 CI 성공과 코드 리뷰를 보장합니다. babysit-pr es una herramienta que automatiza el proceso de PR, supervisando persistentemente hasta que se alcanza un resultado terminal, como la fusión o cierre de la PR babysit-pr est un outil qui automatise le processus de PR, surveillant de manière persistante jusqu''à ce qu''un résultat terminal soit atteint, comme la fusion ou la fermeture de la PR babysit-pr ist ein Tool, das den PR-Prozess automatisiert, indem es persistent überwacht, bis ein Endresultat erreicht ist, wie die Zusammenführung oder Schließung der PR O babysit-pr é uma ferramenta de automação que monitora persistentemente as PRs até que ocorra um dos resultados finais, como merge ou fechamento. Babysit-PR - это инструмент автоматизации, который постоянно отслеживает PR до тех пор, пока не произойдет один из конечных результатов, таких как слияние или закрытие. babysit-pr هو أداة آليّة تراقب الطلبات بثبات حتى تحدث واحدة من النتائج النهائية، مثل الدمج أو الإغلاق. how to use babysit-pr babysit-pr alternative babysit-pr setup guide what is babysit-pr babysit-pr vs github actions babysit-pr install automated pr management ci/cd pipeline optimization pr management tools babysit-pr PR 请求监控 CI 成功 代码审查 合并冲突检测 AI 工具 持续集成 代码质量保证 Monitors PRs for successful CI outcomes Checks for unaddressed review comments Verifies required review approval Detects potential merge conflicts Automates PR management until terminal outcome Handles situations requiring user help, such as CI infrastructure issues babysit-pr is a persistent PR babysitter that automates the management of pull requests until they reach a terminal outcome, such as merge, closure, or requiring user help.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xingyun-New/Skills-XiaoSiMen/math-teacher', 'community', 'xingyun-New', 'Skills-XiaoSiMen', 'xingyun-New/Skills-XiaoSiMen', 'math-teacher', 0, 0, 60, '2026-03-08T01:41:49Z', '2026-03-08T02:14:26.038Z', 'dc48e105d412bf924c97d2d027a759f871ed0feadda307b10c8ac745309813ac', '{"id":"xingyun-New/Skills-XiaoSiMen/math-teacher","name":"math-teacher","description":{"en":"The math-teacher skill transforms math learning into interactive, visual experiences, benefiting students and educators alike. It creates interactive HTML/JS artifacts on demand and scales from basic arithmetic to advanced calculus.","zh":"Math Teacher AI工具是一种交互式的数学学习工具，通过即时生成交互式HTML/JS工件、自适应学习和视觉化学习，实现数学学习的创新","ja":"Math Teacher AIエージェントは、インタラクティブな数学学習ツールであり、即時生成のHTML/JSアーティファクト、適応学習、視覚学習を提供します","ko":"Math Teacher AI 도구는 즉각적인 플레이그라운드 생성, 적응형 학습, 시각적 학습을 통해 수학 학습을 혁신하는 인터랙티브 수학 학습 도구입니다","es":"Math Teacher es un agente de aprendizaje interactivo que genera experiencias de aprendizaje visuales y divertidas a través de artefactos interactivos y desafíos gamificados","fr":"Math Teacher est un agent d''apprentissage interactif qui génère des expériences d''apprentissage visuelles et amusantes à travers des artefacts interactifs et des défis gamifiés","de":"Math Teacher ist ein interaktiver Lernagent, der visuelle und unterhaltsame Lernerfahrungen durch interaktive Artefakte und gamifizierte Herausforderungen generiert","pt":"O Professor de Matemática é um agente interativo que gera experiências de aprendizado de matemática em tempo real, utilizando HTML/JS e aprendizado adaptativo","ru":"ИИ Агент Математического Преподавателя - это интерактивный агент, генерирующий математические задачи в режиме реального времени, используя HTML/JS и адаптивное обучение","ar":"معلم الرياضيات الإصطناعي هو وكيل تفاعلي يولد تجارب تعليمية رياضية في الوقت الفعلي، باستخدام HTML/JS وتعلم متكيف"},"seo":{"title":{"en":"math-teacher: Interactive Math Learning Setup Guide | AI ...","zh":"Math Teacher AI工具设置指南","ja":"Math Teacher AIエージェントのベストプラクティス","ko":"Math Teacher AI 도구 설치 가이드","es":"Guía de Configuración para Math Teacher: Generación de Ap...","fr":"Guide de Mise en Route pour Math Teacher: Expériences d''A...","de":"Einrichtungsleitfaden für Math Teacher: Interaktive Lernu...","pt":"Guia de Configuração do Professor de Matemática","ru":"Настройка ИИ Агента Математического Преподавателя","ar":"دليل إعداد معلم الرياضيات الإصطناعي"},"description":{"en":"Unlock interactive math learning with math-teacher! Discover how to generate engaging experiences through HTML/JS artifacts, adaptive learning, and visual pl...","zh":"Math Teacher AI工具，通过交互式的HTML/JS工件、自适应学习和视觉化学习，实现数学学习的创新","ja":"Math Teacher AIエージェントは、インタラクティブなHTML/JSアーティファクト、適応学習、視覚学習を提供します","ko":"Math Teacher AI 도구는 즉각적인 플레이그라운드 생성, 적응형 학습, 시각적 학습을 통해 수학 학습을 혁신합니다","es":"Descubre cómo Math Teacher transforma el aprendizaje de matemáticas en experiencias visuales e interactivas con generación de playgrounds y desafíos gamificados","fr":"Découvrez comment Math Teacher transforme l''apprentissage des mathématiques en expériences visuelles et interactives avec génération de playgrounds et défis ...","de":"Erfahren Sie, wie Math Teacher das Mathe-Lernen in interaktive und visuelle Erfahrungen mit Playground-Generierung und gamifizierten Herausforderungen umwandelt","pt":"Descubra como o Professor de Matemática cria experiências de aprendizado interativas com geração instantânea de playgrounds e aprendizado adaptativo","ru":"Узнайте, как ИИ Агент Математического Преподавателя генерирует интерактивные математические задачи и адаптивное обучение","ar":"اكتشف كيف يقوم معلم الرياضيات الإصطناعي بإنشاء تجارب تعليمية تفاعلية مع توليد فوري للعبة وتعلم متكيف"},"definition":{"en":"math-teacher is an interactive, playful math teacher that generates engaging learning experiences through interactive artifacts, visual playgrounds, and gamified challenges.","zh":"Math Teacher AI工具是一种通过交互式HTML/JS工件、自适应学习和视觉化学习实现数学学习的创新AI工具","ja":"Math Teacher AIエージェントは、インタラクティブなHTML/JSアーティファクト、適応学習、視覚学習を提供する数学学習のためのAIエージェントです","ko":"Math Teacher AI 도구는 즉각적인 플레이그라운드 생성, 적응형 학습, 시각적 학습을 통해 수학 학습을 혁신하는 AI 도구입니다","es":"Math Teacher es un agente de aprendizaje de matemáticas que utiliza HTML/JS para crear experiencias interactivas y visuales","fr":"Math Teacher est un agent d''apprentissage des mathématiques qui utilise HTML/JS pour créer des expériences interactives et visuelles","de":"Math Teacher ist ein Mathe-Lernagent, der HTML/JS verwendet, um interaktive und visuelle Erfahrungen zu erstellen","pt":"O que é um Professor de Matemática? É um agente de IA que cria experiências de aprendizado de matemática interativas e visuais","ru":"Что такое ИИ Агент Математического Преподавателя? Это агент, генерирующий интерактивные математические задачи и визуальное обучение","ar":"ما هو معلم الرياضيات الإصطناعي؟ هو وكيل إصطناعي يولد تجارب تعليمية رياضية تفاعلية ومرئية"},"features":{"en":["Instant Playground Generation using HTML/JS","Adaptive Learning that scales from basic arithmetic to advanced calculus","Visual Learning through graphs, animations, and interactive visuals","Creates interactive HTML/JS artifacts on demand","Supports gamified challenges for enhanced engagement","Generates interactive visual playgrounds for immersive learning"],"zh":["即时生成交互式HTML/JS工件","自适应学习：从基本算术到高级微积分","视觉化学习：图表、动画和交互式可视化","游戏化挑战"],"ja":["インタラクティブなHTML/JSアーティファクトの即時生成","適応学習：基本的な算術から高度な微積分まで","視覚学習：グラフ、アニメーション、インタラクティブな視覚化","ゲーム化されたチャレンジ"],"ko":["즉각적인 플레이그라운드 생성","적응형 학습: 기본 산수에서 고급 미적분까지","시각적 학습: 그래프, 애니메이션, 인터랙티브 시각화","게임화된 도전"],"es":["Generación instantánea de playgrounds interactivos","Aprendizaje adaptativo desde aritmética básica hasta cálculo avanzado","Aprendizaje visual con gráficos, animaciones y visualizaciones interactivas","Desafíos gamificados para aumentar la motivación del estudiante","Uso de HTML/JS para crear artefactos interactivos","Escalabilidad para satisfacer las necesidades de estudiantes de diferentes niveles"],"fr":["Génération instantanée de playgrounds interactifs","Apprentissage adaptatif depuis l''arithmétique de base jusqu''au calcul avancé","Apprentissage visuel avec des graphiques, des animations et des visualisations interactives","Défis gamifiés pour augmenter la motivation de l''étudiant","Utilisation de HTML/JS pour créer des artefacts interactifs","Évolutivité pour répondre aux besoins des étudiants de différents niveaux"],"de":["Instant-Playground-Generierung für interaktive Lernerfahrungen","Adaptives Lernen von grundlegender Arithmetik bis hin zu fortgeschrittenem Kalkül","Visuelles Lernen mit Grafiken, Animationen und interaktiven Visualisierungen","Gamifizierte Herausforderungen zur Steigerung der Schülermotivation","Verwendung von HTML/JS zur Erstellung interaktiver Artefakte","Skalierbarkeit zur Erfüllung der Bedürfnisse von Schülern unterschiedlicher Niveaus"],"pt":["Geração instantânea de playgrounds interativos","Aprendizado adaptativo em matemática","Experiências de aprendizado visuais com gráficos e animações","Desafios gamificados para aprendizado de matemática","Suporte a HTML/JS para criação de artefatos interativos","Escalabilidade de aprendizado, desde aritmética básica até cálculo avançado"],"ru":["Генерация интерактивных математических задач в режиме реального времени","Адаптивное обучение математике","Визуальное обучение с графиками и анимациями","Геймифицированные задачи для обучения математике","Поддержка HTML/JS для создания интерактивных артефактов","Масштабируемость обучения, от базовой арифметики до высшего исчисления"],"ar":["توليد فوري للعبة رياضية تفاعلية","تعلم متكيف في الرياضيات","تجارب تعليمية مرئية مع الرسومات والتحريك","تحديات ملعبة لتعلم الرياضيات","دعم HTML/JS لإنشاء مكونات تفاعلية","توسعة التعلم، من الحساب الأساسي إلى التفاضل والتكامل المتقدم"]},"keywords":{"en":["how to use math-teacher","what is math-teacher","math-teacher alternative","math-teacher vs Khan Academy","math-teacher install","math-teacher setup guide","interactive math learning","adaptive learning software","visual math education"],"zh":["Math Teacher AI工具","AI数学学习","交互式HTML/JS工件","自适应学习","视觉化学习","游戏化挑战","数学教育","AI教育工具"],"ja":["Math Teacher AIエージェント","AI数学学習","インタラクティブなHTML/JSアーティファクト","適応学習","視覚学習","ゲーム化されたチャレンジ","数学教育","AI教育ツール"],"ko":["Math Teacher AI 도구","AI 수학 학습","즉각적인 플레이그라운드 생성","적응형 학습","시각적 학습","게임화된 도전","수학 교육","AI 교육 도구"],"es":["Math Teacher","agentes de aprendizaje de matemáticas","herramientas de aprendizaje interactivo","generación de playgrounds","aprendizaje adaptativo","visualización de datos","gamificación en educación","HTML/JS en educación","tecnologías emergentes en educación"],"fr":["Math Teacher","agents d''apprentissage des mathématiques","outils d''apprentissage interactif","génération de playgrounds","apprentissage adaptatif","visualisation de données","gamification dans l''éducation","HTML/JS dans l''éducation","technologies émergentes dans l''éducation"],"de":["Math Teacher","Mathe-Lernagenten","interaktive Lernwerkzeuge","Playground-Generierung","adaptives Lernen","Datenvisualisierung","Gamification in der Bildung","HTML/JS in der Bildung","emergente Technologien in der Bildung"],"pt":["Professor de Matemática","Aprendizado de Matemática","Experiências de Aprendizado Interativas","Geração de Playground","Aprendizado Adaptativo","Matemática Interativa","HTML/JS em Educação","Ferramentas de Aprendizado de Matemática"],"ru":["ИИ Агент Математического Преподавателя","Обучение Математике","Интерактивные Математические Задачи","Генерация Математических Задач","Адаптивное Обучение","Математика в Режиме Реального Времени","HTML/JS в Образовании","Инструменты для Обучения Математике"],"ar":["معلم الرياضيات الإصطناعي","تعلم الرياضيات","تجارب تعليمية رياضية تفاعلية","توليد رياضية تفاعلية","تعلم متكيف","رياضيات في الوقت الفعلي","HTML/JS في التعليم","أدوات تعلم الرياضيات"]}},"owner":"xingyun-New","repo":"Skills-XiaoSiMen","repoPath":"xingyun-New/Skills-XiaoSiMen","stars":0,"forks":0,"updatedAt":"2026-03-08T01:41:49Z","topics":[],"category":"community","skillMd":{"name":"math-teacher","description":"Interactive math teacher that instantly generates playful, gamified learning experiences. Creates visual playgrounds, interactive artifacts, and engaging games for kids and adults to learn math concepts from basic arithmetic to advanced calculus.","bodyPreview":"# Math Teacher\n\nAn interactive, playful math teacher that instantly generates engaging learning experiences through interactive artifacts, visual playgrounds, and gamified challenges.\n\n## What This Skill Does\n\nTransforms math learning into interactive, visual experiences:\n- **Instant Playground Generation** - Creates interactive HTML/JS artifacts on demand\n- **Adaptive Learning** - Scales from basic arithmetic to advanced calculus\n- **Visual Learning** - Graphs, animations, and interactive visua","body":"# Math Teacher\n\nAn interactive, playful math teacher that instantly generates engaging learning experiences through interactive artifacts, visual playgrounds, and gamified challenges.\n\n## What This Skill Does\n\nTransforms math learning into interactive, visual experiences:\n- **Instant Playground Generation** - Creates interactive HTML/JS artifacts on demand\n- **Adaptive Learning** - Scales from basic arithmetic to advanced calculus\n- **Visual Learning** - Graphs, animations, and interactive visualizations\n- **Gamification** - Points, achievements, challenges, and progress tracking\n- **Question-Driven** - User asks, teacher generates custom learning experiences\n- **Playful Techniques** - Engaging animations, rewards, and fun challenges\n- **No Setup Required** - All artifacts work standalone in browser\n\n## Why This Skill Matters\n\n**Traditional math learning:**\n- Abstract concepts without visualization\n- Passive reading and memorization\n- One-size-fits-all approach\n- Boring drills and repetition\n- Limited interactivity\n- Difficult to stay engaged\n\n**With this skill:**\n- Instant visual understanding\n- Active learning through play\n- Personalized to your level\n- Fun, game-like challenges\n- Immediate feedback loops\n- High engagement and retention\n\n## Core Principles\n\n### 1. Learn by Doing\n- Interactive manipulatives\n- Experiment with variables\n- Real-time feedback\n- Hands-on exploration\n- Visual experimentation\n\n### 2. Gamification First\n- Points and achievements\n- Progress tracking\n- Level systems\n- Challenges and streaks\n- Leaderboards (personal bests)\n- Reward animations\n\n### 3. Visual Learning\n- Dynamic graphs and charts\n- Animated demonstrations\n- Color-coded explanations\n- Interactive diagrams\n- Step-by-step visualizations\n\n### 4. Instant Gratification\n- Generate artifacts immediately\n- No setup or installation\n- Works in any browser\n- Shareable playgrounds\n- Mobile-friendly\n\n### 5. Adaptive Complexity\n- Starts simple, grows complex\n- Detects skill level\n- Progressive difficulty\n- Scaffolded learning\n- Multiple approaches\n\n## Math Topics Covered\n\n### Elementary (Ages 6-12)\n- **Arithmetic**: Addition, subtraction, multiplication, division\n- **Fractions**: Visual fraction bars, equivalent fractions\n- **Geometry**: Shapes, angles, perimeter, area\n- **Patterns**: Number sequences, visual patterns\n- **Word Problems**: Interactive story problems\n- **Time & Money**: Clock reading, coin counting\n\n### Middle School (Ages 12-15)\n- **Pre-Algebra**: Variables, expressions, equations\n- **Ratios & Proportions**: Scale drawings, unit rates\n- **Percentages**: Discounts, interest, growth\n- **Statistics**: Mean, median, mode, graphs\n- **Basic Geometry**: Pythagorean theorem, volume\n- **Integers**: Negative numbers, operations\n\n### High School (Ages 15-18)\n- **Algebra**: Linear equations, quadratics, polynomials\n- **Functions**: Domain/range, graphing, transformations\n- **Trigonometry**: Sin, cos, tan, unit circle\n- **Geometry**: Proofs, similarity, coordinate geometry\n- **Pre-Calculus**: Limits, sequences, series\n- **Statistics**: Probability, distributions, analysis\n\n### Advanced (College+)\n- **Calculus**: Derivatives, integrals, optimization\n- **Linear Algebra**: Matrices, vectors, transformations\n- **Differential Equations**: ODEs, PDEs, modeling\n- **Complex Analysis**: Complex numbers, mappings\n- **Abstract Algebra**: Groups, rings, fields\n- **Real Analysis**: Sequences, series, convergence\n\n## Interactive Playground Examples\n\n### Example 1: Fraction Visualizer (Elementary)\n\n**User asks:** \"Help me understand fractions\"\n\n**Teacher generates:** An interactive pizza fraction visualizer with:\n- Visual pizza slices to understand fractions\n- Interactive sliders to change numerator/denominator\n- Real-time percentage calculation\n- Gamified with points and achievements\n- Equivalent fraction finder\n- Color-coded, playful design\n\n(See `/references/examples/fraction-visualizer.html` for full implementation)\n\n### Example 2: Quadratic Explorer (High School)\n\n**User asks:** \"I don''t understand quadratic functions\"\n\n**Teacher generates:** Interactive graph with sliders for a, b, c coefficients, showing:\n- Real-time parabola graphing\n- Vertex highlighting\n- Roots (x-intercepts) marked\n- Axis of symmetry\n- Discriminant explanation\n- Points for discovering special cases\n\n### Example 3: Derivative Visualizer (Advanced)\n\n**User asks:** \"Show me how derivatives work\"\n\n**Teacher generates:** Interactive calculus playground with:\n- Function input field\n- Tangent line at any point\n- Secant line animation showing limit\n- Slope calculation display\n- Common derivative rules reference\n- Challenge mode: guess the derivative\n\n## Gamification System\n\n### Points & Rewards\n- **Exploration Points** (5pts): Try different values\n- **Discovery Points** (10pts): Find special cases\n- **Mastery Points** (20pts): Complete challenges\n- **Streak Bonus** (2x): Consecutive correct answers\n- **Speed Bonus** (1.5x): Quick correct responses\n\n### Achievements\n- 🌟 **First Steps**: Complete first problem\n- 🔥 **Hot Streak**: 5 correct in a row\n- 🎯 **Bullseye**: Perfect score on challenge\n- 🏆 **Math Master**: 1000 points earned\n- 💡 **Eureka**: Discover hidden pattern\n- 🚀 **Speed Demon**: 10 problems under 5 min\n\n### Progress Tracking\n- Problems attempted\n- Success rate\n- Points earned\n- Current streak\n- Time spent learning\n- Topics mastered\n\n### Challenge Modes\n- **Time Attack**: Solve as many as possible\n- **Accuracy Mode**: Get perfect answers\n- **Exploration**: Discover patterns\n- **Boss Battle**: Complex multi-step problems\n- **Daily Challenge**: New problem each day\n\n## Playful Learning Techniques\n\n### 1. Storytelling\nMath problems wrapped in engaging narratives:\n- \"Space mission\" for algebra\n- \"Treasure hunt\" for geometry\n- \"Recipe scaling\" for ratios\n- \"Game design\" for functions\n\n### 2. Visual Metaphors\nAbstract concepts made concrete:\n- Derivatives = \"speedometer\"\n- Integrals = \"area under curve\"\n- Variables = \"mystery boxes\"\n- Functions = \"magic machines\"\n\n### 3. Progressive Hints\nScaffolded support system:\n- Level 1: Gentle nudge\n- Level 2: Show strategy\n- Level 3: Step-by-step\n- Level 4: Full solution\n\n### 4. Immediate Feedback\nReal-time learning loops:\n- Color-coded correctness\n- Encouraging messages\n- Error explanations\n- Try-again suggestions\n\n### 5. Celebration Animations\nReward correct answers:\n- Confetti explosions\n- Success sounds\n- Growing score counter\n- Achievement popups\n\n## Artifact Generation Patterns\n\n### Standard Playground Structure\n\nEvery generated artifact follows this pattern:\n- Header with title and score display\n- Visual representation area (canvas, SVG, or HTML elements)\n- Interactive controls (sliders, inputs, buttons)\n- Explanation section with real-time feedback\n- Gamification elements (points, achievements, streaks)\n- Self-contained HTML with inline CSS and JavaScript\n- Responsive design for mobile/tablet/desktop\n- Playful, colorful styling with animations\n\n### Key Features in Every Artifact\n\n✅ **Visual**: Graphs, animations, diagrams\n✅ **Interactive**: Sliders, inputs, buttons\n✅ **Responsive**: Works on mobile/tablet/desktop\n✅ **Gamified**: Points, achievements, feedback\n✅ **Educational**: Clear explanations\n✅ **Accessible**: Keyboard navigation, ARIA labels\n✅ **Standalone**: No external dependencies\n\n## Usage Patterns\n\n### Pattern 1: Concept Explanation\n**User:** \"Explain [concept]\"\n**Teacher:** Generates interactive visualization + step-by-step guide\n\n### Pattern 2: Practice Problems\n**User:** \"Give me practice problems for [topic]\"\n**Teacher:** Creates randomized problem generator with hints\n\n### Pattern 3: Visual Understanding\n**User:** \"Show me [concept] visually\"\n**Teacher:** Builds animated demonstration with controls\n\n### Pattern 4: Challenge Mode\n**User:** \"Challenge me on [topic]\"\n**Teacher:** Creates timed quiz game with leaderboard\n\n### Pattern 5: Exploration\n**User:** \"Let me explore [concept]\"\n**Teacher:** Makes open sandbox with guided experiments\n\n## Technical Implementation\n\n### Key Techniques\n- **Canvas Drawing**: Use HTML5 Canvas API for graphs and visualizations\n- **Real-time Updates**: Event listeners that update on user input\n- **Animation Loops**: RequestAnimationFrame for smooth animations\n- **Responsive Design**: CSS Grid, Flexbox, and media queries\n- **No Dependencies**: Pure HTML/CSS/JavaScript (no libraries required)\n\n## Reference Materials\n\nAll included in `/references`:\n- **basic_math.md** - Elementary concepts and techniques\n- **algebra.md** - Algebraic patterns and formulas\n- **geometry.md** - Geometric principles and visualizations\n- **calculus.md** - Derivatives, integrals, limits\n- **statistics.md** - Probability and data analysis\n- **gamification.md** - Game mechanics and reward systems\n\n## Scripts\n\nAll in `/scripts`:\n- **generate_playground.sh** - Create interactive math playground\n- **generate_game.sh** - Build gamified math challenge\n- **generate_quiz.sh** - Create adaptive quiz system\n- **publish-playground.md** - GitHub Pages auto-publish workflow\n\n## Auto-Publish to GitHub Pages\n\nAfter generating any HTML file (playground or game), **automatically execute the publish workflow** (see [publish-playground.md](scripts/publish-playground.md)):\n\n1. Write the HTML to `math-playgrounds/` or `math-games/` directory\n2. Construct the GitHub Pages URL: `https://xingyun-new.github.io/Skills-XiaoSiMen/{dir}/{filename}`\n3. Append a new entry to the math section in the project root `README.md`\n4. Run `git add` → `git commit` → `git push origin main`\n5. Share the online link with the user\n\nThis step runs automatically after every HTML generation — no extra user instruction needed.\n\n## Implementation Approach\n\n**IMPORTANT:** When this skill is invoked, use the Bash tool to execute the appropriate script.\n\n### How to use the scripts:\n\n1. **For general math games/challenges:** Use `generate_game.sh`\n   ```bash\n   bash /Users/jamesrochabrun/Desktop/skills/skills/math-teacher/scripts/generate_game.sh\n   ```\n\n2. **For interactive playgrounds:** Use `generate_playground.sh`\n   ```bash\n   bash /Users/jamesrochabrun/Desktop/skills/skills/math-teacher/scripts/generate_playground.sh\n   ```\n\n3. **For quizzes:** Use `generate_quiz.sh` (if it exists)\n   ```bash\n   bash /Users/jamesrochabrun/Desktop/skills/skills/math-teacher/scripts/generate_quiz.sh\n   ```\n\n**DO NOT** try to invoke these scripts automatically when the skill loads - this causes bash security errors. Always use the Bash tool explicitly to run them.\n\n## Best Practices\n\n### DO:\n✅ Make it visual and interactive\n✅ Start simple, add complexity gradually\n✅ Use colors and animations\n✅ Provide immediate feedback\n✅ Celebrate successes\n✅ Include hints and explanations\n✅ Make it fun and playful\n✅ Support mobile devices\n\n### DON''T:\n❌ Show just formulas without context\n❌ Make it text-heavy\n❌ Assume prior knowledge\n❌ Skip the gamification\n❌ Ignore visual learners\n❌ Make it intimidating\n❌ Use boring, academic tone\n❌ Require external libraries\n\n## Example Interactions\n\n**Beginner:**\n> \"I want to learn multiplication\"\n\n*Generates: Interactive times table grid game with click-to-reveal cards, progress tracking, and achievement badges*\n\n**Intermediate:**\n> \"Help me understand the Pythagorean theorem\"\n\n*Generates: Visual right triangle builder where you can drag vertices, see a², b², c² squares, and animated proof*\n\n**Advanced:**\n> \"Show me how to optimize a function\"\n\n*Generates: 3D surface plot with gradient descent visualization, adjustable learning rate, and path tracing*\n\n## Summary\n\nThis skill transforms math education by:\n- **Instant Engagement** - Generates playgrounds immediately\n- **Visual Learning** - Graphs, animations, interactive diagrams\n- **Gamification** - Points, achievements, challenges\n- **Adaptive Difficulty** - From elementary to advanced\n- **Self-Contained** - All artifacts work standalone\n- **Playful** - Fun, colorful, rewarding\n- **Effective** - Learn by doing and exploring\n\n**\"Math should be an adventure, not a chore.\"** 🚀\n\n---\n\n**Usage:** Ask any math question, request a concept explanation, or say \"teach me [topic]\" and get an instant, interactive learning experience!\n"},"lastSynced":"2026-03-08T02:14:26.038Z","agentAnalysis":{"suitability":{"en":"Perfect for Educational Agents needing interactive math learning experiences with HTML/JS artifact generation.","zh":"非常适合需要交互式数学学习体验的教育代理，能够生成HTML/JS文档。","ja":"教育エージェントがインタラクティブな数学学習体験を必要とする場合に最適で、HTML/JSアーティファクトを生成できます。","ko":"교 dục 에이전트가 대화형 수학 학습 경험을 필요로 할 때 적합하며 HTML/JS 아티팩트를 생성할 수 있습니다.","es":"Perfecto para Agentes Educativos que necesitan experiencias de aprendizaje de matemáticas interactivas con generación de artefactos HTML/JS.","fr":"Parfait pour les agents éducatifs ayant besoin d''expériences d''apprentissage de mathématiques interactives avec génération d''artefacts HTML/JS.","de":"Perfekt für Bildungsagenten, die interaktive Mathe-Lernerfahrungen mit HTML/JS-Artefaktgenerierung benötigen.","pt":"Perfeito para Agentes Educacionais que necessitam de experiências de aprendizado de matemática interativas com geração de artefatos HTML/JS.","ru":"Идеально подходит для образовательных агентов, которым необходимы интерактивные математические обучающие trải nghiệm с генерацией артефактов HTML/JS.","ar":"مثالي للوكلاء التعليميين الذين يحتاجون إلى تجارب تعلم رياضيات تفاعلية مع توليد مكونات HTML/JS."},"recommendation":{"en":"Empowers agents to create adaptive learning environments through instant playground generation, utilizing interactive HTML/JS artifacts, and visual aids like graphs and animations, all scalable from basic arithmetic to advanced calculus using JavaScript libraries.","zh":"赋予代理创建自适应学习环境的能力，通过即时生成操场，利用交互式HTML/JS文档和可视化辅助工具，如图表和动画，所有这些都可以从基本算术到高级微积分使用JavaScript库进行扩展。","ja":"エージェントが即時プレイグラウンド生成を利用してインタラクティブなHTML/JSアーティファクトやグラフ、アニメーションなどのビジュアルエイドを使用して、基本的な算術から高度な微積分まで、JavaScriptライブラリを使用して拡張可能な自適応学習環境を作成できるようにします。","ko":"에이전트가 즉각적인 놀이터 생성을 통해 대화형 HTML/JS 아티팩트와 그래프, 애니메이션 등의 시각적 보조 도구를 사용하여 기본 산술부터 고급 미적분까지 자바스크립트 라이브러리를 사용하여 확장할 수 있는 자기 적응 학습 환경을 만들 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a crear entornos de aprendizaje adaptativos a través de la generación instantánea de entornos de juego, utilizando artefactos HTML/JS interactivos y ayudas visuales como gráficos y animaciones, todo escalable desde aritmética básica hasta cálculo avanzado utilizando bibliotecas de JavaScript.","fr":"Permet aux agents de créer des environnements d''apprentissage adaptatifs grâce à la génération instantanée de playgrounds, en utilisant des artefacts HTML/JS interactifs et des aides visuelles comme des graphiques et des animations, le tout scalable depuis l''arithmétique de base jusqu''au calcul avancé en utilisant des bibliothèques JavaScript.","de":"Ermächtigt Agenten, adaptive Lernumgebungen durch instantane Spielplatzgenerierung zu erstellen, unter Verwendung interaktiver HTML/JS-Artefakte und visueller Hilfsmittel wie Grafiken und Animationen, alles skaliert von grundlegender Arithmetik bis hin zu fortgeschrittenem Kalkül unter Verwendung von JavaScript-Bibliotheken.","pt":"Habilita os agentes a criar ambientes de aprendizado adaptativos por meio da geração instantânea de playgrounds, utilizando artefatos HTML/JS interativos e recursos visuais como gráficos e animações, todos dimensionáveis desde a aritmética básica até o cálculo avançado usando bibliotecas JavaScript.","ru":"Наделяет агентов возможностью создавать адаптивные обучающие среды посредством мгновенной генерации площадок, используя интерактивные артефакты HTML/JS и визуальные средства, такие как графики и анимации, все масштабируемые от базовой арифметики до высшего исчисления с использованием библиотек JavaScript.","ar":"يُعطي الوكلاء القدرة على إنشاء بيئات تعلم متكيفة من خلال توليد ساحات لعب فورية، باستخدام مكونات HTML/JS التفاعلية والمساعدات البصرية مثل الرسوم والرسوم المتحركة، وكلها قابلة للتوسيع من الحسابات الأساسية إلى التفاضل والتكامل المتقدم باستخدام مكتبات JavaScript."},"useCases":{"en":["Generating interactive math lessons for students","Creating visual aids for calculus explanations","Developing gamified math challenges for educational platforms"],"zh":["为学生生成交互式数学课程","为微积分解释创建可视化辅助工具","为教育平台开发游戏化数学挑战"],"ja":["学生向けのインタラクティブな数学レッスンを生成","微積分の説明用のビジュアルエイドを作成","教育プラットフォーム用のゲーム化された数学課題を開発"],"ko":["학생을 위한 대화형 수학 수업 생성","미적분 설명을 위한 시각적 보조 도구 생성","교육 플랫폼을 위한 게임화된 수학 도전 개발"],"es":["Generar lecciones de matemáticas interactivas para estudiantes","Crear ayudas visuales para explicaciones de cálculo","Desarrollar desafíos de matemáticas gamificados para plataformas educativas"],"fr":["Générer des leçons de mathématiques interactives pour les étudiants","Créer des aides visuelles pour les explications de calcul","Développer des défis de mathématiques gamifiés pour les plateformes éducatives"],"de":["Interaktive Mathe-Lektionen für Schüler generieren","Visuelle Hilfsmittel für Erklärungen von Kalkül erstellen","Gamifizierte Mathe-Herausforderungen für Bildungsplattformen entwickeln"],"pt":["Gerar aulas de matemática interativas para estudantes","Criar recursos visuais para explicações de cálculo","Desenvolver desafios de matemática gamificados para plataformas educacionais"],"ru":["Генерировать интерактивные математические уроки для студентов","Создавать визуальные средства для объяснения исчисления","Разрабатывать игровые математические задачи для образовательных платформ"],"ar":["توليد دروس رياضيات تفاعلية للطلاب","إنشاء مساعدات بصرية لشرح التفاضل والتكامل","تطوير تحديات رياضيات متكاملة للمنصات التعليمية"]},"limitations":{"en":["Requires JavaScript execution environment","Limited to math subjects from basic arithmetic to advanced calculus"],"zh":["需要JavaScript执行环境","仅限于从基本算术到高级微积分的数学科目"],"ja":["JavaScript実行環境が必要","基本的な算術から高度な微積分までの数学科目に限定"],"ko":["자바스크립트 실행 환경이 필요","기본 산술부터 고급 미적분까지의 수학 과목으로 제한"],"es":["Requiere un entorno de ejecución de JavaScript","Limitado a materias de matemáticas desde aritmética básica hasta cálculo avanzado"],"fr":["Nécessite un environnement d''exécution JavaScript","Limité aux matières de mathématiques depuis l''arithmétique de base jusqu''au calcul avancé"],"de":["Benötigt eine JavaScript-Ausführungsumgebung","Begrenzt auf Mathematikfächer von grundlegender Arithmetik bis hin zu fortgeschrittenem Kalkül"],"pt":["Exige ambiente de execução JavaScript","Limitado a matérias de matemática desde a aritmética básica até o cálculo avançado"],"ru":["Требует среды выполнения JavaScript","Ограничен предметами математики от базовой арифметики до высшего исчисления"],"ar":["يتطلب بيئة تشغيل JavaScript","محدود بمواد الرياضيات من الحسابات الأساسية إلى التفاضل والتكامل المتقدم"]},"version":4},"contentHash":"dc48e105d412bf924c97d2d027a759f871ed0feadda307b10c8ac745309813ac","qualityScore":60}');
