INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xingyun-New/Skills-XiaoSiMen/math-teacher', 'math-teacher', 'xingyun-New', 'Skills-XiaoSiMen', 'community', 'math-teacher xingyun-New Skills-XiaoSiMen community The math-teacher skill transforms math learning into interactive, visual experiences, benefiting students and educators alike. It creates interactive HTML/JS artifacts on demand and scales from basic arithmetic to advanced calculus. Math Teacher AI工具是一种交互式的数学学习工具，通过即时生成交互式HTML/JS工件、自适应学习和视觉化学习，实现数学学习的创新 Math Teacher AIエージェントは、インタラクティブな数学学習ツールであり、即時生成のHTML/JSアーティファクト、適応学習、視覚学習を提供します Math Teacher AI 도구는 즉각적인 플레이그라운드 생성, 적응형 학습, 시각적 학습을 통해 수학 학습을 혁신하는 인터랙티브 수학 학습 도구입니다 Math Teacher es un agente de aprendizaje interactivo que genera experiencias de aprendizaje visuales y divertidas a través de artefactos interactivos y desafíos gamificados Math Teacher est un agent d''apprentissage interactif qui génère des expériences d''apprentissage visuelles et amusantes à travers des artefacts interactifs et des défis gamifiés Math Teacher ist ein interaktiver Lernagent, der visuelle und unterhaltsame Lernerfahrungen durch interaktive Artefakte und gamifizierte Herausforderungen generiert O Professor de Matemática é um agente interativo que gera experiências de aprendizado de matemática em tempo real, utilizando HTML/JS e aprendizado adaptativo ИИ Агент Математического Преподавателя - это интерактивный агент, генерирующий математические задачи в режиме реального времени, используя HTML/JS и адаптивное обучение معلم الرياضيات الإصطناعي هو وكيل تفاعلي يولد تجارب تعليمية رياضية في الوقت الفعلي، باستخدام HTML/JS وتعلم متكيف how to use math-teacher what is math-teacher math-teacher alternative math-teacher vs Khan Academy math-teacher install math-teacher setup guide interactive math learning adaptive learning software visual math education Math Teacher AI工具 AI数学学习 交互式HTML/JS工件 自适应学习 视觉化学习 游戏化挑战 数学教育 AI教育工具 Instant Playground Generation using HTML/JS Adaptive Learning that scales from basic arithmetic to advanced calculus Visual Learning through graphs, animations, and interactive visuals Creates interactive HTML/JS artifacts on demand Supports gamified challenges for enhanced engagement Generates interactive visual playgrounds for immersive learning math-teacher is an interactive, playful math teacher that generates engaging learning experiences through interactive artifacts, visual playgrounds, and gamified challenges.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ketzal88/ai-analyzer/agent-orchestration-multi-agent-optimize', 'community', 'ketzal88', 'ai-analyzer', 'ketzal88/ai-analyzer', 'agent-orchestration-multi-agent-optimize', 0, 0, 60, '2026-03-07T20:43:05Z', '2026-03-08T02:14:29.642Z', '07e8ae8527830021cbe7c8892dbcd4dfa038f9fb755122417bbf85a0d3744c6c', '{"id":"ketzal88/ai-analyzer/agent-orchestration-multi-agent-optimize","name":"agent-orchestration-multi-agent-optimize","description":{"en":"The agent-orchestration-multi-agent-optimize skill improves multi-agent coordination, throughput, and latency for developers. It helps optimize complex workflows and identify bottlenecks.","zh":"多智能体优化工具包用于提高多智能体的协调性、吞吐量和延迟，通过对智能体工作流进行 профилиング和优化","ja":"マルチエージェント最適化ツールキットは、複数のエージェントの調整、スループット、または待ち時間を改善するために使用されます","ko":"멀티 에이전트 최적화 도구킷은 여러 에이전트의 조정, 처리량 또는 지연 시간을 개선하는 데 사용됩니다","es":"Optimiza la coordinación y el rendimiento de tus agentes con esta herramienta de optimización multi-agente.","fr":"Optimisez la coordination et les performances de vos agents avec cet outil d''optimisation multi-agents.","de":"Optimieren Sie die Koordination und Leistung Ihrer Agenten mit diesem Multi-Agenten-Optimierungstool.","pt":"A ferramenta de otimização de múltiplos agentes é usada para melhorar a coordenação e o throughput em workflows complexos.","ru":"Инструмент оптимизации многоагентной оркестрации используется для улучшения координации и пропускной способности в сложных рабочих процессах.","ar":"أداة تحسين إدارة العوامل المتعددة تستخدم لتحسين التنسيق والإنتاجية في سلاسل العمل المعقدة."},"seo":{"title":{"en":"agent-orchestration-multi-agent-optimize: Multi-Agent Opt...","zh":"多智能体优化工具包设置指南","ja":"マルチエージェント最適化ツールキットのベストプラクティス","ko":"멀티 에이전트 최적화 도구킷 설정 가이드","es":"Guía de configuración para agent-orchestration-multi-agen...","fr":"Guide de démarrage rapide pour l''optimisation mult