INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ketzal88/ai-analyzer/agent-orchestration-multi-agent-optimize', 'agent-orchestration-multi-agent-optimize', 'ketzal88', 'ai-analyzer', 'community', 'agent-orchestration-multi-agent-optimize ketzal88 ai-analyzer community The agent-orchestration-multi-agent-optimize skill improves multi-agent coordination, throughput, and latency for developers. It helps optimize complex workflows and identify bottlenecks. 多智能体优化工具包用于提高多智能体的协调性、吞吐量和延迟，通过对智能体工作流进行 профилиング和优化 マルチエージェント最適化ツールキットは、複数のエージェントの調整、スループット、または待ち時間を改善するために使用されます 멀티 에이전트 최적화 도구킷은 여러 에이전트의 조정, 처리량 또는 지연 시간을 개선하는 데 사용됩니다 Optimiza la coordinación y el rendimiento de tus agentes con esta herramienta de optimización multi-agente. Optimisez la coordination et les performances de vos agents avec cet outil d''optimisation multi-agents. Optimieren Sie die Koordination und Leistung Ihrer Agenten mit diesem Multi-Agenten-Optimierungstool. A ferramenta de otimização de múltiplos agentes é usada para melhorar a coordenação e o throughput em workflows complexos. Инструмент оптимизации многоагентной оркестрации используется для улучшения координации и пропускной способности в сложных рабочих процессах. أداة تحسين إدارة العوامل المتعددة تستخدم لتحسين التنسيق والإنتاجية في سلاسل العمل المعقدة. how to use agent-orchestration-multi-agent-optimize agent-orchestration-multi-agent-optimize setup guide multi-agent optimization techniques agent-orchestration-multi-agent-optimize vs single agent tuning agent-orchestration-multi-agent-optimize install optimizing multi-agent workflows agent-orchestration-multi-agent-optimize alternative what is agent-orchestration-multi-agent-optimize agent-orchestration-multi-agent-optimize tutorial 多智能体优化 AIエージェント开发 智能体协调 吞吐量优化 延迟减少 工作流 профилиング 编排策略设计 成本优化 Improves multi-agent coordination and throughput Profiles agent workflows to identify bottlenecks Designs orchestration strategies for complex workflows Optimizes cost, context usage, and tool efficiency Establishes efficient multi-agent workflows agent-orchestration-multi-agent-optimize is a multi-agent optimization toolkit for improving coordination, profiling workflows, and designing efficient orchestration strategies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vorynkavitaliy/openclaw-assistent/prompt-engineering-patterns', 'community', 'vorynkavitaliy', 'openclaw-assistent', 'vorynkavitaliy/openclaw-assistent', 'prompt-engineering-patterns', 0, 0, 60, '2026-03-06T19:12:48Z', '2026-03-08T02:17:35.623Z', '747cb530259ee0d6f77d9b57fd649ec49c292f7a9808939f5a64cd0aa7d8f4c6', '{"id":"vorynkavitaliy/openclaw-assistent/prompt-engineering-patterns","name":"prompt-engineering-patterns","description":{"en":"The prompt-engineering-patterns skill helps developers maximize LLM performance, reliability, and controllability by designing complex prompts and optimizing prompt performance.","zh":"prompt-engineering-patterns是一种用于设计和优化LLM提示的技术，能够提高性能和可靠性","ja":"AIエージェントのプロンプトエンジニアリングパターンは、LLMの性能と信頼性を高めるための重要な技術です","ko":"prompt-engineering-patterns는 LLM의 성능과 안정성을 높이기 위한 고급 기술입니다","pt":"Domine técnicas avançadas de engenharia de prompt para maximizar o desempenho e a confiabilidade das aplicações LLM","ru":"Освойте продвинутые техники инженерии промптов, чтобы максимизировать производительность и надежность приложений LLM","ar":"استخدم تقنيات متقدمة للهندسة البداية لتعزيز الأداء والموثوقية للتطبيقات LLM"},"seo":{"title":{"en":"Prompt-Engineering-Patterns: Mastering LLM Performance | ...","zh":"prompt-engineering-patterns 优化指南","ja":"AIエージェントのプロンプトエンジニアリングパターン ベストプラクティス","ko":"prompt-engineering-patterns 설정 가이드","pt":"Padrões de Engenharia de Prompt: Guia de Configuração par...","ru":"Шаблоны инженерии промптов: Настройка производительности ...","ar":"نماذج هندسة البداية: دليل الإعداد لأدوات الإي الأجنت"},"description":{"en":"Unlock advanced prompt engineering techniques for LLM applications. Learn how to optimize prompt performance, implement chain-of-thought patterns, and more. ...","zh":"了解prompt-engineering-patterns的技术细节，包括设计复杂提示和优化LLM性能","ja":"AIエージェントのプロンプトエンジニアリングパターンを使用してLLMの性能を最大化する","ko":"prompt-engineering-patterns를 사용하여 생산성과 안정성을 높이는 방법","pt":"Aprenda a maximizar o desempenho e a confiabilidade das aplicações LLM com padrões de engenharia de prompt avançados","ru":"Узнайте, как максимизировать производительность и надежность приложений LLM с помощью продвинутых шаблонов инженерии промптов","ar":"تعلم كيفية تعزيز الأداء والموثوقية للتطبيقات LLM باستخدام أنماط هندسة البداية المتقدمة"},"definition":{"en":"prompt-engineering-patterns is a set of advanced techniques for optimizing language model performance, including designing complex prompts, implementing structured reasoning patterns, and building few-shot learning systems.","zh":"prompt-engineering-patterns是一种用于设计和优化LLM提示的技术","ja":"AIエージェントのプロンプトエンジニアリングパターンは、LLMの入力を設計および最適化する技術です","ko":"prompt-engineering-patterns는 LLM의 입력을 설계하고 최적화하는 기술입니다","pt":"Padrões de engenharia de prompt são técnicas avançadas para melhorar o desempenho e a confiabilidade das aplicações LLM","ru":"Шаблоны инженерии промптов - это продвинутые техники для улучшения производительности и надежности приложений LLM","ar":"نماذج هندسة البداية هي تقنيات متقدمة لتحسين الأداء والموثوقية للتطبيقات LLM"},"features":{"en":["Designs complex prompts for production LLM applications","Optimizes prompt performance and consistency","Implements structured reasoning patterns, such as chain-of-thought and tree-of-thought","Builds few-shot learning systems with dynamic example selection","Creates reusable prompt templates with variable interpolation","Debugs prompt performance issues"],"zh":["设计复杂提示","优化LLM性能和一致性","实现结构化推理模式（chain-of-thought、tree-of-thought）","构建少样本学习系统","创建可重用提示模板"],"ja":["複雑なプロンプトの設計","LLMの性能と一貫性の最適化","構造化推論パターンの実装（chain-of-thought、tree-of-thought）","少샘플学習システムの構築","再利用可能なプロンプトテンプレートの作成"],"ko":["複雑한 프롬프트 설계","LLM 성능과 일관성 최적화","구조화된 추론 패턴 구현（chain-of-thought、tree-of-thought）","少し 샘플 학습 시스템 구축","재사용 가능한 프롬프트 템플릿 생성"],"pt":["Desenvolvimento de prompts complexos para aplicações LLM de produção","Otimização do desempenho e consistência dos prompts","Implementação de padrões de raciocínio estruturados (cadeia de pensamento, árvore de pensamento)","Criação de sistemas de aprendizado com poucos exemplos e seleção dinâmica de exemplos","Construção de templates de prompt reutilizáveis com interpolação de variáveis"],"ru":["Разработка сложных промптов для приложений LLM в производстве","Оптимизация производительности и согласованности промптов","Реализация структурированных шаблонов рассуждений (цепочка мыслей, дерево мыслей)","Создание систем обучения с небольшим количеством примеров и динамическим выбором примеров","Строительство переиспользуемых шаблонов промптов с интерполяцией переменных"],"ar":["إنشاء بدائيات معقدة لتطبيقات LLM الإنتاجية","تحسين الأداء والثبات للبدائيات","تنفيذ أنماط الاستدلال المنظمة (سلسلة الأفكار، شجرة الأفكار)","إنشاء أنظمة التعلم مع عدد قليل من الأمثلة والاختيار الديناميكي للأمثلة","بناء قوالب بدائية قابلة لإعادة الاستخدام مع استبدال المتغيرات"]},"keywords":{"en":["how to use prompt-engineering-patterns","prompt-engineering-patterns alternative","prompt-engineering-patterns setup guide","what is prompt-engineering-patterns","prompt-engineering-patterns vs competitor","prompt-engineering-patterns install","mastering LLM performance","optimizing prompt performance","chain-of-thought patterns","few-shot learning systems"],"zh":["prompt-engineering-patterns","LLM性能优化","复杂提示设计","结构化推理模式","少样本学习","可重用提示模板","AIエージェント","自然语言处理"],"ja":["AIエージェント","プロンプトエンジニアリングパターン","LLMの性能最適化","複雑なプロンプトの設計","構造化推論パターン","少샘플学習","再利用可能なプロンプトテンプレート","自然言語処理"],"ko":["prompt-engineering-patterns","LLM 성능 최적화","複雑한 프롬프트 설계","구조화된 추론 패턴","少し 샘플 학습","재사용 가능한 프롬프트 템플릿","AI 에이전트","자연어 처리"],"pt":["engenharia de prompt","padrões de engenharia de prompt","aplicações LLM","produção de prompts","otimização de desempenho","raciocínio estruturado","aprendizado com poucos exemplos"],"ru":["инженерия промптов","шаблоны инженерии промптов","приложения LLM","производство промптов","оптимизация производительности","структурированные шаблоны рассуждений","обучение с небольшим количеством примеров"],"ar":["هندسة البداية","نماذج هندسة البداية","تطبيقات LLM","إنتاج البداية","تحسين الأداء","أنماط الاستدلال المنظمة","التعلم مع عدد قليل من الأمثلة"]}},"owner":"vorynkavitaliy","repo":"openclaw-assistent","repoPath":"vorynkavitaliy/openclaw-assistent","stars":0,"forks":0,"updatedAt":"2026-03-06T19:12:48Z","topics":[],"category":"community","skillMd":{"name":"prompt-engineering-patterns","description":"Master advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability in production. Use when optimizing prompts, improving LLM outputs, or designing production prompt templates.","bodyPreview":"# Prompt Engineering Patterns\n\nMaster advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability.\n\n## When to Use This Skill\n\n- Designing complex prompts for production LLM applications\n- Optimizing prompt performance and consistency\n- Implementing structured reasoning patterns (chain-of-thought, tree-of-thought)\n- Building few-shot learning systems with dynamic example selection\n- Creating reusable prompt templates with variable interpolation\n- Debuggin","body":"# Prompt Engineering Patterns\n\nMaster advanced prompt engineering techniques to maximize LLM performance, reliability, and controllability.\n\n## When to Use This Skill\n\n- Designing complex prompts for production LLM applications\n- Optimizing prompt performance and consistency\n- Implementing structured reasoning patterns (chain-of-thought, tree-of-thought)\n- Building few-shot learning systems with dynamic example selection\n- Creating reusable prompt templates with variable interpolation\n- Debugging and refining prompts that produce inconsistent outputs\n- Implementing system prompts for specialized AI assistants\n- Using structured outputs (JSON mode) for reliable parsing\n\n## Core Capabilities\n\n### 1. Few-Shot Learning\n\n- Example selection strategies (semantic similarity, diversity sampling)\n- Balancing example count with context window constraints\n- Constructing effective demonstrations with input-output pairs\n- Dynamic example retrieval from knowledge bases\n- Handling edge cases through strategic example selection\n\n### 2. Chain-of-Thought Prompting\n\n- Step-by-step reasoning elicitation\n- Zero-shot CoT with \"Let''s think step by step\"\n- Few-shot CoT with reasoning traces\n- Self-consistency techniques (sampling multiple reasoning paths)\n- Verification and validation steps\n\n### 3. Structured Outputs\n\n- JSON mode for reliable parsing\n- Pydantic schema enforcement\n- Type-safe response handling\n- Error handling for malformed outputs\n\n### 4. Prompt Optimization\n\n- Iterative refinement workflows\n- A/B testing prompt variations\n- Measuring prompt performance metrics (accuracy, consistency, latency)\n- Reducing token usage while maintaining quality\n- Handling edge cases and failure modes\n\n### 5. Template Systems\n\n- Variable interpolation and formatting\n- Conditional prompt sections\n- Multi-turn conversation templates\n- Role-based prompt composition\n- Modular prompt components\n\n### 6. System Prompt Design\n\n- Setting model behavior and constraints\n- Defining output formats and structure\n- Establishing role and expertise\n- Safety guidelines and content policies\n- Context setting and background information\n\n## Quick Start\n\n```python\nfrom langchain_anthropic import ChatAnthropic\nfrom langchain_core.prompts import ChatPromptTemplate\nfrom pydantic import BaseModel, Field\n\n# Define structured output schema\nclass SQLQuery(BaseModel):\n    query: str = Field(description=\"The SQL query\")\n    explanation: str = Field(description=\"Brief explanation of what the query does\")\n    tables_used: list[str] = Field(description=\"List of tables referenced\")\n\n# Initialize model with structured output\nllm = ChatAnthropic(model=\"claude-sonnet-4-6\")\nstructured_llm = llm.with_structured_output(SQLQuery)\n\n# Create prompt template\nprompt = ChatPromptTemplate.from_messages([\n    (\"system\", \"\"\"You are an expert SQL developer. Generate efficient, secure SQL queries.\n    Always use parameterized queries to prevent SQL injection.\n    Explain your reasoning briefly.\"\"\"),\n    (\"user\", \"Convert this to SQL: {query}\")\n])\n\n# Create chain\nchain = prompt | structured_llm\n\n# Use\nresult = await chain.ainvoke({\n    \"query\": \"Find all users who registered in the last 30 days\"\n})\nprint(result.query)\nprint(result.explanation)\n```\n\n## Key Patterns\n\n### Pattern 1: Structured Output with Pydantic\n\n```python\nfrom anthropic import Anthropic\nfrom pydantic import BaseModel, Field\nfrom typing import Literal\nimport json\n\nclass SentimentAnalysis(BaseModel):\n    sentiment: Literal[\"positive\", \"negative\", \"neutral\"]\n    confidence: float = Field(ge=0, le=1)\n    key_phrases: list[str]\n    reasoning: str\n\nasync def analyze_sentiment(text: str) -> SentimentAnalysis:\n    \"\"\"Analyze sentiment with structured output.\"\"\"\n    client = Anthropic()\n\n    message = client.messages.create(\n        model=\"claude-sonnet-4-6\",\n        max_tokens=500,\n        messages=[{\n            \"role\": \"user\",\n            \"content\": f\"\"\"Analyze the sentiment of this text.\n\nText: {text}\n\nRespond with JSON matching this schema:\n{{\n    \"sentiment\": \"positive\" | \"negative\" | \"neutral\",\n    \"confidence\": 0.0-1.0,\n    \"key_phrases\": [\"phrase1\", \"phrase2\"],\n    \"reasoning\": \"brief explanation\"\n}}\"\"\"\n        }]\n    )\n\n    return SentimentAnalysis(**json.loads(message.content[0].text))\n```\n\n### Pattern 2: Chain-of-Thought with Self-Verification\n\n```python\nfrom langchain_core.prompts import ChatPromptTemplate\n\ncot_prompt = ChatPromptTemplate.from_template(\"\"\"\nSolve this problem step by step.\n\nProblem: {problem}\n\nInstructions:\n1. Break down the problem into clear steps\n2. Work through each step showing your reasoning\n3. State your final answer\n4. Verify your answer by checking it against the original problem\n\nFormat your response as:\n## Steps\n[Your step-by-step reasoning]\n\n## Answer\n[Your final answer]\n\n## Verification\n[Check that your answer is correct]\n\"\"\")\n```\n\n### Pattern 3: Few-Shot with Dynamic Example Selection\n\n```python\nfrom langchain_voyageai import VoyageAIEmbeddings\nfrom langchain_core.example_selectors import SemanticSimilarityExampleSelector\nfrom langchain_chroma import Chroma\n\n# Create example selector with semantic similarity\nexample_selector = SemanticSimilarityExampleSelector.from_examples(\n    examples=[\n        {\"input\": \"How do I reset my password?\", \"output\": \"Go to Settings > Security > Reset Password\"},\n        {\"input\": \"Where can I see my order history?\", \"output\": \"Navigate to Account > Orders\"},\n        {\"input\": \"How do I contact support?\", \"output\": \"Click Help > Contact Us or email support@example.com\"},\n    ],\n    embeddings=VoyageAIEmbeddings(model=\"voyage-3-large\"),\n    vectorstore_cls=Chroma,\n    k=2  # Select 2 most similar examples\n)\n\nasync def get_few_shot_prompt(query: str) -> str:\n    \"\"\"Build prompt with dynamically selected examples.\"\"\"\n    examples = await example_selector.aselect_examples({\"input\": query})\n\n    examples_text = \"\\n\".join(\n        f\"User: {ex[''input'']}\\nAssistant: {ex[''output'']}\"\n        for ex in examples\n    )\n\n    return f\"\"\"You are a helpful customer support assistant.\n\nHere are some example interactions:\n{examples_text}\n\nNow respond to this query:\nUser: {query}\nAssistant:\"\"\"\n```\n\n### Pattern 4: Progressive Disclosure\n\nStart with simple prompts, add complexity only when needed:\n\n```python\nPROMPT_LEVELS = {\n    # Level 1: Direct instruction\n    \"simple\": \"Summarize this article: {text}\",\n\n    # Level 2: Add constraints\n    \"constrained\": \"\"\"Summarize this article in 3 bullet points, focusing on:\n- Key findings\n- Main conclusions\n- Practical implications\n\nArticle: {text}\"\"\",\n\n    # Level 3: Add reasoning\n    \"reasoning\": \"\"\"Read this article carefully.\n1. First, identify the main topic and thesis\n2. Then, extract the key supporting points\n3. Finally, summarize in 3 bullet points\n\nArticle: {text}\n\nSummary:\"\"\",\n\n    # Level 4: Add examples\n    \"few_shot\": \"\"\"Read articles and provide concise summaries.\n\nExample:\nArticle: \"New research shows that regular exercise can reduce anxiety by up to 40%...\"\nSummary:\n• Regular exercise reduces anxiety by up to 40%\n• 30 minutes of moderate activity 3x/week is sufficient\n• Benefits appear within 2 weeks of starting\n\nNow summarize this article:\nArticle: {text}\n\nSummary:\"\"\"\n}\n```\n\n### Pattern 5: Error Recovery and Fallback\n\n```python\nfrom pydantic import BaseModel, ValidationError\nimport json\n\nclass ResponseWithConfidence(BaseModel):\n    answer: str\n    confidence: float\n    sources: list[str]\n    alternative_interpretations: list[str] = []\n\nERROR_RECOVERY_PROMPT = \"\"\"\nAnswer the question based on the context provided.\n\nContext: {context}\nQuestion: {question}\n\nInstructions:\n1. If you can answer confidently (>0.8), provide a direct answer\n2. If you''re somewhat confident (0.5-0.8), provide your best answer with caveats\n3. If you''re uncertain (<0.5), explain what information is missing\n4. Always provide alternative interpretations if the question is ambiguous\n\nRespond in JSON:\n{{\n    \"answer\": \"your answer or ''I cannot determine this from the context''\",\n    \"confidence\": 0.0-1.0,\n    \"sources\": [\"relevant context excerpts\"],\n    \"alternative_interpretations\": [\"if question is ambiguous\"]\n}}\n\"\"\"\n\nasync def answer_with_fallback(\n    context: str,\n    question: str,\n    llm\n) -> ResponseWithConfidence:\n    \"\"\"Answer with error recovery and fallback.\"\"\"\n    prompt = ERROR_RECOVERY_PROMPT.format(context=context, question=question)\n\n    try:\n        response = await llm.ainvoke(prompt)\n        return ResponseWithConfidence(**json.loads(response.content))\n    except (json.JSONDecodeError, ValidationError) as e:\n        # Fallback: try to extract answer without structure\n        simple_prompt = f\"Based on: {context}\\n\\nAnswer: {question}\"\n        simple_response = await llm.ainvoke(simple_prompt)\n        return ResponseWithConfidence(\n            answer=simple_response.content,\n            confidence=0.5,\n            sources=[\"fallback extraction\"],\n            alternative_interpretations=[]\n        )\n```\n\n### Pattern 6: Role-Based System Prompts\n\n```python\nSYSTEM_PROMPTS = {\n    \"analyst\": \"\"\"You are a senior data analyst with expertise in SQL, Python, and business intelligence.\n\nYour responsibilities:\n- Write efficient, well-documented queries\n- Explain your analysis methodology\n- Highlight key insights and recommendations\n- Flag any data quality concerns\n\nCommunication style:\n- Be precise and technical when discussing methodology\n- Translate technical findings into business impact\n- Use clear visualizations when helpful\"\"\",\n\n    \"assistant\": \"\"\"You are a helpful AI assistant focused on accuracy and clarity.\n\nCore principles:\n- Always cite sources when making factual claims\n- Acknowledge uncertainty rather than guessing\n- Ask clarifying questions when the request is ambiguous\n- Provide step-by-step explanations for complex topics\n\nConstraints:\n- Do not provide medical, legal, or financial advice\n- Redirect harmful requests appropriately\n- Protect user privacy\"\"\",\n\n    \"code_reviewer\": \"\"\"You are a senior software engineer conducting code reviews.\n\nReview criteria:\n- Correctness: Does the code work as intended?\n- Security: Are there any vulnerabilities?\n- Performance: Are there efficiency concerns?\n- Maintainability: Is the code readable and well-structured?\n- Best practices: Does it follow language idioms?\n\nOutput format:\n1. Summary assessment (approve/request changes)\n2. Critical issues (must fix)\n3. Suggestions (nice to have)\n4. Positive feedback (what''s done well)\"\"\"\n}\n```\n\n## Integration Patterns\n\n### With RAG Systems\n\n```python\nRAG_PROMPT = \"\"\"You are a knowledgeable assistant that answers questions based on provided context.\n\nContext (retrieved from knowledge base):\n{context}\n\nInstructions:\n1. Answer ONLY based on the provided context\n2. If the context doesn''t contain the answer, say \"I don''t have information about that in my knowledge base\"\n3. Cite specific passages using [1], [2] notation\n4. If the question is ambiguous, ask for clarification\n\nQuestion: {question}\n\nAnswer:\"\"\"\n```\n\n### With Validation and Verification\n\n```python\nVALIDATED_PROMPT = \"\"\"Complete the following task:\n\nTask: {task}\n\nAfter generating your response, verify it meets ALL these criteria:\n✓ Directly addresses the original request\n✓ Contains no factual errors\n✓ Is appropriately detailed (not too brief, not too verbose)\n✓ Uses proper formatting\n✓ Is safe and appropriate\n\nIf verification fails on any criterion, revise before responding.\n\nResponse:\"\"\"\n```\n\n## Performance Optimization\n\n### Token Efficiency\n\n```python\n# Before: Verbose prompt (150+ tokens)\nverbose_prompt = \"\"\"\nI would like you to please take the following text and provide me with a comprehensive\nsummary of the main points. The summary should capture the key ideas and important details\nwhile being concise and easy to understand.\n\"\"\"\n\n# After: Concise prompt (30 tokens)\nconcise_prompt = \"\"\"Summarize the key points concisely:\n\n{text}\n\nSummary:\"\"\"\n```\n\n### Caching Common Prefixes\n\n```python\nfrom anthropic import Anthropic\n\nclient = Anthropic()\n\n# Use prompt caching for repeated system prompts\nresponse = client.messages.create(\n    model=\"claude-sonnet-4-6\",\n    max_tokens=1000,\n    system=[\n        {\n            \"type\": \"text\",\n            \"text\": LONG_SYSTEM_PROMPT,\n            \"cache_control\": {\"type\": \"ephemeral\"}\n        }\n    ],\n    messages=[{\"role\": \"user\", \"content\": user_query}]\n)\n```\n\n## Best Practices\n\n1. **Be Specific**: Vague prompts produce inconsistent results\n2. **Show, Don''t Tell**: Examples are more effective than descriptions\n3. **Use Structured Outputs**: Enforce schemas with Pydantic for reliability\n4. **Test Extensively**: Evaluate on diverse, representative inputs\n5. **Iterate Rapidly**: Small changes can have large impacts\n6. **Monitor Performance**: Track metrics in production\n7. **Version Control**: Treat prompts as code with proper versioning\n8. **Document Intent**: Explain why prompts are structured as they are\n\n## Common Pitfalls\n\n- **Over-engineering**: Starting with complex prompts before trying simple ones\n- **Example pollution**: Using examples that don''t match the target task\n- **Context overflow**: Exceeding token limits with excessive examples\n- **Ambiguous instructions**: Leaving room for multiple interpretations\n- **Ignoring edge cases**: Not testing on unusual or boundary inputs\n- **No error handling**: Assuming outputs will always be well-formed\n- **Hardcoded values**: Not parameterizing prompts for reuse\n\n## Success Metrics\n\nTrack these KPIs for your prompts:\n\n- **Accuracy**: Correctness of outputs\n- **Consistency**: Reproducibility across similar inputs\n- **Latency**: Response time (P50, P95, P99)\n- **Token Usage**: Average tokens per request\n- **Success Rate**: Percentage of valid, parseable outputs\n- **User Satisfaction**: Ratings and feedback\n\n## Resources\n\n- [Anthropic Prompt Engineering Guide](https://docs.anthropic.com/en/docs/build-with-claude/prompt-engineering)\n- [Claude Prompt Caching](https://docs.anthropic.com/en/docs/build-with-claude/prompt-caching)\n- [OpenAI Prompt Engineering](https://platform.openai.com/docs/guides/prompt-engineering)\n- [LangChain Prompts](https://python.langchain.com/docs/concepts/prompts/)\n"},"lastSynced":"2026-03-08T02:17:35.623Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced LLM Agents needing to maximize performance, reliability, and controllability through expertly crafted prompts.","zh":"适合高级LLM代理，需要通过精心设计的提示来最大化性能、可靠性和可控性。","ja":"高性能、信頼性、制御性を実現するために、熟練したプロンプトを作成する必要がある、高度なLLMエージェントに最適です。","ko":"고급 LLM 에이전트가 전문적으로 설계된 프롬프트를 통해 성능, 신뢰성 및 제어성을 최대화하는 데 적합합니다.","es":"Ideal para Agentes LLM Avanzados que necesitan maximizar el rendimiento, la confiabilidad y el control a través de instrucciones expertamente diseñadas.","fr":"Idéal pour les Agents LLM Avancés ayant besoin de maximiser les performances, la fiabilité et la contrôlabilité grâce à des instructions expertement conçues.","de":"Ideal für Advanced LLM Agents, die Leistung, Zuverlässigkeit und Steuerbarkeit durch expertenmäßig erstellte Anweisungen maximieren müssen.","pt":"Ideal para Agentes LLM Avançados que precisam maximizar o desempenho, a confiabilidade e o controle por meio de prompts criados por especialistas.","ru":"Идеально подходит для продвинутых агентов LLM, которым необходимо максимизировать производительность, надежность и контролируемость посредством экспертно созданных подсказок.","ar":"مثالي للوكلاء LLM المتقدمين الذين يحتاجون إلى تعظيم الأداء والموثوقية والتحكم من خلال подсказات من تصميم الخبراء."},"recommendation":{"en":"Empowers agents to design complex prompts and optimize prompt performance, leveraging techniques such as chain-of-thought and tree-of-thought patterns, few-shot learning, and dynamic example selection, all while creating reusable prompt templates with variable interpolation.","zh":"赋予代理设计复杂提示和优化提示性能的能力，利用诸如思维链和思维树模式、少样本学习和动态示例选择等技术，同时创建带有变量插值的可重用提示模板。","ja":"エージェントが複雑なプロンプトを設計し、プロンプトのパフォーマンスを最適化する能力を提供します。チェーン・オブ・ソートやツリー・オブ・ソート・パターン、少샷ラーニング、ダイナミックな例選択などのテクニックを利用し、同時に変数補間を備えた再利用可能なプロンプトテンプレートを作成します。","ko":"에이전트가 복잡한 프롬프트를 설계하고 프롬프트 성능을 최적화할 수 있는 능력을 제공하며, 사슬-오브-사고 및 트리-오브-사고 패턴, 少샷 학습 및 동적 예제 선택 등과 같은 기술을 활용하여 동시에 변수 보간을 갖춘 재사용 가능한 프롬프트 템플릿을 생성합니다.","es":"Permite a los agentes diseñar instrucciones complejas y optimizar el rendimiento de las instrucciones, aprovechando técnicas como patrones de cadena de pensamiento y patrones de árbol de pensamiento, aprendizaje de pocos disparos y selección de ejemplos dinámicos, todo mientras se crean plantillas de instrucciones reutilizables con interpolación de variables.","fr":"Permet aux agents de concevoir des instructions complexes et d''optimiser les performances des instructions, en exploitant des techniques telles que les modèles de chaîne de pensée et les modèles d''arbre de pensée, l''apprentissage à few-shot et la sélection d''exemples dynamiques, le tout en créant des modèles d''instructions réutilisables avec interpolation de variables.","de":"Ermöglicht es Agenten, komplexe Anweisungen zu entwerfen und die Anweisungsleistung zu optimieren, indem Techniken wie Denkmusterketten und Denkbaum-Muster, few-shot-Lernen und dynamische Beispielwahl genutzt werden, während wiederverwendbare Anweisungsvorlagen mit Variableninterpolation erstellt werden.","pt":"Habilita os agentes a projetar prompts complexos e otimizar o desempenho dos prompts, utilizando técnicas como padrões de cadeia de pensamento e padrões de árvore de pensamento, aprendizado de poucos disparos e seleção dinâmica de exemplos, ao mesmo tempo em que cria modelos de prompts reutilizáveis com interpolação de variáveis.","ru":"Наделяет агентов возможностью проектировать сложные подсказки и оптимизировать производительность подсказок, используя такие техники, как цепочка мыслей и дерево мыслей, обучение на нескольких примерах и динамический выбор примеров, а также создание повторно используемых шаблонов подсказок с интерполяцией переменных.","ar":"يمنح الوكلاء القدرة على تصميم подсказات معقدة وتحسين أداء الاشارات، باستخدام تقنيات مثل أنماط سلسلة التفكير وأنماط شجرة التفكير والتعلم من القليل من الأمثلة والاختيار الديناميكي للأمثلة، وفي الوقت نفسه إنشاء قوالب اشارات قابلة لإعادة الاستخدام مع استبدال المتغيرات."},"useCases":{"en":["Designing intricate prompts for production LLM applications","Optimizing prompt performance and consistency for improved reliability","Implementing structured reasoning patterns for enhanced controllability"],"zh":["为生产LLM应用程序设计复杂的提示","优化提示性能和一致性以提高可靠性","实现结构化推理模式以增强可控性"],"ja":["生産用LLMアプリケーション向けの複雑なプロンプトの設計","プロンプトのパフォーマンスと一貫性の最適化による信頼性の向上","構造化された推論パターンの実装による制御性の強化"],"ko":["생산용 LLM 애플리케이션을 위한 복잡한 프롬프트 설계","프롬프트 성능 및 일관성 최적화를 통한 신뢰성 향상","구조화된推論 패턴의 구현을 통한 제어성 향상"],"es":["Diseñar instrucciones intrincadas para aplicaciones LLM de producción","Optimizar el rendimiento de las instrucciones y la coherencia para una mayor confiabilidad","Implementar patrones de razonamiento estructurados para una mayor controlabilidad"],"fr":["Concevoir des instructions complexes pour les applications LLM de production","Optimiser les performances des instructions et la cohérence pour une meilleure fiabilité","Mettre en œuvre des modèles de raisonnement structurés pour une meilleure contrôlabilité"],"de":["Entwerfen von komplexen Anweisungen für LLM-Produktionsanwendungen","Optimieren der Anweisungsleistung und Konsistenz für eine verbesserte Zuverlässigkeit","Implementieren von strukturierten Denkmustern für eine verbesserte Steuerbarkeit"],"pt":["Projetar prompts intrincados para aplicações LLM de produção","Otimizar o desempenho e a consistência dos prompts para confiabilidade melhorada","Implementar padrões de raciocínio estruturado para controle melhorado"],"ru":["Проектирование сложных подсказок для приложений LLM в производстве","Оптимизация производительности и согласованности подсказок для повышения надежности","Реализация структурированных шаблонов рассуждений для повышения контроля"],"ar":["تصميم اشارات معقدة لتطبيقات LLM الإنتاجية","تحسين أداء الاشارات والاتساق لتحسين الموثوقية","تنفيذ أنماط التفكير المنظمة لتحسين التحكم"]},"limitations":{"en":["Requires understanding of LLM internals and prompt engineering principles","May necessitate significant computational resources for complex prompt optimization"],"zh":["需要了解LLM内部和提示工程原则","可能需要大量的计算资源来优化复杂的提示"],"ja":["LLM内部とプロンプトエンジニアリングの原則を理解する必要がある","複雑なプロンプトの最適化には大量の計算リソースが必要になる可能性がある"],"ko":["LLM 내부 및 프롬프트 엔지니어링 원리를 이해해야 함","복잡한 프롬프트 최적화를 위해大量의 계산 리소스가 필요할 수 있음"],"es":["Requiere comprensión de los internos de LLM y los principios de ingeniería de instrucciones","Puede necesitar recursos computacionales significativos para la optimización compleja de instrucciones"],"fr":["Nécessite une compréhension des internes de LLM et des principes d''ingénierie des instructions","Peut nécessiter des ressources computationnelles importantes pour l''optimisation complexe des instructions"],"de":["Benötigt Verständnis für LLM-Interne und Anweisungstechnik-Prinzipien","Kann erhebliche Rechenressourcen für komplexe Anweisungsoptimierung erfordern"],"pt":["Exige compreensão dos internos do LLM e princípios de engenharia de prompts","Pode necessitar de recursos computacionais significativos para otimização de prompts complexos"],"ru":["Требует понимания внутренней структуры LLM и принципов инженерии подсказок","Может потребовать значительных вычислительных ресурсов для оптимизации сложных подсказок"],"ar":["يتطلب فهمًا لذات LLM ومبادئ هندسة الاشارات","قد يحتاج إلى موارد حسابية كبيرة لتحسين اشارات معقدة"]},"version":4},"contentHash":"747cb530259ee0d6f77d9b57fd649ec49c292f7a9808939f5a64cd0aa7d8f4c6","qualityScore":60}');
