INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cartridge-gg/glitchbomb/create-a-plan', 'create-a-plan', 'cartridge-gg', 'glitchbomb', 'community', 'create-a-plan cartridge-gg glitchbomb community The create-a-plan skill runs a structured technical interview to turn ideas into implementable plans, outputting organized foundations, workstreams, and integrations for parallel execution. 创建计划技能是一个技术面试工具，用于生成详细的可执行计划，支持并行执行 計画作成スキルは、技術面接ツールを使用して詳細な実行可能な計画を生成します。並列実行に対応 계획 생성 기술은 기술 인터뷰 도구를 사용하여 상세한 실행 가능한 계획을 생성하며 병렬 실행을 지원합니다 Create-a-plan es una habilidad que convierte ideas en planes implementables con una estructura técnica Create-a-plan est une compétence qui transforme les idées en plans exécutables avec une structure technique Create-a-plan ist eine Fähigkeit, die Ideen in umsetzbare Pläne mit einer technischen Struktur umwandelt O Create-a-Plan é uma ferramenta que executa uma entrevista técnica estruturada para transformar ideias ou especificações existentes em planos detalhados. Create-a-Plan - это инструмент, который выполняет структурированное техническое интервью для преобразования идей или существующих спецификаций в подробные планы. أداة Create-a-Plan هي أداة تقوم بتشغيل مقابلة تقنية منسقة لتحويل الأفكار أو المواصفات الحالية إلى خطط مفصلة how to use create-a-plan create-a-plan setup guide what is create-a-plan create-a-plan alternative create-a-plan vs project management tools create-a-plan install SPEC.md file format technical interview process 创建计划技能 AI工具 技术面试 详细计划 并行执行 规格文件 计划文件 功能请求 技术开发 Runs structured technical interviews to create detailed plans Accepts input from SPEC.md, PLAN.md, or RFC.md files Processes rough descriptions of ideas or feature requests Outputs organized plans for parallel execution Prioritizes foundations, independent workstreams, and merge/integration tasks create-a-plan is a skill that generates detailed, implementable plans from rough ideas or existing specs using a structured technical interview process.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('harshahosur81/ag-opencode-skills/nx-workspace-patterns', 'community', 'harshahosur81', 'ag-opencode-skills', 'harshahosur81/ag-opencode-skills', 'nx-workspace-patterns', 0, 0, 60, '2026-03-07T12:46:33.766Z', '2026-03-07T13:03:23.565Z', '6286fae01303804282fedd8b858cd8312e0637126abe6b8f3d01eab19e9777a0', '{"id":"harshahosur81/ag-opencode-skills/nx-workspace-patterns","name":"nx-workspace-patterns","description":{"en":"The nx-workspace-patterns skill provides production patterns for Nx monorepo management, benefiting developers setting up new workspaces, configuring project boundaries, and optimizing CI with affected commands.","zh":"Nx Workspace Patterns提供生产模式，用于Nx单体仓库管理，优化CI和远程缓存","ja":"Nx Workspace Patternsは、Nxモノリポ管理のためのプロダクションパターンを提供し、CIとリモートキャッシュを最適化します","ko":"Nx Workspace Patterns는 Nx 모노리포 관리를 위한 생산 패턴을 제공하여 CI 및 리모ート 캐싱을 최적화합니다","es":"nx-workspace-patterns es una colección de patrones para la gestión de monorepos con Nx. Incluye configuración de proyectos, optimización de CI y gestión de dependencias","fr":"Les modèles de workspace Nx sont une collection de modèles pour la gestion de monorepos avec Nx. Ils incluent la configuration de projets, l''optimisation de CI et la gestion de dépendances","de":"nx-workspace-patterns ist eine Sammlung von Mustern für die Verwaltung von Monorepos mit Nx. Sie umfasst die Konfiguration von Projekten, die Optimierung von CI und die Verwaltung von Abhängigkeiten","pt":"O Nx Workspace Patterns fornece padrões de produção para gerenciamento de monorepo Nx, incluindo configuração de projetos e dependências","ru":"Шаблоны Nx Workspace предоставляют шаблоны производства для управления монорепозиторием Nx, включая конфигурацию проектов и зависимостей","ar":"توفر أنماط مساحة العمل Nx أنماط الإنتاج لإدارة مستودع المجرد Nx، بما في ذلك تكوين المشاريع والاعتمادات"},"seo":{"title":{"en":"nx-workspace-patterns: Mastering Nx Monorepo Management |...","zh":"Nx Workspace Patterns_SETUP GUIDE","ja":"Nx Workspace Patternsベストプラクティス","ko":"Nx Workspace Patterns 설정 가이드","es":"Guía de configuración de nx-workspace-patterns para monor...","fr":"Configurer les modèles de workspace Nx pour les monorepos","de":"Einrichtungsleitfaden für nx-workspace-patterns in Monorepos","pt":"Guia de Configuração do Nx Workspace Patterns","ru":"Настройка шаблонов Nx Workspace: ИИ Агенты для разработчиков","ar":"دليل إعداد أنماط مساحة العمل Nx"},"description":{"en":"Unlock efficient Nx workspace setup and optimization with 300+ skills. Learn how to implement remote caching and manage dependencies between projects.","zh":"了解Nx Workspace Patterns的生产模式，优化CI和远程缓存，AIエージェント","ja":"Nx Workspace Patternsのプロダクションパターンを学び、CIとリモートキャッシュを最適化する","ko":"Nx Workspace Patterns의 생산 패턴을 알아보고 CI 및 리모ート 캐싱을 최적화하는 방법","es":"Aprende a configurar y optimizar tus monorepos con nx-workspace-patterns. Mejora la gestión de proyectos y dependencias","fr":"Découvrez comment configurer et optimiser vos monorepos avec les modèles de workspace Nx. Améliorez la gestion de projets et de dépendances","de":"Erfahren Sie, wie Sie Ihre Monorepos mit nx-workspace-patterns konfigurieren und optimieren. Verbessern Sie die Projekt- und Abhängigkeitsverwaltung","pt":"Aprenda a configurar e otimizar o seu monorepo com o Nx Workspace Patterns, incluindo configuração de projetos e dependências","ru":"Узнайте, как настроить и оптимизировать свой монорепозиторий с помощью шаблонов Nx Workspace, включая конфигурацию проектов и зависимостей","ar":"تعرف على كيفية إعداد وتحسين مستودعك المجرد باستخدام أنماط مساحة العمل Nx، بما في ذلك تكوين المشاريع والاعتمادات"},"definition":{"en":"nx-workspace-patterns is a collection of skills for efficient Nx monorepo management, covering setup, configuration, and optimization techniques.","zh":"Nx Workspace Patterns是一种用于Nx单体仓库管理的生产模式","ja":"Nx Workspace Patternsは、Nxモノリポ管理のためのプロダクションパターンです","ko":"Nx Workspace Patterns는 Nx 모노리포 관리를 위한 생산 패턴입니다","es":"nx-workspace-patterns es un conjunto de patrones para la gestión de monorepos con Nx, que facilita la configuración y optimización de proyectos","fr":"Les modèles de workspace Nx sont un ensemble de modèles pour la gestion de monorepos avec Nx, qui facilitent la configuration et l''optimisation de projets","de":"nx-workspace-patterns ist ein Satz von Mustern für die Verwaltung von Monorepos mit Nx, der die Konfiguration und Optimierung von Projekten erleichtert","pt":"O que é Nx Workspace Patterns? É um conjunto de padrões de produção para gerenciamento de monorepo Nx","ru":"Что такое шаблоны Nx Workspace? Это набор шаблонов производства для управления монорепозиторием Nx","ar":"ما هي أنماط مساحة العمل Nx؟ هي مجموعة من أنماط الإنتاج لإدارة مستودع المجرد Nx"},"features":{"en":["Configures project boundaries for efficient Nx workspace management","Optimizes CI with affected commands for faster build times","Implements remote caching for improved performance","Manages dependencies between projects with shared libraries","Migrates existing projects to Nx for streamlined development","Sets up new Nx workspaces with best practices"],"zh":["设置新的Nx工作空间","配置项目边界","优化CI以affected命令","实现远程缓存","管理项目之间的依赖关系","迁移到Nx"],"ja":["新しいNxワークスペースの設定","プロジェクト境界の構成","CIの最適化with affectedコマンド","リモートキャッシュの実装","プロジェクト間の依存関係の管理","Nxへの移行"],"ko":["새로운 Nx 작업 공간 설정","프로젝트 경계 구성","CI 최적화 with affected 명령","리모ート 캐싱 구현","프로젝트 간 의존성 관리","Nx로의 마이그레이션"],"es":["Configuración de proyectos y aplicaciones con Nx","Optimización de CI con comandos afectados","Implementación de caché remota para mejorar el rendimiento","Gestión de dependencias entre proyectos","Migración a Nx desde otros sistemas de gestión de monorepos"],"fr":["Configuration de projets et d''applications avec Nx","Optimisation de CI avec des commandes affectées","Implementation d''un cache distant pour améliorer les performances","Gestion de dépendances entre projets","Migration vers Nx à partir d''autres systèmes de gestion de monorepos"],"de":["Konfiguration von Projekten und Anwendungen mit Nx","Optimierung von CI mit betroffenen Befehlen","Implementierung von Remote-Caching für bessere Leistung","Verwaltung von Abhängigkeiten zwischen Projekten","Migration zu Nx von anderen Monorepo-Management-Systemen"],"pt":["Configuração de projetos e dependências","Otimização de CI com comandos afetados","Implementação de cache remoto","Gerenciamento de dependências entre projetos","Migração para o Nx"],"ru":["Конфигурация проектов и зависимостей","Оптимизация CI с помощью команд, затрагивающих","Реализация удаленного кэширования","Управление зависимостями между проектами","Миграция на Nx"],"ar":["تكوين المشاريع والاعتمادات","تحسين CI باستخدام أوامر المؤثرة","تنفيذ ذاكرة التخزين المؤقت عن بعد","إدارة الاعتمادات بين المشاريع","هجرة إلى Nx"]},"keywords":{"en":["how to use nx-workspace-patterns","nx-workspace-patterns setup guide","nx monorepo management best practices","nx-workspace-patterns vs lerna","nx affected commands tutorial","nx remote caching installation","nx workspace optimization techniques","nx-workspace-patterns alternative","nx-workspace-patterns install"],"zh":["Nx Workspace Patterns","AIエージェント","Nx单体仓库管理","CI优化","远程缓存","项目边界配置","affected命令","Nx迁移"],"ja":["Nx Workspace Patterns","AIエージェント","Nxモノリポ管理","CI最適化","リモートキャッシュ","プロジェクト境界構成","affectedコマンド","Nx移行"],"ko":["Nx Workspace Patterns","AI 에이전트","Nx 모노리포 관리","CI 최적화","리모트 캐싱","프로젝트 경계 구성","affected 명령","Nx 마이그레이션"],"es":["nx-workspace-patterns","monorepos","gestión de proyectos","optimización de CI","caché remota","dependencias entre proyectos","migración a Nx","herramientas de desarrollo de software","patrones de diseño de software"],"fr":["modèles de workspace Nx","monorepos","gestion de projets","optimisation de CI","cache distant","dépendances entre projets","migration vers Nx","outils de développement de logiciels","modèles de conception de logiciels"],"de":["nx-workspace-patterns","monorepos","projektverwaltung","ci-optimierung","remote-caching","abhängigkeiten zwischen projekten","migration zu nx","software-entwicklungs-tools","software-design-muster"],"pt":["nx workspace patterns","monorepo nx","configuração de projetos","otimização de ci","cache remoto","gerenciamento de dependências","migração para o nx","desenvolvimento de software","arquitetura de cloud"],"ru":["шаблоны nx workspace","монорепозиторий nx","конфигурация проектов","оптимизация ci","удаленное кэширование","управление зависимостями","миграция на nx","разработка программного обеспечения","облачная архитектура"],"ar":["أنماط مساحة العمل nx","مستودع المجرد nx","تكوين المشاريع","تحسين ci","ذاكرة التخزين المؤقت عن بعد","إدارة الاعتمادات","هجرة إلى nx","تطوير البرمجيات","هندسة السحابة"]}},"owner":"harshahosur81","repo":"ag-opencode-skills","repoPath":"harshahosur81/ag-opencode-skills","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.766Z","topics":[],"category":"community","skillMd":{"name":"nx-workspace-patterns","description":"Configure and optimize Nx monorepo workspaces. Use when setting up Nx, configuring project boundaries, optimizing build caching, or implementing affected commands.","bodyPreview":"# Nx Workspace Patterns\n\nProduction patterns for Nx monorepo management.\n\n## When to Use This Skill\n\n- Setting up new Nx workspaces\n- Configuring project boundaries\n- Optimizing CI with affected commands\n- Implementing remote caching\n- Managing dependencies between projects\n- Migrating to Nx\n\n## Core Concepts\n\n### 1. Nx Architecture\n\n```\nworkspace/\n├── apps/              # Deployable applications\n│   ├── web/\n│   └── api/\n├── libs/              # Shared libraries\n│   ├── shared/\n│   │   ├── ui/","body":"# Nx Workspace Patterns\n\nProduction patterns for Nx monorepo management.\n\n## When to Use This Skill\n\n- Setting up new Nx workspaces\n- Configuring project boundaries\n- Optimizing CI with affected commands\n- Implementing remote caching\n- Managing dependencies between projects\n- Migrating to Nx\n\n## Core Concepts\n\n### 1. Nx Architecture\n\n```\nworkspace/\n├── apps/              # Deployable applications\n│   ├── web/\n│   └── api/\n├── libs/              # Shared libraries\n│   ├── shared/\n│   │   ├── ui/\n│   │   └── utils/\n│   └── feature/\n│       ├── auth/\n│       └── dashboard/\n├── tools/             # Custom executors/generators\n├── nx.json            # Nx configuration\n└── workspace.json     # Project configuration\n```\n\n### 2. Library Types\n\n| Type | Purpose | Example |\n|------|---------|---------|\n| **feature** | Smart components, business logic | `feature-auth` |\n| **ui** | Presentational components | `ui-buttons` |\n| **data-access** | API calls, state management | `data-access-users` |\n| **util** | Pure functions, helpers | `util-formatting` |\n| **shell** | App bootstrapping | `shell-web` |\n\n## Templates\n\n### Template 1: nx.json Configuration\n\n```json\n{\n  \"$schema\": \"./node_modules/nx/schemas/nx-schema.json\",\n  \"npmScope\": \"myorg\",\n  \"affected\": {\n    \"defaultBase\": \"main\"\n  },\n  \"tasksRunnerOptions\": {\n    \"default\": {\n      \"runner\": \"nx/tasks-runners/default\",\n      \"options\": {\n        \"cacheableOperations\": [\n          \"build\",\n          \"lint\",\n          \"test\",\n          \"e2e\",\n          \"build-storybook\"\n        ],\n        \"parallel\": 3\n      }\n    }\n  },\n  \"targetDefaults\": {\n    \"build\": {\n      \"dependsOn\": [\"^build\"],\n      \"inputs\": [\"production\", \"^production\"],\n      \"cache\": true\n    },\n    \"test\": {\n      \"inputs\": [\"default\", \"^production\", \"{workspaceRoot}/jest.preset.js\"],\n      \"cache\": true\n    },\n    \"lint\": {\n      \"inputs\": [\"default\", \"{workspaceRoot}/.eslintrc.json\"],\n      \"cache\": true\n    },\n    \"e2e\": {\n      \"inputs\": [\"default\", \"^production\"],\n      \"cache\": true\n    }\n  },\n  \"namedInputs\": {\n    \"default\": [\"{projectRoot}/**/*\", \"sharedGlobals\"],\n    \"production\": [\n      \"default\",\n      \"!{projectRoot}/**/?(*.)+(spec|test).[jt]s?(x)?(.snap)\",\n      \"!{projectRoot}/tsconfig.spec.json\",\n      \"!{projectRoot}/jest.config.[jt]s\",\n      \"!{projectRoot}/.eslintrc.json\"\n    ],\n    \"sharedGlobals\": [\n      \"{workspaceRoot}/babel.config.json\",\n      \"{workspaceRoot}/tsconfig.base.json\"\n    ]\n  },\n  \"generators\": {\n    \"@nx/react\": {\n      \"application\": {\n        \"style\": \"css\",\n        \"linter\": \"eslint\",\n        \"bundler\": \"webpack\"\n      },\n      \"library\": {\n        \"style\": \"css\",\n        \"linter\": \"eslint\"\n      },\n      \"component\": {\n        \"style\": \"css\"\n      }\n    }\n  }\n}\n```\n\n### Template 2: Project Configuration\n\n```json\n// apps/web/project.json\n{\n  \"name\": \"web\",\n  \"$schema\": \"../../node_modules/nx/schemas/project-schema.json\",\n  \"sourceRoot\": \"apps/web/src\",\n  \"projectType\": \"application\",\n  \"tags\": [\"type:app\", \"scope:web\"],\n  \"targets\": {\n    \"build\": {\n      \"executor\": \"@nx/webpack:webpack\",\n      \"outputs\": [\"{options.outputPath}\"],\n      \"defaultConfiguration\": \"production\",\n      \"options\": {\n        \"compiler\": \"babel\",\n        \"outputPath\": \"dist/apps/web\",\n        \"index\": \"apps/web/src/index.html\",\n        \"main\": \"apps/web/src/main.tsx\",\n        \"tsConfig\": \"apps/web/tsconfig.app.json\",\n        \"assets\": [\"apps/web/src/assets\"],\n        \"styles\": [\"apps/web/src/styles.css\"]\n      },\n      \"configurations\": {\n        \"development\": {\n          \"extractLicenses\": false,\n          \"optimization\": false,\n          \"sourceMap\": true\n        },\n        \"production\": {\n          \"optimization\": true,\n          \"outputHashing\": \"all\",\n          \"sourceMap\": false,\n          \"extractLicenses\": true\n        }\n      }\n    },\n    \"serve\": {\n      \"executor\": \"@nx/webpack:dev-server\",\n      \"defaultConfiguration\": \"development\",\n      \"options\": {\n        \"buildTarget\": \"web:build\"\n      },\n      \"configurations\": {\n        \"development\": {\n          \"buildTarget\": \"web:build:development\"\n        },\n        \"production\": {\n          \"buildTarget\": \"web:build:production\"\n        }\n      }\n    },\n    \"test\": {\n      \"executor\": \"@nx/jest:jest\",\n      \"outputs\": [\"{workspaceRoot}/coverage/{projectRoot}\"],\n      \"options\": {\n        \"jestConfig\": \"apps/web/jest.config.ts\",\n        \"passWithNoTests\": true\n      }\n    },\n    \"lint\": {\n      \"executor\": \"@nx/eslint:lint\",\n      \"outputs\": [\"{options.outputFile}\"],\n      \"options\": {\n        \"lintFilePatterns\": [\"apps/web/**/*.{ts,tsx,js,jsx}\"]\n      }\n    }\n  }\n}\n```\n\n### Template 3: Module Boundary Rules\n\n```json\n// .eslintrc.json\n{\n  \"root\": true,\n  \"ignorePatterns\": [\"**/*\"],\n  \"plugins\": [\"@nx\"],\n  \"overrides\": [\n    {\n      \"files\": [\"*.ts\", \"*.tsx\", \"*.js\", \"*.jsx\"],\n      \"rules\": {\n        \"@nx/enforce-module-boundaries\": [\n          \"error\",\n          {\n            \"enforceBuildableLibDependency\": true,\n            \"allow\": [],\n            \"depConstraints\": [\n              {\n                \"sourceTag\": \"type:app\",\n                \"onlyDependOnLibsWithTags\": [\n                  \"type:feature\",\n                  \"type:ui\",\n                  \"type:data-access\",\n                  \"type:util\"\n                ]\n              },\n              {\n                \"sourceTag\": \"type:feature\",\n                \"onlyDependOnLibsWithTags\": [\n                  \"type:ui\",\n                  \"type:data-access\",\n                  \"type:util\"\n                ]\n              },\n              {\n                \"sourceTag\": \"type:ui\",\n                \"onlyDependOnLibsWithTags\": [\"type:ui\", \"type:util\"]\n              },\n              {\n                \"sourceTag\": \"type:data-access\",\n                \"onlyDependOnLibsWithTags\": [\"type:data-access\", \"type:util\"]\n              },\n              {\n                \"sourceTag\": \"type:util\",\n                \"onlyDependOnLibsWithTags\": [\"type:util\"]\n              },\n              {\n                \"sourceTag\": \"scope:web\",\n                \"onlyDependOnLibsWithTags\": [\"scope:web\", \"scope:shared\"]\n              },\n              {\n                \"sourceTag\": \"scope:api\",\n                \"onlyDependOnLibsWithTags\": [\"scope:api\", \"scope:shared\"]\n              },\n              {\n                \"sourceTag\": \"scope:shared\",\n                \"onlyDependOnLibsWithTags\": [\"scope:shared\"]\n              }\n            ]\n          }\n        ]\n      }\n    }\n  ]\n}\n```\n\n### Template 4: Custom Generator\n\n```typescript\n// tools/generators/feature-lib/index.ts\nimport {\n  Tree,\n  formatFiles,\n  generateFiles,\n  joinPathFragments,\n  names,\n  readProjectConfiguration,\n} from ''@nx/devkit'';\nimport { libraryGenerator } from ''@nx/react'';\n\ninterface FeatureLibraryGeneratorSchema {\n  name: string;\n  scope: string;\n  directory?: string;\n}\n\nexport default async function featureLibraryGenerator(\n  tree: Tree,\n  options: FeatureLibraryGeneratorSchema\n) {\n  const { name, scope, directory } = options;\n  const projectDirectory = directory\n    ? `${directory}/${name}`\n    : `libs/${scope}/feature-${name}`;\n\n  // Generate base library\n  await libraryGenerator(tree, {\n    name: `feature-${name}`,\n    directory: projectDirectory,\n    tags: `type:feature,scope:${scope}`,\n    style: ''css'',\n    skipTsConfig: false,\n    skipFormat: true,\n    unitTestRunner: ''jest'',\n    linter: ''eslint'',\n  });\n\n  // Add custom files\n  const projectConfig = readProjectConfiguration(tree, `${scope}-feature-${name}`);\n  const projectNames = names(name);\n\n  generateFiles(\n    tree,\n    joinPathFragments(__dirname, ''files''),\n    projectConfig.sourceRoot,\n    {\n      ...projectNames,\n      scope,\n      tmpl: '''',\n    }\n  );\n\n  await formatFiles(tree);\n}\n```\n\n### Template 5: CI Configuration with Affected\n\n```yaml\n# .github/workflows/ci.yml\nname: CI\n\non:\n  push:\n    branches: [main]\n  pull_request:\n    branches: [main]\n\nenv:\n  NX_CLOUD_ACCESS_TOKEN: ${{ secrets.NX_CLOUD_ACCESS_TOKEN }}\n\njobs:\n  main:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n        with:\n          fetch-depth: 0\n\n      - uses: actions/setup-node@v4\n        with:\n          node-version: 20\n          cache: ''npm''\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Derive SHAs for affected commands\n        uses: nrwl/nx-set-shas@v4\n\n      - name: Run affected lint\n        run: npx nx affected -t lint --parallel=3\n\n      - name: Run affected test\n        run: npx nx affected -t test --parallel=3 --configuration=ci\n\n      - name: Run affected build\n        run: npx nx affected -t build --parallel=3\n\n      - name: Run affected e2e\n        run: npx nx affected -t e2e --parallel=1\n```\n\n### Template 6: Remote Caching Setup\n\n```typescript\n// nx.json with Nx Cloud\n{\n  \"tasksRunnerOptions\": {\n    \"default\": {\n      \"runner\": \"nx-cloud\",\n      \"options\": {\n        \"cacheableOperations\": [\"build\", \"lint\", \"test\", \"e2e\"],\n        \"accessToken\": \"your-nx-cloud-token\",\n        \"parallel\": 3,\n        \"cacheDirectory\": \".nx/cache\"\n      }\n    }\n  },\n  \"nxCloudAccessToken\": \"your-nx-cloud-token\"\n}\n\n// Self-hosted cache with S3\n{\n  \"tasksRunnerOptions\": {\n    \"default\": {\n      \"runner\": \"@nx-aws-cache/nx-aws-cache\",\n      \"options\": {\n        \"cacheableOperations\": [\"build\", \"lint\", \"test\"],\n        \"awsRegion\": \"us-east-1\",\n        \"awsBucket\": \"my-nx-cache-bucket\",\n        \"awsProfile\": \"default\"\n      }\n    }\n  }\n}\n```\n\n## Common Commands\n\n```bash\n# Generate new library\nnx g @nx/react:lib feature-auth --directory=libs/web --tags=type:feature,scope:web\n\n# Run affected tests\nnx affected -t test --base=main\n\n# View dependency graph\nnx graph\n\n# Run specific project\nnx build web --configuration=production\n\n# Reset cache\nnx reset\n\n# Run migrations\nnx migrate latest\nnx migrate --run-migrations\n```\n\n## Best Practices\n\n### Do''s\n- **Use tags consistently** - Enforce with module boundaries\n- **Enable caching early** - Significant CI savings\n- **Keep libs focused** - Single responsibility\n- **Use generators** - Ensure consistency\n- **Document boundaries** - Help new developers\n\n### Don''ts\n- **Don''t create circular deps** - Graph should be acyclic\n- **Don''t skip affected** - Test only what changed\n- **Don''t ignore boundaries** - Tech debt accumulates\n- **Don''t over-granularize** - Balance lib count\n\n## Resources\n\n- [Nx Documentation](https://nx.dev/getting-started/intro)\n- [Module Boundaries](https://nx.dev/core-features/enforce-module-boundaries)\n- [Nx Cloud](https://nx.app/)\n"},"lastSynced":"2026-03-07T13:03:23.565Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing advanced Nx monorepo management capabilities.","zh":"非常适合需要高级 Nx 单体仓库管理功能的 DevOps 代理。","ja":"DevOps エージェントが Nx モノリポ管理の高度な機能を必要とする場合に最適です。","ko":"고급 Nx 모노리포 관리 기능이 필요한 DevOps 에이전트에게 적합합니다.","es":"Perfecto para agentes de DevOps que necesitan capacidades de gestión de monorepo de Nx avanzadas.","fr":"Parfait pour les agents DevOps ayant besoin de fonctionnalités de gestion de monorepo Nx avancées.","de":"Perfekt für DevOps-Agents, die erweiterte Nx-Monorepo-Verwaltungsfunktionen benötigen.","pt":"Perfeito para Agentes DevOps que precisam de capacidades avançadas de gerenciamento de monorepo Nx.","ru":"Идеально для агентов DevOps, которым требуются расширенные возможности управления монорепозиторием Nx.","ar":"مثالي لعميل DevOps الذي يحتاج إلى إمكانيات متقدمة لإدارة monorepo Nx."},"recommendation":{"en":"Empowers agents to optimize CI with affected commands, implement remote caching, and manage dependencies between projects using Nx workspace patterns, leveraging libraries and project boundaries for efficient monorepo setup and configuration.","zh":"赋予代理人优化 CI 的能力，使用受影响的命令，实现远程缓存，并使用 Nx 工作空间模式管理项目之间的依赖关系，利用库和项目边界实现高效的单体仓库设置和配置。","ja":"エージェントが CI を最適化する能力を与え、影響を受けたコマンドを使用してリモート キャッシュを実装し、Nx ワークスペース パターンを使用してプロジェクト間の依存関係を管理し、ライブラリとプロジェクトの境界を使用してモノリポの設定と構成を効率化します。","ko":"에이전트가 CI를 최적화 할 수 있는 능력을 부여하여 영향을 받은 명령을 사용하여 원격 캐싱을 구현하고 Nx 작업 공간 패턴을 사용하여 프로젝트 간의 종속성을 관리하며 라이브러리와 프로젝트 경계를 사용하여 모노리포 설정 및 구성의 효율성을 높입니다.","es":"Habilita a los agentes a optimizar la integración continua con comandos afectados, implementar la caché remota y gestionar las dependencias entre proyectos utilizando patrones de espacio de trabajo de Nx, aprovechando las bibliotecas y los límites de proyecto para una configuración y configuración de monorepo eficientes.","fr":"Permet aux agents d''optimiser l''intégration continue avec des commandes affectées, de mettre en œuvre un cache distant et de gérer les dépendances entre les projets en utilisant des modèles d''espace de travail Nx, en exploitant les bibliothèques et les limites de projet pour une configuration et une configuration de monorepo efficaces.","de":"Ermächtigt Agents, die kontinuierliche Integration mit betroffenen Befehlen zu optimieren, Remote-Caching zu implementieren und Abhängigkeiten zwischen Projekten mithilfe von Nx-Arbeitsbereichsmustern zu verwalten, indem Bibliotheken und Projektgrenzen für eine effiziente Monorepo-Einrichtung und -Konfiguration genutzt werden.","pt":"Habilita os agentes a otimizar a CI com comandos afetados, implementar cache remoto e gerenciar dependências entre projetos usando padrões de espaço de trabalho Nx, aproveitando bibliotecas e limites de projeto para configuração e instalação eficientes de monorepo.","ru":"Наделяет агентов возможностью оптимизировать CI с помощью команд, затрагивающих изменения, реализовать удаленный кэш и управлять зависимостями между проектами с использованием шаблонов рабочего пространства Nx, используя библиотеки и границы проекта для эффективной настройки и конфигурации монорепозитория.","ar":"يمنح الوكلاء القدرة على تحسين CI باستخدام أوامر المتأثرة بها، وتنفيذ ذاكرة التخزين المؤقت عن بعد، وإدارة التبعيات بين المشاريع باستخدام أنماط مساحة العمل Nx، واستخدام المكتبات وحدود المشروع من أجل إعداد وتكوين كفء ل monorepo."},"useCases":{"en":["Setting up new Nx workspaces with optimized project structures","Configuring project boundaries for efficient dependency management","Optimizing CI pipelines with affected commands for faster deployment"],"zh":["设置具有优化的项目结构的新 Nx 工作空间","配置项目边界以实现高效的依赖管理","使用受影响的命令优化 CI 流水线以实现更快的部署"],"ja":["最適化されたプロジェクト構造を持つ新しい Nx ワークスペースを設定する","プロジェクト境界を設定して依存関係の管理を効率化する","影響を受けたコマンドを使用して CI パイプラインを最適化し、デプロイを高速化する"],"ko":["최적화된 프로젝트 구조를 가진 새로운 Nx 작업 공간을 설정하는 것","프로젝트 경계를 구성하여 종속성 관리를 효율화하는 것","영향을 받은 명령을 사용하여 CI 파이프라인을 최적화하여 배포를 더 빠르게 하는 것"],"es":["Configuración de nuevos espacios de trabajo de Nx con estructuras de proyecto optimizadas","Configuración de límites de proyecto para una gestión de dependencias eficiente","Optimización de tuberías de integración continua con comandos afectados para una implementación más rápida"],"fr":["Configuration de nouveaux espaces de travail Nx avec des structures de projet optimisées","Configuration des limites de projet pour une gestion de dépendances efficace","Optimisation des pipelines d''intégration continue avec des commandes affectées pour un déploiement plus rapide"],"de":["Einrichtung neuer Nx-Arbeitsbereiche mit optimierten Projektstrukturen","Konfiguration von Projektgrenzen für eine effiziente Abhängigkeitsverwaltung","Optimierung von Continuous-Integration-Pipelines mit betroffenen Befehlen für eine schnellere Bereitstellung"],"pt":["Configuração de novos espaços de trabalho Nx com estruturas de projeto otimizadas","Configuração de limites de projeto para gerenciamento eficiente de dependências","Otimização de pipelines CI com comandos afetados para implantação mais rápida"],"ru":["Настройка новых рабочих пространств Nx с оптимизированной структурой проектов","Настройка границ проекта для эффективного управления зависимостями","Оптимизация конвейеров CI с командами, затрагивающими изменения, для более быстрой развертки"],"ar":["إعداد مساحات عمل Nx جديدة مع هياكل مشروع محسنة","تكوين حدود المشروع لإدارة التبعيات بكفاءة","تحسين خطوط أنابيب CI مع أوامر المتأثرة بها من أجل نشر أسرع"]},"limitations":{"en":["Requires Nx monorepo setup","Limited to Nx workspace management"],"zh":["需要 Nx 单体仓库设置","仅限于 Nx 工作空间管理"],"ja":["Nx モノリポの設定が必要","Nx ワークスペース管理のみに限定される"],"ko":["Nx 모노리포 설정이 필요","Nx 작업 공간 관리에만 제한됨"],"es":["Requiere configuración de monorepo de Nx","Limitado a la gestión del espacio de trabajo de Nx"],"fr":["Nécessite une configuration de monorepo Nx","Limité à la gestion de l''espace de travail Nx"],"de":["Erfordert Nx-Monorepo-Setup","Begrenzt auf die Verwaltung des Nx-Arbeitsbereichs"],"pt":["Exige configuração de monorepo Nx","Limitado ao gerenciamento de espaço de trabalho Nx"],"ru":["Требует настройки монорепозитория Nx","Ограничен управлением рабочим пространством Nx"],"ar":["يتطلب إعداد monorepo Nx","محدود بإدارة مساحة العمل Nx"]},"version":4},"contentHash":"6286fae01303804282fedd8b858cd8312e0637126abe6b8f3d01eab19e9777a0","qualityScore":60}');
