INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('harshahosur81/ag-opencode-skills/nx-workspace-patterns', 'nx-workspace-patterns', 'harshahosur81', 'ag-opencode-skills', 'community', 'nx-workspace-patterns harshahosur81 ag-opencode-skills community The nx-workspace-patterns skill provides production patterns for Nx monorepo management, benefiting developers setting up new workspaces, configuring project boundaries, and optimizing CI with affected commands. Nx Workspace Patterns提供生产模式，用于Nx单体仓库管理，优化CI和远程缓存 Nx Workspace Patternsは、Nxモノリポ管理のためのプロダクションパターンを提供し、CIとリモートキャッシュを最適化します Nx Workspace Patterns는 Nx 모노리포 관리를 위한 생산 패턴을 제공하여 CI 및 리모ート 캐싱을 최적화합니다 nx-workspace-patterns es una colección de patrones para la gestión de monorepos con Nx. Incluye configuración de proyectos, optimización de CI y gestión de dependencias Les modèles de workspace Nx sont une collection de modèles pour la gestion de monorepos avec Nx. Ils incluent la configuration de projets, l''optimisation de CI et la gestion de dépendances nx-workspace-patterns ist eine Sammlung von Mustern für die Verwaltung von Monorepos mit Nx. Sie umfasst die Konfiguration von Projekten, die Optimierung von CI und die Verwaltung von Abhängigkeiten O Nx Workspace Patterns fornece padrões de produção para gerenciamento de monorepo Nx, incluindo configuração de projetos e dependências Шаблоны Nx Workspace предоставляют шаблоны производства для управления монорепозиторием Nx, включая конфигурацию проектов и зависимостей توفر أنماط مساحة العمل Nx أنماط الإنتاج لإدارة مستودع المجرد Nx، بما في ذلك تكوين المشاريع والاعتمادات how to use nx-workspace-patterns nx-workspace-patterns setup guide nx monorepo management best practices nx-workspace-patterns vs lerna nx affected commands tutorial nx remote caching installation nx workspace optimization techniques nx-workspace-patterns alternative nx-workspace-patterns install Nx Workspace Patterns AIエージェント Nx单体仓库管理 CI优化 远程缓存 项目边界配置 affected命令 Nx迁移 Configures project boundaries for efficient Nx workspace management Optimizes CI with affected commands for faster build times Implements remote caching for improved performance Manages dependencies between projects with shared libraries Migrates existing projects to Nx for streamlined development Sets up new Nx workspaces with best practices nx-workspace-patterns is a collection of skills for efficient Nx monorepo management, covering setup, configuration, and optimization techniques.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ThinkfleetAI/thinkfleet-engine/github-action-gen', 'community', 'ThinkfleetAI', 'thinkfleet-engine', 'ThinkfleetAI/thinkfleet-engine', 'github-action-gen', 0, 0, 60, '2026-03-07T12:46:33.790Z', '2026-03-07T13:04:26.626Z', '702367d412e26389bc4d35ec43bdecb6f104066af8929564c14b51cae4c4fde5', '{"id":"ThinkfleetAI/thinkfleet-engine/github-action-gen","name":"github-action-gen","description":{"en":"github-action-gen is a skill that generates complete GitHub Actions workflow files, handling common patterns and including caching for faster runs. It benefits developers by simplifying workflow creation.","zh":"GitHub Action 生成器是一种自动化工具，能够自动生成 GitHub Actions 工作流文件，支持测试、构建和部署等功能","ja":"GitHub Actions ワークフロー生成ツールは、GitHub Actions ワークフローを自動生成するツールで、テスト、ビルド、デプロイなどの機能をサポートしています","ko":"GitHub Action 생성기는 GitHub Actions 워크플로우를 자동으로 생성하는 도구로 테스트、빌드 및 배포와 같은 기능을 지원합니다","es":"github-action-gen es una herramienta de línea de comandos que genera archivos de flujo de trabajo de GitHub Actions para automatizar tareas como pruebas, compilación y despliegue","fr":"github-action-gen est un outil de ligne de commande qui génère des fichiers de flux de travail GitHub Actions pour automatiser des tâches telles que les tests, la construction et le déploiement","de":"github-action-gen ist ein Kommandozeilen-Tool, das GitHub-Actions-Workflow-Dateien für die Automatisierung von Aufgaben wie Tests, Build und Deployment generiert","pt":"O GitHub Action Generator é uma ferramenta que gera fluxos de trabalho do GitHub Actions com base em descrições simples. Ele suporta padrões comuns como testes, compilação e implantação.","ru":"ИИ Агент GitHub Action Generator — это инструмент, который генерирует рабочие процессы GitHub Actions на основе простых описаний. Он поддерживает общие шаблоны, такие как тестирование, сборка и развертывание.","ar":"جهاز