INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fgarofalo56/Suppercharge_Microsoft_Fabric/github', 'github', 'fgarofalo56', 'Suppercharge_Microsoft_Fabric', 'community', 'github fgarofalo56 Suppercharge_Microsoft_Fabric community The github skill provides complete GitHub integration via the gh CLI, covering repositories, issues, and more. It benefits developers and teams working with GitHub. GitHub Operations Skill 提供 90+ 个操作，涵盖 GitHub 的所有方面，包括仓库、问题、拉取请求等。使用 gh CLI 实现全面的 GitHub 集成 GitHub AIエージェントは、リポジトリ、課題、プルリクエストなど 90 種類以上の操作を提供し、GitHub のすべての側面をカバーします。gh CLI を使用して、完全な GitHub 統合を実現します GitHub Operations Skill은 90가지 이상의 운영을 제공하여 GitHub의 모든 측면을 다룹니다. 저장소, 이슈, 풀 리퀘스트 등이 포함됩니다. gh CLI를 사용하여 전체적인 GitHub 통합을 구현합니다 El skill de GitHub ofrece integración completa con el CLI de GitHub, incluyendo operaciones para repositorios, problemas, solicitudes de extracción y más Le skill GitHub propose une intégration complète avec le CLI GitHub, y compris des opérations pour les référentiels, les problèmes, les demandes d''extraction et plus Das GitHub-Skill bietet eine vollständige Integration mit dem GitHub-CLI, einschließlich Operationen für Repositorys, Probleme, Pull-Requests und mehr O GitHub Operations Skill fornece integração completa via CLI, com 90+ operações para repositórios, problemas e mais Навык операций GitHub обеспечивает полную интеграцию через CLI, с более 90 операциями для репозиториев, проблем и т. д. مahir GitHub Operations Skill يوفر التكامل الكامل عبر واجهة سطر الأوامر، مع أكثر من 90 عملية لمستودعات، مشاكل وغيرها github setup guide how to use gh CLI github integration for developers github vs gitlab github alternative for repository management installing gh CLI for github github authentication and verification github operations for AI agents GitHub Operations Skill gh CLI 仓库管理 问题管理 拉取请求 Actions 安全功能 讨论和项目管理 GitHub 集成 Provides 90+ operations for GitHub integration via the gh CLI Supports repository operations, including issues and pull requests Enables authentication and verification using gh auth login and gh auth status Covers GitHub features such as Actions, security, discussions, and projects Allows for real-time intelligence and Direct Lake integration github is a skill providing 90+ operations for GitHub integration, including repository management and issue tracking via the gh CLI');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('frizynn/gralph/prd', 'community', 'frizynn', 'gralph', 'frizynn/gralph', 'prd', 0, 0, 60, '2026-03-07T01:49:01.453Z', '2026-03-07T01:56:21.347Z', '1b5b65364f2b7ea9022bcb23ad369bcbc6171cdfc69707d3009dec692be2e4ef', '{"id":"frizynn/gralph/prd","name":"prd","description":{"en":"prd is a high-performance implementation that orchestrates multi-agent execution for AI agents like Amp, Cursor, and Codex. It generates detailed Product Requirements Documents based on user input and clarifying questions.","zh":"PRD 技术实现了高性能的自动化循环，利用 Git worktree 隔离和多代理执行","ja":"PRD は AIエージェントを使用した自動化ループの高性能実装です","ko":"PRD는 고성능 자동화 루프 구현을 위한 기술로, Git worktree 분리 및 다중 에이전트 실행을 지원","es":"PRD es una implementación de alto rendimiento que orquesta la ejecución de agentes múltiples, utilizando aislamiento de Git worktree para escalar el desarrollo impulsado por PRD","fr":"PRD est une mise en œuvre de haute performance qui orchestre l''exécution de plusieurs agents, en utilisant l''isolement de Git worktree pour faire évoluer le développement piloté par PRD","de":"PRD ist eine Hochleistungs-Implementierung, die die Ausführung von Multi-Agenten orchestriert, indem sie die Isolation von Git worktree zur Skalierung der PRD-getriebenen Entwicklung nutzt","pt":"O PRD é uma implementação de alto desempenho do loop autônomo Ralph, que orquestra a execução de multi-agentes em Claude Code e Cursor.","ru":"PRD — это высокопроизводительная реализация автономного цикла Ralph, которая оркестрирует выполнение многоагентных задач в Claude Code и Cursor.","ar":"PRD هو تنفيذ ذو أداء عالي للدوائر المستقلة رالف، والذي يتولى تنفيذ مهام متعددة الوكلاء في كلود كود وكيرسر."},"seo":{"title":{"en":"prd: Automated PRD Generation for AI Agents | AI Agent Skill","zh":"PRD 技术指南：高性能自动化循环实现","ja":"PRD ベストプラクティス：AIエージェントによる自動化ループ","ko":"PRD 개발 가이드: 고성능 자동화 루프 구현","es":"Guía de configuración de PRD para Agentes de IA","fr":"Guide de mise en place de PRD pour les Outils d''IA","de":"Einrichtungsleitfaden für PRD mit KI-Agents","pt":"Guia de Configuração do PRD: Implementação de Loop Autôno...","ru":"Настройка PRD: Высокопроизводительная Реализация Автономн...","ar":"دليل إعداد PRD: تنفيذ حلقة مستقلة عالية الأداء"},"description":{"en":"Discover how prd automates Product Requirements Documents creation, ask clarifying questions, and generate structured PRDs. Learn more and get started with p...","zh":"了解 PRD 技术的高性能实现，利用 Git worktree 隔离和多代理执行","ja":"AIエージェントを使用した PRD 自動化ループのベストプラクティスを学ぶ","ko":"고성능 자동화 루프 구현을 위한 PRD 개발 가이드, Git worktree 분리 및 다중 에이전트 실행","es":"Optimice su desarrollo con PRD, una implementación de alto rendimiento para la orquestación de la ejecución de agentes múltiples","fr":"Améliorez votre développement avec PRD, une mise en œuvre de haute performance pour l''orchestration de l''exécution de plusieurs agents","de":"Optimieren Sie Ihre Entwicklung mit PRD, einer Hochleistungs-Implementierung für die Orchestrierung der Ausführung von Multi-Agenten","pt":"Aprenda a configurar o PRD com nossa guia passo a passo e melhore a eficiência do desenvolvimento com agentes de IA como Amp, Cursor e Codex.","ru":"Узнайте, как настроить PRD с нашей пошаговой инструкцией и повысьте эффективность разработки с помощью ИИ агентов, таких как Amp, Cursor и Codex.","ar":"تعلم كيفية إعداد PRD بفضل دليلنا المتقدم خطوة خطوة وطور كفاءة التطوير باستخدام وكلاء الذكاء الاصطناعي مثل Amp و Cursor و Codex."},"definition":{"en":"prd is a skill that automates the creation of Product Requirements Documents, utilizing Git worktree isolation for scalable PRD-driven development","zh":"PRD 是一种高性能的自动化循环技术，用于实现产品需求文档的生成","ja":"PRD は AIエージェントを使用した自動化ループの高性能実装の一種です","ko":"PRD는 고성능 자동화 루프 구현을 위한 기술로, 제품 요구 사항 문서 생성을 지원","es":"PRD es una herramienta de IA que genera documentos de requisitos de producto detallados y claros para la implementación de agentes de IA","fr":"PRD est un outil d''IA qui génère des documents de spécifications de produit détaillés et clairs pour la mise en œuvre d''agents d''IA","de":"PRD ist ein KI-Tool, das detaillierte und klare Produktanforderungsdokumente für die Implementierung von KI-Agents generiert","pt":"O PRD é um gerador de documentos de requisitos de produto que cria especificações claras e ação para implementação por agentes de IA.","ru":"PRD — это генератор документов требований к продукту, который создает четкие и действенные спецификации для реализации ИИ агентами.","ar":"PRD هو مولد وثائق متطلبات المنتج التي تنشئ مواصفات واضحة وقابلة للتنفيذ من قبل وكلاء الذكاء الاصطناعي."},"features":{"en":["Builds repository context to avoid ambiguity or conflicts","Asks 3-5 essential clarifying questions with lettered options","Generates structured PRDs based on user answers","Saves PRDs to tasks/prd-[feature-name].md files","Utilizes Git worktree isolation for scalable PRD-driven development"],"zh":["利用 Git worktree 隔离实现多代理执行","支持 Claude Code 和 Cursor 多代理协调","生成结构化的产品需求文档（PRD）","自动保存 PRD 文档至 tasks/prd-[feature-name].md","支持多个 AI 代理（Amp, Cursor, Codex 等）"],"ja":["Git worktree の分離を使用したマルチエージェントの実行","Claude Code と Cursor のマルチエージェントの調整をサポート","構造化された製品要件文書（PRD）を生成","PRD 文書を tasks/prd-[feature-name].md に自動保存","複数の AI エージェント（Amp, Cursor, Codex など）をサポート"],"ko":["Git worktree 분리 기능을 통한 다중 에이전트 실행","Claude Code 및 Cursor 다중 에이전트 협조 지원","구조화된 제품 요구 사항 문서（PRD）생성","PRD 문서를 tasks/prd-[feature-name].md에 자동 저장","다중 AI 에이전트（Amp, Cursor, Codex 등）지원"],"es":["Orquestación de la ejecución de agentes múltiples","Utilización de aislamiento de Git worktree para escalar el desarrollo","Generación de documentos de requisitos de producto detallados y claros","Compatibilidad con agentes de IA como Amp, Cursor y Codex","Creación de contexto de repositorio para evitar ambigüedades o conflictos"],"fr":["Orchestration de l''exécution de plusieurs agents","Utilisation de l''isolement de Git worktree pour faire évoluer le développement","Génération de documents de spécifications de produit détaillés et clairs","Compatibilité avec les agents d''IA tels que Amp, Cursor et Codex","Création de contexte de référentiel pour éviter les ambigüités ou les conflits"],"de":["Orchestrierung der Ausführung von Multi-Agenten","Verwendung der Isolation von Git worktree zur Skalierung der Entwicklung","Generierung detaillierter und klarer Produktanforderungsdokumente","Kompatibilität mit KI-Agents wie Amp, Cursor und Codex","Erstellung von Repository-Kontext zur Vermeidung von Mehrdeutigkeiten oder Konflikten"],"pt":["Implementação de loop autônomo de alto desempenho","Orquestração de multi-agentes em Claude Code e Cursor","Utilização de Git worktree para isolamento e escalabilidade","Geração de documentos de requisitos de produto claros e ação","Compatibilidade com agentes de IA como Amp, Cursor e Codex","Suporte à criação de repositórios de contexto para evitar ambiguidades"],"ru":["Высокопроизводительная реализация автономного цикла","Оркестрирование многоагентных задач в Claude Code и Cursor","Использование Git worktree для изоляции и масштабируемости","Генерация документов требований к продукту, четких и действенных","Совместимость с ИИ агентами, такими как Amp, Cursor и Codex","Поддержка создания контекста репозиториев для избежания неоднозначностей"],"ar":["تنفيذ حلقة مستقلة عالية الأداء","تنسيق مهام متعددة الوكلاء في كلود كود وكيرسر","استخدام Git worktree للعزل والتمكين","إنشاء وثائق متطلبات المنتج واضحة وقابلة للتنفيذ","دعم توافق وكلاء الذكاء الاصطناعي مثل Amp و Cursor و Codex","دعم إنشاء سياق مستودعات لتجنب الغموض"]},"keywords":{"en":["how to use prd","prd alternative","prd setup guide","what is prd","prd vs amp","prd install","prd generator","prd for ai agents","automated prd generation"],"zh":["PRD 技术","自动化循环","Git worktree 隔离","多代理执行","AI 代理","产品需求文档"," Claude Code","Cursor"],"ja":["PRD 技術","自動化ループ","Git worktree 分離","マルチエージェントの実行","AI エージェント","製品要件文書","Claude Code","Cursor","AIエージェント"],"ko":["PRD 기술","고성능 자동화 루프","Git worktree 분리","다중 에이전트 실행","AI 에이전트","제품 요구 사항 문서","Claude Code","Cursor","고성능 자동화"],"es":["PRD","Agentes de IA","Desarrollo de software","Git worktree","Orquestación de agentes","Generación de documentos de requisitos de producto","Amp","Cursor","Codex"],"fr":["PRD","Outils d''IA","Développement de logiciels","Git worktree","Orchestration d''agents","Génération de documents de spécifications de produit","Amp","Cursor","Codex"],"de":["PRD","KI-Agents","Software-Entwicklung","Git worktree","Orchestrierung von Agenten","Generierung von Produktanforderungsdokumenten","Amp","Cursor","Codex"],"pt":["PRD","loop autônomo","agentes de IA","desenvolvimento de software","Git worktree","Claude Code","Cursor","Amp","Codex","documentos de requisitos de produto"],"ru":["PRD","автономный цикл","ИИ агенты","разработка программного обеспечения","Git worktree","Claude Code","Cursor","Amp","Codex","документы требований к продукту"],"ar":["PRD","حلقة مستقلة","وكلاء الذكاء الاصطناعي","تطوير البرمجيات","Git worktree","كلود كود","كيرسر","أмп","كودكس","وثائق متطلبات المنتج"]}},"owner":"frizynn","repo":"gralph","repoPath":"frizynn/gralph","stars":0,"forks":0,"updatedAt":"2026-03-07T01:49:01.453Z","topics":[],"category":"community","skillMd":{"name":"prd","description":"Generate a Product Requirements Document (PRD) for a new feature. Use when planning a feature, starting a new project, or when asked to create a PRD. The PRD should be detailed enough for execution by AI agents across tools (Amp, Cursor, Codex, etc.). Triggers on: create a prd, write prd for, plan this feature, requirements for, spec out.","bodyPreview":"# PRD Generator\n\nCreate detailed Product Requirements Documents that are clear, actionable, and suitable for implementation by AI agents (Amp, Cursor, Codex, etc.).\n\n---\n\n## The Job\n\n1. Build repository context as needed to avoid ambiguity or conflicts\n2. Receive a feature description from the user\n3. Ask 3-5 essential clarifying questions (with lettered options)\n4. Generate a structured PRD based on answers\n5. Save to `tasks/prd-[feature-name].md`\n\n**Important:** Do NOT start implementing. Just","body":"# PRD Generator\n\nCreate detailed Product Requirements Documents that are clear, actionable, and suitable for implementation by AI agents (Amp, Cursor, Codex, etc.).\n\n---\n\n## The Job\n\n1. Build repository context as needed to avoid ambiguity or conflicts\n2. Receive a feature description from the user\n3. Ask 3-5 essential clarifying questions (with lettered options)\n4. Generate a structured PRD based on answers\n5. Save to `tasks/prd-[feature-name].md`\n\n**Important:** Do NOT start implementing. Just create the PRD.\n\n---\n\n## Step 0: Repository Context (As Needed)\n\nGather only the context required to remove ambiguity. Prefer targeted reading:\n\n- Start with high-signal sources (README, docs, config, entry points)\n- Scan for related features, data models, and modules that touch the request\n- Identify conventions, constraints, and dependencies that affect scope\n\nIf the request is highly ambiguous or spans multiple subsystems, expand the review to more of the repo. Summarize findings in brief working notes before writing the PRD.\n\n---\n\n## Step 1: Clarifying Questions\n\nAsk only critical questions where the initial prompt is ambiguous. Focus on:\n\n- **Problem/Goal:** What problem does this solve?\n- **Core Functionality:** What are the key actions?\n- **Scope/Boundaries:** What should it NOT do?\n- **Success Criteria:** How do we know it''s done?\n- **Constraints/Dependencies:** Any tech, data, or policy constraints?\n\n### Format Questions Like This:\n\n```\n1. What is the primary goal of this feature?\n   A. Improve user onboarding experience\n   B. Increase user retention\n   C. Reduce support burden\n   D. Other: [please specify]\n\n2. Who is the target user?\n   A. New users only\n   B. Existing users only\n   C. All users\n   D. Admin users only\n\n3. What is the scope?\n   A. Minimal viable version\n   B. Full-featured implementation\n   C. Just the backend/API\n   D. Just the UI\n```\n\nThis lets users respond with \"1A, 2C, 3B\" for quick iteration.\n\n---\n\n## Step 2: PRD Structure\n\nGenerate the PRD with these sections:\n\n### 1. Introduction/Overview\nBrief description of the feature and the problem it solves.\n\n### 2. Goals\nSpecific, measurable objectives (bullet list).\n\n### 3. User Stories\nEach story needs:\n- **Title:** Short descriptive name\n- **Description:** \"As a [user], I want [feature] so that [benefit]\"\n- **Task Definition:** A precise, detailed description of the work and expected outcome, written as a single cohesive task (no sub-tasks or step lists)\n- **Acceptance Criteria:** Verifiable checklist of what \"done\" means\n\nEach story should be small enough to implement in one focused session, but detailed enough that the task is unambiguous without needing sub-tasks.\n\n**Format:**\n```markdown\n### US-001: [Title]\n**Description:** As a [user], I want [feature] so that [benefit].\n\n**Task Definition:** Describe the implementation in one detailed task: include the specific data changes, UI behavior, API expectations, and any constraints, but do not break into sub-tasks or steps.\n\n**Acceptance Criteria:**\n- [ ] Specific verifiable criterion\n- [ ] Another criterion\n- [ ] Typecheck/lint passes\n- [ ] **[UI stories only]** Verify in browser using dev-browser skill\n```\n\n**Important:** \n- Acceptance criteria must be verifiable, not vague. \"Works correctly\" is bad. \"Button shows confirmation dialog before deleting\" is good.\n- Task Definition must be a single, detailed task statement. Do not include sub-tasks or step-by-step lists.\n- **For any story with UI changes:** Always include \"Verify in browser using dev-browser skill\" as acceptance criteria. This ensures visual verification of frontend work.\n\n### 4. Functional Requirements\nNumbered list of specific functionalities:\n- \"FR-1: The system must allow users to...\"\n- \"FR-2: When a user clicks X, the system must...\"\n\nBe explicit and unambiguous.\n\n### 5. Non-Goals (Out of Scope)\nWhat this feature will NOT include. Critical for managing scope.\n\n### 6. Design Considerations (Optional)\n- UI/UX requirements\n- Link to mockups if available\n- Relevant existing components to reuse\n\n### 7. Technical Considerations (Optional)\n- Known constraints or dependencies\n- Integration points with existing systems\n- Performance requirements\n\n### 8. Success Metrics\nHow will success be measured?\n- \"Reduce time to complete X by 50%\"\n- \"Increase conversion rate by 10%\"\n\n### 9. Open Questions\nRemaining questions or areas needing clarification.\n\n### 10. Assumptions & Dependencies\nList explicit assumptions and external dependencies (APIs, teams, data sources).\n\n### 11. Risks & Mitigations\nCall out likely risks (performance, security, UX, data quality) and mitigations.\n\n### 12. Rollout & Monitoring (Optional)\n- Rollout plan (feature flag, staged release, rollback)\n- Analytics/telemetry needed to measure success\n\n### 13. Privacy & Security (Optional)\nData handling, PII, access controls, and compliance notes.\n\n---\n\n## Writing for Junior Developers\n\nThe PRD reader may be a junior developer or AI agent. Therefore:\n\n- Be explicit and unambiguous\n- Avoid jargon or explain it\n- Provide enough detail to understand purpose and core logic\n- Number requirements for easy reference\n- Use concrete examples where helpful\n- Prefer tool-agnostic instructions; only mention specific tools when required\n\n---\n\n## Output\n\n- **Format:** Markdown (`.md`)\n- **Location:** `tasks/`\n- **Filename:** `prd-[feature-name].md` (kebab-case)\n- **Include:** Always add a line `prd-id: <feature-name-kebab-case>` at the top of the PRD (after the # title)\n\n---\n\n## Example PRD\n\n```markdown\n# PRD: Task Priority System\n\nprd-id: task-priority-system\n\n## Introduction\n\nAdd priority levels to tasks so users can focus on what matters most. Tasks can be marked as high, medium, or low priority, with visual indicators and filtering to help users manage their workload effectively.\n\n## Goals\n\n- Allow assigning priority (high/medium/low) to any task\n- Provide clear visual differentiation between priority levels\n- Enable filtering and sorting by priority\n- Default new tasks to medium priority\n\n## User Stories\n\n### US-001: Add priority field to database\n**Description:** As a developer, I need to store task priority so it persists across sessions.\n\n**Task Definition:** Add a `priority` field to the tasks data model with allowed values ''high'' | ''medium'' | ''low'', default to ''medium'', ensure it is persisted in storage, and update any necessary types or validation to accept and return the field consistently.\n\n**Acceptance Criteria:**\n- [ ] Add priority column to tasks table: ''high'' | ''medium'' | ''low'' (default ''medium'')\n- [ ] Generate and run migration successfully\n- [ ] Typecheck passes\n\n### US-002: Display priority indicator on task cards\n**Description:** As a user, I want to see task priority at a glance so I know what needs attention first.\n\n**Task Definition:** Display a priority badge on each task card using the existing badge component, map colors to priority values (red/high, yellow/medium, gray/low), and ensure the badge is visible in the default card layout without additional interaction.\n\n**Acceptance Criteria:**\n- [ ] Each task card shows colored priority badge (red=high, yellow=medium, gray=low)\n- [ ] Priority visible without hovering or clicking\n- [ ] Typecheck passes\n- [ ] Verify in browser using dev-browser skill\n\n### US-003: Add priority selector to task edit\n**Description:** As a user, I want to change a task''s priority when editing it.\n\n**Task Definition:** Add a priority dropdown to the task edit modal that reflects the current value, persists changes immediately on selection, and updates the UI to the new priority without a full page refresh.\n\n**Acceptance Criteria:**\n- [ ] Priority dropdown in task edit modal\n- [ ] Shows current priority as selected\n- [ ] Saves immediately on selection change\n- [ ] Typecheck passes\n- [ ] Verify in browser using dev-browser skill\n\n### US-004: Filter tasks by priority\n**Description:** As a user, I want to filter the task list to see only high-priority items when I''m focused.\n\n**Task Definition:** Add a priority filter control to the task list header with options All | High | Medium | Low, persist the selection in URL params, and show a clear empty state when no tasks match the selected filter.\n\n**Acceptance Criteria:**\n- [ ] Filter dropdown with options: All | High | Medium | Low\n- [ ] Filter persists in URL params\n- [ ] Empty state message when no tasks match filter\n- [ ] Typecheck passes\n- [ ] Verify in browser using dev-browser skill\n\n## Functional Requirements\n\n- FR-1: Add `priority` field to tasks table (''high'' | ''medium'' | ''low'', default ''medium'')\n- FR-2: Display colored priority badge on each task card\n- FR-3: Include priority selector in task edit modal\n- FR-4: Add priority filter dropdown to task list header\n- FR-5: Sort by priority within each status column (high to medium to low)\n\n## Non-Goals\n\n- No priority-based notifications or reminders\n- No automatic priority assignment based on due date\n- No priority inheritance for subtasks\n\n## Technical Considerations\n\n- Reuse existing badge component with color variants\n- Filter state managed via URL search params\n- Priority stored in database, not computed\n\n## Success Metrics\n\n- Users can change priority in under 2 clicks\n- High-priority tasks immediately visible at top of lists\n- No regression in task list performance\n\n## Open Questions\n\n- Should priority affect task ordering within a column?\n- Should we add keyboard shortcuts for priority changes?\n```\n\n---\n\n## Checklist\n\nBefore saving the PRD:\n\n- [ ] Asked clarifying questions with lettered options\n- [ ] Incorporated user''s answers\n- [ ] User stories are small and specific\n- [ ] Functional requirements are numbered and unambiguous\n- [ ] Non-goals section defines clear boundaries\n- [ ] Saved to `tasks/prd-[feature-name].md`"},"lastSynced":"2026-03-07T01:56:21.347Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Amp, Cursor, and Codex requiring structured Product Requirements Document generation","zh":"适合于Amp、Cursor和Codex等AI代理，需要生成结构化的产品需求文档","ja":"Amp、Cursor、CodexなどのAIエージェントに適しており、構造化された製品要件文書の生成を必要とする","ko":"Amp, Cursor, Codex와 같은 AI 에이전트에 적합하며 구조화된 제품 요구 사항 문서 생성이 필요함","es":"Ideal para agentes de IA como Amp, Cursor y Codex que requieren la generación de documentos de requisitos de producto estructurados","fr":"Idéal pour les agents d''IA comme Amp, Cursor et Codex nécessitant la génération de documents de spécifications de produit structurés","de":"Ideal für KI-Agents wie Amp, Cursor und Codex, die die Erstellung von strukturierten Produktanforderungsdokumenten erfordern","pt":"Ideal para agentes de IA como Amp, Cursor e Codex que requerem geração de documentos de requisitos de produto estruturados","ru":"Идеально подходит для агентов ИИ, таких как Amp, Cursor и Codex, требующих генерации структурированных документов требований к продукту","ar":"مثالية لعميل الذكاء الاصطناعي مثل Amp و Cursor و Codex الذين يتطلبون إنشاء مستندات متطلبات المنتج المنظمة"},"recommendation":{"en":"Empowers agents to generate detailed Product Requirements Documents based on user input and clarifying questions, utilizing multi-agent execution and providing clear, actionable documents in markdown format, saved to a `tasks` repository","zh":"赋予代理生成详细的产品需求文档的能力，基于用户输入和澄清问题，利用多代理执行，并提供清晰、可执行的文档，以markdown格式保存在`tasks`仓库中","ja":"ユーザー入力と質問を明確化することにより、詳細な製品要件文書を生成するエージェントの能力を付与し、多エージェントの実行を利用し、Markdown形式の明確な可実行文書を`tasks`リポジトリに保存する","ko":"사용자 입력과 질문을 명확화하여 자세한 제품 요구 사항 문서를 생성할 수 있는 에이전트의 능력을 부여하며, 다중 에이전트 실행을 활용하여 markdown 형식의 명확한 실행 가능한 문서를 `tasks` 저장소에 저장함","es":"Habilita a los agentes a generar documentos de requisitos de producto detallados basados en la entrada del usuario y preguntas de aclaración, utilizando la ejecución multi-agente y proporcionando documentos claros y ejecutables en formato markdown, guardados en un repositorio `tasks`","fr":"Permet aux agents de générer des documents de spécifications de produit détaillés basés sur les entrées utilisateur et les questions de clarification, en utilisant l''exécution multi-agent et en fournissant des documents clairs et exécutables au format markdown, enregistrés dans un répertoire `tasks`","de":"Ermöglicht es Agents, detaillierte Produktanforderungsdokumente basierend auf Benutzereingaben und Klarstellungsfragen zu generieren, indem sie die Multi-Agent-Ausführung nutzen und klare, ausführbare Dokumente im Markdown-Format bereitstellen, die in einem `tasks`-Repository gespeichert werden","pt":"Habilita os agentes a gerar documentos de requisitos de produto detalhados com base na entrada do usuário e em perguntas esclarecedoras, utilizando a execução de multiagentes e fornecendo documentos claros e executáveis no formato markdown, salvos em um repositório `tasks`","ru":"Позволяет агентам генерировать подробные документы требований к продукту на основе ввода пользователя и уточняющих вопросов, используя многозвенную исполнение и предоставляя четкие, выполнимые документы в формате markdown, сохраненные в репозитории `tasks`","ar":"تمكين الوكلاء من إنشاء مستندات متطلبات المنتج التفصيلية بناءً على إدخال المستخدم والأسئلة التوضيحية، باستخدام تنفيذ متعدد الوكلاء وتقديم مستندات واضحة وقابلة للتنفيذ بالتنسيق markdown، محفوظة في مستودع `tasks`"},"useCases":{"en":["Generating PRDs for new feature implementations","Clarifying user requirements through automated questioning","Creating structured documents for AI agent implementation"],"zh":["为新功能实现生成PRD","通过自动化提问来澄清用户需求","为AI代理实现创建结构化文档"],"ja":["新機能の実装のためのPRDを生成する","自動質問を通じてユーザー要件を明確化する","AIエージェントの実装のための構造化文書を作成する"],"ko":["새로운 기능 구현을 위한 PRD 생성","자동화된 질문을 통해 사용자 요구 사항 명확화","AI 에이전트 구현을 위한 구조화된 문서 생성"],"es":["Generación de PRD para la implementación de nuevas características","Aclaración de los requisitos del usuario a través de preguntas automatizadas","Creación de documentos estructurados para la implementación de agentes de IA"],"fr":["Génération de PRD pour la mise en œuvre de nouvelles fonctionnalités","Clarification des exigences utilisateur via des questions automatisées","Création de documents structurés pour la mise en œuvre d''agents d''IA"],"de":["Erstellung von PRD für die Implementierung neuer Funktionalitäten","Klärung der Benutzeranforderungen durch automatisierte Fragen","Erstellung von strukturierten Dokumenten für die Implementierung von KI-Agents"],"pt":["Geração de PRDs para implementações de recursos novos","Esclarecimento dos requisitos do usuário por meio de perguntas automatizadas","Criação de documentos estruturados para implementação de agente de IA"],"ru":["Генерация документов требований к продукту для реализации новых функций","Уточнение требований пользователя с помощью автоматизированных вопросов","Создание структурированных документов для реализации агента ИИ"],"ar":["إنشاء مستندات متطلبات المنتج لتنفيذ ميزات جديدة","توضيح متطلبات المستخدم من خلال الأسئلة الأوتوماتيكية","إنشاء مستندات منظمات لتنفيذ عميل الذكاء الاصطناعي"]},"limitations":{"en":["Requires user input for feature description","Limited to generating markdown documents","Does not support direct implementation, only PRD generation"],"zh":["需要用户输入以描述功能","仅限生成markdown文档","不支持直接实现，只支持PRD生成"],"ja":["機能の説明のためのユーザー入力が必要","Markdown文書の生成のみ","直接実装はサポートされず、PRDの生成のみ"],"ko":["기능 설명을 위한 사용자 입력이 필요함","markdown 문서 생성만 가능","직접 구현은 지원되지 않으며, PRD 생성만 지원함"],"es":["Requiere la entrada del usuario para la descripción de características","Limitado a la generación de documentos markdown","No admite la implementación directa, solo la generación de PRD"],"fr":["Nécessite l''entrée de l''utilisateur pour la description des fonctionnalités","Limité à la génération de documents markdown","Ne prend pas en charge la mise en œuvre directe, mais uniquement la génération de PRD"],"de":["Benutzereingabe für die Funktionsbeschreibung erforderlich","Begrenzt auf die Generierung von Markdown-Dokumenten","Unterstützt keine direkte Implementierung, nur die PRD-Generierung"],"pt":["Requer entrada do usuário para descrição de recurso","Limitado à geração de documentos markdown","Não suporta implementação direta, apenas geração de PRD"],"ru":["Требует ввода пользователя для описания функции","Ограничен генерацией документов markdown","Не поддерживает прямую реализацию, только генерацию документа требований к продукту"],"ar":["يتطلب إدخال المستخدم لوصف الميزة","محدود بالتنسيق markdown","لا يدعم التنفيذ المباشر، بل إنشاء مستند متطلبات المنتج فقط"]},"version":4},"contentHash":"1b5b65364f2b7ea9022bcb23ad369bcbc6171cdfc69707d3009dec692be2e4ef","qualityScore":60}');
