INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Draculabo/AntigravityManager/openspec-bulk-archive-change', 'openspec-bulk-archive-change', 'Draculabo', 'AntigravityManager', 'community', 'openspec-bulk-archive-change Draculabo AntigravityManager community account-manager antigravity antigravity-ai antigravity-ide antigravity-tools antigravity2api electron gemini gemini-api gemini-pro openspec-bulk-archive-change是基于Electron的强大应用程序，用于管理Antigravity应用程序的账户和进程 openspec-bulk-archive-changeは、Electronベースの強力なアプリケーションで、アカウントとプロセスを管理するためのAntigravityアプリケーション openspec-bulk-archive-change는 Electron 기반의 강력한 애플리케이션으로 Antigravity 애플리케이션의 계정 및 프로세스를 관리 Antigravity Manager es una aplicación Electron para gestionar cuentas y procesos de Antigravity, ofreciendo una interfaz intuitiva para cambiar cuentas y controlar el ciclo de vida de la aplicación Antigravity Manager est une application Electron pour gérer les comptes et les processus d''Antigravity, offrant une interface intuitive pour changer de comptes et contrôler le cycle de vie de l''application Antigravity Manager ist eine Electron-Anwendung zum Verwalten von Konten und Prozessen von Antigravity, mit einer benutzerfreundlichen Oberfläche zum Wechseln von Konten und Steuern des Lebenszyklus der Anwendung O openspec-bulk-archive-change é uma ferramenta poderosa para gerenciar contas e processos da aplicação Antigravity openspec-bulk-archive-change - это мощный инструмент для управления учетными записями и процессами приложения Antigravity openspec-bulk-archive-change هو أداة قوية لإدارة الحسابات والعمليات لتطبيق Antigravity Antigravity Manager is a powerful Electron-based application designed to manage accounts and processes for the Antigravity application. It provides a seamless interface for switching accounts, backing up progress, and controlling the application lifecycle. 如何使用openspec-bulk-archive-change 什么是Antigravity应用程序 openspec-bulk-archive-change安装 Antigravity应用程序替代品 Electron开发框架 AI智能工具下载 账户管理工具 进程控制软件 Antigravity Manager is a powerful Electron-based application designed to manage accounts and processes for the Antigravity application. It provides a seamless interface for switching accounts, backing up progress, and controlling the application lifecycle.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dkapellusch/AO/wt-split', 'community', 'dkapellusch', 'AO', 'dkapellusch/AO', 'wt-split', 2, 0, 60, '2026-02-25T22:54:40Z', '2026-02-26T08:41:51.979Z', '0f21b8c2ba1c72f9aacd4f0b45e58b3342a00afd91974ae6fb77a5590827efa6', '{"id":"dkapellusch/AO/wt-split","name":"wt-split","description":{"zh":"wt-split是用于OpenCode和ClaudeCode的外部Ralph循环，支持Sandoxing和模型交换","ja":"wt-splitは、OpenCodeとClaudeCode用の外部Ralphループです。Sandoxingとモデルスワッピングをサポートします","ko":"wt-split은 OpenCode와 ClaudeCode용 외부 랄프 루프로, 샌드박싱과 모델 스와핑을 지원합니다","es":"wt-split es una herramienta de AI para automatización que soporta Sandoxing y Model Swapping para Rate Limits, ideal para desarrolladores","fr":"wt-split est un outil d''IA pour l''automatisation qui prend en charge Sandoxing et Model Swapping pour les limites de taux, idéal pour les développeurs","de":"wt-split ist ein KI-Tool für Automatisierung, das Sandoxing und Model Swapping für Rate Limits unterstützt, ideal für Entwickler","pt":"O wt-split é uma ferramenta de IA que suporta Sandoxing e Model Swapping para Rate Limits em OpenCode e ClaudeCode","ru":"ИИ Агент wt-split поддерживает Sandoxing и Model Swapping для Rate Limits в OpenCode и ClaudeCode","ar":"أداة الذكاء الاصطناعي wt-split تدعم Sandoxing و Model Swapping ل Rate Limits في OpenCode و ClaudeCode","en":"External Ralph Loop for OpenCode and ClaudeCode. Supports Sandoxing and Model Swapping for Rate Limits"},"seo":{"title":{"zh":"wt-split AI工具：支持Sandoxing和模型交换的外部Ralph循环","ja":"wt-split AIエージェント：Sandoxingとモデルスワッピング対応の外部Ralphループ","ko":"wt-split AI 에이전트: 샌드박싱 및 모델 스와핑 지원 외부 랄프 루프","es":"wt-split: Herramientas de AI para Automatización","fr":"wt-split: Outils d''IA pour l''Automatisation","de":"wt-split: KI-Tools für Automatisierung","pt":"Ferramentas de IA: wt-split para OpenCode e ClaudeCode","ru":"ИИ Агенты: wt-split для OpenCode и ClaudeCode","ar":"