INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('oriolrius/pki-manager-web/GitHub CLI', 'GitHub CLI', 'oriolrius', 'pki-manager-web', 'community', 'GitHub CLI oriolrius pki-manager-web community GitHub CLI AI工具提供安全的X.509证书生命周期管理，支持Cosmian KMS集成，简化证书管理流程 GitHub CLI AIエージェントは、安全なX.509証明書のライフサイクル管理を提供し、Cosmian KMSをサポートして証明書管理プロセスを簡素化します GitHub CLI AI 에이전트는 보안이 강화된 X.509 인증서 수명주기 관리를 제공하며 Cosmian KMS를 지원하여 인증서 관리 프로세스를 간소화합니다 GitHub CLI es una herramienta para la gestión segura del ciclo de vida de certificados X.509 con integración de Cosmian KMS. GitHub CLI est un outil pour la gestion sécurisée du cycle de vie des certificats X.509 avec intégration de Cosmian KMS. GitHub CLI ist ein Tool für das sichere Zertifikatsmanagement von X.509 mit Integration von Cosmian KMS. O GitHub CLI é uma ferramenta de gerenciamento de certificados X.509 segura com integração do Cosmian KMS, permitindo o gerenciamento de ciclo de vida de certificados. GitHub CLI - это инструмент для безопасного управления сертификатами X.509 с интеграцией Cosmian KMS, обеспечивающий управление жизненным циклом сертификатов. GitHub CLI هو أداة لإدارة شهادات X.509 آمنة مع دمج Cosmian KMS، مما يسمح بإدارة دورة حياة الشهادات. Web-based PKI Manager - Secure X.509 certificate lifecycle management with Cosmian KMS integration GitHub CLI AI工具 X.509证书生命周期管理 Cosmian KMS PKI管理器 如何使用GitHub CLI AI工具 GitHub CLI AI工具安装 GitHub CLI AI工具替代品 Web-based PKI Manager - Secure X.509 certificate lifecycle management with Cosmian KMS integration');
