INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jellydn/my-ai-tools/adr', 'adr', 'jellydn', 'my-ai-tools', 'community', 'adr jellydn my-ai-tools community adr技能提供代码工具的综合配置管理，支持自定义配置、MCP服务器、插件和命令 adrスキルは、コードツールの包括的な設定管理を提供し、カスタム設定、MCPサーバー、プラグイン、コマンドをサポートします adr 스킬은 코드 도구의 종합적인 구성 관리를 제공하며, 사용자 정의 구성, MCP 서버, 플러그인, 명령어를 지원합니다 ADR proporciona una interfaz unificada para administrar registros de decisiones de arquitectura para herramientas de codificación AI ADR fournit une interface unifiée pour gérer les registres de décisions d''architecture pour les outils de codage AI ADR bietet eine einheitliche Schnittstelle zur Verwaltung von Architekturentscheidungsprotokollen für AI-Coding-Tools O ADR fornece uma interface unificada para gerenciar registros de decisões de arquitetura para ferramentas de codificação AI ADR предоставляет унифицированный интерфейс для управления записями об архитектурных решениях для инструментов кодирования AI يوفر ADR واجهة موحدة لإدارة سجلات قرارات بنية أدوات الترميز الإصدارية Comprehensive configuration management for AI coding tools - Replicate my complete setup for Claude Code, OpenCode, Amp, Codex and Claude Code Switch with custom configurations, MCP servers, plugins, and commands. adr技能 代码工具配置管理 Claude Code OpenCode Amp Codex MCP服务器 插件 命令 Comprehensive configuration management for AI coding tools - Replicate my complete setup for Claude Code, OpenCode, Amp, Codex and Claude Code Switch with custom configurations, MCP servers, plugins, and commands.');
