INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aiskillstore/marketplace/nano-image-generator', 'nano-image-generator', 'aiskillstore', 'marketplace', 'community', 'nano-image-generator aiskillstore marketplace community Nano 图像生成器是一种安全审计的技能，用于生成高质量图像，支持参考图像和风格转换 Nano 画像ジェネレーターは、セキュリティ監査済みのスキルで、高品質の画像を生成します。参考画像とスタイル転送に対応 Nano 이미지 생성기는 보안 감사를 통과한 기술로, 고화질 이미지 생성을 지원하며 참조 이미지 및 스타일 전환을 제공합니다 El generador de imágenes Nano permite crear imágenes personalizadas para cualquier necesidad de activos visuales. Soporta imágenes de referencia para transferencia de estilo y consistencia de personajes. Le générateur d''images Nano permet de créer des images personnalisées pour tout besoin d''actifs visuels. Il prend en charge les images de référence pour le transfert de style et la cohérence des personnages. Der Nano-Bild-Generator ermöglicht die Erstellung benutzerdefinierter Bilder für jede visuelle Anforderung. Er unterstützt Referenzbilder für Stilübertragung und Charakterkonsistenz. O Gerador de Imagens Nano é uma ferramenta de código aberto que permite criar imagens personalizadas com estilo de transferência e consistência de personagens. Нано Генератор Изображений - это открытое программное обеспечение, которое позволяет создавать индивидуальные изображения с стилевым переносом и последовательностью персонажей. مُولِد الصُور النانو هو اِداة مفتوحة المَصدر تُمكِّنُكَ مِنْ إِصطِناع الصُور المُتخصِصة بِأَنماط نَقْل وَتوحيد الشَخَصِيّات Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified. 图像生成 Nano 图像生成器 参考图像 风格转换 一键式图像生成 高质量图像输出 Security-audited skills for Claude, Codex & Claude Code. One-click install, quality verified.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Jeffallan/claude-skills/code-reviewer', 'community', 'Jeffallan', 'claude-skills', 'Jeffallan/claude-skills', 'code-reviewer', 0, 0, 60, '2026-02-20T04:13:19.576Z', '2026-02-20T04:44:01.519Z', '0ce7d2a7e27cc38abb490645d20709d40d7102e8058a2465aab7efadba64599c', '{"id":"Jeffallan/claude-skills/code-reviewer","name":"code-reviewer","description":{"zh":"代码审查专家，负责进行彻底的代码审查，提供建设性的反馈，帮助开发者成长","ja":"コードレビューエキスパート、徹底的なコードレビューを実施し、建設的なフィードバックを提供して開発者を成長させる","ko":"코드 리뷰 전문가, 철저한 코드 리뷰를 수행하고 건설적인 피드백을 제공하여 개발者の 성장을 지원","es":"La revisión de código es un proceso crucial para garantizar la calidad y seguridad del código. Nuestra herramienta de revisión de código ayuda a los desarrolladores a mejorar su código","fr":"La révision de code est un processus crucial pour garantir la qualité et la sécurité du code. Notre outil de révision de code aide les développeurs à améliorer leur code","de":"Die Code-Review ist ein entscheidender Prozess, um die Qualität und Sicherheit des Codes zu gewährleisten. Unser Code-Review-Tool hilft Entwicklern, ihren Code zu verbessern","pt":"A revisão de código é um processo essencial para garantir a qualidade e a segurança do código. Nossa ferramenta ajuda a identificar erros e melhorar a performance.","ru":"Проверка кода - это необходимый процесс для обеспечения качества и безопасности кода. Наш инструмент помогает выявить ошибки и улучшить производительность.","ar":"استعراض الشفرة هو عملية أساسية لضمان جودة وأمان الشفرة. أداتنا تساعد في تحديد الأخطاء وتحسين الأداء.","en":"66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer."},"seo":{"title":{"zh":"代码审查专家 - 代码质量审计","ja":"コードレビューエキスパート - コード品質の監査","ko":"코드 리뷰 전문가 - 코드 품질 감사","es":"Revisión de código experta","fr":"Révision de code expérimentée","de":"Experten-Code-Review","pt":"Revisão de Código: Melhore a Qualidade com Nossa Ferramenta","ru":"Проверка Код: Улучшите Качество с Нашим Инструментом","ar":"استعراض الشفرة: تحسين الجودة مع أداتنا","en":"code-reviewer"},"description":{"zh":"代码审查专家，负责进行彻底的代码审查，提供建设性的反馈，帮助开发者成长","ja":"コードレビューエキスパート、徹底的なコードレビューを実施し、建設的なフィードバックを提供して開発者を成長させる","ko":"코드 리뷰 전문가, 철저한 코드 리뷰를 수행하고 건설적인 피드백을 제공하여 개발者の 성장을 지원","es":"La revisión de código es un proceso crucial para garantizar la calidad y seguridad del código. Nuestra herramienta de revisión de código ayuda a los desarrol...","fr":"La révision de code est un processus crucial pour garantir la qualité et la sécurité du code. Notre outil de révision de code aide les développeurs à amélior...","de":"Die Code-Review ist ein entscheidender Prozess, um die Qualität und Sicherheit des Codes zu gewährleisten. Unser Code-Review-Tool hilft Entwicklern, ihren Co...","pt":"A revisão de código é um processo essencial para garantir a qualidade e a segurança do código. Nossa ferramenta ajuda a identificar erros e melhorar a perfor...","ru":"Проверка кода - это необходимый процесс для обеспечения качества и безопасности кода. Наш инструмент помогает выявить ошибки и улучшить производительность.","ar":"استعراض الشفرة هو عملية أساسية لضمان جودة وأمان الشفرة. أداتنا تساعد في تحديد الأخطاء وتحسين الأداء.","en":"66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer."},"definition":{"en":"66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer."},"features":{"zh":["代码审查","代码质量审计","安全性检查","性能优化","维护性提高"],"ja":["コードレビュー","コード品質の監査","セキュリティチェック","パフォーマンス最適化","メンテナンス性の向上"],"ko":["코드 리뷰","코드 품질 감사","보안성 확인","성능 최적화","유지 보수성 향상"],"es":["Revisión de código para corrección y seguridad","Análisis de rendimiento y mantenibilidad","Identificación de oportunidades de refactorización","Proporciona comentarios constructivos para mejorar el código"],"fr":["Révision de code pour la correction et la sécurité","Analyse des performances et de la maintenabilité","Identification des opportunités de refactorisation","Fournit des commentaires constructifs pour améliorer le code"],"de":["Code-Review für Korrektheit und Sicherheit","Analyse der Leistung und Wartbarkeit","Identifizierung von Refactoring-Möglichkeiten","Bietet konstruktives Feedback zur Code-Verbesserung"],"pt":["Análise de código para identificar erros","Melhoria da performance e da segurança","Feedbacks construtivos para melhorar as habilidades de programação","Integração com ferramentas de desenvolvimento","Suporte a múltiplos linguagens de programação"],"ru":["Анализ кода для выявления ошибок","Улучшение производительности и безопасности","Конструктивные отзывы для улучшения навыков программирования","Интеграция с инструментами разработки","Поддержка нескольких языков программирования"],"ar":["تحليل الشفرة لتحديد الأخطاء","تحسين الأداء والأمان","تعليقات بناءة لتحسين مهارات البرمجة","التكامل مع أدوات التطوير","دعم لغات برمجة متعددة"]},"keywords":{"zh":["代码审查","代码质量","代码安全","代码性能","代码维护","代码优化","代码审计"],"ja":["コードレビュー","コード品質","コードセキュリティ","コードパフォーマンス","コードメンテナンス","コード最適化","コード監査"],"ko":["코드 리뷰","코드 품질","코드 보안","코드 성능","코드 유지 보수","코드 최적화","코드 감사"],"es":["revisión de código","desarrollo full-stack","calidad del código","seguridad del código","rendimiento del código","mantenibilidad del código"],"fr":["révision de code","développement full-stack","qualité du code","sécurité du code","performance du code","maintenabilité du code"],"de":["Code-Review","Full-Stack-Entwicklung","Code-Qualität","Code-Sicherheit","Code-Performance","Code-Wartbarkeit"],"pt":["revisão de código","qualidade de código","segurança de código","desenvolvimento de software","ferramentas de desenvolvimento","linguagens de programação"],"ru":["проверка кода","качество кода","безопасность кода","разработка программного обеспечения","инструменты разработки","языки программирования"],"ar":["استعراض الشفرة","جودة الشفرة","أمان الشفرة","تطوير البرمجيات","أدوات التطوير","لغات البرمجة"]}},"owner":"Jeffallan","repo":"claude-skills","repoPath":"Jeffallan/claude-skills","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.576Z","topics":[],"category":"community","skillMd":{"name":"code-reviewer","description":"Use when reviewing pull requests, conducting code quality audits, or identifying security vulnerabilities. Invoke for PR reviews, code quality checks, refactoring suggestions.","version":"1.0.0","bodyPreview":"# Code Reviewer\n\nSenior engineer conducting thorough, constructive code reviews that improve quality and share knowledge.\n\n## Role Definition\n\nYou are a principal engineer with 12+ years of experience across multiple languages. You review code for correctness, security, performance, and maintainability. You provide actionable feedback that helps developers grow.\n\n## When to Use This Skill\n\n- Reviewing pull requests\n- Conducting code quality audits\n- Identifying refactoring opportunities\n- Checki","body":"# Code Reviewer\n\nSenior engineer conducting thorough, constructive code reviews that improve quality and share knowledge.\n\n## Role Definition\n\nYou are a principal engineer with 12+ years of experience across multiple languages. You review code for correctness, security, performance, and maintainability. You provide actionable feedback that helps developers grow.\n\n## When to Use This Skill\n\n- Reviewing pull requests\n- Conducting code quality audits\n- Identifying refactoring opportunities\n- Checking for security vulnerabilities\n- Validating architectural decisions\n\n## Core Workflow\n\n1. **Context** - Read PR description, understand the problem\n2. **Structure** - Review architecture and design decisions\n3. **Details** - Check code quality, security, performance\n4. **Tests** - Validate test coverage and quality\n5. **Feedback** - Provide categorized, actionable feedback\n\n## Reference Guide\n\nLoad detailed guidance based on context:\n\n<!-- Spec Compliance and Receiving Feedback rows adapted from obra/superpowers by Jesse Vincent (@obra), MIT License -->\n\n| Topic | Reference | Load When |\n|-------|-----------|-----------|\n| Review Checklist | `references/review-checklist.md` | Starting a review, categories |\n| Common Issues | `references/common-issues.md` | N+1 queries, magic numbers, patterns |\n| Feedback Examples | `references/feedback-examples.md` | Writing good feedback |\n| Report Template | `references/report-template.md` | Writing final review report |\n| Spec Compliance | `references/spec-compliance-review.md` | Reviewing implementations, PR review, spec verification |\n| Receiving Feedback | `references/receiving-feedback.md` | Responding to review comments, handling feedback |\n\n## Constraints\n\n### MUST DO\n- Understand context before reviewing\n- Provide specific, actionable feedback\n- Include code examples in suggestions\n- Praise good patterns\n- Prioritize feedback (critical → minor)\n- Review tests as thoroughly as code\n- Check for security issues\n\n### MUST NOT DO\n- Be condescending or rude\n- Nitpick style when linters exist\n- Block on personal preferences\n- Demand perfection\n- Review without understanding the why\n- Skip praising good work\n\n## Output Templates\n\nCode review report should include:\n1. Summary (overall assessment)\n2. Critical issues (must fix)\n3. Major issues (should fix)\n4. Minor issues (nice to have)\n5. Positive feedback\n6. Questions for author\n7. Verdict (approve/request changes/comment)\n\n## Knowledge Reference\n\nSOLID, DRY, KISS, YAGNI, design patterns, OWASP Top 10, language idioms, testing patterns\n"},"lastSynced":"2026-02-20T04:44:01.519Z","agentAnalysis":{"suitability":{"en":"Ideal for AI coding assistants like Claude Code needing advanced code analysis and review capabilities for multiple programming languages.","zh":"适用于需要高级代码分析和多种编程语言代码审查能力的AI编码助手，如Claude Code。","ja":"Claude Codeのような、高度なコード分析および複数のプログラミング言語のコードレビュー機能を必要とするAIコーディングアシスタントに適しています。","ko":"고급 코드 분석 및 여러 프로그래밍 언어의 코드 리뷰 기능이 필요한 AI 코딩 도우미인 Claude Code에 적합합니다.","es":"Ideal para asistentes de codificación de IA como Claude Code que necesitan capacidades de análisis y revisión de código avanzadas para múltiples lenguajes de programación.","fr":"Idéal pour les assistants de codage IA comme Claude Code nécessitant des capacités d''analyse et de révision de code avancées pour plusieurs langages de programmation.","de":"Ideal für AI-Coding-Assistenten wie Claude Code, die erweiterte Code-Analyse- und Überprüfungsfunktionen für mehrere Programmiersprachen benötigen.","pt":"Ideal para assistentes de codificação de IA, como Claude Code, que necessitam de capacidades avançadas de análise e revisão de código para múltiplas linguagens de programação.","ru":"Идеально подходит для помощников кодирования ИИ, таких как Claude Code, требующих продвинутых возможностей анализа и проверки кода для нескольких языков программирования.","ar":"مثالي لمساعدي كتابة البرمجيات الإصدارية مثل كلود كود التي تحتاج إلى قدرات متقدمة لتحليل ومراجعة الشفرة للغات برمجة متعددة."},"recommendation":{"en":"Empowers agents to conduct thorough code reviews for correctness, security, performance, and maintainability, providing actionable feedback through pull request reviews and code quality audits, leveraging expertise across various languages and development frameworks.","zh":"赋予代理人对代码进行彻底审查的能力，以检查正确性、安全性、性能和可维护性，并通过拉取请求审查和代码质量审计提供可行的反馈，利用各类语言和开发框架的专业知识。","ja":"エージェントに正確性、セキュリティ、パフォーマンス、保守性を確認するための徹底的なコードレビューを実施する能力を与え、プルリクエストのレビューとコード品質の監査を通じて実行可能なフィードバックを提供し、さまざまな言語と開発フレームワークの専門知識を活用します。","ko":"에이전트가 코드의 정확성, 보안, 성능 및 유지보수성을 확인하기 위한 철저한 코드 리뷰를 수행할 수 있는 능력을 부여하며, 코드 품질에 대한 감사를 통해 실행 가능한 피드백을 제공하고, 다양한 언어 및 개발 프레임워크의 전문 지식을 활용합니다.","es":"Habilita a los agentes a realizar revisiones de código exhaustivas para la corrección, la seguridad, el rendimiento y la mantenibilidad, proporcionando comentarios accionables a través de revisiones de solicitudes de extracción y auditorías de calidad de código, aprovechando la experiencia en varios lenguajes y marcos de desarrollo.","fr":"Permet aux agents de réaliser des révisions de code exhaustives pour la correction, la sécurité, les performances et la maintenabilité, fournissant des commentaires actionnables via des révisions de demandes d''extraction et des audits de qualité de code, en exploitant l''expertise dans divers langages et cadres de développement.","de":"Ermöglicht es Agenten, gründliche Code-Überprüfungen für Korrektheit, Sicherheit, Leistung und Wartbarkeit durchzuführen und handhabbare Feedback durch Überprüfungen von Pull-Request und Code-Qualitätsaudits bereitzustellen, indem es die Expertise in verschiedenen Sprachen und Entwicklungsumgebungen nutzt.","pt":"Habilita os agentes a realizar revisões de código aprofundadas para correção, segurança, desempenho e manutenção, fornecendo feedbacks concretos por meio de revisões de solicitações de pull e auditorias de qualidade de código, aproveitando a especialização em várias linguagens e estruturas de desenvolvimento.","ru":"Наделяет агентов возможностью проводить тщательные обзоры кода на правильность, безопасность, производительность и поддерживаемость, обеспечивая действенные отзывы через обзоры запросов на включение и аудиты качества кода, используя экспертизу в различных языках и фреймворках разработки.","ar":"تمكّن الوكلاء من إجراء استعراضات شفرة شاملة لضمان الصحة والأمان والأداء والصيانة، وتقديم تعليقات قابلة للتنفيذ من خلال استعراضات طلبات السحب وعمليات تدقيق جودة الشفرة، واستخدام الخبرة عبر لغات واطارات عمل متعددة."},"useCases":{"en":["Reviewing pull requests for syntax errors and best practices","Conducting code quality audits to identify refactoring opportunities","Identifying security vulnerabilities in code submissions"],"zh":["审查拉取请求中的语法错误和最佳实践","进行代码质量审计以确定重构机会","识别代码提交中的安全漏洞"],"ja":["プルリクエストの文法エラーとベストプラクティスをレビューする","コード品質監査を実施してリファクタリングの機会を特定する","コード提出の中のセキュリティ脆弱性を特定する"],"ko":["풀 リクエ스트의 문법 오류 및 모범 사례를 검토","코드 품질 감사를 통해 리팩토링 기회를 식별","코드 제출의 보안 취약점을 식별"],"es":["Revisar solicitudes de extracción para errores de sintaxis y mejores prácticas","Realizar auditorías de calidad de código para identificar oportunidades de refactorización","Identificar vulnerabilidades de seguridad en las presentaciones de código"],"fr":["Réviser les demandes d''extraction pour les erreurs de syntaxe et les meilleures pratiques","Réaliser des audits de qualité de code pour identifier les opportunités de refactorisation","Identifier les vulnérabilités de sécurité dans les soumissions de code"],"de":["Überprüfen von Pull-Requests auf Syntaxfehler und Best Practices","Durchführen von Code-Qualitätsaudits, um Refactoring-Möglichkeiten zu identifizieren","Identifizieren von Sicherheitslücken in Code-Einreichungen"],"pt":["Revisar solicitações de pull para erros de sintaxe e boas práticas","Realizar auditorias de qualidade de código para identificar oportunidades de refatoração","Identificar vulnerabilidades de segurança em submissões de código"],"ru":["Просмотр запросов на включение для ошибок синтаксиса и最佳 практик","Проведение аудитов качества кода для выявления возможностей рефакторинга","Определение уязвимостей безопасности в представленных кодах"],"ar":["استعراض طلبات السحب لأخطاء البناء وأفضل الممارسات","إجراء عمليات تدقيق لجودة الشفرة لتحديد فرص إعادة هيكلة","تحديد نقاط الضعف الأمنية في الشفرات المقدمة"]},"limitations":{"en":["Requires expertise in multiple programming languages","Limited to code review and audit capabilities, not a replacement for human judgment"],"zh":["需要多种编程语言的专业知识","仅限代码审查和审计功能，不是人类判断力的替代品"],"ja":["複数のプログラミング言語の専門知識が必要","コードレビューと監査機能に限定されており、人間の判断力の代わりではありません"],"ko":["여러 프로그래밍 언어에 대한 전문 지식이 필요","코드 리뷰 및 감사 기능에만 제한되며, 인간의 판단力的 대체品은 아닙니다"],"es":["Requiere experiencia en múltiples lenguajes de programación","Limitado a capacidades de revisión y auditoría de código, no sustituye el juicio humano"],"fr":["Nécessite une expertise dans plusieurs langages de programmation","Limité aux capacités de révision et d''audit de code, ne remplace pas le jugement humain"],"de":["Benötigt Expertise in mehreren Programmiersprachen","Begrenzt auf Code-Überprüfungs- und Auditfunktionen, ersetzt nicht die menschliche Urteilsfähigkeit"],"pt":["Exige especialização em múltiplas linguagens de programação","Limitado a capacidades de revisão e auditoria de código, não substituindo o julgamento humano"],"ru":["Требует экспертизы в нескольких языках программирования","Ограничен возможностями проверки и аудита кода, не заменяя человеческий суд"],"ar":["يتطلب خبرة في لغات برمجة متعددة","محدود بوسائل استعراض وعمليات تدقيق الشفرة، وليس بديلاً للقضاء البشري"]},"version":3},"contentHash":"0ce7d2a7e27cc38abb490645d20709d40d7102e8058a2465aab7efadba64599c","qualityScore":60}');
