INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Jeffallan/claude-skills/code-reviewer', 'code-reviewer', 'Jeffallan', 'claude-skills', 'community', 'code-reviewer Jeffallan claude-skills community 代码审查专家，负责进行彻底的代码审查，提供建设性的反馈，帮助开发者成长 コードレビューエキスパート、徹底的なコードレビューを実施し、建設的なフィードバックを提供して開発者を成長させる 코드 리뷰 전문가, 철저한 코드 리뷰를 수행하고 건설적인 피드백을 제공하여 개발者の 성장을 지원 La revisión de código es un proceso crucial para garantizar la calidad y seguridad del código. Nuestra herramienta de revisión de código ayuda a los desarrolladores a mejorar su código La révision de code est un processus crucial pour garantir la qualité et la sécurité du code. Notre outil de révision de code aide les développeurs à améliorer leur code Die Code-Review ist ein entscheidender Prozess, um die Qualität und Sicherheit des Codes zu gewährleisten. Unser Code-Review-Tool hilft Entwicklern, ihren Code zu verbessern A revisão de código é um processo essencial para garantir a qualidade e a segurança do código. Nossa ferramenta ajuda a identificar erros e melhorar a performance. Проверка кода - это необходимый процесс для обеспечения качества и безопасности кода. Наш инструмент помогает выявить ошибки и улучшить производительность. استعراض الشفرة هو عملية أساسية لضمان جودة وأمان الشفرة. أداتنا تساعد في تحديد الأخطاء وتحسين الأداء. 66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer. 代码审查 代码质量 代码安全 代码性能 代码维护 代码优化 代码审计 66 Specialized Skills for Full-Stack Developers. Transform Claude Code into your expert pair programmer.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('addyosmani/web-quality-skills/core-web-vitals', 'community', 'addyosmani', 'web-quality-skills', 'addyosmani/web-quality-skills', 'core-web-vitals', 0, 0, 60, '2026-02-20T04:13:19.577Z', '2026-02-20T04:47:28.273Z', 'b03396c9bd7a41950bbaf5964bc8f1cf60a3c81830a6171614d6413c8bff308c', '{"id":"addyosmani/web-quality-skills/core-web-vitals","name":"core-web-vitals","description":{"zh":"Core Web Vitals 优化是指针对三个影响 Google 搜索排名和用户体验的指标进行的优化","ja":"Core Web Vitals 最適化は、Google 検索ランキングとユーザーエクスペリエンスに影響を与える 3 つの指標を対象とした最適化です","ko":"Core Web Vitals 최적화는 Google 검색 순위와 사용자 경험에 영향을 미치는 세 가지 지표를 대상으로 하는 최적화입니다","es":"Optimiza tu sitio web con las métricas de Core Web Vitals para mejorar la experiencia del usuario y el ranking en Google. Aprende sobre LCP, INP y CLS.","fr":"Optimisez votre site web avec les métriques de Core Web Vitals pour améliorer l''expérience utilisateur et le référencement Google. Découvrez le LCP, l''INP et le CLS.","de":"Optimieren Sie Ihre Website mit den Core-Web-Vitals-Metriken, um die Benutzererfahrung und das Google-Ranking zu verbessern. Erfahren Sie mehr über LCP, INP und CLS.","pt":"Otimização de Core Web Vitals para melhorar a experiência do usuário e o ranqueamento no Google Search","ru":"Оптимизация Core Web Vitals для улучшения пользовательского опыта и ранжирования в Google Search","ar":"تحسين Core Web Vitals لتحسين تجربة المستخدم وترتيب البحث في جوجل","en":"Agent Skills for optimizing web quality based on Lighthouse and Core Web Vitals."},"seo":{"title":{"zh":"Core Web Vitals 优化","ja":"Core Web Vitals 最適化","ko":"Core Web Vitals 최적화","es":"Optimización de Core Web Vitals para desarrolladores","fr":"Optimisation des Core Web Vitals pour les développeurs","de":"Core Web Vitals-Optimierung für Entwickler","pt":"Otimização de Core Web Vitals para Desenvolvedores","ru":"Оптимизация Core Web Vitals для разработчиков","ar":"تحسين Core Web Vitals للمطورين","en":"core-web-vitals"},"description":{"zh":"Core Web Vitals 优化是指针对三个影响 Google 搜索排名和用户体验的指标进行的优化","ja":"Core Web Vitals 最適化は、Google 検索ランキングとユーザーエクスペリエンスに影響を与える 3 つの指標を対象とした最適化です","ko":"Core Web Vitals 최적화는 Google 검색 순위와 사용자 경험에 영향을 미치는 세 가지 지표를 대상으로 하는 최적화입니다","es":"Optimiza tu sitio web con las métricas de Core Web Vitals para mejorar la experiencia del usuario y el ranking en Google. Aprende sobre LCP, INP y CLS.","fr":"Optimisez votre site web avec les métriques de Core Web Vitals pour améliorer l''expérience utilisateur et le référencement Google. Découvrez le LCP, l''INP et...","de":"Optimieren Sie Ihre Website mit den Core-Web-Vitals-Metriken, um die Benutzererfahrung und das Google-Ranking zu verbessern. Erfahren Sie mehr über LCP, INP ...","pt":"Otimização de Core Web Vitals para melhorar a experiência do usuário e o ranqueamento no Google Search","ru":"Оптимизация Core Web Vitals для улучшения пользовательского опыта и ранжирования в Google Search","ar":"تحسين Core Web Vitals لتحسين تجربة المستخدم وترتيب البحث في جوجل","en":"Agent Skills for optimizing web quality based on Lighthouse and Core Web Vitals."},"definition":{"en":"Agent Skills for optimizing web quality based on Lighthouse and Core Web Vitals."},"features":{"zh":["优化加载时间 (LCP)","提高交互性 (INP)","改善视觉稳定性 (CLS)","提高 Google 搜索排名","提升用户体验","使用 Lighthouse 进行分析"],"ja":["読み込み時間 (LCP) の最適化","対話性 (INP) の向上","視覚的安定性 (CLS) の改善","Google 検索ランキングの向上","ユーザーエクスペリエンスの向上","Lighthouse を使用した分析"],"ko":["로딩 시간 (LCP) 최적화","상호 작용性 (INP) 향상","시각적 안정성 (CLS) 개선","Google 검색 순위 향상","사용자 경험 향상","Lighthouse를 사용한 분석"],"es":["Optimización de la carga del sitio web (LCP)","Mejora de la interactividad del sitio web (INP)","Optimización de la estabilidad visual del sitio web (CLS)","Análisis de las métricas de Core Web Vitals","Mejora del ranking en Google","Mejora de la experiencia del usuario"],"fr":["Optimisation du chargement du site web (LCP)","Amélioration de l''interactivité du site web (INP)","Optimisation de la stabilité visuelle du site web (CLS)","Analyse des métriques de Core Web Vitals","Amélioration du référencement Google","Amélioration de l''expérience utilisateur"],"de":["Optimierung der Ladezeit der Website (LCP)","Verbesserung der Interaktivität der Website (INP)","Optimierung der visuellen Stabilität der Website (CLS)","Analyse der Core-Web-Vitals-Metriken","Verbesserung des Google-Rankings","Verbesserung der Benutzererfahrung"],"pt":["Otimização de LCP (Largest Contentful Paint) para melhorar a velocidade de carregamento","Otimização de INP (Interaction to Next Paint) para melhorar a interatividade","Otimização de CLS (Cumulative Layout Shift) para melhorar a estabilidade visual","Análise de desempenho com base nos 75% percentil","Melhoria da experiência do usuário e do ranqueamento no Google Search"],"ru":["Оптимизация LCP (Largest Contentful Paint) для улучшения скорости загрузки","Оптимизация INP (Interaction to Next Paint) для улучшения интерактивности","Оптимизация CLS (Cumulative Layout Shift) для улучшения визуальной стабильности","Анализ производительности на основе 75-го процентиля","Улучшение пользовательского опыта и ранжирования в Google Search"],"ar":["تحسين LCP (Largest Contentful Paint) لتحسين سرعة التحميل","تحسين INP (Interaction to Next Paint) لتحسين التفاعل","تحسين CLS (Cumulative Layout Shift) لتحسين الاستقرار المرئي","تحليل الأداء بناءً على Percentil 75","تحسين تجربة المستخدم وترتيب البحث في جوجل"]},"keywords":{"zh":["Core Web Vitals","LCP","INP","CLS","Google 搜索排名","网页质量","用户体验","Lighthouse","性能优化"],"ja":["Core Web Vitals","LCP","INP","CLS","Google 検索ランキング","ウェブページ品質","ユーザーエクスペリエンス","Lighthouse","パフォーマンス最適化"],"ko":["Core Web Vitals","LCP","INP","CLS","Google 검색 순위","웹 페이지 품질","사용자 경험","Lighthouse","성능 최적화"],"es":["Core Web Vitals","Optimización de sitios web","Mejora de la experiencia del usuario","Ranking en Google","LCP","INP","CLS","Desarrollo web","SEO"],"fr":["Core Web Vitals","Optimisation de sites web","Amélioration de l''expérience utilisateur","Référencement Google","LCP","INP","CLS","Développement web","SEO"],"de":["Core Web Vitals","Optimierung von Websites","Verbesserung der Benutzererfahrung","Google-Ranking","LCP","INP","CLS","Webentwicklung","SEO"],"pt":["Core Web Vitals","Otimização de desempenho","Experiência do usuário","Ranqueamento no Google Search","LCP","INP","CLS","Desenvolvimento web"],"ru":["Core Web Vitals","Оптимизация производительности","Пользовательский опыт","Ранжирование в Google Search","LCP","INP","CLS","Веб-разработка"],"ar":["Core Web Vitals","تحسين الأداء","تجربة المستخدم","ترتيب البحث في جوجل","LCP","INP","CLS","تطوير الويب"]}},"owner":"addyosmani","repo":"web-quality-skills","repoPath":"addyosmani/web-quality-skills","stars":0,"forks":0,"updatedAt":"2026-02-20T04:13:19.577Z","topics":[],"category":"community","skillMd":{"name":"core-web-vitals","description":"Optimize Core Web Vitals (LCP, INP, CLS) for better page experience and search ranking. Use when asked to improve Core Web Vitals, fix LCP, reduce CLS, optimize INP, page experience optimization, or fix layout shifts.","version":"1.0","bodyPreview":"# Core Web Vitals optimization\n\nTargeted optimization for the three Core Web Vitals metrics that affect Google Search ranking and user experience.\n\n## The three metrics\n\n| Metric | Measures | Good | Needs work | Poor |\n|--------|----------|------|------------|------|\n| **LCP** | Loading | ≤ 2.5s | 2.5s – 4s | > 4s |\n| **INP** | Interactivity | ≤ 200ms | 200ms – 500ms | > 500ms |\n| **CLS** | Visual Stability | ≤ 0.1 | 0.1 – 0.25 | > 0.25 |\n\nGoogle measures at the **75th percentile** — 75% of page","body":"# Core Web Vitals optimization\n\nTargeted optimization for the three Core Web Vitals metrics that affect Google Search ranking and user experience.\n\n## The three metrics\n\n| Metric | Measures | Good | Needs work | Poor |\n|--------|----------|------|------------|------|\n| **LCP** | Loading | ≤ 2.5s | 2.5s – 4s | > 4s |\n| **INP** | Interactivity | ≤ 200ms | 200ms – 500ms | > 500ms |\n| **CLS** | Visual Stability | ≤ 0.1 | 0.1 – 0.25 | > 0.25 |\n\nGoogle measures at the **75th percentile** — 75% of page visits must meet \"Good\" thresholds.\n\n---\n\n## LCP: Largest Contentful Paint\n\nLCP measures when the largest visible content element renders. Usually this is:\n- Hero image or video\n- Large text block\n- Background image\n- `<svg>` element\n\n### Common LCP issues\n\n**1. Slow server response (TTFB > 800ms)**\n```\nFix: CDN, caching, optimized backend, edge rendering\n```\n\n**2. Render-blocking resources**\n```html\n<!-- ❌ Blocks rendering -->\n<link rel=\"stylesheet\" href=\"/all-styles.css\">\n\n<!-- ✅ Critical CSS inlined, rest deferred -->\n<style>/* Critical above-fold CSS */</style>\n<link rel=\"preload\" href=\"/styles.css\" as=\"style\" \n      onload=\"this.onload=null;this.rel=''stylesheet''\">\n```\n\n**3. Slow resource load times**\n```html\n<!-- ❌ No hints, discovered late -->\n<img src=\"/hero.jpg\" alt=\"Hero\">\n\n<!-- ✅ Preloaded with high priority -->\n<link rel=\"preload\" href=\"/hero.webp\" as=\"image\" fetchpriority=\"high\">\n<img src=\"/hero.webp\" alt=\"Hero\" fetchpriority=\"high\">\n```\n\n**4. Client-side rendering delays**\n```javascript\n// ❌ Content loads after JavaScript\nuseEffect(() => {\n  fetch(''/api/hero-text'').then(r => r.json()).then(setHeroText);\n}, []);\n\n// ✅ Server-side or static rendering\n// Use SSR, SSG, or streaming to send HTML with content\nexport async function getServerSideProps() {\n  const heroText = await fetchHeroText();\n  return { props: { heroText } };\n}\n```\n\n### LCP optimization checklist\n\n```markdown\n- [ ] TTFB < 800ms (use CDN, edge caching)\n- [ ] LCP image preloaded with fetchpriority=\"high\"\n- [ ] LCP image optimized (WebP/AVIF, correct size)\n- [ ] Critical CSS inlined (< 14KB)\n- [ ] No render-blocking JavaScript in <head>\n- [ ] Fonts don''t block text rendering (font-display: swap)\n- [ ] LCP element in initial HTML (not JS-rendered)\n```\n\n### LCP element identification\n```javascript\n// Find your LCP element\nnew PerformanceObserver((list) => {\n  const entries = list.getEntries();\n  const lastEntry = entries[entries.length - 1];\n  console.log(''LCP element:'', lastEntry.element);\n  console.log(''LCP time:'', lastEntry.startTime);\n}).observe({ type: ''largest-contentful-paint'', buffered: true });\n```\n\n---\n\n## INP: Interaction to Next Paint\n\nINP measures responsiveness across ALL interactions (clicks, taps, key presses) during a page visit. It reports the worst interaction (at 98th percentile for high-traffic pages).\n\n### INP breakdown\n\nTotal INP = **Input Delay** + **Processing Time** + **Presentation Delay**\n\n| Phase | Target | Optimization |\n|-------|--------|--------------|\n| Input Delay | < 50ms | Reduce main thread blocking |\n| Processing | < 100ms | Optimize event handlers |\n| Presentation | < 50ms | Minimize rendering work |\n\n### Common INP issues\n\n**1. Long tasks blocking main thread**\n```javascript\n// ❌ Long synchronous task\nfunction processLargeArray(items) {\n  items.forEach(item => expensiveOperation(item));\n}\n\n// ✅ Break into chunks with yielding\nasync function processLargeArray(items) {\n  const CHUNK_SIZE = 100;\n  for (let i = 0; i < items.length; i += CHUNK_SIZE) {\n    const chunk = items.slice(i, i + CHUNK_SIZE);\n    chunk.forEach(item => expensiveOperation(item));\n    \n    // Yield to main thread\n    await new Promise(r => setTimeout(r, 0));\n    // Or use scheduler.yield() when available\n  }\n}\n```\n\n**2. Heavy event handlers**\n```javascript\n// ❌ All work in handler\nbutton.addEventListener(''click'', () => {\n  // Heavy computation\n  const result = calculateComplexThing();\n  // DOM updates\n  updateUI(result);\n  // Analytics\n  trackEvent(''click'');\n});\n\n// ✅ Prioritize visual feedback\nbutton.addEventListener(''click'', () => {\n  // Immediate visual feedback\n  button.classList.add(''loading'');\n  \n  // Defer non-critical work\n  requestAnimationFrame(() => {\n    const result = calculateComplexThing();\n    updateUI(result);\n  });\n  \n  // Use requestIdleCallback for analytics\n  requestIdleCallback(() => trackEvent(''click''));\n});\n```\n\n**3. Third-party scripts**\n```javascript\n// ❌ Eagerly loaded, blocks interactions\n<script src=\"https://heavy-widget.com/widget.js\"></script>\n\n// ✅ Lazy loaded on interaction or visibility\nconst loadWidget = () => {\n  import(''https://heavy-widget.com/widget.js'')\n    .then(widget => widget.init());\n};\nbutton.addEventListener(''click'', loadWidget, { once: true });\n```\n\n**4. Excessive re-renders (React/Vue)**\n```javascript\n// ❌ Re-renders entire tree\nfunction App() {\n  const [count, setCount] = useState(0);\n  return (\n    <div>\n      <Counter count={count} />\n      <ExpensiveComponent /> {/* Re-renders on every count change */}\n    </div>\n  );\n}\n\n// ✅ Memoized expensive components\nconst MemoizedExpensive = React.memo(ExpensiveComponent);\n\nfunction App() {\n  const [count, setCount] = useState(0);\n  return (\n    <div>\n      <Counter count={count} />\n      <MemoizedExpensive />\n    </div>\n  );\n}\n```\n\n### INP optimization checklist\n\n```markdown\n- [ ] No tasks > 50ms on main thread\n- [ ] Event handlers complete quickly (< 100ms)\n- [ ] Visual feedback provided immediately\n- [ ] Heavy work deferred with requestIdleCallback\n- [ ] Third-party scripts don''t block interactions\n- [ ] Debounced input handlers where appropriate\n- [ ] Web Workers for CPU-intensive operations\n```\n\n### INP debugging\n```javascript\n// Identify slow interactions\nnew PerformanceObserver((list) => {\n  for (const entry of list.getEntries()) {\n    if (entry.duration > 200) {\n      console.warn(''Slow interaction:'', {\n        type: entry.name,\n        duration: entry.duration,\n        processingStart: entry.processingStart,\n        processingEnd: entry.processingEnd,\n        target: entry.target\n      });\n    }\n  }\n}).observe({ type: ''event'', buffered: true, durationThreshold: 16 });\n```\n\n---\n\n## CLS: Cumulative Layout Shift\n\nCLS measures unexpected layout shifts. A shift occurs when a visible element changes position between frames without user interaction.\n\n**CLS Formula:** `impact fraction × distance fraction`\n\n### Common CLS causes\n\n**1. Images without dimensions**\n```html\n<!-- ❌ Causes layout shift when loaded -->\n<img src=\"photo.jpg\" alt=\"Photo\">\n\n<!-- ✅ Space reserved -->\n<img src=\"photo.jpg\" alt=\"Photo\" width=\"800\" height=\"600\">\n\n<!-- ✅ Or use aspect-ratio -->\n<img src=\"photo.jpg\" alt=\"Photo\" style=\"aspect-ratio: 4/3; width: 100%;\">\n```\n\n**2. Ads, embeds, and iframes**\n```html\n<!-- ❌ Unknown size until loaded -->\n<iframe src=\"https://ad-network.com/ad\"></iframe>\n\n<!-- ✅ Reserve space with min-height -->\n<div style=\"min-height: 250px;\">\n  <iframe src=\"https://ad-network.com/ad\" height=\"250\"></iframe>\n</div>\n\n<!-- ✅ Or use aspect-ratio container -->\n<div style=\"aspect-ratio: 16/9;\">\n  <iframe src=\"https://youtube.com/embed/...\" \n          style=\"width: 100%; height: 100%;\"></iframe>\n</div>\n```\n\n**3. Dynamically injected content**\n```javascript\n// ❌ Inserts content above viewport\nnotifications.prepend(newNotification);\n\n// ✅ Insert below viewport or use transform\nconst insertBelow = viewport.bottom < newNotification.top;\nif (insertBelow) {\n  notifications.prepend(newNotification);\n} else {\n  // Animate in without shifting\n  newNotification.style.transform = ''translateY(-100%)'';\n  notifications.prepend(newNotification);\n  requestAnimationFrame(() => {\n    newNotification.style.transform = '''';\n  });\n}\n```\n\n**4. Web fonts causing FOUT**\n```css\n/* ❌ Font swap shifts text */\n@font-face {\n  font-family: ''Custom'';\n  src: url(''custom.woff2'') format(''woff2'');\n}\n\n/* ✅ Optional font (no shift if slow) */\n@font-face {\n  font-family: ''Custom'';\n  src: url(''custom.woff2'') format(''woff2'');\n  font-display: optional;\n}\n\n/* ✅ Or match fallback metrics */\n@font-face {\n  font-family: ''Custom'';\n  src: url(''custom.woff2'') format(''woff2'');\n  font-display: swap;\n  size-adjust: 105%; /* Match fallback size */\n  ascent-override: 95%;\n  descent-override: 20%;\n}\n```\n\n**5. Animations triggering layout**\n```css\n/* ❌ Animates layout properties */\n.animate {\n  transition: height 0.3s, width 0.3s;\n}\n\n/* ✅ Use transform instead */\n.animate {\n  transition: transform 0.3s;\n}\n.animate.expanded {\n  transform: scale(1.2);\n}\n```\n\n### CLS optimization checklist\n\n```markdown\n- [ ] All images have width/height or aspect-ratio\n- [ ] All videos/embeds have reserved space\n- [ ] Ads have min-height containers\n- [ ] Fonts use font-display: optional or matched metrics\n- [ ] Dynamic content inserted below viewport\n- [ ] Animations use transform/opacity only\n- [ ] No content injected above existing content\n```\n\n### CLS debugging\n```javascript\n// Track layout shifts\nnew PerformanceObserver((list) => {\n  for (const entry of list.getEntries()) {\n    if (!entry.hadRecentInput) {\n      console.log(''Layout shift:'', entry.value);\n      entry.sources?.forEach(source => {\n        console.log(''  Shifted element:'', source.node);\n        console.log(''  Previous rect:'', source.previousRect);\n        console.log(''  Current rect:'', source.currentRect);\n      });\n    }\n  }\n}).observe({ type: ''layout-shift'', buffered: true });\n```\n\n---\n\n## Measurement tools\n\n### Lab testing\n- **Chrome DevTools** → Performance panel, Lighthouse\n- **WebPageTest** → Detailed waterfall, filmstrip\n- **Lighthouse CLI** → `npx lighthouse <url>`\n\n### Field data (real users)\n- **Chrome User Experience Report (CrUX)** → BigQuery or API\n- **Search Console** → Core Web Vitals report\n- **web-vitals library** → Send to your analytics\n\n```javascript\nimport {onLCP, onINP, onCLS} from ''web-vitals'';\n\nfunction sendToAnalytics({name, value, rating}) {\n  gtag(''event'', name, {\n    event_category: ''Web Vitals'',\n    value: Math.round(name === ''CLS'' ? value * 1000 : value),\n    event_label: rating\n  });\n}\n\nonLCP(sendToAnalytics);\nonINP(sendToAnalytics);\nonCLS(sendToAnalytics);\n```\n\n---\n\n## Framework quick fixes\n\n### Next.js\n```jsx\n// LCP: Use next/image with priority\nimport Image from ''next/image'';\n<Image src=\"/hero.jpg\" priority fill alt=\"Hero\" />\n\n// INP: Use dynamic imports\nconst HeavyComponent = dynamic(() => import(''./Heavy''), { ssr: false });\n\n// CLS: Image component handles dimensions automatically\n```\n\n### React\n```jsx\n// LCP: Preload in head\n<link rel=\"preload\" href=\"/hero.jpg\" as=\"image\" fetchpriority=\"high\" />\n\n// INP: Memoize and useTransition\nconst [isPending, startTransition] = useTransition();\nstartTransition(() => setExpensiveState(newValue));\n\n// CLS: Always specify dimensions in img tags\n```\n\n### Vue/Nuxt\n```vue\n<!-- LCP: Use nuxt/image with preload -->\n<NuxtImg src=\"/hero.jpg\" preload loading=\"eager\" />\n\n<!-- INP: Use async components -->\n<component :is=\"() => import(''./Heavy.vue'')\" />\n\n<!-- CLS: Use aspect-ratio CSS -->\n<img :style=\"{ aspectRatio: ''16/9'' }\" />\n```\n\n## References\n\n- [web.dev LCP](https://web.dev/articles/lcp)\n- [web.dev INP](https://web.dev/articles/inp)\n- [web.dev CLS](https://web.dev/articles/cls)\n- [Performance skill](../performance/SKILL.md)\n"},"lastSynced":"2026-02-20T04:47:28.273Z","agentAnalysis":{"suitability":{"en":"Ideal for SEO-focused AI Agents needing to optimize web quality based on Lighthouse and Core Web Vitals metrics like LCP, INP, and CLS.","zh":"适合需要优化基于 Lighthouse 和 Core Web Vitals 指标（如 LCP、INP 和 CLS）的 SEO 着重的 AI Agent 的理想选择","ja":"Lighthouse および Core Web Vitals メトリクス（LCP、INP、CLS など）に基づいて Web 品質を最適化する必要がある SEO 対応 AI エージェントに最適","ko":"Lighthouse 및 Core Web Vitals 메트릭(LCP, INP, CLS 등)을 기준으로 웹 품질을 최적화해야 하는 SEO 중심의 AI 에이전트에 적합","es":"Ideal para agentes de IA centrados en SEO que necesitan optimizar la calidad web basada en las métricas de Lighthouse y Core Web Vitals como LCP, INP y CLS.","fr":"Idéal pour les agents d''IA axés sur le SEO qui ont besoin d''optimiser la qualité web en fonction des métriques Lighthouse et Core Web Vitals comme LCP, INP et CLS.","de":"Ideal für SEO-fokussierte KI-Agents, die die Webqualität basierend auf Lighthouse- und Core-Web-Vitals-Metriken wie LCP, INP und CLS optimieren müssen.","pt":"Ideal para agentes de IA focados em SEO que precisam otimizar a qualidade da web com base em métricas do Lighthouse e Core Web Vitals, como LCP, INP e CLS.","ru":"Идеально подходит для агентов ИИ, ориентированных на SEO, которым необходимо оптимизировать качество веб-страниц на основе метрик Lighthouse и Core Web Vitals, таких как LCP, INP и CLS.","ar":"مثالي لعميل إيه آي محوره على تحسين محركات البحث و الذي يحتاج إلى تحسين جودة الويب على أساس مقاييس لايت هاوس و معايير الويب الأساسية مثل ل سي بي، إن بي و سي ال اس."},"recommendation":{"en":"Empowers agents to analyze and optimize web pages for better Google Search ranking and user experience by targeting the 75th percentile of page loads, leveraging metrics such as Largest Contentful Paint (LCP), Interactivity (INP), and Cumulative Layout Shift (CLS) to ensure fast loading times, smooth interactivity, and visual stability.","zh":"赋予代理分析和优化网页以获得更好的 Google 搜索排名和用户体验，通过针对页面加载的 75 百分位，利用诸如最大内容绘制（LCP）、交互性（INP）和累积布局偏移（CLS）等指标，以确保快速加载时间、平滑交互和视觉稳定性","ja":"エージェントが Web ページを分析および最適化して、Google 検索ランキングとユーザーエクスペリエンスを向上させることを可能にします。ページ読み込みの 75 パーセンタイルを対象とし、最大コンテンツ描画 (LCP)、インタラクティビティ (INP)、累積レイアウトシフト (CLS) などのメトリクスを利用して、高速な読み込み時間、スムーズなインタラクティビティ、視覚的な安定性を確保します","ko":"에이전트가 웹 페이지를 분석 및 최적화하여 Google 검색 순위와 사용자 경험을 향상시킬 수 있도록 합니다. 페이지 로드의 75 퍼센트를 대상으로 하여 최대 콘텐츠 페인트(LCP), 상호작용(INP), 누적 레이아웃 시프트(CLS) 등과 같은 메트릭스를 활용하여 빠른 로딩 시간, 부드러운 상호작용, 시각적 안정성을 보장합니다","es":"Habilita a los agentes a analizar y optimizar las páginas web para mejorar el ranking de Google Search y la experiencia del usuario, apuntando al percentil 75 de las cargas de página, aprovechando métricas como la Pintura de Contenido Más Grande (LCP), Interactividad (INP) y Cambio de Diseño Acumulado (CLS) para garantizar tiempos de carga rápidos, interactividad suave y estabilidad visual.","fr":"Permet aux agents d''analyser et d''optimiser les pages web pour améliorer le classement de Google Search et l''expérience utilisateur en ciblant le percentile 75 des chargements de page, en exploitant des métriques telles que la Peinture de Contenu la Plus Grande (LCP), l''Interactivité (INP) et le Changement de Disposition Cumulatif (CLS) pour assurer des temps de chargement rapides, une interactivité fluide et une stabilité visuelle.","de":"Ermächtigt Agents, Webseiten zu analysieren und zu optimieren, um die Google-Suchmaschinenrangliste und die Benutzererfahrung zu verbessern, indem sie auf den 75. Perzentil der Seitenladevorgänge abzielen, wobei Metriken wie Largest Contentful Paint (LCP), Interaktivität (INP) und kumulativer Layout-Wechsel (CLS) genutzt werden, um schnelle Ladezeiten, sanfte Interaktivität und visuelle Stabilität sicherzustellen.","pt":"Habilita os agentes a analisar e otimizar páginas da web para melhor ranqueamento no Google Search e experiência do usuário, visando o percentil 75 dos carregamentos de página, utilizando métricas como Largest Contentful Paint (LCP), Interatividade (INP) e Cumulative Layout Shift (CLS) para garantir tempos de carregamento rápidos, interatividade suave e estabilidade visual.","ru":"Наделяет агентов возможностью анализировать и оптимизировать веб-страницы для улучшения рейтинга в поиске Google и пользовательского опыта, ориентируясь на 75-й процентиль загрузок страниц, используя метрики, такие как Largest Contentful Paint (LCP), Интерактивность (INP) и Кумулятивный сдвиг макета (CLS), для обеспечения быстрых времен загрузки, плавной интерактивности и визуальной стабильности.","ar":"تمكين العميل من تحليل و تحسين صفحات الويب من أجل تحسين ترتيب البحث في جوجل و تجربة المستخدم، بالاستهداف من حيث المئوية 75 من عمليات تحميل الصفحة، واستخدام مقاييس مثل لارجست كونتينت فول باينت (إل سي بي)، التفاعل (إن بي)، وتراكم تحول التخطيط (سي ال اس) لضمان أوقات تحميل سريعة و تفاعل ملس و استقرار بصرية."},"useCases":{"en":["Optimizing web pages for improved LCP scores","Analyzing and reducing INP to enhance user interactivity","Debugging CLS issues to ensure visual stability"],"zh":["优化网页以提高 LCP 得分","分析和减少 INP 以增强用户交互","调试 CLS 问题以确保视觉稳定性"],"ja":["LCP スコアを向上させるための Web ページの最適化","ユーザーのインタラクティビティを向上させるための INP の分析と削減","視覚的な安定性を確保するための CLS の問題のデバッグ"],"ko":["LCP 점수를 향상시키기 위한 웹 페이지 최적화","사용자 상호작용을 향상시키기 위한 INP 분석 및 감소","시각적 안정성을 보장하기 위한 CLS 문제 디버깅"],"es":["Optimizar las páginas web para mejorar las puntuaciones de LCP","Analizar y reducir INP para mejorar la interactividad del usuario","Depurar problemas de CLS para garantizar la estabilidad visual"],"fr":["Optimiser les pages web pour améliorer les scores LCP","Analyser et réduire l''INP pour améliorer l''interactivité de l''utilisateur","Déboguer les problèmes de CLS pour assurer la stabilité visuelle"],"de":["Webseiten für verbesserte LCP-Scores optimieren","INP analysieren und reduzieren, um die Benutzerinteraktivität zu verbessern","CLS-Probleme debuggen, um die visuelle Stabilität sicherzustellen"],"pt":["Otimizar páginas da web para melhorar escores de LCP","Analizar e reduzir INP para melhorar a interatividade do usuário","Depurar problemas de CLS para garantir estabilidade visual"],"ru":["Оптимизировать веб-страницы для улучшения показателей LCP","Анализировать и снижать INP для улучшения интерактивности пользователя","Отладить проблемы CLS для обеспечения визуальной стабильности"],"ar":["تحسين صفحات الويب لتحسين درجات ل سي بي","تحليل وتقليل إن بي لتحسين تفاعل المستخدم","تصحيح أخطاء سي ال اس لضمان الاستقرار البصري"]},"limitations":{"en":["Requires Lighthouse integration for metrics analysis","Focuses on the 75th percentile of page loads for metric evaluation","Limited to optimizing for LCP, INP, and CLS metrics"],"zh":["需要 Lighthouse 集成以进行指标分析","专注于页面加载的 75 百分位进行指标评估","仅限于优化 LCP、INP 和 CLS 指标"],"ja":["メトリクス分析のために Lighthouse 統合が必要","メトリクスの評価のためにページ読み込みの 75 パーセンタイルに焦点を当てている","LCP、INP、CLS メトリクスの最適化に限定"],"ko":["메트릭스 분석을 위한 Lighthouse 통합이 필요","메트릭스 평가를 위한 페이지 로드의 75 퍼센트에 초점","LCP, INP, CLS 메트릭스 최적화에 제한"],"es":["Requiere la integración de Lighthouse para el análisis de métricas","Se centra en el percentil 75 de las cargas de página para la evaluación de métricas","Limitado a la optimización de las métricas LCP, INP y CLS"],"fr":["Nécessite l''intégration de Lighthouse pour l''analyse des métriques","Se concentre sur le percentile 75 des chargements de page pour l''évaluation des métriques","Limité à l''optimisation des métriques LCP, INP et CLS"],"de":["Benötigt die Integration von Lighthouse für die Analyse von Metriken","Konzentriert sich auf den 75. Perzentil der Seitenladevorgänge für die Bewertung von Metriken","Begrenzt auf die Optimierung der Metriken LCP, INP und CLS"],"pt":["Requer integração com o Lighthouse para análise de métricas","Se concentra no percentil 75 dos carregamentos de página para avaliação de métricas","Limitado à otimização para métricas LCP, INP e CLS"],"ru":["Требует интеграции с Lighthouse для анализа метрик","Фокусируется на 75-м процентиле загрузок страниц для оценки метрик","Ограничен оптимизацией для метрик LCP, INP и CLS"],"ar":["يتطلب التكامل مع لايت هاوس لتحليل المقاييس","يركز على المئوية 75 من عمليات تحميل الصفحة لتقييم المقاييس","محدود بالتحسين لمقاييس إل سي بي وإن بي وسي ال اس"]},"version":3},"contentHash":"b03396c9bd7a41950bbaf5964bc8f1cf60a3c81830a6171614d6413c8bff308c","qualityScore":60}');
