INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('addyosmani/web-quality-skills/core-web-vitals', 'core-web-vitals', 'addyosmani', 'web-quality-skills', 'community', 'core-web-vitals addyosmani web-quality-skills community Core Web Vitals 优化是指针对三个影响 Google 搜索排名和用户体验的指标进行的优化 Core Web Vitals 最適化は、Google 検索ランキングとユーザーエクスペリエンスに影響を与える 3 つの指標を対象とした最適化です Core Web Vitals 최적화는 Google 검색 순위와 사용자 경험에 영향을 미치는 세 가지 지표를 대상으로 하는 최적화입니다 Optimiza tu sitio web con las métricas de Core Web Vitals para mejorar la experiencia del usuario y el ranking en Google. Aprende sobre LCP, INP y CLS. Optimisez votre site web avec les métriques de Core Web Vitals pour améliorer l''expérience utilisateur et le référencement Google. Découvrez le LCP, l''INP et le CLS. Optimieren Sie Ihre Website mit den Core-Web-Vitals-Metriken, um die Benutzererfahrung und das Google-Ranking zu verbessern. Erfahren Sie mehr über LCP, INP und CLS. Otimização de Core Web Vitals para melhorar a experiência do usuário e o ranqueamento no Google Search Оптимизация Core Web Vitals для улучшения пользовательского опыта и ранжирования в Google Search تحسين Core Web Vitals لتحسين تجربة المستخدم وترتيب البحث في جوجل Agent Skills for optimizing web quality based on Lighthouse and Core Web Vitals. Core Web Vitals LCP INP CLS Google 搜索排名 网页质量 用户体验 Lighthouse 性能优化 Agent Skills for optimizing web quality based on Lighthouse and Core Web Vitals.');
